type RichTextPath = number[];
type RichAstStyleRecord = Record<string, string | number>;

const setRichTextAtPath = (
  node: RichAstNode,
  path: RichTextPath,
  text: string,
): RichAstNode | null => {
  if (path.length === 0) {
    return node.kind === "text" ? { ...node, text } : null;
  }
  if (node.kind !== "element") return null;
  const [head, ...rest] = path;
  const child = node.children[head];
  if (!child) return null;
  const nextChild = setRichTextAtPath(child, rest, text);
  if (!nextChild) return null;
  const children = [...node.children];
  children[head] = nextChild;
  return { ...node, children };
};

const getRichAstNodeAtPath = (
  node: RichAstNode,
  path: RichTextPath,
): RichAstNode | null => {
  if (path.length === 0) return node;
  if (node.kind !== "element") return null;
  const [head, ...rest] = path;
  const child = node.children[head];
  return child ? getRichAstNodeAtPath(child, rest) : null;
};

const getRichElementStyleAtPath = (
  node: RichAstNode,
  path: RichTextPath,
): RichAstStyleRecord => {
  const target = getRichAstNodeAtPath(node, path);
  if (!target || target.kind !== "element") return {};
  const style = target.props.style;
  return style && typeof style === "object" && !Array.isArray(style)
    ? ({ ...style } as RichAstStyleRecord)
    : {};
};

const patchRichElementStyleAtPath = (
  node: RichAstNode,
  path: RichTextPath,
  patch: Record<string, string | number | null>,
): RichAstNode | null => {
  if (node.kind !== "element") return null;
  if (path.length === 0) {
    const prevStyle = getRichElementStyleAtPath(node, []);
    const nextRaw: Record<string, string | number> = { ...prevStyle };
    for (const [key, value] of Object.entries(patch)) {
      if (value === null || value === "") {
        delete nextRaw[key];
      } else {
        nextRaw[key] = value;
      }
    }
    const style = sanitizeQuizAstStyleObject(nextRaw);
    const props = { ...node.props };
    if (Object.keys(style).length > 0) {
      props.style = style;
    } else {
      delete props.style;
    }
    return { ...node, props };
  }

  const [head, ...rest] = path;
  const child = node.children[head];
  if (!child) return null;
  const nextChild = patchRichElementStyleAtPath(child, rest, patch);
  if (!nextChild) return null;
  const children = [...node.children];
  children[head] = nextChild;
  return { ...node, children };
};

const getRichTextStyleTargetPath = (textPath: RichTextPath): RichTextPath =>
  textPath.length > 0 ? textPath.slice(0, -1) : [];

interface RichTextStyleSnapshot {
  fontFamily: string;
  fontSize: number;
  lineHeight: number;
  bold: boolean;
  italic: boolean;
  color: string;
  backgroundColor: string;
  align: "left" | "center" | "right";
}

const readRichTextStyleSnapshot = (
  element: RichElement,
  textPath: RichTextPath | null,
): RichTextStyleSnapshot | null => {
  if (!textPath) return null;
  const style = getRichElementStyleAtPath(element.react_layout, getRichTextStyleTargetPath(textPath));
  const fontSize =
    typeof style.fontSize === "number"
      ? style.fontSize
      : typeof style.fontSize === "string"
        ? Number.parseFloat(style.fontSize)
        : Number.NaN;
  const lineHeight =
    typeof style.lineHeight === "number"
      ? style.lineHeight
      : typeof style.lineHeight === "string"
        ? Number.parseFloat(style.lineHeight)
        : Number.NaN;
  const fontWeight = String(style.fontWeight ?? "");
  const fontStyle = String(style.fontStyle ?? "");
  const textAlign = String(style.textAlign ?? "left");

  return {
    fontFamily: typeof style.fontFamily === "string" ? style.fontFamily : "Inter, sans-serif",
    fontSize: Number.isFinite(fontSize) && fontSize > 0 ? fontSize : 36,
    lineHeight: Number.isFinite(lineHeight) && lineHeight > 0 ? lineHeight : 1.25,
    bold: fontWeight === "700" || fontWeight === "bold",
    italic: fontStyle === "italic",
    color: typeof style.color === "string" ? style.color : "#0f172a",
    backgroundColor:
      typeof style.backgroundColor === "string" ? style.backgroundColor : "transparent",
    align: textAlign === "center" || textAlign === "right" ? textAlign : "left",
  };
};

/** Canvas "button" mode: the ring and the round button scale by percentages of the box, keeping the selection consistent with the logical size */
const CANVAS_AUDIO_BUTTON_LOGICAL_SIZE = { width: 112, height: 112 } as const;
const CANVAS_AUDIO_PLAYER_LOGICAL_SIZE = { width: 480, height: 120 } as const;

function shrinkWrapAudioDisplaySize(
  el: AudioElement,
  next: { width: number; height: number },
): Pick<AudioElement, "size" | "position"> {
  const dx = (el.size.width - next.width) / 2;
  const dy = (el.size.height - next.height) / 2;
  return {
    size: { width: next.width, height: next.height },
    position: { x: el.position.x + dx, y: el.position.y + dy },
  };
}

/**
 * Map canvas selection to `scene.quiz.questions[].question_id`. In the new
 * single-element quiz model the binding lives directly on the canvas element.
 */
function getQuizQuestionIdForCanvasSelection(
  slide: SlideElement | undefined,
  element: CourseElement | null | undefined,
): string | null {
  if (!slide || !element) return null;
  if (element.element_type !== "quiz") return null;
  const id = (element as QuizSlideElement).quiz_question_id;
  return id ? id : null;
}

function getEditorQuestionConfig(
  quiz: QuizConfig | null | undefined,
  wrapper: QuizSlideElement,
): QuizQuestion | null {
  if (!quiz?.enabled) return null;
  return quiz.questions.find((q) => q.question_id === wrapper.quiz_question_id) ?? null;
}

/** Canvas quiz badge: e.g. "题1 · 单选题" (falls back when unbound or missing from quiz). */
function formatQuizCanvasBadgeLabel(
  t: CoursewareTranslateFn,
  quiz: QuizConfig | null | undefined,
  wrapper: QuizSlideElement,
  typeLabels: Record<QuizQuestionType, string>,
): string {
  const qid = wrapper.quiz_question_id;
  if (!qid || !quiz?.enabled) {
    return t("coursewareEditor.common.questionElement");
  }
  const index = quiz.questions.findIndex((q) => q.question_id === qid);
  if (index < 0) {
    return t("coursewareEditor.common.questionElement");
  }
  const question = quiz.questions[index]!;
  const kind = typeLabels[question.type] ?? question.type;
  return t("coursewareEditor.common.questionBadge", { number: index + 1, kind });
}

function resolveQuizModalInitialQuestionId(
  pendingQuestionId: string | null,
  slide: SlideElement | undefined,
  selectedElementIds: string[],
  quiz: QuizConfig | null | undefined,
  activeQuestionId: string | null,
): string | null {
  const valid = (id: string | null | undefined): string | null =>
    id && quiz?.questions.some((q) => q.question_id === id) ? id : null;
  return (
    valid(pendingQuestionId) ??
    valid(activeQuestionId) ??
    resolveQuizQuestionIdForEditorSelection(slide, selectedElementIds, quiz) ??
    quiz?.questions[0]?.question_id ??
    null
  );
}

/** Prefer the first selected element that maps to a question still present in `quiz`. */
function resolveQuizQuestionIdForEditorSelection(
  slide: SlideElement | undefined,
  selectedElementIds: string[],
  quiz: QuizConfig | null | undefined,
): string | null {
  if (!slide || selectedElementIds.length === 0) return null;
  const valid = quiz?.questions.length
    ? new Set(quiz.questions.map((q) => q.question_id))
    : null;
  for (const elementId of selectedElementIds) {
    const el = slide.children_elements.find((c) => c.element_id === elementId);
    const qid = getQuizQuestionIdForCanvasSelection(slide, el);
    if (!qid) continue;
    if (valid && !valid.has(qid)) continue;
    return qid;
  }
  return null;
}

/** Label from AST; falls back to `optionId` when the option node has no text. */
const getQuizOptionDisplayLabel = (
  question: QuizQuestion | null | undefined,
  optionId: string,
): string => {
  if (!question) return optionId;
  const label = extractQuizOptionLabelFromAst(question.react_layout, optionId);
  return label.length > 0 ? label : optionId;
};

/** Fixed on top in the layer list / z-order: narration topmost, the Vtuber right below it, neither draggable to change layers. */
const isPinnedLayerElement = (el: CourseElement): boolean =>
  el.element_type === "narration" || el.element_type === "vtuber";

/** Stacking only inside slide thumbnails / the minimap; must stay below global modals (z-100+), and the container needs `isolate`. */
const SLIDE_PREVIEW_VTUBER_Z_OFFSET = 20;
const SLIDE_PREVIEW_NARRATION_Z_OFFSET = 30;
/** Thumbnail corner badge (duration etc.), must be above {@link resolveEditorThumbnailStackZ} (including the Vtuber / narration top offset). */
const SLIDE_PREVIEW_CHROME_Z_INDEX = 10_000;
/** The minimap's current viewport frame, above the Vtuber / narration layers inside thumbnails and below the badge chrome. */
const SLIDE_PREVIEW_MINIMAP_VIEWPORT_Z_INDEX = SLIDE_PREVIEW_CHROME_Z_INDEX - 1;

const resolveEditorThumbnailStackZ = (el: CourseElement, stackZ: number): number => {
  if (el.element_type === "narration") return SLIDE_PREVIEW_NARRATION_Z_OFFSET + stackZ;
  if (el.element_type === "vtuber") return SLIDE_PREVIEW_VTUBER_Z_OFFSET + stackZ;
  return stackZ;
};

/**
 * Timeline rows: narration on top, the Vtuber next; each quiz question element is its own row; the rest follow the canvas stacking order.
 * In the new single-element quiz model every quiz is its own row — there's no
 * "merged" multi-segment row anymore.
 */
type EditorTimelineRow =
  | { kind: "narration"; childIndex: number }
  | { kind: "vtuber"; childIndex: number }
  | { kind: "other"; childIndex: number };

function buildEditorTimelineRows(slide: SlideElement): EditorTimelineRow[] {
  const narrationRows: EditorTimelineRow[] = [];
  const vtuberRows: EditorTimelineRow[] = [];
  const otherRows: EditorTimelineRow[] = [];
  for (const unit of buildQuestionStackRenderUnits(slide)) {
    const el = unit.element;
    const idx = slide.children_elements.findIndex((c) => c.element_id === el.element_id);
    if (idx < 0) continue;
    if (el.element_type === "narration") {
      narrationRows.push({ kind: "narration", childIndex: idx });
    } else if (el.element_type === "vtuber") {
      vtuberRows.push({ kind: "vtuber", childIndex: idx });
    } else {
      otherRows.push({ kind: "other", childIndex: idx });
    }
  }
  // Stack units are back→front; timeline rows match layer list (front at top).
  return [...narrationRows, ...vtuberRows, ...otherRows.reverse()];
}

/**
 * The left "layers" list: narration on top, the Vtuber next; the rest follow the canvas stacking order.
 * `unitIndex` points at the index of the matching unit in {@link buildQuestionStackRenderUnits}, so dragging / reordering can
 * map a "display row" back to the underlying stack unit index.
 */
type EditorLayerRow =
  | { kind: "narration"; childIndex: number; unitIndex: number }
  | { kind: "vtuber"; childIndex: number; unitIndex: number }
  | { kind: "other"; childIndex: number; unitIndex: number };

function buildEditorLayerRows(slide: SlideElement): EditorLayerRow[] {
  const narrationRows: EditorLayerRow[] = [];
  const vtuberRows: EditorLayerRow[] = [];
  const stackRows: EditorLayerRow[] = [];
  buildQuestionStackRenderUnits(slide).forEach((unit, unitIndex) => {
    const el = unit.element;
    const idx = slide.children_elements.findIndex((c) => c.element_id === el.element_id);
    if (idx < 0) return;
    if (el.element_type === "narration") {
      narrationRows.push({ kind: "narration", childIndex: idx, unitIndex });
    } else if (el.element_type === "vtuber") {
      vtuberRows.push({ kind: "vtuber", childIndex: idx, unitIndex });
    } else {
      stackRows.push({ kind: "other", childIndex: idx, unitIndex });
    }
  });
  // Stack units are back→front; layer list shows front at top (「顶层 ↑」).
  stackRows.reverse();
  return [...narrationRows, ...vtuberRows, ...stackRows];
}

const getSelectAllElementIds = (slide: SlideElement): string[] => {
  return slide.children_elements
    .filter((element) => !isElementEditBlocked(element))
    .map((element) => element.element_id);
};

type EditorAxisRect = { left: number; top: number; right: number; bottom: number };

const normalizeEditorAxisRect = (x0: number, y0: number, x1: number, y1: number): EditorAxisRect => ({
  left: Math.min(x0, x1),
  top: Math.min(y0, y1),
  right: Math.max(x0, x1),
  bottom: Math.max(y0, y1),
});

const editorAxisRectsOverlap = (a: EditorAxisRect, b: EditorAxisRect): boolean =>
  a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;

const elementBoundsFromTransform = (t: LiveTransform): EditorAxisRect => ({
  left: t.x,
  top: t.y,
  right: t.x + t.width,
  bottom: t.y + t.height,
});

const isMarqueeSelectableCanvasElement = (
  slide: SlideElement,
  el: CourseElement,
  playheadMs: number,
): boolean => {
  if (isElementEditBlocked(el)) return false;
  if (!isElementVisibleAtTimeInSlide(el, playheadMs, slide)) return false;
  if (el.element_type === "audio" && getCanvasAudioDisplayMode(el) === "hidden") return false;
  return true;
};

const resolveMarqueeSelectionIds = (
  slide: SlideElement,
  playheadMs: number,
  marquee: EditorAxisRect,
  resolveTransform: (el: CourseElement) => LiveTransform,
): string[] => {
  const selected: string[] = [];
  for (const el of slide.children_elements) {
    if (!isMarqueeSelectableCanvasElement(slide, el, playheadMs)) continue;
    const bounds = elementBoundsFromTransform(resolveTransform(el));
    if (editorAxisRectsOverlap(marquee, bounds)) selected.push(el.element_id);
  }
  return selected;
};

const MARQUEE_DRAG_THRESHOLD_PX = 4;

/** Locked by the user by hand (persisted into the element JSON) */
const isElementLocked = (element: CourseElement | null | undefined): boolean =>
  element?.locked === true;

/** Frozen exclusively by the agent for this conversation turn (editor memory only, never persisted) */
const agentChatFrozenElementIdsRef: { current: ReadonlySet<string> } = { current: new Set() };

const isElementAgentChatFrozen = (elementId: string): boolean =>
  agentChatFrozenElementIdsRef.current.has(elementId);

const isElementEditBlocked = (element: CourseElement | null | undefined): boolean =>
  isElementLocked(element) ||
  (element != null && isElementAgentChatFrozen(element.element_id));

/** Same position as the canvas floating "lock" badge (px within StageArea), used for hit testing so hover isn't lost when moving onto the badge. */
const EDITOR_LOCKED_CHIP_PX = 20;
const EDITOR_LOCKED_CHIP_INSET_PX = 12;
const EDITOR_LOCKED_CHIP_Z_INDEX = 2147483647;

/** The badge sits at the element's top right by default; when the element goes beyond the canvas it is clamped inside the stage, so the badge doesn't fall outside the stage and let pointerleave clear the hover. */
const getEditorLockedUnlockChipLayout = (
  t: LiveTransform,
  stageScale: number,
  stageWpx: number,
  stageHpx: number,
): { chipLeftPx: number; chipTopPx: number; hitMinX: number; hitMaxX: number; hitMinY: number; hitMaxY: number } => {
  const chipPx = EDITOR_LOCKED_CHIP_PX;
  const insetPx = EDITOR_LOCKED_CHIP_INSET_PX;
  const padPx = 8;
  let leftPx = (t.x + t.width) * stageScale - insetPx;
  let topPx = t.y * stageScale - insetPx;
  leftPx = clamp(leftPx, 0, Math.max(0, stageWpx - chipPx));
  topPx = clamp(topPx, 0, Math.max(0, stageHpx - chipPx));
  return {
    chipLeftPx: leftPx,
    chipTopPx: topPx,
    hitMinX: (leftPx - padPx) / stageScale,
    hitMaxX: (leftPx + chipPx + padPx) / stageScale,
    hitMinY: (topPx - padPx) / stageScale,
    hitMaxY: (topPx + chipPx + padPx) / stageScale,
  };
};

const slidePointHitsLockedElementUnlockChip = (
  x: number,
  y: number,
  t: LiveTransform,
  stageScale: number,
  stageWpx: number,
  stageHpx: number,
): boolean => {
  const L = getEditorLockedUnlockChipLayout(t, stageScale, stageWpx, stageHpx);
  return x >= L.hitMinX && x <= L.hitMaxX && y >= L.hitMinY && y <= L.hitMaxY;
};

type OpenElementContextMenuFn = (
  elementId: string,
  clientX: number,
  clientY: number,
  options?: {
    slideX?: number;
    slideY?: number;
    stageScale?: number;
    stageWpx?: number;
    stageHpx?: number;
    manualMarkMode?: boolean;
  },
) => void;

/** All visible elements hit at canvas coordinates (top down; locked layers included; for right-click overlap selection). */
const findCanvasElementsAtPoint = (
  slide: SlideElement,
  playheadMs: number,
  x: number,
  y: number,
  resolveTransform: (el: CourseElement) => LiveTransform,
  options?: {
    manualMarkMode?: boolean;
    stageScale?: number;
    stageWpx?: number;
    stageHpx?: number;
  },
): CourseElement[] => {
  const manualMarkMode = options?.manualMarkMode ?? false;
  const stageScale = options?.stageScale ?? 1;
  const stageWpx = options?.stageWpx ?? 0;
  const stageHpx = options?.stageHpx ?? 0;
  const candidates: Array<{ element: CourseElement; order: number; z: number }> = [];
  buildQuestionStackRenderUnits(slide).forEach((unit, unitIndex) => {
    const el = unit.element;
    candidates.push({ element: el, order: unitIndex, z: el.style.z_index });
  });
  candidates.sort((a, b) => (a.z === b.z ? a.order - b.order : a.z - b.z));
  const hits: CourseElement[] = [];
  for (let i = candidates.length - 1; i >= 0; i -= 1) {
    const el = candidates[i]!.element;
    if (manualMarkMode && (el.element_type === "vtuber" || el.element_type === "narration")) {
      continue;
    }
    if (isElementAgentChatFrozen(el.element_id)) continue;
    if (!isElementVisibleAtTimeInSlide(el, playheadMs, slide)) continue;
    if (el.element_type === "audio" && getCanvasAudioDisplayMode(el) === "hidden") continue;
    const t = resolveTransform(el);
    const inBounds = x >= t.x && x <= t.x + t.width && y >= t.y && y <= t.y + t.height;
    const onUnlockChip =
      isElementLocked(el) &&
      slidePointHitsLockedElementUnlockChip(x, y, t, stageScale, stageWpx, stageHpx);
    if (inBounds || onUnlockChip) hits.push(el);
  }
  return hits;
};

/** The topmost visible element hit at canvas coordinates (locked layers included; for the context menu). */
const findTopCanvasElementAtPoint = (
  slide: SlideElement,
  playheadMs: number,
  x: number,
  y: number,
  resolveTransform: (el: CourseElement) => LiveTransform,
  options?: {
    manualMarkMode?: boolean;
    stageScale?: number;
    stageWpx?: number;
    stageHpx?: number;
  },
): CourseElement | null => {
  return (
    findCanvasElementsAtPoint(slide, playheadMs, x, y, resolveTransform, options)[0] ?? null
  );
};

const formatCanvasElementOverlapLabel = (element: CourseElement): string => {
  const name = element.name?.trim();
  if (name) return name;
  return element.element_type;
};

const isTextElement = (element: CourseElement): element is TextElement =>
  element.element_type === "text";

/**
 * Quiz-element child filter: returns the `element_id`s of all `element_type:"quiz"`
 * boxes on the slide. Used when deleting / cleaning up `scene.quiz.questions[]`
 * entries that lose their canvas binding.
 */
const collectQuizElementIdsOnSlide = (slide: SlideElement): Set<string> => {
  const out = new Set<string>();
  for (const el of slide.children_elements) {
    if (el.element_type === "quiz") out.add(el.element_id);
  }
  return out;
};

/**
 * Find the `quiz_question_id`s for any `element_type:"quiz"` boxes being
 * removed from a slide. The caller pairs this with
 * {@link removeQuizEntriesForQuestionIds} to keep `scene.quiz.questions[]` in
 * sync when canvas elements are deleted.
 */
const quizQuestionIdsForRemovedQuestionElements = (
  children: CourseElement[],
  removedIds: Set<string>,
): Set<string> => {
  const out = new Set<string>();
  for (const el of children) {
    if (el.element_type !== "quiz" || !removedIds.has(el.element_id)) continue;
    const qid = (el as QuizSlideElement).quiz_question_id;
    if (qid) out.add(qid);
  }
  return out;
};

const removeQuizEntriesForQuestionIds = (
  quiz: QuizConfig | null | undefined,
  questionIds: Set<string>,
): QuizConfig | null | undefined => {
  if (!quiz || questionIds.size === 0) return undefined;
  const nextQuestions = quiz.questions.filter((q) => !questionIds.has(q.question_id));
  if (nextQuestions.length === quiz.questions.length) return undefined;
  if (nextQuestions.length === 0) return null;
  return { ...quiz, questions: nextQuestions };
};

const fallbackEditorMetaT: CoursewareTranslateFn = (key, variables) => {
  let text = (coursewareRoutesEn as Record<string, string>)[key] ?? String(key);
  if (variables) {
    for (const [name, value] of Object.entries(variables)) {
      text = text.replaceAll(`{${name}}`, String(value));
    }
  }
  return text;
};

let activeEditorMetaLabels: CoursewareEditorMetaLabels =
  buildCoursewareEditorMetaLabels(fallbackEditorMetaT);

let activeCanvasTemplateLabels: CanvasQuestionTemplateLabels =
  buildCanvasQuestionTemplateLabels(fallbackEditorMetaT);

const getEditorMeta = (): CoursewareEditorMetaLabels => activeEditorMetaLabels;

const getCanvasTemplateLabels = (): CanvasQuestionTemplateLabels =>
  activeCanvasTemplateLabels;

const DEFAULT_SLIDE_DURATION_MS = 5_000;
const DEFAULT_HIGHLIGHT_DURATION_MS = 1_800;
const MIN_HIGHLIGHT_DURATION_MS = 500;
const HIGHLIGHT_TRANSITION_MS = 260;
const SLIDE_THUMBNAIL_SCALE = 0.09;
const SCENE_HISTORY_LIMIT = 100;
const NARRATION_DEFAULT_GAP_MS = 200;
const AUTO_NARRATION_AUDIO_TOAST_ID = "courseware-editor-auto-narration-audio";
const EDITOR_AUTO_SAVE_DEBOUNCE_MS = 5000;
/** Maximum interval before syncing changes to courseware-service (avoids frequent PUTs) */
const EDITOR_SERVER_SYNC_INTERVAL_MS = 1 * 60 * 1000;
/** When localStorage holds "1", the import/export menu shows next to the save button */
const COURSEWARE_EDITOR_IMPORT_EXPORT_STORAGE_KEY = "courseware-editor:import-export";

function isCoursewareEditorImportExportEnabled(): boolean {
  if (typeof window === "undefined") return false;
  return window.localStorage.getItem(COURSEWARE_EDITOR_IMPORT_EXPORT_STORAGE_KEY) === "1";
}
const DEFAULT_TEXT_FONT_FAMILY =
  `"PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC", Inter, sans-serif`;
type LocalFontData = {
  family: string;
  fullName?: string;
};

type WindowWithLocalFonts = Window & {
  queryLocalFonts?: () => Promise<LocalFontData[]>;
};

type SelectedKeyframe = {
  elementId: string;
  at: number;
};

type SelectedHighlight = {
  elementId: string;
  highlightId: string;
};

/** Quiz question type → editor sidebar icon (replaces legacy QUESTION_TEMPLATE_ICON). */
const QUIZ_QUESTION_TYPE_ICON: Record<QuizQuestionType, React.ReactNode> = {
  single_choice: <CircleDot className="h-4 w-4" />,
  multiple_choice: <ListChecks className="h-4 w-4" />,
  fill_blank: <PencilLine className="h-4 w-4" />,
  essay: <PencilLine className="h-4 w-4" />,
  shadowing: <Mic className="h-4 w-4" />,
  speech: <AudioLines className="h-4 w-4" />,
};

const genId = (prefix: string): string => {
  const rand =
    typeof globalThis.crypto?.randomUUID === "function"
      ? globalThis.crypto.randomUUID().replace(/-/g, "").slice(0, 10)
      : `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
  return `${prefix}_${rand}`;
};

const cloneQuizQuestionForCanvasPaste = cloneQuizQuestionWithFreshIds;

const collectSubtreeElementIds = (el: CourseElement, into: Set<string>): void => {
  into.add(el.element_id);
  if (el.element_type === "group") {
    for (const ch of (el as GroupElement).children_elements) {
      collectSubtreeElementIds(ch as CourseElement, into);
    }
  }
  if (el.element_type === "html") {
    for (const ch of (el as HtmlElement).children_elements) {
      collectSubtreeElementIds(ch as CourseElement, into);
    }
  }
};

const buildElementIdMapForPaste = (roots: CourseElement[]): Map<string, string> => {
  const allIds = new Set<string>();
  for (const r of roots) {
    collectSubtreeElementIds(r, allIds);
  }
  const idMap = new Map<string, string>();
  for (const id of allIds) {
    idMap.set(id, genId("el"));
  }
  return idMap;
};

const remapElementTreeForPaste = (el: CourseElement, idMap: Map<string, string>): CourseElement => {
  const mapId = (id: string): string => (idMap.has(id) ? idMap.get(id)! : id);
  const nextId = mapId(el.element_id);
  let next: CourseElement = { ...el, element_id: nextId } as CourseElement;

  if (next.element_type === "narration") {
    const n = next as NarrationElement;
    next = {
      ...n,
      vtuber_element_id: n.vtuber_element_id ? mapId(n.vtuber_element_id) : n.vtuber_element_id,
    } as NarrationElement;
  } else if (next.element_type === "group") {
    const g = next as GroupElement;
    next = {
      ...g,
      children_elements: g.children_elements.map((ch) =>
        remapElementTreeForPaste(ch as CourseElement, idMap),
      ),
    } as GroupElement;
  } else if (next.element_type === "html") {
    const h = next as HtmlElement;
    next = {
      ...h,
      children_elements: h.children_elements.map((ch) =>
        remapElementTreeForPaste(ch as CourseElement, idMap),
      ),
    } as HtmlElement;
  }

  if (next.event_bindings.length > 0) {
    next = {
      ...next,
      event_bindings: next.event_bindings.map((b) => ({
        ...b,
        binding_id: genId("bind"),
      })),
    } as CourseElement;
  }

  if (next.highlight_segments && next.highlight_segments.length > 0) {
    next = {
      ...next,
      highlight_segments: next.highlight_segments.map((h) => ({
        ...h,
        highlight_id: genId("hl"),
      })),
    } as CourseElement;
  }

  return next;
};

/** Remap element subtree IDs (and quiz bindings) for an independent canvas copy. */
const cloneSlideChildrenWithFreshIds = (
  sources: CourseElement[],
  quiz: QuizConfig | null | undefined,
): { children: CourseElement[]; newQuestions: QuizQuestion[] } => {
  const idMap = buildElementIdMapForPaste(sources);
  let remapped = sources.map((el) => remapElementTreeForPaste(el, idMap));

  const quizIdMap = new Map<string, string>();
  const newQuestions: QuizQuestion[] = [];
  for (const el of remapped) {
    if (el.element_type !== "quiz") continue;
    const oldQid = (el as QuizSlideElement).quiz_question_id;
    if (!oldQid || quizIdMap.has(oldQid)) continue;
    const sourceQuiz = quiz?.questions.find((q) => q.question_id === oldQid);
    if (!sourceQuiz) continue;
    const clonedQ = cloneQuizQuestionForCanvasPaste(sourceQuiz);
    quizIdMap.set(oldQid, clonedQ.question_id);
    newQuestions.push(clonedQ);
  }

  remapped = remapped.map((el) => {
    if (el.element_type !== "quiz") return el;
    const wrap = el as QuizSlideElement;
    const oldQid = wrap.quiz_question_id;
    if (!oldQid) return el;
    const nu = quizIdMap.get(oldQid);
    if (nu) return { ...wrap, quiz_question_id: nu };
    const stillExists = quiz?.questions.some((q) => q.question_id === oldQid);
    return stillExists ? el : { ...wrap, quiz_question_id: "" };
  });

  return { children: remapped, newQuestions };
};

const cloneSlideChildrenIndependent = (
  children: readonly CourseElement[],
  quiz: QuizConfig | null | undefined,
): { children: CourseElement[]; newQuestions: QuizQuestion[] } =>
  cloneSlideChildrenWithFreshIds(
    JSON.parse(JSON.stringify(children)) as CourseElement[],
    quiz,
  );

const mergeClonedQuizQuestionsIntoConfig = (
  prevQuiz: QuizConfig | null | undefined,
  newQuestions: QuizQuestion[],
  defaultGradeLevels: Parameters<typeof newQuizGradeLevel>[0][],
): QuizConfig | null | undefined => {
  if (newQuestions.length === 0) return prevQuiz;
  const baseQuiz: QuizConfig =
    prevQuiz ?? {
      enabled: true,
      total_score: 100,
      score_allocation: "even_split",
      time_limit_minutes: null,
      questions: [],
      grade_levels: defaultGradeLevels.map((g) => newQuizGradeLevel(g)),
      score_summary: null,
    };
  let nextQuiz: QuizConfig = {
    ...baseQuiz,
    enabled: true,
    questions: [...baseQuiz.questions, ...newQuestions],
  };
  return maybeApplyEvenQuizScores(nextQuiz) ?? nextQuiz;
};

const cloneSlideForDuplicate = (
  source: SlideElement,
  quiz: QuizConfig | null | undefined,
  slideCopyName: string,
): { slide: SlideElement; newQuestions: QuizQuestion[] } => {
  const slideDraft = JSON.parse(JSON.stringify(source)) as SlideElement;
  const { children, newQuestions } = cloneSlideChildrenIndependent(slideDraft.children_elements, quiz);
  return {
    slide: {
      ...slideDraft,
      element_id: genId("el_slide"),
      name: slideCopyName,
      children_elements: children,
      event_bindings: slideDraft.event_bindings.map((b) => ({
        ...b,
        binding_id: genId("bind"),
      })),
      highlight_segments: slideDraft.highlight_segments?.map((h) => ({
        ...h,
        highlight_id: genId("hl"),
      })),
      flow_pause_points: slideDraft.flow_pause_points?.map((p) => ({
        ...p,
        pause_id: genId("pause"),
      })),
    },
    newQuestions,
  };
};

const clamp = (value: number, min: number, max: number): number =>
  Math.min(Math.max(value, min), max);

/**
 * Slide-local playhead offset (same axis as `currentTime`) after inserted elements’
 * {@link BaseElement.enter_effect} has finished; at least `playheadOffset`.
 */
const computeEditorSeekOffsetPastNewElementEnterEffects = (
  slideBase: SlideElement,
  newElements: readonly CourseElement[],
  playheadOffset: number,
): number => {
  if (newElements.length === 0) return playheadOffset;
  const slideStart = slideBase.timeline.start_at;
  const slideEnd = slideBase.timeline.end_at;
  const span = Math.max(0, slideEnd - slideStart);
  const slideDraft: SlideElement = {
    ...slideBase,
    children_elements: [...slideBase.children_elements, ...newElements],
  };
  let maxOffset = playheadOffset;
  for (const el of newElements) {
    const completionAbs = getEnterEffectCompletionTime(el, slideDraft);
    maxOffset = Math.max(maxOffset, completionAbs - slideStart);
  }
  const upper = Math.max(0, span - 1);
  return clamp(maxOffset, 0, upper);
};

const normalizeTransitionsForSlideCount = (
  transitions: readonly Transition[],
  slideCount: number,
): Transition[] => {
  const needed = Math.max(0, slideCount - 1);
  const out = transitions.slice(0, needed);
  while (out.length < needed) out.push(Transitions.NONE);
  return out;
};

const reorderSlidesWithTransitions = (
  slides: readonly SlideElement[],
  transitions: readonly Transition[],
  from: number,
  to: number,
): { slides: SlideElement[]; transitions: Transition[] } => {
  const nextSlides = [...slides];
  const [moved] = nextSlides.splice(from, 1);
  if (!moved) {
    return {
      slides: [...slides],
      transitions: normalizeTransitionsForSlideCount(transitions, slides.length),
    };
  }
  nextSlides.splice(to, 0, moved);

  const normalizedTransitions = normalizeTransitionsForSlideCount(transitions, slides.length);
  const outgoingBySlideId = new Map<string, Transition>();
  slides.forEach((slide, index) => {
    outgoingBySlideId.set(slide.element_id, normalizedTransitions[index] ?? Transitions.NONE);
  });

  return {
    slides: nextSlides,
    transitions: nextSlides
      .slice(0, -1)
      .map((slide) => outgoingBySlideId.get(slide.element_id) ?? Transitions.NONE),
  };
};

/**
 * Resize element start (left handle). Editor timelines use slide-local 0..slideDuration.
 * Avoids `clamp(lo,hi)` when lo>hi (would force end before start).
 */
const clampResizeStartLocal = (
  endFixed: number,
  rawStart: number,
  slideDurationLocal: number,
  minSpan: number,
): number => {
  const maxEnd = Math.max(0, slideDurationLocal);
  const endClamped = clamp(endFixed, 0, maxEnd);
  const effectiveSpan = Math.min(minSpan, endClamped);
  const maxStart = Math.max(0, endClamped - effectiveSpan);
  return clamp(rawStart, 0, maxStart);
};

/**
 * Resize element end (right handle). See {@link clampResizeStartLocal}.
 */
const clampResizeEndLocal = (
  startFixed: number,
  rawEnd: number,
  slideDurationLocal: number,
  minSpan: number,
): number => {
  const maxEnd = Math.max(0, slideDurationLocal);
  const startClamped = clamp(startFixed, 0, maxEnd);
  const room = Math.max(0, maxEnd - startClamped);
  const effectiveMinEnd = startClamped + Math.min(minSpan, room);
  let e = rawEnd;
  if (effectiveMinEnd <= maxEnd) {
    e = clamp(e, effectiveMinEnd, maxEnd);
  } else {
    e = maxEnd;
  }
  return Math.max(e, startClamped);
};

/** When both edges move (grouped resize), normalize start/end together into slide bounds. */
const normalizeTimelinePairLocal = (
  rawStart: number,
  rawEnd: number,
  slideDurationLocal: number,
  minSpan: number,
): { start_at: number; end_at: number } => {
  const maxEnd = Math.max(0, slideDurationLocal);
  let s = clamp(rawStart, 0, maxEnd);
  let e = clamp(rawEnd, 0, maxEnd);
  if (e < s) {
    const t = s;
    s = e;
    e = t;
  }
  const room = maxEnd - s;
  const targetSpan = Math.min(minSpan, Math.max(0, room));
  if (e - s < targetSpan) {
    e = Math.min(maxEnd, s + targetSpan);
    if (e - s < targetSpan) {
      s = Math.max(0, e - targetSpan);
    }
  }
  if (e < s) e = s;
  return { start_at: s, end_at: e };
};

/**
 * Strip OSS / presign signature queries from the whole scene before persisting.
 *
 * The new quiz model has no canvas member elements, so processing like the old `sanitizeSlideStripQuestionMemberKeyframes`
 * ("thinning out the keyframes of question members") isn't needed. Here the asset URLs in the scene are only
 * normalized recursively with `stripCoursewareAssetSignatureFromUrl`.
 */
const stripUrlIfSignable = (value: string): string =>
  value ? stripCoursewareAssetSignatureFromUrl(value) || value : value;

const stripSignaturesFromElement = (el: CourseElement): CourseElement => {
  switch (el.element_type) {
    case "rich":
      // Strip the signature query from <img src> in the rich AST (held presigned in editor memory)
      // before persisting (storage rule: expiring URLs aren't saved).
      // On load the presign pass (tryPresignSceneAssetUrls) signs them again.
      return {
        ...el,
        react_layout: mapRichAstAssetUrl(el.react_layout, stripUrlIfSignable),
      };
    case "ppt": {
      // Strip the src signature query, and **never persist presign's temporary cache (signed_slide_urls)**
      // (storage rule: expiring URLs aren't saved).
      const ppt = el as PPTElement;
      const { signed_slide_urls: _omit, ...rest } = ppt;
      void _omit;
      return { ...rest, src: stripUrlIfSignable(rest.src) };
    }
    case "image":
    case "video":
    case "audio":
    case "svg":
      return { ...el, source: stripUrlIfSignable(el.source) };
    case "html":
      return {
        ...el,
        src: stripUrlIfSignable(el.src),
        children_elements: el.children_elements.map(stripSignaturesFromElement),
      };
    case "group":
      return {
        ...el,
        children_elements: el.children_elements.map(stripSignaturesFromElement),
      };
    case "narration": {
      const metadata = stripAITeacherAssetUrlsFromMetadata(
        (el.metadata ?? {}) as Record<string, unknown>,
        stripUrlIfSignable,
      );
      return {
        ...el,
        metadata: metadata as NarrationElement["metadata"],
        segments: el.segments.map((seg) => ({ ...seg, audio_url: stripUrlIfSignable(seg.audio_url) })),
      };
    }
    case "vtuber": {
      const metadata = stripAITeacherAssetUrlsFromMetadata(
        (el.metadata ?? {}) as Record<string, unknown>,
        stripUrlIfSignable,
      );
      return { ...el, metadata: metadata as VtuberElement["metadata"] };
    }
    default:
      return el;
  }
};

const stripSignaturesFromQuestion = (q: QuizQuestion): QuizQuestion => {
  const url = q.content_narration_audio_url
    ? stripUrlIfSignable(q.content_narration_audio_url)
    : q.content_narration_audio_url;
  if (url === q.content_narration_audio_url) return q;
  return { ...q, content_narration_audio_url: url };
};

const getNarrationTeacherId = (narration: NarrationElement): string | null => {
  if (typeof narration.ai_teacher_id === "string" && narration.ai_teacher_id.trim()) {
    return narration.ai_teacher_id;
  }
  const metadataTeacherId = narration.metadata?.ai_teacher_id;
  return typeof metadataTeacherId === "string" && metadataTeacherId.trim()
    ? metadataTeacherId
    : null;
};

const NARRATION_TEACHER_BINDING_UNLINKED_META = "ai_teacher_binding_unlinked";

const buildVtuberByIdForSlide = (
  slide: SlideElement,
  sceneVtubers: readonly VtuberElement[],
): Map<string, VtuberElement> => {
  const map = new Map<string, VtuberElement>();
  for (const vtuber of listVtubersOnSlide(slide)) {
    map.set(vtuber.element_id, vtuber);
  }
  for (const vtuber of sceneVtubers) {
    map.set(vtuber.element_id, vtuber);
  }
  return map;
};

/** Before persisting: fill in ai_teacher_id from metadata / the bound vtuber so serialize passes. */
const normalizeNarrationElementForPersistence = (
  el: NarrationElement,
  vtuberById: ReadonlyMap<string, VtuberElement>,
): NarrationElement => {
  let teacherId = getNarrationTeacherId(el) ?? "";
  if (!teacherId) {
    const vtuberId = el.vtuber_element_id?.trim();
    if (vtuberId) {
      const vtuber = vtuberById.get(vtuberId);
      if (vtuber) {
        teacherId = getAiTeacherIdFromVtuberMetadata(
          vtuber.metadata as Record<string, unknown>,
        );
      }
    }
  }
  if (!teacherId) {
    return normalizeElementForSerialization(el) as NarrationElement;
  }
  const withTeacher: NarrationElement = {
    ...el,
    ai_teacher_id: teacherId,
    metadata: {
      ...((el.metadata ?? {}) as Record<string, unknown>),
      ai_teacher_id: teacherId,
    } as NarrationElement["metadata"],
  };
  return normalizeElementForSerialization(withTeacher) as NarrationElement;
};

const normalizeSlideChildForPersistence = (
  el: CourseElement,
  vtuberById: ReadonlyMap<string, VtuberElement>,
): CourseElement => {
  const stripped = stripSignaturesFromElement(el);
  if (stripped.element_type === "narration") {
    return normalizeNarrationElementForPersistence(
      stripped as NarrationElement,
      vtuberById,
    );
  }
  if (stripped.element_type === "group" || stripped.element_type === "html") {
    const withChildren = stripped as GroupElement | HtmlElement;
    return {
      ...withChildren,
      children_elements: withChildren.children_elements.map((child) =>
        normalizeSlideChildForPersistence(child as CourseElement, vtuberById),
      ),
    } as CourseElement;
  }
  return stripped;
};

const buildUnsignedSceneForPersistence = (scene: Scene): Scene => ({
  ...scene,
  slide_elements: scene.slide_elements.map((slide) => {
    const vtuberById = buildVtuberByIdForSlide(slide, scene.vtuber_elements);
    const withStrippedUrls: SlideElement = {
      ...slide,
      background_image_url: slide.background_image_url
        ? stripUrlIfSignable(slide.background_image_url)
        : slide.background_image_url,
      background_html_src: slide.background_html_src
        ? stripUrlIfSignable(slide.background_html_src)
        : slide.background_html_src,
      children_elements: slide.children_elements.map((el) =>
        normalizeSlideChildForPersistence(el, vtuberById),
      ),
    };
    return normalizeElementForSerialization(withStrippedUrls) as SlideElement;
  }),
  audio_elements: scene.audio_elements.map((audio) => ({
    ...audio,
    source: stripUrlIfSignable(audio.source),
  })),
  vtuber_elements: scene.vtuber_elements.map(
    (vtuber) => stripSignaturesFromElement(vtuber) as VtuberElement,
  ),
  quiz: scene.quiz
    ? { ...scene.quiz, questions: scene.quiz.questions.map(stripSignaturesFromQuestion) }
    : scene.quiz,
});

const isEditableTarget = (target: EventTarget | null): boolean => {
  const el = target as HTMLElement | null;
  if (!el) return false;
  const tag = el.tagName;
  return tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || el.isContentEditable;
};

const isEditorSelectAllScopeTarget = (target: EventTarget | null): boolean => {
  const targetEl = target as HTMLElement | null;
  if (targetEl?.closest('[data-hotkey-scope="stage"], [data-hotkey-scope="timeline"]')) {
    return true;
  }
  const activeEl = document.activeElement as HTMLElement | null;
  return Boolean(activeEl?.closest('[data-hotkey-scope="stage"], [data-hotkey-scope="timeline"]'));
};

/** AI assistant sidebar: bubbles are read-only DOM, so the browser must handle text operations such as Ctrl/Cmd+C */
const isCoursewareAgentChatHotkeyScopeTarget = (target: EventTarget | null): boolean => {
  const scope = '[data-hotkey-scope="ai-chat"], .courseware-editor-ai-panel';
  const targetEl = target as HTMLElement | null;
  if (targetEl?.closest(scope)) return true;
  const activeEl = document.activeElement as HTMLElement | null;
  return Boolean(activeEl?.closest(scope));
};

const hasNativeTextSelection = (): boolean => {
  if (typeof window === "undefined") return false;
  const sel = window.getSelection();
  return Boolean(sel && !sel.isCollapsed && sel.toString().length > 0);
};

const makePreviewStorageId = (): string => genId("preview");

const getCoursewareIdFromUrl = (): string | null => {
  if (typeof window === "undefined") return null;
  const coursewareId = new URLSearchParams(window.location.search).get("courseware_id")?.trim();
  return coursewareId || null;
};

/** Lesson / course context carried by the URL when entering the editor from course management (for mounting the chapter knowledge base). */
const getEditorCourseSectionContextFromUrl = (): {
  sectionId: string | null;
  courseId: string | null;
} => {
  if (typeof window === "undefined") {
    return { sectionId: null, courseId: null };
  }
  const params = new URLSearchParams(window.location.search);
  return {
    sectionId: params.get("section_id")?.trim() || null,
    courseId: params.get("course_id")?.trim() || null,
  };
};

/** Instance id of a new courseware (a UUID, consistent with the agent's `coursewareId` and the asset API; works in HTTP environments too). */
const makeNewCoursewareId = (): string => generateUuidV4();

const assignCoursewareIdToUrl = (coursewareId: string): void => {
  if (typeof window === "undefined") return;
  const url = new URL(window.location.href);
  url.searchParams.set("courseware_id", coursewareId);
  window.history.replaceState(window.history.state, "", url.toString());
};

/** Ensure URL has courseware_id before auth redirect builds login callback. */
const ensureCoursewareIdInUrl = (): string => {
  const fromUrl = getCoursewareIdFromUrl();
  if (fromUrl) return fromUrl;
  const newId = makeNewCoursewareId();
  assignCoursewareIdToUrl(newId);
  return newId;
};

/** Supports raw Scene JSON or `{ scene: Scene }` (e.g. preview/local storage bundle). */
const extractScenePayloadFromEditorJson = (parsed: unknown): unknown => {
  if (
    parsed &&
    typeof parsed === "object" &&
    "scene" in parsed &&
    (parsed as { scene?: unknown }).scene !== undefined
  ) {
    return (parsed as { scene: unknown }).scene;
  }
  return parsed;
};

type EditorSceneStorageBundle = {
  scene: Scene;
  /** Time of the last localStorage write; null for the old format without this field */
  savedAt: Date | null;
  loadIssues: CoursewareLoadIssue[];
};

const deserializeEditorSceneContent = (
  content: unknown,
  language: SupportedLanguage = "zh",
): { scene: Scene; loadIssues: CoursewareLoadIssue[]; isInvalidFallback: boolean } => {
  const result = loadSceneTolerantly(content, language);
  return {
    scene: expandSceneForNarration(dedupeSceneElementIds(result.scene)),
    loadIssues: collectCoursewareLoadIssues(result),
    // The empty scene sentinel produced by the lenient parsing fallback: callers must refuse it, so it isn't stored as valid content by mistake
    isInvalidFallback: isInvalidSceneFallback(result),
  };
};

const readEditorSceneBundleFromStorage = async (
  coursewareId: string,
  language: SupportedLanguage = "zh",
): Promise<EditorSceneStorageBundle | null> => {
  try {
    const parsed = await readEditorSceneRecord(makeEditorStorageKey(coursewareId));
    if (parsed === null) return null;
    if (
      parsed &&
      typeof parsed === "object" &&
      "savedAt" in parsed &&
      "scene" in parsed &&
      (parsed as { scene?: unknown }).scene !== undefined
    ) {
      const bundle = parsed as { scene: unknown; savedAt?: unknown };
      const savedAt =
        typeof bundle.savedAt === "string" && bundle.savedAt.trim()
          ? new Date(bundle.savedAt)
          : null;
      const loaded = deserializeEditorSceneContent(bundle.scene, language);
      if (loaded.isInvalidFallback) return null;
      return {
        scene: loaded.scene,
        savedAt: savedAt && !Number.isNaN(savedAt.getTime()) ? savedAt : null,
        loadIssues: loaded.loadIssues,
      };
    }
    const scenePayload = extractScenePayloadFromEditorJson(parsed);
    const loaded = deserializeEditorSceneContent(scenePayload, language);
    if (loaded.isInvalidFallback) return null;
    return {
      scene: loaded.scene,
      savedAt: null,
      loadIssues: loaded.loadIssues,
    };
  } catch (error) {
    console.warn("Failed to load saved courseware editor scene.", error);
    return null;
  }
};

const writeEditorSceneToStorage = async (
  coursewareId: string,
  scene: Scene,
  savedAt: Date = new Date(),
): Promise<void> => {
  await writeEditorSceneRecord(makeEditorStorageKey(coursewareId), {
    savedAt: savedAt.toISOString(),
    scene: serializeScene(scene),
  });
};

type CoursewareLoadCandidate = {
  scene: Scene;
  savedAt: Date | null;
  updatedAt: Date | null;
  loadIssues: CoursewareLoadIssue[];
};

type CoursewareInitialPick = {
  scene: Scene;
  loadedFromRemote: boolean;
  loadedFromLocal: boolean;
  displaySavedAt: Date | null;
  remoteUpdatedAt: Date | null;
  loadIssues: CoursewareLoadIssue[];
};

/**
 * When both remote and local exist: the remote version wins.
 * The local draft is a fallback only when the remote is unavailable or unsynced; after a successful remote save the local copy is cleared.
 */
const pickCoursewareInitialSource = (
  remote: CoursewareLoadCandidate | null,
  local: CoursewareLoadCandidate | null,
): CoursewareInitialPick | null => {
  if (!remote && !local) return null;

  if (remote) {
    return {
      scene: remote.scene,
      loadedFromRemote: true,
      loadedFromLocal: false,
      displaySavedAt: remote.updatedAt ?? remote.savedAt,
      remoteUpdatedAt: remote.updatedAt,
      loadIssues: remote.loadIssues,
    };
  }

  return {
    scene: local!.scene,
    loadedFromRemote: false,
    loadedFromLocal: true,
    displaySavedAt: local!.savedAt ?? new Date(),
    remoteUpdatedAt: null,
    loadIssues: local!.loadIssues,
  };
};

const hashPreviewSceneText = (value: string): string => {
  let hash = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
};

const formatTimeMs = (ms: number): string => {
  const clamped = Math.max(0, ms);
  const totalSeconds = Math.floor(clamped / 1000);
  const m = Math.floor(totalSeconds / 60);
  const s = totalSeconds % 60;
  const hundredths = Math.floor((clamped % 1000) / 10);
  return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}.${hundredths.toString().padStart(2, "0")}`;
};

const KEYFRAME_TIME_COLLISION_THRESHOLD_MS = 8;

const isSameKeyframeTime = (a: number, b: number): boolean =>
  Math.abs(a - b) <= KEYFRAME_TIME_COLLISION_THRESHOLD_MS;

const hasKeyframeAt = (
  keyframes: Keyframe[],
  at: number,
  excludeIndex?: number,
): boolean =>
  keyframes.some(
    (keyframe, index) => index !== excludeIndex && isSameKeyframeTime(keyframe.at, at),
  );

const normalizeKeyframesByTime = (keyframes: Keyframe[]): Keyframe[] => {
  const sorted = [...keyframes].sort((a, b) => a.at - b.at);
  return sorted.filter(
    (keyframe, index) =>
      index === 0 ||
      !sorted.slice(0, index).some((prev) => isSameKeyframeTime(prev.at, keyframe.at)),
  );
};

interface HighlightRegion {
  highlight: ElementHighlight;
  x: number;
  y: number;
  width: number;
  height: number;
  zIndex: number;
  opacityMultiplier: number;
}

const createElementHighlightAt = (
  element: CourseElement,
  time: number,
  duration = DEFAULT_HIGHLIGHT_DURATION_MS,
): ElementHighlight => {
  const latestStart = Math.max(
    element.timeline.start_at,
    element.timeline.end_at - MIN_HIGHLIGHT_DURATION_MS,
  );
  const startAt = clamp(Math.floor(time), element.timeline.start_at, latestStart);
  const endAt = clamp(startAt + duration, startAt + MIN_HIGHLIGHT_DURATION_MS, element.timeline.end_at);
  return {
    highlight_id: genId("hl"),
    start_at: startAt,
    end_at: Math.max(startAt, endAt),
    padding_px: 0,
    border_radius_px: 28,
    overlay_color: "#000000",
    overlay_opacity: 0.62,
  };
};

const shiftElementTimedRanges = (element: CourseElement, deltaMs: number): CourseElement => {
  if (Math.abs(deltaMs) < 0.001) return element;
  return {
    ...element,
    keyframes: element.keyframes.map((keyframe) => ({
      ...keyframe,
      at: keyframe.at + deltaMs,
    })),
    animations: element.animations.map((animation) => ({
      ...animation,
      start_at: animation.start_at + deltaMs,
      end_at: animation.end_at + deltaMs,
    })),
    highlight_segments: element.highlight_segments?.map((highlight) => ({
      ...highlight,
      start_at: highlight.start_at + deltaMs,
      end_at: highlight.end_at + deltaMs,
    })),
  };
};

/**
 * Constrain an `element_type:"quiz"` box to the slide timeline.
 * When the question has TTS narration audio, span is locked to that duration
 * (move only). Otherwise preserve the editor's start/end (move + resize) and
 * snap so multiple quiz blocks on one slide do not overlap.
 */
const normalizeQuizElementTimeline = (
  element: CourseElement,
  slide: SlideElement,
  quiz?: QuizConfig | null,
): CourseElement => {
  if (element.element_type !== "quiz") return element;
  const slideStart = slide.timeline.start_at;
  const slideEnd = slide.timeline.end_at;
  const slideDur = Math.max(1, slideEnd - slideStart);
  const wrap = element as QuizSlideElement;
  const fixedSpan = resolveQuizQuestionFixedNarrationSpanMs(slideDur, {
    quiz,
    questionId: wrap.quiz_question_id,
  });
  const span =
    fixedSpan ??
    Math.max(
      MIN_ELEMENT_TIMELINE_SPAN_MS,
      Math.min(slideDur, element.timeline.end_at - element.timeline.start_at),
    );
  const otherQuestions = slide.children_elements
    .filter(
      (el) => el.element_type === "quiz" && el.element_id !== element.element_id,
    )
    .map((el) => el.timeline);
  const snapped = snapQuizQuestionTimelineMove(
    element.timeline.start_at,
    span,
    slideStart,
    slideEnd,
    otherQuestions,
  );
  return clampElementTimedRangesToTimeline({
    ...element,
    timeline: snapped,
  });
};

const finalizeEditorElement = (
  element: CourseElement,
  slide: SlideElement,
  quiz?: QuizConfig | null,
): CourseElement => {
  let el = element;
  // The serialization schema requires timeline.start_at >= 0; editor operations sometimes shift child elements as a whole into negative time.
  if (el.timeline.start_at < 0) {
    const shiftUp = -el.timeline.start_at;
    el = shiftElementTimedRanges(
      {
        ...el,
        timeline: {
          start_at: 0,
          end_at: el.timeline.end_at + shiftUp,
        },
      },
      shiftUp,
    );
  }
  el = clampElementTimedRangesToTimeline(el);
  el = normalizeQuizElementTimeline(el, slide, quiz);
  if (el.element_type === "quiz") {
    el = { ...el, keyframes: [] };
  }
  if (el.element_type === "text") {
    el = { ...el, font_family: coerceTextFontFamily(el.font_family) };
  }
  return el;
};

const getActiveHighlightRegions = (slide: SlideElement, time: number): HighlightRegion[] =>
  slide.children_elements.flatMap((element) => {
    if (!isElementVisibleAtTimeInSlide(element, time, slide)) return [];
    const transform = interpolateElementTransformInSlide(element, time, slide);
    return getElementHighlightSegments(element)
      .filter(
        (highlight) =>
          isElementHighlightActiveAtTime(highlight, time) ||
          (time > highlight.end_at && time <= highlight.end_at + HIGHLIGHT_TRANSITION_MS),
      )
      .map((highlight) => {
        const entering = time < highlight.start_at + HIGHLIGHT_TRANSITION_MS;
        const exiting = time > highlight.end_at;
        const enterProgress = clamp(
          (time - highlight.start_at) / HIGHLIGHT_TRANSITION_MS,
          0,
          1,
        );
        const exitProgress = clamp(
          (time - highlight.end_at) / HIGHLIGHT_TRANSITION_MS,
          0,
          1,
        );
        const scale = entering && !exiting ? 1.5 - 0.5 * enterProgress : 1;
        const opacityMultiplier = exiting
          ? 1 - exitProgress
          : entering
            ? enterProgress
            : 1;
        const padding = highlight.padding_px;
        const baseWidth = transform.size.width + padding * 2;
        const baseHeight = transform.size.height + padding * 2;
        const cx = transform.position.x + transform.size.width / 2;
        const cy = transform.position.y + transform.size.height / 2;
        const x = clamp(cx - (baseWidth * scale) / 2, 0, SLIDE_LOGICAL_WIDTH);
        const y = clamp(cy - (baseHeight * scale) / 2, 0, SLIDE_LOGICAL_HEIGHT);
        const right = clamp(cx + (baseWidth * scale) / 2, 0, SLIDE_LOGICAL_WIDTH);
        const bottom = clamp(cy + (baseHeight * scale) / 2, 0, SLIDE_LOGICAL_HEIGHT);
        return {
          highlight,
          x,
          y,
          width: Math.max(0, right - x),
          height: Math.max(0, bottom - y),
          zIndex: element.style.z_index,
          opacityMultiplier,
        };
      });
  });

const roundedRectPath = (
  x: number,
  y: number,
  width: number,
  height: number,
  radius: number,
): string => {
  const r = clamp(radius, 0, Math.min(width, height) / 2);
  const right = x + width;
  const bottom = y + height;
  if (r <= 0) return `M${x} ${y}H${right}V${bottom}H${x}Z`;
  return [
    `M${x + r} ${y}`,
    `H${right - r}`,
    `A${r} ${r} 0 0 1 ${right} ${y + r}`,
    `V${bottom - r}`,
    `A${r} ${r} 0 0 1 ${right - r} ${bottom}`,
    `H${x + r}`,
    `A${r} ${r} 0 0 1 ${x} ${bottom - r}`,
    `V${y + r}`,
    `A${r} ${r} 0 0 1 ${x + r} ${y}`,
    "Z",
  ].join("");
};

type DraggedResource =
  | { kind: "template-text"; variant: "heading" | "body" }
  | { kind: "template-shape"; color: string; name: string }
  | { kind: "template-button" }
  | { kind: "template-image"; url: string; name: string }
  | { kind: "template-html" }
  | { kind: "asset"; asset: CoursewareAssetItem }
  | { kind: "ai-teacher"; teacher: AITeacherInfo };

// ---------- initial scene ----------

const SCENE_LANGUAGE_METADATA_KEY = "language";

const buildInitialScene = (meta: {
  defaultSceneName: string;
  defaultSlideName: string;
}, language: SupportedLanguage): Scene => {
  const slide1Id = genId("el_slide");

  const slide1: SlideElement = {
    element_type: "slide",
    element_id: slide1Id,
    name: meta.defaultSlideName,
    fps: 30,
    position: { x: 0, y: 0 },
    size: { width: SLIDE_LOGICAL_WIDTH, height: SLIDE_LOGICAL_HEIGHT },
    timeline: { start_at: 0, end_at: DEFAULT_SLIDE_DURATION_MS },
    style: { opacity: 1, rotation_deg: 0, z_index: 0 },
    enter_effect: "none",
    exit_effect: "none",
    animations: [],
    keyframes: [],
    event_bindings: [],
    action_mappings: {},
    event_scripts: {},
    preset_script: "",
    metadata: {},
    background_color: "#F0F0ED",
    children_elements: [],
  };

  return deserializeScene({
    scene_id: genId("sc"),
    name: meta.defaultSceneName,
    controller: {
      play: true,
      next: true,
      back: true,
      seekBar: true,
      time: true,
      slideNumber: true,
      volume: true,
      fullScreen: true,
      brand: true,
      playbackRate: true,
    },
    transitions: [],
    preset_script: "",
    metadata: {
      [SCENE_LANGUAGE_METADATA_KEY]: language,
    },
    slide_elements: [slide1],
    vtuber_elements: [],
  });
};

function readSceneGenerationLanguage(
  scene: Pick<Scene, "metadata">,
  fallback: SupportedLanguage,
): SupportedLanguage {
  const raw = scene.metadata?.[SCENE_LANGUAGE_METADATA_KEY];
  return raw === "zh" || raw === "en" || raw === "ja" ? raw : fallback;
}

