const isTransparentShapeColor = (value: string | undefined | null): boolean => {
  const trimmed = (value ?? "").trim().toLowerCase();
  return !trimmed || trimmed === "transparent" || trimmed === "none";
};

const DEFAULT_VISIBLE_SHAPE_STROKE_COLOR = "#1a202c";

/** When the stroke is still transparent, widen the line: reuse the fill color, or a default dark stroke when the fill is transparent too. */
const resolveAutoShapeStrokeColor = (fillColor: string): string =>
  isTransparentShapeColor(fillColor) ? DEFAULT_VISIBLE_SHAPE_STROKE_COLOR : fillColor;

const applyRectangleOrEllipseStrokeWidth = (
  el: RectangleElement | EllipseElement,
  stroke_width: number,
): RectangleElement | EllipseElement => {
  const nextWidth = Math.max(0, stroke_width);
  if (nextWidth <= 0 || !isTransparentShapeColor(el.stroke_color)) {
    return { ...el, stroke_width: nextWidth };
  }
  return {
    ...el,
    stroke_width: nextWidth,
    stroke_color: resolveAutoShapeStrokeColor(el.color),
  };
};

const applyRectangleOrEllipseStrokeColor = (
  el: RectangleElement | EllipseElement,
  stroke_color: string,
): RectangleElement | EllipseElement => {
  const next = { ...el, stroke_color };
  if (!isTransparentShapeColor(stroke_color) && el.stroke_width <= 0) {
    return { ...next, stroke_width: 2 };
  }
  return next;
};

