const buildBlankSlide = (index: number, template?: SlideElement): SlideElement => {
  const defaults: SlideElement = {
    element_type: "slide",
    element_id: genId("el_slide"),
    name: getEditorMeta().slideName(index),
    fps: 30,
    position: { x: 0, y: 0 },
    size: { width: SLIDE_LOGICAL_WIDTH, height: SLIDE_LOGICAL_HEIGHT },
    timeline: { start_at: 0, end_at: DEFAULT_SLIDE_DURATION_MS },
    style: { opacity: 1, rotation_deg: 0, z_index: 0 },
    enter_effect: "none",
    exit_effect: "none",
    animations: [],
    keyframes: [],
    event_bindings: [],
    action_mappings: {},
    event_scripts: {},
    preset_script: "",
    metadata: {},
    background_color: "#F0F0ED",
    children_elements: [],
  };

  if (!template) return defaults;

  const durationMs = Math.max(
    0,
    template.timeline.end_at - template.timeline.start_at,
  );
  const endAt = durationMs > 0 ? durationMs : DEFAULT_SLIDE_DURATION_MS;

  return {
    ...template,
    element_id: genId("el_slide"),
    name: getEditorMeta().slideName(index),
    timeline: { start_at: 0, end_at: endAt },
    metadata: { ...template.metadata },
    children_elements: [],
    animations: [],
    keyframes: [],
    highlight_segments: undefined,
    flow_pause_points: undefined,
    event_bindings: [],
    action_mappings: {},
    event_scripts: {},
    preset_script: "",
  };
};

// ---------- helpers ----------

const normalizeZIndex = (list: CourseElement[]): CourseElement[] => {
  // Narration on top, then vtuber, then all other elements.
  const regular = list.filter((el) => !isPinnedLayerElement(el));
  const vtuber = list.filter((el) => el.element_type === "vtuber");
  const narration = list.filter((el) => el.element_type === "narration");
  return [...regular, ...vtuber, ...narration].map((el, i) => ({
    ...el,
    style: { ...el.style, z_index: i },
  }));
};

const computeNarrationTotalMs = (n: NarrationElement): number =>
  n.segments.reduce((acc, seg) => acc + seg.gap_ms + seg.duration_ms, 0);

// Fixed visual scale for timeline: each second takes the same width,
// and long timelines overflow horizontally.
const TIMELINE_PX_PER_SECOND = 100;
/** Blank space to the right of the scrollable timeline content, so the slide end tick doesn't touch the viewport's right edge. */
const TIMELINE_TAIL_PADDING_PX = 48;
/** Minimum duration when resizing a slide with the timeline's end drag handle (matching min=1s of the duration input). */
const SLIDE_DURATION_DRAG_MIN_MS = 1_000;
/** Drag feel: larger than {@link TIMELINE_PX_PER_SECOND} is less sensitive (more horizontal travel needed to change 1 second). */
const SLIDE_DURATION_DRAG_PX_PER_SECOND = 175;
/** Round to this step (ms) before previewing/committing a drag, so pointer jitter doesn't make the duration jump. */
const SLIDE_DURATION_DRAG_STEP_MS = 100;
/** Transition duration of the timeline width shrinking/expanding after releasing the handle. */
const SLIDE_DURATION_RELEASE_TRANSITION_MS = 280;
const SLIDE_DURATION_RESIZE_SNAP_EXCLUDE_ID = "__slide_duration_resize__";

/** ±seconds text shown in the floating bubble while dragging the slide duration (e.g. +3.2s, -2s). */
function formatSlideDurationDragDeltaLabel(deltaMs: number): string {
  const sign = deltaMs >= 0 ? "+" : "-";
  const absSec = Math.round((Math.abs(deltaMs) / 1000) * 10) / 10;
  const text = Number.isInteger(absSec) ? String(absSec) : absSec.toFixed(1);
  return `${sign}${text}s`;
}

// Ensures the slide duration is at least the longest narration on it.
// Narration element timelines are normalized to their real content length
// (sum of segment gap/duration), while slide duration may grow to fit.
// When growing the slide, only the *display window* of elements that
// previously reached the slide end is extended to the new end — keyframes
// stay anchored at their original absolute times, and elements that ended
// earlier keep their original end times.
const TIMELINE_END_EPSILON_MS = 1;
/** Minimum element display window when editing via the timeline / properties (ms). */
const MIN_ELEMENT_TIMELINE_SPAN_MS = 100;
/**
 * When the remaining slide time after the playhead is shorter than this, the new element's entrance moves earlier
 * to secure enough display span (preventing enter/exit from shrinking near the end).
 */
const MIN_REMAINING_FOR_PLAYHEAD_ANCHORED_ELEMENT_MS = 500;

/**
 * Decide a new child element's timeline using the playhead position as the entrance start.
 * When there isn't enough time left at the end, the entrance moves earlier so {@link preferredSpanMs} fits.
 */
/** HTML / quiz canvas elements fill the slide timeline by default when inserted. */
const resolveFullSlideChildElementTimeline = (
  slideStart: number,
  slideEnd: number,
): { start_at: number; end_at: number } => ({
  start_at: slideStart,
  end_at: slideEnd,
});

const resolveNewChildElementTimeline = (
  slideStart: number,
  slideEnd: number,
  localPlayhead: number,
  preferredSpanMs: number = DEFAULT_SLIDE_DURATION_MS,
): { start_at: number; end_at: number } => {
  const slideDur = Math.max(1, slideEnd - slideStart);
  const preferredSpan = Math.min(
    Math.max(MIN_ELEMENT_TIMELINE_SPAN_MS, preferredSpanMs),
    slideDur,
  );
  const idealStart = clamp(slideStart + localPlayhead, slideStart, slideEnd);
  const remaining = slideEnd - idealStart;

  if (remaining >= preferredSpan) {
    return { start_at: idealStart, end_at: idealStart + preferredSpan };
  }
  if (remaining >= MIN_REMAINING_FOR_PLAYHEAD_ANCHORED_ELEMENT_MS) {
    return {
      start_at: idealStart,
      end_at: Math.max(idealStart + MIN_ELEMENT_TIMELINE_SPAN_MS, slideEnd),
    };
  }
  const startAt = Math.max(slideStart, slideEnd - preferredSpan);
  return {
    start_at: startAt,
    end_at: Math.min(startAt + preferredSpan, slideEnd),
  };
};

/** Editor: timeline bars of several quiz questions on the same canvas may not overlap, snapping to the nearest feasible range while dragging. */
const QUIZ_TIMELINE_GAP_EPSILON_MS = 1;

/** When the quiz question already has narration audio, the timeline span is locked to the audio duration (not beyond the slide duration); otherwise returns null (the editor may adjust start/end freely). */
const resolveQuizQuestionFixedNarrationSpanMs = (
  slideDur: number,
  source:
    | { quiz: QuizConfig | null | undefined; questionId: string }
    | { question: Pick<QuizQuestion, "content_narration_audio_url" | "content_narration_duration_ms"> },
): number | null => {
  const cap = Math.max(1, slideDur);
  let q: Pick<QuizQuestion, "content_narration_audio_url" | "content_narration_duration_ms"> | undefined;
  if ("question" in source) {
    q = source.question;
  } else if (source.questionId.trim() && source.quiz) {
    q = source.quiz.questions.find((x) => x.question_id === source.questionId);
  }
  if (
    q &&
    q.content_narration_audio_url.trim().length > 0 &&
    (q.content_narration_duration_ms ?? 0) > 0
  ) {
    return Math.min(Math.max(1, q.content_narration_duration_ms), cap);
  }
  return null;
};

const slideHasQuizQuestionBlock = (slide: SlideElement): boolean =>
  slide.children_elements.some((el) => el.element_type === "quiz");

