function CanvasToolbarMenu({
  anchor,
  children,
  className = "",
  themeMode = "dark",
}: {
  anchor: ToolbarMenuAnchor | null;
  children: ReactNode;
  className?: string;
  themeMode?: EditorThemeMode;
}) {
  if (!anchor || typeof document === "undefined") return null;
  const isDark = themeMode === "dark";
  return createPortal(
    // Portaled to body it leaves the editor theme root, so the theme scope must be carried explicitly.
    <div
      data-canvas-toolbar-menu
      data-courseware-editor-theme={themeMode}
      className={`fixed z-100 overflow-hidden rounded-lg border shadow-[0_10px_18px_rgba(15,23,42,0.12)] ${
        isDark
          ? "dark border-slate-700 bg-slate-900 text-slate-100"
          : "border-slate-200 bg-white text-slate-900"
      } ${className}`}
      style={{ top: anchor.top, left: anchor.left, width: anchor.width }}
    >
      {children}
    </div>,
    document.body,
  );
}

