function ToolbarAssetPickerDialog({
  panel,
  coursewareId,
  themeMode,
  onPick,
  onClose,
  onDragResourceStart,
  onDragResourceEnd,
  uploadedAssetsRegistry,
  pickMode = "add",
}: {
  panel: ToolbarAssetPanel;
  coursewareId: string;
  themeMode: EditorThemeMode;
  onPick: (asset: CoursewareAssetItem) => void;
  onClose: () => void;
  onDragResourceStart: (resource: DraggedResource) => void;
  onDragResourceEnd: () => void;
  uploadedAssetsRegistry?: UploadedAssetsRegistry;
  pickMode?: "add" | "replace";
}) {
  const { t, language } = useI18nNew();
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [assets, setAssets] = useState<CoursewareAssetItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deletingAssetId, setDeletingAssetId] = useState<string | null>(null);
  const [downloadingAssetId, setDownloadingAssetId] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isFileDragOver, setIsFileDragOver] = useState(false);
  const [hiddenForDrag, setHiddenForDrag] = useState(false);
  const hideForDragRafRef = useRef<number | null>(null);

  const pickButtonLabel =
    pickMode === "replace"
      ? panel === "image"
        ? t("coursewareEditor.resources.replaceWithThisImage")
        : panel === "video"
          ? t("coursewareEditor.resources.replaceWithThisVideo")
          : panel === "document"
            ? t("coursewareEditor.resources.replaceWithThisDocument")
            : t("coursewareEditor.resources.addToCanvas")
      : t("coursewareEditor.resources.addToCanvas");

  const loadAssets = useCallback(async (): Promise<void> => {
    setIsLoading(true);
    setError(null);
    try {
      const responses = await Promise.all(
        TOOLBAR_ASSET_KIND_FILTERS[panel].map((kind) =>
          coursewareAssetsApi.listAssets({
            courseware_id: coursewareId,
            page_number: 1,
            page_size: 40,
            order: "desc",
            asset_kind: kind,
          }),
        ),
      );
      const rawAssets = responses.flatMap((response) => response.data).filter((asset) => {
        if (isQuizAnswerRecordingAsset(asset)) return false;
        return TOOLBAR_ASSET_KIND_FILTERS[panel].includes(
          mapExtensionToAssetKindFilter(asset.extension, asset.mimeType),
        );
      });
      const signedByOriginal = await coursewareAssetsApi.batchPresignUrls(
        coursewareId,
        rawAssets.map((asset) => asset.url),
      );
      setAssets(rawAssets.map((asset) => ({ ...asset, url: signedByOriginal[asset.url] ?? asset.url })));
    } catch (err) {
      setError(err instanceof Error ? err.message : t("coursewareEditor.resources.loadFailed"));
    } finally {
      setIsLoading(false);
    }
  }, [coursewareId, panel, t]);

  useEffect(() => {
    void loadAssets();
  }, [loadAssets]);

  useEffect(
    () => () => {
      if (hideForDragRafRef.current !== null) {
        window.cancelAnimationFrame(hideForDragRafRef.current);
      }
    },
    [],
  );

  const uploadFiles = async (files: File[]): Promise<void> => {
    if (files.length === 0 || isUploading) return;
    const validFiles = files.filter((file) => isToolbarAssetFile(file, panel));
    if (validFiles.length === 0) {
      setError(t("coursewareEditor.toast.unsupportedFiles", { names: files.map((file) => file.name).join(t("coursewareEditor.common.listSeparator")) }));
      return;
    }
    setIsUploading(true);
    setError(null);
    try {
      const uploaded = await uploadCoursewareAssetFiles(coursewareId, validFiles, undefined, language);
      uploadedAssetsRegistry?.notify(uploaded);
      await loadAssets();
      toast.success(
        uploaded.length === 1
          ? t("coursewareEditor.toast.uploadSuccessSingle", { name: uploaded[0].name })
          : t("coursewareEditor.toast.uploadSuccessMultiple", { count: uploaded.length }),
      );
    } catch (err) {
      if (err instanceof AggregateUploadError && err.uploaded.length > 0) {
        uploadedAssetsRegistry?.notify(err.uploaded);
        await loadAssets();
        setError(t("coursewareEditor.toast.uploadPartialFailed", {
          successCount: err.uploaded.length,
          failed: err.failedNames.join(t("coursewareEditor.common.listSeparator")),
        }));
      } else {
        setError(err instanceof Error ? err.message : t("coursewareEditor.toast.uploadFailed"));
      }
    } finally {
      setIsUploading(false);
    }
  };

  const beginAssetDrag = useCallback(
    (event: ReactDragEvent, asset: CoursewareAssetItem): void => {
      event.dataTransfer.effectAllowed = "copy";
      event.dataTransfer.setData("text/plain", "courseware-resource");
      applyCoursewareAssetDragImage(event, asset);
      onDragResourceStart({ kind: "asset", asset });
      // Hiding within the same frame would interrupt HTML5 dragging, so the dialog is hidden after the drag is established
      hideForDragRafRef.current = window.requestAnimationFrame(() => {
        hideForDragRafRef.current = window.requestAnimationFrame(() => {
          setHiddenForDrag(true);
          hideForDragRafRef.current = null;
        });
      });
    },
    [onDragResourceStart],
  );

  const handleAssetDragEnd = useCallback(
    (event: ReactDragEvent): void => {
      if (hideForDragRafRef.current !== null) {
        window.cancelAnimationFrame(hideForDragRafRef.current);
        hideForDragRafRef.current = null;
      }
      onDragResourceEnd();
      setHiddenForDrag(false);
      const dropEffect = event.dataTransfer.dropEffect;
      if (dropEffect === "copy" || dropEffect === "move") {
        onClose();
      }
    },
    [onClose, onDragResourceEnd],
  );

  const handleFileDragOver = (event: ReactDragEvent<HTMLDivElement>): void => {
    if (!event.dataTransfer.types.includes("Files")) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "copy";
    setIsFileDragOver(true);
  };

  const handleContentDragOver = (event: ReactDragEvent<HTMLDivElement>): void => {
    if (event.dataTransfer.types.includes("Files")) {
      handleFileDragOver(event);
      return;
    }
    if (event.dataTransfer.types.includes("text/plain")) {
      event.preventDefault();
      event.dataTransfer.dropEffect = "copy";
    }
  };

  const handleFileDragLeave = (event: ReactDragEvent<HTMLDivElement>): void => {
    if (!event.dataTransfer.types.includes("Files")) return;
    event.preventDefault();
    if (event.currentTarget.contains(event.relatedTarget as Node | null)) return;
    setIsFileDragOver(false);
  };

  const handleFileDrop = (event: ReactDragEvent<HTMLDivElement>): void => {
    if (!event.dataTransfer.types.includes("Files")) return;
    event.preventDefault();
    setIsFileDragOver(false);
    const files = Array.from(event.dataTransfer.files);
    void uploadFiles(files);
  };

  const handleDeleteAsset = async (asset: CoursewareAssetItem): Promise<void> => {
    if (deletingAssetId) return;
    if (!window.confirm(t("coursewareEditor.confirm.deleteAsset", { name: asset.name }))) return;
    setDeletingAssetId(asset.id);
    setError(null);
    try {
      await coursewareAssetsApi.deleteAsset(coursewareId, asset.id);
      await loadAssets();
    } catch (err) {
      setError(err instanceof Error ? err.message : t("coursewareEditor.resources.deleteFailed"));
    } finally {
      setDeletingAssetId(null);
    }
  };

  const handleDownloadAsset = async (asset: CoursewareAssetItem): Promise<void> => {
    if (downloadingAssetId) return;
    setDownloadingAssetId(asset.id);
    try {
      const res = await fetch(asset.url);
      if (!res.ok) {
        throw new Error(
          t("coursewareEditor.errors.downloadHttpFailed", {
            status: res.status,
            statusText: res.statusText,
          }),
        );
      }
      const blob = await res.blob();
      const objectUrl = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = objectUrl;
      anchor.download = asset.name;
      anchor.rel = "noopener";
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      URL.revokeObjectURL(objectUrl);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : t("coursewareEditor.toast.downloadFailed"));
    } finally {
      setDownloadingAssetId(null);
    }
  };

  const title =
    panel === "image"
      ? t("coursewareEditor.common.image")
      : panel === "audio"
        ? t("coursewareEditor.common.audio")
        : panel === "video"
          ? t("coursewareEditor.common.video")
          : t("coursewareEditor.canvasToolbar.document");

  return createPortal(
    <div
      data-toolbar-asset-picker
      data-courseware-editor-theme={themeMode}
      className={`fixed inset-0 z-110 flex items-center justify-center bg-slate-900/35 p-4 transition-opacity duration-150 dark:bg-slate-950/50 sm:p-6 ${
        hiddenForDrag ? "pointer-events-none opacity-0" : ""
      }`}
      onPointerDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="flex min-h-[min(52vh,420px)] max-h-[78vh] w-full max-w-[min(96vw,920px)] flex-col overflow-hidden rounded-xl border border-slate-300 bg-white text-slate-900 shadow-2xl dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100">
        <header className="flex items-center justify-between border-b border-slate-200 px-4 py-3 dark:border-slate-800">
          <div className="flex items-center gap-2 text-sm font-semibold">
            <FolderOpen className="h-4 w-4 text-blue-600 dark:text-blue-400" />
            {title}
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              disabled={isUploading}
              onClick={() => fileInputRef.current?.click()}
              className="inline-flex items-center gap-1.5 rounded-md border border-slate-300 bg-slate-50 px-2.5 py-1.5 text-xs font-semibold text-slate-700 hover:border-blue-500/70 hover:bg-blue-50 hover:text-blue-800 disabled:cursor-wait disabled:opacity-50 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-300 dark:hover:border-blue-500/70 dark:hover:bg-blue-600/20 dark:hover:text-blue-50"
            >
              {isUploading ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden />
              ) : (
                <Upload className="h-3.5 w-3.5" aria-hidden />
              )}
              {t("coursewareEditor.resources.uploadFile")}
            </button>
            <button
              type="button"
              className="rounded p-1 text-slate-500 hover:bg-slate-100 hover:text-slate-800 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-slate-200"
              onClick={onClose}
              aria-label={t("coursewareEditor.common.close")}
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </header>
        <div
          className={`relative flex min-h-0 flex-1 flex-col overflow-y-auto p-3 transition ${
            isFileDragOver ? "bg-blue-50 ring-2 ring-inset ring-blue-400/50 dark:bg-blue-600/10 dark:ring-blue-500/40" : ""
          }`}
          onDragOver={handleContentDragOver}
          onDragLeave={handleFileDragLeave}
          onDrop={handleFileDrop}
        >
          {isFileDragOver ? (
            <div className="pointer-events-none absolute inset-3 z-10 flex items-center justify-center rounded-lg border-2 border-dashed border-blue-400/70 bg-blue-50/80 dark:border-blue-400/60 dark:bg-blue-600/10">
              <div className="flex flex-col items-center gap-1 text-blue-700 dark:text-blue-200">
                <Upload className="h-5 w-5" />
                <span className="text-xs font-medium">{t("coursewareEditor.common.dropToUpload")}</span>
              </div>
            </div>
          ) : null}
          {error ? (
            <div className="mb-3 shrink-0 rounded border border-rose-300/60 bg-rose-50 px-3 py-2 text-xs text-rose-700 dark:border-rose-400/40 dark:bg-rose-500/10 dark:text-rose-300">
              {error}
            </div>
          ) : null}
          {isLoading ? (
            <div className="flex min-h-0 flex-1 items-center justify-center gap-2 text-xs text-slate-500 dark:text-slate-400">
              <Loader2 className="h-4 w-4 animate-spin" />
              {t("coursewareEditor.common.loading")}
            </div>
          ) : assets.length === 0 ? (
            <div className="flex min-h-0 flex-1 items-stretch">
              <div className="flex flex-1 flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-slate-300 px-6 py-10 text-center dark:border-slate-700">
                <div className="flex h-14 w-14 items-center justify-center rounded-full bg-slate-100 text-slate-500 dark:bg-slate-800/80 dark:text-slate-400">
                  <Upload className="h-7 w-7" aria-hidden />
                </div>
                <div className="flex max-w-xs flex-col gap-1">
                  <p className="text-sm font-medium text-slate-700 dark:text-slate-300">{t("coursewareEditor.common.noFiles")}</p>
                  <p className="text-xs text-slate-500">{t("coursewareEditor.common.dropToUpload")}</p>
                </div>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-3 gap-2 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6">
              {assets.map((asset) => {
                const extKind = getAssetKind(asset.extension, asset.mimeType);
                const canInsertToCanvas = isCanvasInsertableAsset(asset);
                const Icon =
                  extKind === "image"
                    ? ImageIcon
                    : extKind === "video"
                      ? Video
                      : extKind === "audio"
                        ? Music
                        : extKind === "ppt"
                          ? Presentation
                          : FileIcon;
                return (
                  <div
                    key={asset.id}
                    draggable={canInsertToCanvas}
                    title={
                      canInsertToCanvas
                        ? t("coursewareEditor.resources.clickToAddCanvas")
                        : t("coursewareEditor.resources.referenceOnly")
                    }
                    className={`group relative flex h-full min-w-0 flex-col overflow-hidden rounded border border-slate-200 bg-white outline-none dark:border-slate-800 dark:bg-slate-950/40 ${
                      canInsertToCanvas
                        ? "cursor-grab active:cursor-grabbing hover:border-blue-400/60 hover:bg-slate-50 dark:hover:border-blue-500/40 dark:hover:bg-slate-900/60"
                        : ""
                    }`}
                    onDragStart={
                      canInsertToCanvas ? (event) => beginAssetDrag(event, asset) : undefined
                    }
                    onDragEnd={canInsertToCanvas ? handleAssetDragEnd : undefined}
                  >
                    <div
                      className={`absolute right-1 top-1 z-20 flex flex-col gap-1 transition-opacity duration-150 ${
                        deletingAssetId === asset.id || downloadingAssetId === asset.id
                          ? "opacity-100"
                          : "opacity-0 group-hover:opacity-100 group-focus-within:opacity-100"
                      }`}
                    >
                      <button
                        type="button"
                        title={t("coursewareEditor.common.deleteFromLibrary")}
                        disabled={deletingAssetId === asset.id}
                        className="rounded bg-white/95 p-1 text-slate-500 shadow hover:bg-rose-600/90 hover:text-white disabled:cursor-wait disabled:opacity-50 dark:bg-slate-950/90 dark:text-slate-400"
                        onClick={(e) => {
                          e.stopPropagation();
                          void handleDeleteAsset(asset);
                        }}
                        onPointerDown={(e) => e.stopPropagation()}
                        onDragStart={(e) => e.stopPropagation()}
                        aria-label={`${t("coursewareEditor.common.delete")} ${asset.name}`}
                      >
                        {deletingAssetId === asset.id ? (
                          <Loader2 className="h-3 w-3 animate-spin" aria-hidden />
                        ) : (
                          <Trash2 className="h-3 w-3" aria-hidden />
                        )}
                      </button>
                      <button
                        type="button"
                        title={t("coursewareEditor.common.downloadFile")}
                        disabled={downloadingAssetId === asset.id}
                        className="rounded bg-white/95 p-1 text-slate-500 shadow hover:bg-blue-600/90 hover:text-white disabled:cursor-wait disabled:opacity-50 dark:bg-slate-950/90 dark:text-slate-400"
                        onClick={(e) => {
                          e.stopPropagation();
                          void handleDownloadAsset(asset);
                        }}
                        onPointerDown={(e) => e.stopPropagation()}
                        onDragStart={(e) => e.stopPropagation()}
                        aria-label={t("coursewareEditor.resources.downloadAsset", { name: asset.name })}
                      >
                        {downloadingAssetId === asset.id ? (
                          <Loader2 className="h-3 w-3 animate-spin" aria-hidden />
                        ) : (
                          <Download className="h-3 w-3" aria-hidden />
                        )}
                      </button>
                    </div>
                    <div className="relative flex aspect-4/3 w-full shrink-0 items-center justify-center overflow-hidden bg-slate-100 dark:bg-slate-800">
                      {extKind === "image" ? (
                        <img
                          src={asset.url}
                          alt=""
                          className="max-h-full max-w-full object-contain"
                          loading="lazy"
                          draggable={false}
                        />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center text-slate-500 dark:text-slate-200">
                          <Icon className="h-8 w-8 opacity-90" />
                        </div>
                      )}
                    </div>
                    <div className="flex flex-1 flex-col gap-1 p-1.5">
                      <div className="line-clamp-2 min-h-[2.5em] break-all text-center text-[10px] leading-tight text-slate-800 dark:text-slate-100">
                        {asset.name}
                      </div>
                      <div className="truncate text-center text-[9px] text-slate-500">
                        {asset.extension.toUpperCase()} · {formatFileSize(asset.size)}
                      </div>
                      {canInsertToCanvas ? (
                        <button
                          type="button"
                          className="mt-auto w-full rounded border border-blue-500/45 px-1 py-1 text-[10px] font-medium text-blue-700 hover:bg-blue-50 dark:text-blue-300 dark:hover:bg-blue-600/15"
                          onPointerDown={(e) => e.stopPropagation()}
                          onDragStart={(e) => e.stopPropagation()}
                          onClick={() => {
                            onPick(asset);
                            onClose();
                          }}
                        >
                          {pickButtonLabel}
                        </button>
                      ) : (
                        <div className="mt-auto text-center text-[9px] text-slate-500">
                          {t("coursewareEditor.resources.referenceOnly")}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept={TOOLBAR_ASSET_ACCEPT[panel]}
          multiple
          className="hidden"
          onChange={(event) => {
            const files = Array.from(event.currentTarget.files ?? []);
            event.currentTarget.value = "";
            void uploadFiles(files);
          }}
        />
      </div>
    </div>,
    document.body,
  );
}

