function ToolbarAssetSourceMenu({
  anchor,
  themeMode,
  panel,
  label,
  coursewareId,
  coursewareOrgId,
  uploadedAssetsRegistry,
  onAddElement,
  onClose,
  onDragResourceStart,
  onDragResourceEnd,
}: {
  anchor: ToolbarMenuAnchor | null;
  themeMode: EditorThemeMode;
  panel: ToolbarAssetPanel;
  label: string;
  coursewareId: string | null;
  coursewareOrgId: string | null;
  uploadedAssetsRegistry?: UploadedAssetsRegistry;
  onAddElement: (element: CourseElement) => void;
  onClose: () => void;
  onDragResourceStart: (resource: DraggedResource) => void;
  onDragResourceEnd: () => void;
}) {
  const { t, language } = useI18nNew();
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [aiGenerateOpen, setAiGenerateOpen] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const addAsset = (asset: CoursewareAssetItem): void => {
    if (!isCanvasInsertableAsset(asset)) return;
    const elementPromise =
      asset.extension === "pdf" || asset.extension === "pptx"
        ? buildPptElementFromAssetWithPresign(coursewareId, asset)
        : Promise.resolve(buildAssetElement(asset));
    void elementPromise
      .then((element) => {
        onAddElement(element);
        toast.success(t("coursewareEditor.toast.assetInserted", { name: asset.name }), { duration: 3000 });
        onClose();
      })
      .catch((err) => {
        toast.error(err instanceof Error ? err.message : t("coursewareEditor.toast.pptInsertFailed"));
      });
  };

  const uploadFiles = async (files: File[]): Promise<void> => {
    if (!coursewareId || files.length === 0 || isUploading) return;
    const validFiles = files.filter((file) => isToolbarAssetFile(file, panel));
    if (validFiles.length === 0) {
      setError(t("coursewareEditor.toast.unsupportedFiles", { names: files.map((file) => file.name).join(t("coursewareEditor.common.listSeparator")) }));
      return;
    }
    setIsUploading(true);
    setError(null);
    try {
      const uploaded = await uploadCoursewareAssetFiles(coursewareId, validFiles, undefined, language);
      uploadedAssetsRegistry?.notify(uploaded);
      uploaded.forEach(addAsset);
    } catch (err) {
      if (err instanceof AggregateUploadError && err.uploaded.length > 0) {
        uploadedAssetsRegistry?.notify(err.uploaded);
        err.uploaded.forEach(addAsset);
        setError(t("coursewareEditor.toast.uploadPartialFailed", {
          successCount: err.uploaded.length,
          failed: err.failedNames.join(t("coursewareEditor.common.listSeparator")),
        }));
      } else {
        setError(err instanceof Error ? err.message : t("coursewareEditor.toast.uploadFailed"));
      }
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <>
      <CanvasToolbarMenu anchor={anchor} themeMode={themeMode} className="grid gap-2.5 p-2.5">
        <div className="flex min-w-0 items-center justify-between gap-2">
          <div className="text-[13px] font-bold leading-tight text-slate-700 dark:text-slate-300">{label}</div>
          <div className="flex shrink-0 items-center gap-1.5">
            {panel === "image" ? (
              <ToolbarSourceIconButton
                icon={<Sparkles className="h-4 w-4" />}
                label={t("coursewareEditor.resources.generateWithAi")}
                disabled={!coursewareId}
                onClick={() => setAiGenerateOpen(true)}
              />
            ) : null}
            <ToolbarSourceIconButton
              icon={<FolderOpen className="h-4 w-4" />}
              label={t("coursewareEditor.resources.pickFromLibrary")}
              disabled={!coursewareId}
              onClick={() => setPickerOpen(true)}
            />
            <ToolbarSourceIconButton
              icon={<Upload className="h-4 w-4" />}
              label={t("coursewareEditor.resources.selectFile")}
              disabled={!coursewareId}
              loading={isUploading}
              onClick={() => fileInputRef.current?.click()}
            />
          </div>
        </div>
        {panel === "document" ? (
          <p className="text-[11px] font-semibold leading-snug text-slate-500">
            {t("coursewareEditor.canvasToolbar.documentFormats")}
          </p>
        ) : null}
        {error ? (
          <div className="rounded border border-rose-300 bg-rose-50 p-2 text-[11px] text-rose-700 dark:border-rose-400/40 dark:bg-rose-500/10 dark:text-rose-300">
            {error}
          </div>
        ) : null}
        <p className="text-[11px] font-semibold leading-snug text-slate-500">
          {t("coursewareEditor.canvasToolbar.sourceNote")}
        </p>
        <input
          ref={fileInputRef}
          type="file"
          accept={TOOLBAR_ASSET_ACCEPT[panel]}
          multiple
          className="hidden"
          onChange={(event) => {
            const files = Array.from(event.currentTarget.files ?? []);
            event.currentTarget.value = "";
            void uploadFiles(files);
          }}
        />
      </CanvasToolbarMenu>
      {pickerOpen && coursewareId ? (
        <ToolbarAssetPickerDialog
          panel={panel}
          coursewareId={coursewareId}
          themeMode={themeMode}
          onPick={addAsset}
          onClose={() => setPickerOpen(false)}
          onDragResourceStart={onDragResourceStart}
          onDragResourceEnd={onDragResourceEnd}
          uploadedAssetsRegistry={uploadedAssetsRegistry}
        />
      ) : null}
      {aiGenerateOpen && coursewareId ? (
        <CoursewareImageGenerateModal
          coursewareId={coursewareId}
          coursewareOrgId={coursewareOrgId}
          themeMode={themeMode}
          onInsert={(asset) => {
            uploadedAssetsRegistry?.notify([asset]);
            addAsset(asset);
          }}
          onClose={() => setAiGenerateOpen(false)}
        />
      ) : null}
    </>
  );
}

function ToolbarAiTeacherAvatar({ url }: { url?: string | null }) {
  const [broken, setBroken] = useState(false);
  if (url && !broken) {
    return (
      <img
        src={url}
        alt=""
        className="h-full w-full object-cover"
        onError={() => setBroken(true)}
      />
    );
  }
  return <User className="h-4 w-4 text-slate-500 dark:text-slate-400" />;
}

function ToolbarAiTeacherMenu({
  anchor,
  themeMode,
  coursewareOrgId,
  onAddElement,
  onClose,
}: {
  anchor: ToolbarMenuAnchor | null;
  themeMode: EditorThemeMode;
  coursewareOrgId: string | null;
  onAddElement: (element: CourseElement) => void;
  onClose: () => void;
}) {
  const { t } = useI18nNew();
  const [teachers, setTeachers] = useState<AITeacherInfo[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!coursewareOrgId?.trim()) return;
    let cancelled = false;
    const loadTeachers = async (): Promise<void> => {
      setIsLoading(true);
      setError(null);
      try {
        const { data } = await aiTeacherApi.getAITeachers({ page_number: 1, page_size: 20 }, coursewareOrgId);
        if (!cancelled) setTeachers(data);
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : t("coursewareEditor.resources.aiTeacherLoadFailed"));
      } finally {
        if (!cancelled) setIsLoading(false);
      }
    };
    void loadTeachers();
    return () => {
      cancelled = true;
    };
  }, [coursewareOrgId, t]);

  return (
    <CanvasToolbarMenu anchor={anchor} themeMode={themeMode} className="p-2">
      <div className="mb-2 px-1 text-xs font-bold text-slate-700 dark:text-slate-300">
        {t("coursewareEditor.canvasToolbar.aiAvatar")}
      </div>
      {isLoading ? (
        <div className="flex items-center justify-center gap-2 py-4 text-xs text-slate-500 dark:text-slate-400">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          {t("coursewareEditor.resources.aiTeachersLoading")}
        </div>
      ) : error ? (
        <div className="rounded border border-rose-300 bg-rose-50 p-2 text-[11px] text-rose-700 dark:border-rose-400/40 dark:bg-rose-500/10 dark:text-rose-300">{error}</div>
      ) : teachers.length === 0 ? (
        <div data-ai-teacher-empty="" className="rounded border border-dashed border-slate-300 p-4 text-center text-xs text-slate-500 dark:border-slate-700 dark:text-slate-400">
          {t("coursewareEditor.resources.noAiTeachers")}
          {createAiTeacherAction() ? (
            <button
              type="button"
              onClick={() => {
                createAiTeacherAction()?.();
                onClose();
              }}
              className="mt-2 block w-full rounded-md bg-blue-600 px-2 py-1.5 font-medium text-white hover:bg-blue-700"
            >
              {t("coursewareEditor.resources.createAiTeacher")}
            </button>
          ) : null}
        </div>
      ) : (
        <div className="max-h-72 overflow-y-auto">
          {teachers.map((teacher) => (
            <button
              key={teacher.ai_teacher_id}
              type="button"
              onClick={() => {
                onAddElement(buildAITeacherElement(teacher));
                onClose();
              }}
              className="flex w-full items-center gap-2 rounded-md px-2 py-2 text-left hover:bg-blue-50 dark:hover:bg-blue-600/25"
            >
              <span className="flex h-9 w-9 shrink-0 items-center justify-center overflow-hidden rounded-full bg-slate-200 dark:bg-slate-800">
                <ToolbarAiTeacherAvatar url={teacher.ai_teacher_avatar_url} />
              </span>
              <span className="min-w-0 flex-1">
                <span className="block truncate text-xs font-semibold text-slate-800 dark:text-slate-100">{teacher.ai_teacher_name}</span>
                <span className="block truncate text-[10px] text-slate-500 dark:text-slate-400">
                  {teacher.ai_teacher_language || teacher.ai_teacher_id}
                </span>
              </span>
              <span className="text-[10px] text-blue-600 dark:text-blue-300">{t("coursewareEditor.common.add")}</span>
            </button>
          ))}
        </div>
      )}
    </CanvasToolbarMenu>
  );
}

/**
 * The toolbar's "transform / fade / highlight / keyframes" animation bubbles.
 */
function ToolbarAnimationMenu({
  mode,
  anchor,
  themeMode,
  element,
  slide,
  currentTime,
  recordKeyframes,
  selectedKeyframe,
  onUpdateElement,
  onSelectKeyframe,
  onSeek,
  onAddKeyframeAtCurrentTime,
  onAddHighlightAtCurrentTime,
  onClose,
}: {
  mode: ToolbarAnimationMode;
  anchor: ToolbarMenuAnchor | null;
  themeMode: EditorThemeMode;
  element: CourseElement;
  slide: SlideElement;
  currentTime: number;
  recordKeyframes: boolean;
  selectedKeyframe: SelectedKeyframe | null;
  onUpdateElement: (updater: (el: CourseElement) => CourseElement) => void;
  onSelectKeyframe: (keyframe: SelectedKeyframe | null) => void;
  onSeek: (ms: number) => void;
  onAddKeyframeAtCurrentTime: () => void;
  onAddHighlightAtCurrentTime: () => void;
  onClose: () => void;
}) {
  const { t } = useI18nNew();
  const isSlideCanvasAudioElement = element.element_type === "audio";
  const title =
    mode === "transform"
      ? t("coursewareEditor.canvasToolbar.transform")
      : mode === "fade"
        ? t("coursewareEditor.canvasToolbar.fade")
        : mode === "highlight"
          ? t("coursewareEditor.canvasToolbar.highlight")
          : t("coursewareEditor.common.timingKeyframes");
  return (
    <CanvasToolbarMenu anchor={anchor} themeMode={themeMode} className="p-0">
      <div className="flex items-center justify-between gap-2 border-b border-slate-200 px-3 py-2 dark:border-slate-700">
        <span className="text-xs font-semibold text-slate-800 dark:text-slate-100">{title}</span>
        <button
          type="button"
          onClick={onClose}
          className="rounded p-0.5 text-slate-500 hover:bg-slate-100 hover:text-slate-800 dark:text-slate-400 dark:hover:bg-slate-700/60 dark:hover:text-slate-100"
          aria-label={t("coursewareEditor.common.close")}
        >
          <X className="h-3.5 w-3.5" />
        </button>
      </div>
      <div className="max-h-[min(64vh,560px)] space-y-4 overflow-y-auto p-3">
        {mode === "transform" ? (
          <>
            <div className="space-y-2">
              <div className="text-[11px] font-semibold text-slate-600 dark:text-slate-300">
                {t("coursewareEditor.common.transformCurrentTime")}
              </div>
              <ElementTransformFields
                element={element}
                slide={slide}
                currentTime={currentTime}
                onUpdateElement={onUpdateElement}
              />
            </div>
            <div className="space-y-2">
              <div className="text-[11px] font-semibold text-slate-600 dark:text-slate-300">{t("coursewareEditor.common.opacity")}</div>
              <ElementOpacityField
                element={element}
                slide={slide}
                currentTime={currentTime}
                recordKeyframes={recordKeyframes}
                onUpdateElement={onUpdateElement}
              />
            </div>
          </>
        ) : mode === "fade" ? (
          <div className="space-y-2">
            <ElementEnterExitFields element={element} onUpdateElement={onUpdateElement} />
          </div>
        ) : mode === "highlight" ? (
          <div className="space-y-2">
            <ElementHighlightFields
              element={element}
              currentTime={currentTime}
              onUpdateElement={onUpdateElement}
              onAddHighlightAtCurrentTime={onAddHighlightAtCurrentTime}
              onSeek={onSeek}
            />
          </div>
        ) : !isSlideCanvasAudioElement ? (
          <ElementKeyframeFields
            element={element}
            currentTime={currentTime}
            selectedKeyframe={selectedKeyframe}
            onUpdateElement={onUpdateElement}
            onSelectKeyframe={onSelectKeyframe}
            onSeek={onSeek}
            onAddKeyframeAtCurrentTime={onAddKeyframeAtCurrentTime}
          />
        ) : null}
      </div>
    </CanvasToolbarMenu>
  );
}

function CanvasEditorToolbar({
  themeMode,
  activePanel,
  onActivePanelChange,
  hasMusicTracks,
  hasQuizConfig,
  quizValidationIssueCount,
  quizValidationFirstIssue,
  selectedElement,
  selectedRichTextStyle,
  selectedSvgTextStyle,
  onUpdateSelectedElement,
  onUpdateSelectedRichTextStyle,
  onUpdateSelectedSvgTextStyle,
  onSetSlideBackgroundImage,
  onSetSlideBackgroundHtml,
  slide,
  currentTime,
  recordKeyframes,
  selectedKeyframe,
  onSeek,
  onSelectKeyframe,
  onAddKeyframeAtCurrentTime,
  onAddHighlightAtCurrentTime,
  onOpenMusicSettings,
  onOpenQuizSettings,
  onOpenQuizSettingsForQuestion,
  onOpenQuizLayoutEditor,
  editorQuiz,
  coursewareId,
  coursewareOrgId,
  uploadedAssetsRegistry,
  onAddElement,
  onAddQuestionTemplate,
  onAddScoreSummaryTemplate,
  flowPausePoints,
  selectedFlowPauseId,
  onAddFlowPause,
  onDeleteFlowPause,
  onSelectFlowPause,
  onDragResourceStart,
  onDragResourceEnd,
}: {
  themeMode: EditorThemeMode;
  activePanel: CanvasToolbarPanel;
  onActivePanelChange: (panel: CanvasToolbarPanel) => void;
  hasMusicTracks: boolean;
  hasQuizConfig: boolean;
  quizValidationIssueCount: number;
  quizValidationFirstIssue: string | null;
  selectedElement: CourseElement | null;
  selectedRichTextStyle: RichTextStyleSnapshot | null;
  selectedSvgTextStyle: SvgTextStyleSnapshot | null;
  onUpdateSelectedElement: (
    updater: (el: CourseElement) => CourseElement,
    options?: { recordHistory?: boolean },
  ) => void;
  onUpdateSelectedRichTextStyle: (
    patch: Record<string, string | number | null>,
    options?: { recordHistory?: boolean },
  ) => void;
  onUpdateSelectedSvgTextStyle: (patch: SvgTextStylePatch) => void;
  onSetSlideBackgroundImage: (source: string, elementId: string) => void;
  onSetSlideBackgroundHtml: (
    src: string,
    contentZoom: number | undefined,
    elementId: string,
  ) => void;
  slide: SlideElement | undefined;
  currentTime: number;
  recordKeyframes: boolean;
  selectedKeyframe: SelectedKeyframe | null;
  onSeek: (ms: number) => void;
  onSelectKeyframe: (keyframe: SelectedKeyframe | null) => void;
  onAddKeyframeAtCurrentTime: () => void;
  onAddHighlightAtCurrentTime: () => void;
  onOpenMusicSettings: () => void;
  onOpenQuizSettings: () => void;
  onOpenQuizSettingsForQuestion: (questionId: string) => void;
  onOpenQuizLayoutEditor: (questionId: string, elementId: string) => void;
  editorQuiz: QuizConfig | null;
  coursewareId: string | null;
  coursewareOrgId: string | null;
  uploadedAssetsRegistry?: UploadedAssetsRegistry;
  onAddElement: (element: CourseElement) => void;
  onAddQuestionTemplate: (kind: QuizQuestionType) => void;
  onAddScoreSummaryTemplate: () => void;
  flowPausePoints: SlideFlowPausePoint[];
  selectedFlowPauseId: string | null;
  onAddFlowPause: () => void;
  onDeleteFlowPause: (pauseId: string) => void;
  onSelectFlowPause: (pauseId: string | null) => void;
  onDragResourceStart: (resource: DraggedResource) => void;
  onDragResourceEnd: () => void;
}) {
  const { t } = useI18nNew();
  const editorLabels = useCoursewareEditorLabels();
  const toolbarRootRef = useRef<HTMLDivElement | null>(null);
  const triggerRefs = useRef<Partial<Record<Exclude<CanvasToolbarPanel, null>, HTMLButtonElement | null>>>({});
  const [activeTriggerEl, setActiveTriggerEl] = useState<HTMLElement | null>(null);
  const [imageReplacePickerOpen, setImageReplacePickerOpen] = useState(false);
  const [videoReplacePickerOpen, setVideoReplacePickerOpen] = useState(false);
  const [documentReplacePickerOpen, setDocumentReplacePickerOpen] = useState(false);

  const togglePanel = (panel: Exclude<CanvasToolbarPanel, null>): void => {
    onActivePanelChange(activePanel === panel ? null : panel);
  };

  useLayoutEffect(() => {
    if (!activePanel) {
      setActiveTriggerEl(null);
      return;
    }
    setActiveTriggerEl(triggerRefs.current[activePanel] ?? null);
  }, [activePanel]);

  const menuWidth =
    activePanel === "text"
      ? 156
      : activePanel === "shape"
        ? 144
        : activePanel === "image" ||
            activePanel === "audio" ||
            activePanel === "video" ||
            activePanel === "document"
          ? 260
            : activePanel === "ai"
            ? 372
            : activePanel === "quiz"
              ? 280
              : activePanel === "flow"
                ? 156
                : activePanel === "transform"
                ? 340
                : activePanel === "fade"
                  ? 300
                  : activePanel === "highlight"
                    ? 340
                    : activePanel === "keyframes"
                      ? 360
                      : 260;
  const menuAnchor = useToolbarMenuAnchor(activeTriggerEl, activePanel !== null, menuWidth);

  useEffect(() => {
    if (!activePanel) return;
    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target as Node;
      if (toolbarRootRef.current?.contains(target)) return;
      if ((target as Element).closest?.("[data-canvas-toolbar-menu]")) return;
      if ((target as Element).closest?.("[data-toolbar-asset-picker]")) return;
      if ((target as Element).closest?.("[data-toolbar-image-generate]")) return;
      if ((target as Element).closest?.("[data-courseware-color-popover]")) return;
      if ((target as Element).closest?.("[data-toolbar-number-slider-popover]")) return;
      if ((target as Element).closest?.("[data-toolbar-text-font-menu]")) return;
      if ((target as Element).closest?.("[data-toolbar-inline-select-menu]")) return;
      onActivePanelChange(null);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [activePanel, onActivePanelChange]);

  const textElement = selectedElement?.element_type === "text" ? selectedElement : null;
  const selectedFlowPause = selectedFlowPauseId
    ? flowPausePoints.find((p) => p.pause_id === selectedFlowPauseId) ?? null
    : null;
  const imageElement = selectedElement?.element_type === "image" ? selectedElement : null;
  const videoElement = selectedElement?.element_type === "video" ? selectedElement : null;
  const documentElement =
    selectedElement?.element_type === "ppt" || selectedElement?.element_type === "html"
      ? selectedElement
      : null;
  const audioElement = selectedElement?.element_type === "audio" ? selectedElement : null;
  const quizElement =
    selectedElement?.element_type === "quiz" ? (selectedElement as QuizSlideElement) : null;
  const quizQuestionConfig =
    quizElement && editorQuiz ? getEditorQuestionConfig(editorQuiz, quizElement) : null;
  const isSlideCanvasAudioElement = selectedElement?.element_type === "audio";
  const closePanel = (): void => onActivePanelChange(null);

  useEffect(() => {
    if (selectedElement?.element_type !== "image") {
      setImageReplacePickerOpen(false);
    }
  }, [selectedElement?.element_id, selectedElement?.element_type]);

  useEffect(() => {
    if (selectedElement?.element_type !== "video") {
      setVideoReplacePickerOpen(false);
    }
  }, [selectedElement?.element_id, selectedElement?.element_type]);

  useEffect(() => {
    if (selectedElement?.element_type !== "ppt" && selectedElement?.element_type !== "html") {
      setDocumentReplacePickerOpen(false);
    }
  }, [selectedElement?.element_id, selectedElement?.element_type]);

  const handleReplaceImageAsset = useCallback(
    (asset: CoursewareAssetItem): void => {
      if (getAssetKind(asset.extension, asset.mimeType) !== "image") return;
      onUpdateSelectedElement((el) => {
        if (el.element_type !== "image") return el;
        return {
          ...el,
          name: asset.name,
          source: asset.url,
          source_intrinsic_width: null,
          source_intrinsic_height: null,
        };
      });
      toast.success(t("coursewareEditor.toast.imageReplaced", { name: asset.name }), { duration: 3000 });
      setImageReplacePickerOpen(false);
    },
    [onUpdateSelectedElement, t],
  );

  const handleReplaceVideoAsset = useCallback(
    (asset: CoursewareAssetItem): void => {
      if (getAssetKind(asset.extension, asset.mimeType) !== "video") return;
      onUpdateSelectedElement((el) => {
        if (el.element_type !== "video") return el;
        return {
          ...el,
          name: asset.name,
          source: asset.url,
        };
      });
      toast.success(t("coursewareEditor.toast.videoReplaced", { name: asset.name }), { duration: 3000 });
      setVideoReplacePickerOpen(false);
    },
    [onUpdateSelectedElement, t],
  );

  const handleReplaceDocumentAsset = useCallback(
    (asset: CoursewareAssetItem): void => {
      const assetKind = getAssetKind(asset.extension, asset.mimeType);
      if (!documentElement) return;
      if (documentElement.element_type === "html" && assetKind !== "html") {
        toast.error(t("coursewareEditor.toast.documentReplaceMismatch"));
        return;
      }
      if (documentElement.element_type === "ppt" && assetKind !== "ppt") {
        toast.error(t("coursewareEditor.toast.documentReplaceMismatch"));
        return;
      }
      if (documentElement.element_type === "ppt") {
        // The replaced slide HTML is presigned page by page too, reattaching `signed_slide_urls`
        // (right after insertion the load-time pass hasn't run yet, so unsigned CDN URLs would 404).
        const base = resolvePptArtifactSrcFromAsset(asset);
        void presignPptSlideUrlsSafe(coursewareId, base, getCoursewareAssetArtifactSlideCount(asset))
          .then((signedSlideUrls) => {
            onUpdateSelectedElement((el) => {
              if (el.element_type !== "ppt") return el;
              const next = applyPptAssetToElement(el, asset);
              return Object.keys(signedSlideUrls).length > 0
                ? { ...next, signed_slide_urls: signedSlideUrls }
                : next;
            });
          })
          .catch((error: unknown) => {
            toast.error(
              error instanceof Error ? error.message : t("coursewareEditor.toast.pptInsertFailed"),
            );
          });
      } else {
        onUpdateSelectedElement((el) => {
          if (el.element_type !== "html") return el;
          return { ...el, name: asset.name, src: asset.url };
        });
        void invalidateHtmlSourceAutofitCacheAsync({ src: asset.url });
      }
      toast.success(t("coursewareEditor.toast.documentReplaced", { name: asset.name }), { duration: 3000 });
      setDocumentReplacePickerOpen(false);
    },
    [documentElement, onUpdateSelectedElement, t],
  );

  const isAnimationPanel =
    activePanel === "transform" ||
    activePanel === "fade" ||
    activePanel === "highlight" ||
    activePanel === "keyframes";
  const panelContent =
    activePanel === "text" ? (
      <ToolbarTextMenu anchor={menuAnchor} themeMode={themeMode} onAddElement={onAddElement} onClose={closePanel} />
    ) : activePanel === "shape" ? (
      <ToolbarShapeMenu anchor={menuAnchor} themeMode={themeMode} onAddElement={onAddElement} onClose={closePanel} />
    ) : activePanel === "image" || activePanel === "audio" || activePanel === "video" || activePanel === "document" ? (
      <ToolbarAssetSourceMenu
        anchor={menuAnchor}
        themeMode={themeMode}
        panel={activePanel}
        label={
          activePanel === "image"
            ? t("coursewareEditor.common.image")
            : activePanel === "audio"
              ? t("coursewareEditor.common.audio")
              : activePanel === "video"
                ? t("coursewareEditor.common.video")
                : t("coursewareEditor.canvasToolbar.document")
        }
        coursewareId={coursewareId}
        coursewareOrgId={coursewareOrgId}
        uploadedAssetsRegistry={uploadedAssetsRegistry}
        onAddElement={onAddElement}
        onClose={closePanel}
        onDragResourceStart={onDragResourceStart}
        onDragResourceEnd={onDragResourceEnd}
      />
    ) : activePanel === "ai" ? (
      <ToolbarAiTeacherMenu
        anchor={menuAnchor}
        themeMode={themeMode}
        coursewareOrgId={coursewareOrgId}
        onAddElement={onAddElement}
        onClose={closePanel}
      />
    ) : activePanel === "quiz" ? (
      <ToolbarQuizMenu
        anchor={menuAnchor}
        themeMode={themeMode}
        onAddQuestionTemplate={onAddQuestionTemplate}
        onAddScoreSummaryTemplate={onAddScoreSummaryTemplate}
        onOpenQuizSettings={onOpenQuizSettings}
        onClose={closePanel}
      />
    ) : activePanel === "flow" ? (
      <ToolbarFlowMenu
        anchor={menuAnchor}
        themeMode={themeMode}
        onAddFlowPause={onAddFlowPause}
        selectedFlowPauseId={selectedFlowPauseId}
        onDeleteFlowPause={onDeleteFlowPause}
        onClose={closePanel}
      />
    ) : isAnimationPanel && selectedElement && slide ? (
      <ToolbarAnimationMenu
        mode={activePanel as ToolbarAnimationMode}
        anchor={menuAnchor}
        themeMode={themeMode}
        element={selectedElement}
        slide={slide}
        currentTime={currentTime}
        recordKeyframes={recordKeyframes}
        selectedKeyframe={selectedKeyframe}
        onUpdateElement={onUpdateSelectedElement}
        onSelectKeyframe={onSelectKeyframe}
        onSeek={onSeek}
        onAddKeyframeAtCurrentTime={onAddKeyframeAtCurrentTime}
        onAddHighlightAtCurrentTime={onAddHighlightAtCurrentTime}
        onClose={closePanel}
      />
    ) : null;

  return (
    <div
      ref={toolbarRootRef}
      className="relative z-30 shrink-0 overflow-visible border-b border-slate-200 bg-white/95 shadow-sm backdrop-blur dark:border-slate-800 dark:bg-slate-900/90"
    >
      <style>{TOOLBAR_INLINE_NUMBER_SLIDER_STYLES}</style>
      <div className="flex min-h-10 items-center gap-0.5 overflow-x-auto px-3 py-1">
        {[
          { key: "text", icon: <Type className="h-4 w-4" />, label: t("coursewareEditor.common.text") },
          { key: "image", icon: <ImageIcon className="h-4 w-4" />, label: t("coursewareEditor.common.image") },
          { key: "audio", icon: <AudioLines className="h-4 w-4" />, label: t("coursewareEditor.common.audio") },
          { key: "video", icon: <Video className="h-4 w-4" />, label: t("coursewareEditor.common.video") },
          { key: "document", icon: <FileIcon className="h-4 w-4" />, label: t("coursewareEditor.canvasToolbar.document") },
          { key: "ai", icon: <User className="h-4 w-4" />, label: t("coursewareEditor.canvasToolbar.aiAvatar") },
          { key: "shape", icon: <Square className="h-4 w-4" />, label: t("coursewareEditor.common.shape") },
        ].map((item) => (
          <button
            key={item.key}
            ref={(el) => {
              triggerRefs.current[item.key as Exclude<CanvasToolbarPanel, null>] = el;
            }}
            type="button"
            className={canvasToolbarInsertButtonClass(activePanel === item.key)}
            onClick={() => togglePanel(item.key as Exclude<CanvasToolbarPanel, null>)}
            aria-expanded={activePanel === item.key}
            aria-pressed={activePanel === item.key}
          >
            {item.icon}
            <span>{item.label}</span>
            <ChevronDown className="h-2.5 w-2.5 text-slate-400 dark:text-slate-500" />
          </button>
        ))}
        <button
          type="button"
          className={canvasToolbarInsertButtonClass(false)}
          onClick={onOpenMusicSettings}
          title={hasMusicTracks ? t("coursewareEditor.toolbar.musicConfigured") : t("coursewareEditor.toolbar.musicConfigure")}
        >
          <Music className="h-4 w-4" />
          {t("coursewareEditor.canvasToolbar.music")}
          <ChevronDown className="h-2.5 w-2.5 text-slate-400 dark:text-slate-500" />
          {hasMusicTracks ? <span className="h-1.5 w-1.5 rounded-full bg-blue-500" /> : null}
        </button>
        <button
          ref={(el) => {
            triggerRefs.current.quiz = el;
          }}
          type="button"
          className={canvasToolbarInsertButtonClass(activePanel === "quiz")}
          onClick={() => togglePanel("quiz")}
          aria-expanded={activePanel === "quiz"}
          aria-pressed={activePanel === "quiz"}
          title={
            quizValidationFirstIssue ??
            (hasQuizConfig
              ? t("coursewareEditor.toolbar.quizConfigured")
              : t("coursewareEditor.toolbar.quizConfigure"))
          }
        >
          <ClipboardList className="h-4 w-4" />
          {t("coursewareEditor.canvasToolbar.quiz")}
          <ChevronDown className="h-2.5 w-2.5 text-slate-400 dark:text-slate-500" />
          {quizValidationIssueCount > 0 ? (
            <span className="h-1.5 w-1.5 rounded-full bg-amber-500" />
          ) : hasQuizConfig ? (
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
          ) : null}
        </button>
        <button
          ref={(el) => {
            triggerRefs.current.flow = el;
          }}
          type="button"
          className={canvasToolbarInsertButtonClass(activePanel === "flow")}
          onClick={() => togglePanel("flow")}
          aria-expanded={activePanel === "flow"}
          aria-pressed={activePanel === "flow"}
          title={t("coursewareEditor.canvasToolbar.flow")}
        >
          <Workflow className="h-4 w-4" />
          {t("coursewareEditor.canvasToolbar.flow")}
          <ChevronDown className="h-2.5 w-2.5 text-slate-400 dark:text-slate-500" />
          {flowPausePoints.length > 0 ? (
            <span className="h-1.5 w-1.5 rounded-full bg-amber-400" />
          ) : null}
        </button>
      </div>
      {selectedFlowPause && !selectedElement ? (
        <div className="absolute inset-x-0 top-full z-40 flex min-h-10 items-center gap-2 overflow-x-auto border-b border-amber-200/80 bg-amber-50/95 px-3 py-1.5 shadow-[0_8px_16px_rgba(15,23,42,0.08)] backdrop-blur-sm dark:border-amber-900/60 dark:bg-amber-950/40 dark:shadow-[0_8px_16px_rgba(0,0,0,0.22)]">
          <span className="shrink-0 text-xs font-medium text-amber-800 dark:text-amber-100">
            {t("coursewareEditor.canvasToolbar.flowPauseSelected", {
              time: formatTimeMs(selectedFlowPause.at_ms),
            })}
          </span>
          <button
            type="button"
            className="inline-flex h-8 shrink-0 items-center gap-1.5 rounded-md border border-rose-200 bg-white px-2.5 text-xs font-medium text-rose-700 hover:bg-rose-50 dark:border-rose-900/60 dark:bg-slate-900 dark:text-rose-300 dark:hover:bg-rose-500/10"
            onClick={() => onDeleteFlowPause(selectedFlowPause.pause_id)}
          >
            <Trash2 className="h-3.5 w-3.5" aria-hidden />
            {t("coursewareEditor.common.delete")}
          </button>
        </div>
      ) : selectedElement ? (
        <div className="absolute inset-x-0 top-full z-40 flex min-h-10 items-center gap-1 overflow-x-auto border-b border-slate-200 bg-white/95 px-3 py-1.5 shadow-[0_8px_16px_rgba(15,23,42,0.08)] backdrop-blur-sm dark:border-slate-800 dark:bg-slate-900/95 dark:shadow-[0_8px_16px_rgba(0,0,0,0.22)]">
            {textElement ? (
              <>
                <label className="flex shrink-0 items-center rounded-md border border-slate-200 bg-slate-50 text-xs dark:border-slate-700 dark:bg-slate-950/40">
                  <span className="px-2 text-slate-500 dark:text-slate-400">{t("coursewareEditor.properties.font")}</span>
                  <ToolbarTextFontSelect
                    value={textElement.font_family}
                    options={editorLabels.textFontPresets}
                    themeMode={themeMode}
                    onChange={(font_family) =>
                      onUpdateSelectedElement((el) =>
                        el.element_type === "text"
                          ? { ...el, font_family: coerceTextFontFamily(font_family) }
                          : el,
                      )
                    }
                  />
                </label>
                <ToolbarInlineNumberField
                  label={t("coursewareEditor.common.fontSize")}
                  value={Math.round(textElement.font_size)}
                  width="w-14"
                  min={8}
                  max={200}
                  step={1}
                  slider={{ min: 8, max: 200, step: 1 }}
                  themeMode={themeMode}
                  onChange={(font_size) =>
                    onUpdateSelectedElement((el) =>
                      el.element_type === "text" ? { ...el, font_size: Math.max(8, font_size) } : el,
                    )
                  }
                />
                <ToolbarInlineNumberField
                  label={t("coursewareEditor.common.lineHeight")}
                  value={resolveTextLineHeight(textElement.line_height)}
                  width="w-16"
                  min={0.5}
                  max={5}
                  step={0.1}
                  slider={{ min: 0.5, max: 5, step: 0.1 }}
                  themeMode={themeMode}
                  onChange={(line_height) =>
                    onUpdateSelectedElement((el) =>
                      el.element_type === "text"
                        ? { ...el, line_height: resolveTextLineHeight(line_height) }
                        : el,
                    )
                  }
                />
                <button
                  type="button"
                  className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-md border text-sm font-bold ${
                    textElement.bold
                      ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                      : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                  }`}
                  onClick={() =>
                    onUpdateSelectedElement((el) =>
                      el.element_type === "text" ? { ...el, bold: !el.bold } : el,
                    )
                  }
                >
                  B
                </button>
                <button
                  type="button"
                  className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-md border text-sm font-semibold italic ${
                    textElement.italic
                      ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                      : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                  }`}
                  onClick={() =>
                    onUpdateSelectedElement((el) =>
                      el.element_type === "text" ? { ...el, italic: !el.italic } : el,
                    )
                  }
                >
                  I
                </button>
                <span className="flex shrink-0 items-center gap-1 rounded-md border border-slate-200 bg-slate-50 px-2 py-1 text-xs text-slate-500 dark:border-slate-700 dark:bg-slate-950/40 dark:text-slate-400">
                  {t("coursewareEditor.properties.textColor")}
                  <BoundCoursewareColorPicker
                    variant="compact"
                    value={textElement.color}
                    fallbackColor="#1a202c"
                    onChange={(color, options) =>
                      onUpdateSelectedElement(
                        (el) => (el.element_type === "text" ? { ...el, color } : el),
                        options,
                      )
                    }
                  />
                </span>
                <span className="flex shrink-0 items-center gap-1 rounded-md border border-slate-200 bg-slate-50 px-2 py-1 text-xs text-slate-500 dark:border-slate-700 dark:bg-slate-950/40 dark:text-slate-400">
                  {t("coursewareEditor.common.backgroundColor")}
                  <BoundCoursewareColorPicker
                    variant="compact"
                    supportsTransparent
                    value={readTextElementBackgroundColorPickerValue(textElement)}
                    fallbackColor="#ffffff"
                    onChange={(color, options) =>
                      onUpdateSelectedElement(
                        (el) =>
                          el.element_type === "text" ? applyTextElementBackgroundColor(el, color) : el,
                        options,
                      )
                    }
                  />
                </span>
                <div className="flex shrink-0 items-center gap-1">
                  {(["left", "center", "right"] as const).map((align) => {
                    const Icon = align === "left" ? AlignLeft : align === "center" ? AlignCenter : AlignRight;
                    return (
                      <button
                        key={align}
                        type="button"
                        className={`flex h-8 w-8 items-center justify-center rounded-md border ${
                          textElement.align === align
                            ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                            : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                        }`}
                        onClick={() =>
                          onUpdateSelectedElement((el) =>
                            el.element_type === "text" ? { ...el, align } : el,
                          )
                        }
                      >
                        <Icon className="h-4 w-4" />
                      </button>
                    );
                  })}
                </div>
              </>
            ) : selectedSvgTextStyle ? (
              <>
                <label className="flex shrink-0 items-center rounded-md border border-slate-200 bg-slate-50 text-xs dark:border-slate-700 dark:bg-slate-950/40">
                  <span className="px-2 text-slate-500 dark:text-slate-400">{t("coursewareEditor.properties.font")}</span>
                  <ToolbarTextFontSelect
                    value={selectedSvgTextStyle.fontFamily}
                    options={editorLabels.textFontPresets}
                    themeMode={themeMode}
                    onChange={(fontFamily) => onUpdateSelectedSvgTextStyle({ fontFamily })}
                  />
                </label>
                <ToolbarInlineNumberField
                  label={t("coursewareEditor.common.fontSize")}
                  value={Math.round(selectedSvgTextStyle.fontSize)}
                  width="w-14"
                  min={8}
                  max={200}
                  step={1}
                  slider={{ min: 8, max: 200, step: 1 }}
                  themeMode={themeMode}
                  onChange={(fontSize) =>
                    onUpdateSelectedSvgTextStyle({ fontSize: Math.max(8, fontSize) })
                  }
                />
                <ToolbarInlineNumberField
                  label={t("coursewareEditor.common.lineHeight")}
                  value={selectedSvgTextStyle.lineHeight}
                  width="w-16"
                  min={0.5}
                  max={5}
                  step={0.1}
                  slider={{ min: 0.5, max: 5, step: 0.1 }}
                  themeMode={themeMode}
                  onChange={(lineHeight) =>
                    onUpdateSelectedSvgTextStyle({ lineHeight: resolveTextLineHeight(lineHeight) })
                  }
                />
                <button
                  type="button"
                  className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-md border text-sm font-bold ${
                    selectedSvgTextStyle.bold
                      ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                      : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                  }`}
                  onClick={() =>
                    onUpdateSelectedSvgTextStyle({
                      fontWeight: selectedSvgTextStyle.bold ? null : 700,
                    })
                  }
                >
                  B
                </button>
                <button
                  type="button"
                  className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-md border text-sm font-semibold italic ${
                    selectedSvgTextStyle.italic
                      ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                      : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                  }`}
                  onClick={() =>
                    onUpdateSelectedSvgTextStyle({
                      fontStyle: selectedSvgTextStyle.italic ? null : "italic",
                    })
                  }
                >
                  I
                </button>
                <span className="flex shrink-0 items-center gap-1 rounded-md border border-slate-200 bg-slate-50 px-2 py-1 text-xs text-slate-500 dark:border-slate-700 dark:bg-slate-950/40 dark:text-slate-400">
                  {t("coursewareEditor.properties.textColor")}
                  <BoundCoursewareColorPicker
                    variant="compact"
                    value={selectedSvgTextStyle.color}
                    fallbackColor="#0f172a"
                    onChange={(color) => onUpdateSelectedSvgTextStyle({ color })}
                  />
                </span>
                <span className="flex shrink-0 items-center gap-1 rounded-md border border-slate-200 bg-slate-50 px-2 py-1 text-xs text-slate-500 dark:border-slate-700 dark:bg-slate-950/40 dark:text-slate-400">
                  {t("coursewareEditor.common.backgroundColor")}
                  <BoundCoursewareColorPicker
                    variant="compact"
                    supportsTransparent
                    value={selectedSvgTextStyle.backgroundColor}
                    fallbackColor="#ffffff"
                    onChange={(backgroundColor) =>
                      onUpdateSelectedSvgTextStyle({ backgroundColor })
                    }
                  />
                </span>
                <div className="flex shrink-0 items-center gap-1">
                  {(["left", "center", "right"] as const).map((align) => {
                    const Icon =
                      align === "left" ? AlignLeft : align === "center" ? AlignCenter : AlignRight;
                    return (
                      <button
                        key={align}
                        type="button"
                        className={`flex h-8 w-8 items-center justify-center rounded-md border ${
                          selectedSvgTextStyle.align === align
                            ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                            : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                        }`}
                        onClick={() => onUpdateSelectedSvgTextStyle({ textAlign: align })}
                      >
                        <Icon className="h-4 w-4" />
                      </button>
                    );
                  })}
                </div>
                <div className="h-6 w-px shrink-0 bg-slate-200 dark:bg-slate-700" />
              </>
            ) : (
              <>
                {selectedRichTextStyle ? (
                  <>
                    <label className="flex shrink-0 items-center rounded-md border border-slate-200 bg-slate-50 text-xs dark:border-slate-700 dark:bg-slate-950/40">
                      <span className="px-2 text-slate-500 dark:text-slate-400">{t("coursewareEditor.properties.font")}</span>
                      <ToolbarTextFontSelect
                        value={selectedRichTextStyle.fontFamily}
                        options={editorLabels.textFontPresets}
                        themeMode={themeMode}
                        onChange={(fontFamily) => onUpdateSelectedRichTextStyle({ fontFamily })}
                      />
                    </label>
                    <ToolbarInlineNumberField
                      label={t("coursewareEditor.common.fontSize")}
                      value={Math.round(selectedRichTextStyle.fontSize)}
                      width="w-14"
                      min={8}
                      max={200}
                      step={1}
                      slider={{ min: 8, max: 200, step: 1 }}
                      themeMode={themeMode}
                      onChange={(fontSize) =>
                        onUpdateSelectedRichTextStyle({ fontSize: Math.max(8, fontSize) })
                      }
                    />
                    <ToolbarInlineNumberField
                      label={t("coursewareEditor.common.lineHeight")}
                      value={selectedRichTextStyle.lineHeight}
                      width="w-16"
                      min={0.5}
                      max={5}
                      step={0.1}
                      slider={{ min: 0.5, max: 5, step: 0.1 }}
                      themeMode={themeMode}
                      onChange={(lineHeight) =>
                        onUpdateSelectedRichTextStyle({ lineHeight: resolveTextLineHeight(lineHeight) })
                      }
                    />
                    <button
                      type="button"
                      className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-md border text-sm font-bold ${
                        selectedRichTextStyle.bold
                          ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                          : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                      }`}
                      onClick={() =>
                        onUpdateSelectedRichTextStyle({
                          fontWeight: selectedRichTextStyle.bold ? null : 700,
                        })
                      }
                    >
                      B
                    </button>
                    <button
                      type="button"
                      className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-md border text-sm font-semibold italic ${
                        selectedRichTextStyle.italic
                          ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                          : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                      }`}
                      onClick={() =>
                        onUpdateSelectedRichTextStyle({
                          fontStyle: selectedRichTextStyle.italic ? null : "italic",
                        })
                      }
                    >
                      I
                    </button>
                    <span className="flex shrink-0 items-center gap-1 rounded-md border border-slate-200 bg-slate-50 px-2 py-1 text-xs text-slate-500 dark:border-slate-700 dark:bg-slate-950/40 dark:text-slate-400">
                      {t("coursewareEditor.properties.textColor")}
                      <BoundCoursewareColorPicker
                        variant="compact"
                        value={selectedRichTextStyle.color}
                        fallbackColor="#0f172a"
                        onChange={(color, options) =>
                          onUpdateSelectedRichTextStyle({ color }, options)
                        }
                      />
                    </span>
                    <span className="flex shrink-0 items-center gap-1 rounded-md border border-slate-200 bg-slate-50 px-2 py-1 text-xs text-slate-500 dark:border-slate-700 dark:bg-slate-950/40 dark:text-slate-400">
                      {t("coursewareEditor.common.backgroundColor")}
                      <BoundCoursewareColorPicker
                        variant="compact"
                        supportsTransparent
                        value={selectedRichTextStyle.backgroundColor}
                        fallbackColor="#ffffff"
                        onChange={(backgroundColor, options) =>
                          onUpdateSelectedRichTextStyle({ backgroundColor }, options)
                        }
                      />
                    </span>
                    <div className="flex shrink-0 items-center gap-1">
                      {(["left", "center", "right"] as const).map((align) => {
                        const Icon =
                          align === "left" ? AlignLeft : align === "center" ? AlignCenter : AlignRight;
                        return (
                          <button
                            key={align}
                            type="button"
                            className={`flex h-8 w-8 items-center justify-center rounded-md border ${
                              selectedRichTextStyle.align === align
                                ? "border-blue-500 bg-blue-500/20 text-blue-700 dark:text-blue-200"
                                : "border-slate-200 text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                            }`}
                            onClick={() => onUpdateSelectedRichTextStyle({ textAlign: align })}
                          >
                            <Icon className="h-4 w-4" />
                          </button>
                        );
                      })}
                    </div>
                    <div className="h-6 w-px shrink-0 bg-slate-200 dark:bg-slate-700" />
                  </>
                ) : null}
                {quizElement && quizQuestionConfig ? (
                  <>
                    <button
                      type="button"
                      className="inline-flex shrink-0 items-center gap-1.5 rounded-md border border-slate-200 px-2.5 py-1 text-xs font-semibold text-slate-700 transition hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                      title={t("coursewareEditor.question.editInQuizSettings")}
                      onClick={() => onOpenQuizSettingsForQuestion(quizElement.quiz_question_id)}
                    >
                      <PencilLine className="h-3.5 w-3.5" aria-hidden />
                      {t("coursewareEditor.toolbar.editQuizQuestion")}
                    </button>
                    <button
                      type="button"
                      className="inline-flex shrink-0 items-center gap-1.5 rounded-md border border-slate-200 px-2.5 py-1 text-xs font-semibold text-slate-700 transition hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                      title={t("coursewareEditor.quizLayout.openEditor")}
                      onClick={() =>
                        onOpenQuizLayoutEditor(quizElement.quiz_question_id, quizElement.element_id)
                      }
                    >
                      <LayoutTemplate className="h-3.5 w-3.5" aria-hidden />
                      {t("coursewareEditor.toolbar.editQuizLayout")}
                    </button>
                  </>
                ) : null}
                {imageElement ? (
                  <>
                    <button
                      type="button"
                      disabled={!coursewareId}
                      className="inline-flex shrink-0 items-center gap-1.5 rounded-md border border-slate-200 px-2.5 py-1 text-xs font-semibold text-slate-700 transition hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                      onClick={() => setImageReplacePickerOpen(true)}
                    >
                      <ImageIcon className="h-3.5 w-3.5" aria-hidden />
                      {t("coursewareEditor.resources.replaceImage")}
                    </button>
                    <button
                      type="button"
                      disabled={!slide || !imageElement.source}
                      className="inline-flex shrink-0 items-center gap-1.5 rounded-md border border-slate-200 px-2.5 py-1 text-xs font-semibold text-slate-700 transition hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                      title={t("coursewareEditor.resources.setAsBackground")}
                      onClick={() => {
                        onSetSlideBackgroundImage(imageElement.source, imageElement.element_id);
                        toast.success(t("coursewareEditor.toast.setAsBackgroundDone"));
                      }}
                    >
                      <Wallpaper className="h-3.5 w-3.5" aria-hidden />
                      {t("coursewareEditor.resources.setAsBackground")}
                    </button>
                    <ToolbarInlineSelectField<ImageObjectFit>
                      label={t("coursewareEditor.common.objectFit")}
                      value={deriveImageObjectFit(imageElement)}
                      themeMode={themeMode}
                      options={IMAGE_OBJECT_FIT_VALUES.map((value) => ({
                        value,
                        label: t(`coursewareEditor.common.objectFit.${value}`),
                      }))}
                      onChange={(object_fit) =>
                        onUpdateSelectedElement((el) =>
                          el.element_type === "image"
                            ? {
                                ...el,
                                object_fit,
                                preserve_aspect_ratio: object_fit !== "fill",
                              }
                            : el,
                        )
                      }
                    />
                  </>
                ) : null}
                {videoElement ? (
                  <button
                    type="button"
                    disabled={!coursewareId}
                    className="inline-flex shrink-0 items-center gap-1.5 rounded-md border border-slate-200 px-2.5 py-1 text-xs font-semibold text-slate-700 transition hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                    onClick={() => setVideoReplacePickerOpen(true)}
                  >
                    <Video className="h-3.5 w-3.5" aria-hidden />
                    {t("coursewareEditor.resources.replaceVideo")}
                  </button>
                ) : null}
                {documentElement ? (
                  <button
                    type="button"
                    disabled={!coursewareId}
                    className="inline-flex shrink-0 items-center gap-1.5 rounded-md border border-slate-200 px-2.5 py-1 text-xs font-semibold text-slate-700 transition hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                    onClick={() => setDocumentReplacePickerOpen(true)}
                  >
                    {documentElement.element_type === "ppt" ? (
                      <Presentation className="h-3.5 w-3.5" aria-hidden />
                    ) : (
                      <FileIcon className="h-3.5 w-3.5" aria-hidden />
                    )}
                    {t("coursewareEditor.resources.replaceDocument")}
                  </button>
                ) : null}
                {documentElement?.element_type === "html" ? (
                  <button
                    type="button"
                    disabled={!slide || !documentElement.src.trim()}
                    className="inline-flex shrink-0 items-center gap-1.5 rounded-md border border-slate-200 px-2.5 py-1 text-xs font-semibold text-slate-700 transition hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
                    title={t("coursewareEditor.resources.setAsBackground")}
                    onClick={() => {
                      onSetSlideBackgroundHtml(
                        documentElement.src,
                        documentElement.content_zoom,
                        documentElement.element_id,
                      );
                      toast.success(t("coursewareEditor.toast.setAsBackgroundDone"));
                    }}
                  >
                    <Wallpaper className="h-3.5 w-3.5" aria-hidden />
                    {t("coursewareEditor.resources.setAsBackground")}
                  </button>
                ) : null}
                {audioElement ? (
                  <AudioSelectionInlineControls
                    element={audioElement}
                    onUpdateElement={onUpdateSelectedElement}
                    themeMode={themeMode}
                  />
                ) : null}
                <NonTextSelectionInlineControls
                  element={selectedElement}
                  slide={slide}
                  currentTime={currentTime}
                  onUpdateElement={onUpdateSelectedElement}
                  includeShapeColors
                  themeMode={themeMode}
                />
              </>
            )}
            <div className="flex shrink-0 items-center gap-0.5">
                {(
                  [
                    {
                      key: "transform" as const,
                      icon: <ToolbarTransformIcon />,
                      label: t("coursewareEditor.canvasToolbar.transform"),
                    },
                    {
                      key: "fade" as const,
                      icon: <ToolbarFadeIcon />,
                      label: t("coursewareEditor.canvasToolbar.fade"),
                    },
                    {
                      key: "highlight" as const,
                      icon: <Star className="h-4 w-4" />,
                      label: t("coursewareEditor.canvasToolbar.highlight"),
                    },
                    ...(isSlideCanvasAudioElement
                      ? []
                      : [
                          {
                            key: "keyframes" as const,
                            icon: <Diamond className="h-4 w-4" />,
                            label: t("coursewareEditor.common.timingKeyframes"),
                          },
                        ]),
                  ] as const
                ).map((item) => (
                  <button
                    key={item.key}
                    ref={(el) => {
                      triggerRefs.current[item.key] = el;
                    }}
                    type="button"
                    title={item.label}
                    aria-label={item.label}
                    className={canvasToolbarActionButtonClass(activePanel === item.key)}
                    onClick={() => togglePanel(item.key)}
                    aria-expanded={activePanel === item.key}
                    aria-pressed={activePanel === item.key}
                  >
                    {item.icon}
                  </button>
                ))}
            </div>
        </div>
      ) : null}
      {panelContent}
      {imageReplacePickerOpen && coursewareId && imageElement ? (
        <ToolbarAssetPickerDialog
          panel="image"
          coursewareId={coursewareId}
          themeMode={themeMode}
          pickMode="replace"
          onPick={handleReplaceImageAsset}
          onClose={() => setImageReplacePickerOpen(false)}
          onDragResourceStart={onDragResourceStart}
          onDragResourceEnd={onDragResourceEnd}
          uploadedAssetsRegistry={uploadedAssetsRegistry}
        />
      ) : null}
      {videoReplacePickerOpen && coursewareId && videoElement ? (
        <ToolbarAssetPickerDialog
          panel="video"
          coursewareId={coursewareId}
          themeMode={themeMode}
          pickMode="replace"
          onPick={handleReplaceVideoAsset}
          onClose={() => setVideoReplacePickerOpen(false)}
          onDragResourceStart={onDragResourceStart}
          onDragResourceEnd={onDragResourceEnd}
          uploadedAssetsRegistry={uploadedAssetsRegistry}
        />
      ) : null}
      {documentReplacePickerOpen && coursewareId && documentElement ? (
        <ToolbarAssetPickerDialog
          panel="document"
          coursewareId={coursewareId}
          themeMode={themeMode}
          pickMode="replace"
          onPick={handleReplaceDocumentAsset}
          onClose={() => setDocumentReplacePickerOpen(false)}
          onDragResourceStart={onDragResourceStart}
          onDragResourceEnd={onDragResourceEnd}
          uploadedAssetsRegistry={uploadedAssetsRegistry}
        />
      ) : null}
    </div>
  );
}

const COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS = "compact-timeline-playback-range";

const COMPACT_TIMELINE_ARROW_SEEK_BASE_MS = 100;
const COMPACT_TIMELINE_ARROW_SEEK_MAX_MS = 5_000;
const COMPACT_TIMELINE_ARROW_SEEK_INTERVAL_MS = 80;
const COMPACT_TIMELINE_ARROW_SEEK_ACCEL_RAMP_MS = 2_000;

const compactTimelineArrowSeekDelta = (holdMs: number): number => {
  const ramp = clamp(holdMs / COMPACT_TIMELINE_ARROW_SEEK_ACCEL_RAMP_MS, 0, 1);
  return Math.round(
    COMPACT_TIMELINE_ARROW_SEEK_BASE_MS +
      ramp * (COMPACT_TIMELINE_ARROW_SEEK_MAX_MS - COMPACT_TIMELINE_ARROW_SEEK_BASE_MS),
  );
};

const COMPACT_TIMELINE_PLAYBACK_RANGE_STYLES = `
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS} {
  width: 100%;
  height: 12px;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  cursor: pointer;
  outline: none;
}
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}:focus,
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}:focus-visible {
  outline: none;
  box-shadow: none;
}
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}::-webkit-slider-runnable-track {
  height: 3px;
  border-radius: 999px;
  background: linear-gradient(
    to right,
    #3b82f6 0 var(--compact-playback-progress, 0%),
    rgba(51, 65, 85, 0.82) var(--compact-playback-progress, 0%) 100%
  );
}
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}::-moz-range-track {
  height: 3px;
  border-radius: 999px;
  background: rgba(51, 65, 85, 0.82);
}
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}::-moz-range-progress {
  height: 3px;
  border-radius: 999px;
  background: #3b82f6;
}
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}::-webkit-slider-thumb {
  width: 11px;
  height: 11px;
  margin-top: -4px;
  border: 2px solid #0f172a;
  border-radius: 999px;
  appearance: none;
  -webkit-appearance: none;
  background: #fb7185;
  box-shadow: 0 0 0 1px rgba(251, 113, 133, 0.38);
}
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}::-moz-range-thumb {
  width: 11px;
  height: 11px;
  border: 2px solid #0f172a;
  border-radius: 999px;
  background: #fb7185;
  box-shadow: 0 0 0 1px rgba(251, 113, 133, 0.38);
}
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}:hover::-webkit-slider-thumb,
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}:focus-visible::-webkit-slider-thumb {
  background: #fda4af;
}
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}:hover::-moz-range-thumb,
.${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS}:focus-visible::-moz-range-thumb {
  background: #fda4af;
}
`;

function CompactTimelinePlaybackControls({
  currentTime,
  duration,
  flowPausePoints,
  selectedFlowPauseId,
  onUpdateFlowPausePoint,
  onSelectFlowPause,
  onDeleteFlowPause,
  onCaptureHistorySnapshot,
  onCommitHistorySnapshot,
  isPlaying,
  isPlayLoading,
  playheadRef,
  playheadFromRef,
  playheadClockRunning,
  onPlayPause,
  onSeek,
  narrationButtonMode,
  onOpenNarrationModal,
}: {
  currentTime: number;
  duration: number;
  flowPausePoints: SlideFlowPausePoint[];
  selectedFlowPauseId: string | null;
  onUpdateFlowPausePoint: (
    pauseId: string,
    atMs: number,
    options?: { recordHistory?: boolean },
  ) => void;
  onSelectFlowPause: (pauseId: string | null) => void;
  onDeleteFlowPause: (pauseId: string) => void;
  onCaptureHistorySnapshot?: () => Scene;
  onCommitHistorySnapshot?: (snapshot: Scene) => void;
  isPlaying: boolean;
  isPlayLoading: boolean;
  playheadRef: RefObject<number>;
  playheadFromRef: boolean;
  playheadClockRunning: boolean;
  onPlayPause: () => void;
  onSeek: (ms: number) => void;
  narrationButtonMode: "add" | "edit";
  onOpenNarrationModal: () => void;
}) {
  const { t } = useI18nNew();
  const compactTrackRef = useRef<HTMLLabelElement | null>(null);
  const playheadMs = useEditorPlayheadMs(
    playheadFromRef,
    playheadClockRunning,
    currentTime,
    playheadRef,
  );
  const maxDuration = Math.max(1, duration);
  const progressPercent =
    duration > 0 ? clamp((playheadMs / duration) * 100, 0, 100) : 0;
  const playheadSeekRef = useRef(playheadMs);
  playheadSeekRef.current = playheadMs;
  const arrowHoldRef = useRef<{
    direction: -1 | 1;
    holdStart: number;
    intervalId: ReturnType<typeof setInterval>;
  } | null>(null);

  const stopArrowHold = useCallback((): void => {
    const hold = arrowHoldRef.current;
    if (!hold) return;
    clearInterval(hold.intervalId);
    arrowHoldRef.current = null;
  }, []);

  useEffect(() => () => stopArrowHold(), [stopArrowHold]);

  const seekByArrow = useCallback(
    (direction: -1 | 1): void => {
      stopArrowHold();
      const holdStart = Date.now();
      const tick = (): void => {
        const holdMs = Date.now() - holdStart;
        const delta = compactTimelineArrowSeekDelta(holdMs);
        const next = clamp(playheadSeekRef.current + direction * delta, 0, maxDuration);
        if (Math.abs(next - playheadSeekRef.current) < 0.5) {
          stopArrowHold();
          return;
        }
        playheadSeekRef.current = next;
        onSeek(next);
      };
      tick();
      arrowHoldRef.current = {
        direction,
        holdStart,
        intervalId: setInterval(tick, COMPACT_TIMELINE_ARROW_SEEK_INTERVAL_MS),
      };
    },
    [maxDuration, onSeek, stopArrowHold],
  );

  const compactFlowPauseClientXToLocalMs = useCallback(
    (clientX: number): number => {
      const track = compactTrackRef.current;
      if (!track) return 0;
      const rect = track.getBoundingClientRect();
      const ratio = clamp((clientX - rect.left) / Math.max(1, rect.width), 0, 1);
      return ratio * maxDuration;
    },
    [maxDuration],
  );

  return (
    <div className="absolute inset-0 px-3" data-hotkey-scope="timeline">
      <style>{COMPACT_TIMELINE_PLAYBACK_RANGE_STYLES}</style>
      <div className="flex h-full w-full items-center">
        <div className="grid w-full grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-x-2">
          <div className="flex items-center gap-0.5">
            <IconButton
              icon={<SkipBack className="h-4 w-4" />}
              label={t("coursewareEditor.timeline.rewind")}
              onClick={() => onSeek(0)}
            />
            <IconButton
              icon={isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
              label={
                isPlayLoading
                  ? t("coursewareEditor.common.loading")
                  : isPlaying
                    ? t("coursewareEditor.common.pause")
                    : t("coursewareEditor.common.play")
              }
              loading={isPlayLoading}
              onClick={onPlayPause}
            />
            <IconButton
              icon={<SkipForward className="h-4 w-4" />}
              label={t("coursewareEditor.timeline.seekEnd")}
              onClick={() => onSeek(duration)}
            />
          </div>
          <div className="flex min-w-0 flex-col justify-center gap-0.5 pt-1">
            <EditorTimelinePlayheadClock
              playheadRef={playheadRef}
              playheadFromRef={playheadFromRef}
              playheadClockRunning={playheadClockRunning}
              pausedTimeMs={currentTime}
              duration={duration}
              className="font-mono text-xs leading-none tabular-nums text-slate-600 dark:text-slate-300"
            />
            <label
              ref={compactTrackRef}
              className="relative flex h-3 w-full items-center mt-1"
              style={
                {
                  "--compact-playback-progress": `${progressPercent.toFixed(2)}%`,
                } as CSSProperties
              }
              aria-label={t("coursewareEditor.timeline.compactProgress")}
            >
              <input
                type="range"
                min={0}
                max={maxDuration}
                step={10}
                value={clamp(playheadMs, 0, maxDuration)}
                onChange={(e) => onSeek(Number(e.currentTarget.value))}
                onKeyDown={(e) => {
                  if (
                    (e.key === "Delete" || e.key === "Backspace") &&
                    selectedFlowPauseId
                  ) {
                    e.preventDefault();
                    onDeleteFlowPause(selectedFlowPauseId);
                    return;
                  }
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    onPlayPause();
                    return;
                  }
                  if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
                    e.preventDefault();
                    if (e.repeat) return;
                    seekByArrow(e.key === "ArrowLeft" ? -1 : 1);
                  }
                }}
                onKeyUp={(e) => {
                  if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
                    stopArrowHold();
                  }
                }}
                onBlur={stopArrowHold}
                className={`${COMPACT_TIMELINE_PLAYBACK_RANGE_CLASS} outline-none`}
                aria-label={t("coursewareEditor.timeline.compactProgress")}
              />
              <FlowPauseTimelineMarkers
                points={flowPausePoints}
                durationMs={maxDuration}
                layoutDurationMs={maxDuration}
                clientXToLocalMs={compactFlowPauseClientXToLocalMs}
                onUpdatePoint={(pauseId, atMs) =>
                  onUpdateFlowPausePoint(pauseId, atMs, { recordHistory: false })
                }
                onCaptureHistorySnapshot={onCaptureHistorySnapshot}
                onCommitHistorySnapshot={onCommitHistorySnapshot}
                selectedPauseId={selectedFlowPauseId}
                onSelectPause={onSelectFlowPause}
                onDeletePause={onDeleteFlowPause}
                variant="compact"
                dragLabel={t("coursewareEditor.timeline.flowPauseDrag")}
              />
            </label>
          </div>
          <div className="justify-self-end">
            <NarrationButton
              mode={narrationButtonMode}
              onClick={onOpenNarrationModal}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

// ---------- slide panel ----------

interface SlidePanelProps {
  slides: SlideElement[];
  transitions: Transition[];
  selectedIndex: number;
  themeMode: EditorThemeMode;
  stageCanvasScale: number;
  editorQuiz?: QuizConfig | null;
  vtuberSnapshotByElementId: Record<string, string>;
  vtuberSnapshotBySourceKey: Record<string, string>;
  onSelect: (index: number) => void;
  onAdd: () => void;
  onDuplicate: (index: number) => void;
  onRemove: (index: number) => void;
  onRename: (index: number, name: string) => void;
  onTransitionChange: (index: number, transition: Transition) => void;
  onReorder: (from: number, to: number) => void;
}

function SlidePanel({
  slides,
  transitions,
  selectedIndex,
  themeMode,
  stageCanvasScale,
  editorQuiz = null,
  vtuberSnapshotByElementId,
  vtuberSnapshotBySourceKey,
  onSelect,
  onAdd,
  onDuplicate,
  onRemove,
  onRename,
  onTransitionChange,
  onReorder,
}: SlidePanelProps) {
  const editorLabels = useCoursewareEditorLabels();
  const { t, t: translateFn } = editorLabels;
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [draggingIndex, setDraggingIndex] = useState<number | null>(null);
  const [removeConfirm, setRemoveConfirm] = useState<{ index: number; rect: DOMRect } | null>(null);
  const [thumbnailNode, setThumbnailNode] = useState<HTMLDivElement | null>(null);
  const [thumbnailSize, setThumbnailSize] = useState({ width: 0, height: 0 });
  const listScrollRef = useRef<HTMLDivElement>(null);
  const prevSlideCountRef = useRef(slides.length);

  useLayoutEffect(() => {
    const grew = slides.length > prevSlideCountRef.current;
    prevSlideCountRef.current = slides.length;
    if (!grew || selectedIndex !== slides.length - 1) return;
    const el = listScrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [slides.length, selectedIndex]);

  useLayoutEffect(() => {
    if (!thumbnailNode) return;
    const update = (): void => {
      setThumbnailSize({
        width: Math.max(1, thumbnailNode.clientWidth),
        height: Math.max(1, thumbnailNode.clientHeight),
      });
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(thumbnailNode);
    return () => observer.disconnect();
  }, [thumbnailNode]);

  return (
    <aside className="flex h-full min-h-0 w-[220px] min-w-0 shrink-0 flex-col border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900">
      <div className="border-b border-slate-200 dark:border-slate-800 px-3 py-2">
        <span className="text-xs font-semibold text-slate-400 dark:text-slate-500">
          {t("coursewareEditor.common.scenesCount", { count: slides.length })}
        </span>
      </div>
      <div ref={listScrollRef} className="min-h-0 flex-1 overflow-y-auto p-2">
        <ol className="space-y-2">
          {slides.map((slide, index) => {
            const durationMs = Math.max(0, slide.timeline.end_at - slide.timeline.start_at);
            const durationSeconds = durationMs / 1000;
            const durationSecondsLabel = Number.isInteger(durationSeconds)
              ? String(durationSeconds)
              : durationSeconds.toFixed(1);
            return (
            <Fragment key={slide.element_id}>
            <li
              draggable
              onDragStart={() => setDraggingIndex(index)}
              onDragOver={(e) => {
                e.preventDefault();
              }}
              onDrop={() => {
                if (draggingIndex !== null && draggingIndex !== index) {
                  onReorder(draggingIndex, index);
                }
                setDraggingIndex(null);
              }}
              className={`group rounded-md border-2 transition ${
                index === selectedIndex
                  ? "border-blue-500 bg-blue-50 dark:bg-slate-800"
                  : "border-transparent hover:border-slate-300 hover:bg-slate-100 dark:hover:border-slate-700 dark:hover:bg-slate-800/60"
              }`}
            >
              <div
                role="button"
                tabIndex={0}
                className="flex w-full cursor-pointer items-center gap-2 px-2 py-2 text-left outline-0 focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-inset"
                onClick={() => onSelect(index)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    onSelect(index);
                  }
                }}
              >
                <span className="w-6 shrink-0 text-center text-[10px] font-semibold text-slate-400 dark:text-slate-500">
                  {String(index + 1).padStart(2, "0")}
                </span>
                <div
                  ref={index === selectedIndex ? setThumbnailNode : undefined}
                  className="pointer-events-none relative isolate aspect-video w-full overflow-hidden rounded border border-slate-300 dark:border-slate-700 **:pointer-events-none!"
                  style={{ backgroundColor: slide.background_color }}
                >
                  {(() => {
                    const s = getSlideBackgroundImageLayerStyle(
                      slide.background_image_url,
                      slide.background_image_fit,
                    );
                    return s ? (
                      <div className="pointer-events-none absolute inset-0 z-0" style={s} />
                    ) : null;
                  })()}
                  <SlideBackgroundHtmlLayer
                    src={slide.background_html_src}
                    slideId={slide.element_id}
                    contentZoom={slide.background_html_content_zoom}
                    scale={
                      thumbnailSize.width > 0
                        ? thumbnailSize.width / SLIDE_LOGICAL_WIDTH
                        : SLIDE_THUMBNAIL_SCALE
                    }
                    targetSizePx={thumbnailSize.width > 0 ? thumbnailSize : undefined}
                    zClassName="z-1"
                  />
                  <span
                    className="pointer-events-none absolute right-1 top-1 rounded bg-black/50 px-1.5 py-0.5 text-[8px] font-semibold tabular-nums text-white dark:bg-slate-950/80"
                    style={{ zIndex: SLIDE_PREVIEW_CHROME_Z_INDEX }}
                  >
                    {durationSecondsLabel}s
                  </span>
                  {(() => {
                    const snapshotAt = pickMostCompleteSnapshotTime(slide);
                    const thumbnailScaleX =
                      thumbnailSize.width > 0
                        ? thumbnailSize.width / SLIDE_LOGICAL_WIDTH
                        : SLIDE_THUMBNAIL_SCALE;
                    const thumbnailScaleY =
                      thumbnailSize.height > 0
                        ? thumbnailSize.height / SLIDE_LOGICAL_HEIGHT
                        : SLIDE_THUMBNAIL_SCALE;
                    const thumbnailScale = Math.min(thumbnailScaleX, thumbnailScaleY);
                    return buildQuestionStackRenderUnits(slide).map((unit) => {
                      const renderThumb = (el: CourseElement, stackZ: number) => {
                        if (!isElementVisibleAtTimeInSlide(el, snapshotAt, slide)) return null;
                        const t = interpolateElementTransformInSlide(el, snapshotAt, slide);
                        if (t.opacity <= 0.01) return null;
                        const thumbW = t.size.width * thumbnailScaleX;
                        const thumbH = t.size.height * thumbnailScaleY;
                        return (
                          <div
                            key={el.element_id}
                            className="absolute overflow-hidden rounded-[1px]"
                            style={{
                              left: t.position.x * thumbnailScaleX,
                              top: t.position.y * thumbnailScaleY,
                              width: thumbW,
                              height: thumbH,
                              opacity: clamp(t.opacity, 0, 1),
                              transform: t.rotation_deg ? `rotate(${t.rotation_deg}deg)` : undefined,
                              transformOrigin: "center",
                              zIndex: resolveEditorThumbnailStackZ(el, stackZ),
                            }}
                          >
                            {renderElementContent(
                              el,
                              t.size.width,
                              t.size.height,
                              thumbnailScale,
                              "thumbnail",
                              {
                                vtuberSnapshotByElementId,
                                vtuberSnapshotBySourceKey,
                                currentTime: snapshotAt,
                                thumbnailViewportPx: { width: thumbW, height: thumbH },
                                htmlReferenceLayoutScale: stageCanvasScale,
                                editorQuiz,
                                translate: translateFn,
                              },
                            )}
                          </div>
                        );
                      };
                      return renderThumb(unit.element, unit.element.style.z_index);
                    });
                  })()}
                </div>
              </div>
              <div className="flex items-center justify-between px-2 pb-1.5">
                {editingIndex === index ? (
                  <input
                    autoFocus
                    defaultValue={resolveSlideDisplayName(slide.name, index, t)}
                    onBlur={(e) => {
                      const next = e.currentTarget.value.trim();
                      if (isAutoGeneratedSlideName(slide.name)) {
                        // Unchanged or cleared input keeps the slide unnamed so the
                        // label stays localized instead of persisting the display text.
                        if (next && next !== resolveSlideDisplayName(slide.name, index, t)) {
                          onRename(index, next);
                        }
                      } else {
                        onRename(index, next || slide.name);
                      }
                      setEditingIndex(null);
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") e.currentTarget.blur();
                      if (e.key === "Escape") setEditingIndex(null);
                    }}
                    className="flex-1 rounded bg-slate-50 dark:bg-slate-950 px-1.5 py-0.5 text-[11px] text-slate-800 dark:text-slate-200 outline-none ring-1 ring-blue-500"
                  />
                ) : (
                  <button
                    type="button"
                    className="flex-1 truncate text-left text-[11px] text-slate-600 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white"
                    onDoubleClick={() => setEditingIndex(index)}
                    onClick={() => onSelect(index)}
                  >
                    {resolveSlideDisplayName(slide.name, index, t)}
                  </button>
                )}
                <div className="flex opacity-0 transition group-hover:opacity-100">
                  <IconButton
                    icon={<Copy className="h-3 w-3" />}
                    label={t("coursewareEditor.common.copy")}
                    onClick={() => onDuplicate(index)}
                  />
                  <IconButton
                    icon={<Trash2 className="h-3 w-3" />}
                    label={t("coursewareEditor.common.delete")}
                    onClick={(e) => {
                      e.stopPropagation();
                      if (slides.length <= 1) return;
                      setRemoveConfirm({ index, rect: e.currentTarget.getBoundingClientRect() });
                    }}
                    disabled={slides.length <= 1}
                  />
                </div>
              </div>
            </li>
            {index < slides.length - 1 ? (
              <li className="px-2">
                <div className="courseware-editor-slide-transition flex items-center gap-2 px-2">
                  <span className="courseware-editor-slide-transition-label shrink-0 text-[10px] font-medium text-slate-400 dark:text-slate-500">
                    {t("coursewareEditor.transitions.slidePanelLabel")}
                  </span>
                  <select
                    className="courseware-editor-slide-transition-select min-w-0 flex-1 rounded border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-900 px-1.5 py-1 text-[11px] text-slate-800 dark:text-slate-200 outline-none focus:border-blue-500"
                    value={transitions[index] ?? Transitions.NONE}
                    onChange={(event) =>
                      onTransitionChange(index, event.currentTarget.value as Transition)
                    }
                    aria-label={t("coursewareEditor.transitions.betweenSlidesAria", {
                      from: index + 1,
                      to: index + 2,
                    })}
                  >
                    {TRANSITION_VALUES.map((transition) => (
                      <option key={transition} value={transition}>
                        {editorLabels.transitions[transition]}
                      </option>
                    ))}
                  </select>
                </div>
              </li>
            ) : null}
            </Fragment>
            );
          })}
        </ol>
      </div>
      <div className="shrink-0 border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 p-2">
        <button
          type="button"
          className="flex w-full items-center justify-center gap-1 rounded-md border border-dashed border-slate-300 dark:border-slate-700 px-2 py-2 text-[11px] text-slate-500 dark:text-slate-400 transition hover:border-blue-400 hover:bg-blue-500/10 hover:text-blue-700 dark:hover:border-blue-500 dark:hover:bg-blue-500/15 dark:hover:text-blue-300"
          onClick={onAdd}
        >
          <Plus className="h-3.5 w-3.5" />
          {t("coursewareEditor.common.add")}
        </button>
      </div>
      <DeletePageConfirmBubble
        open={removeConfirm !== null}
        anchorRect={removeConfirm?.rect ?? null}
        themeMode={themeMode}
        onCancel={() => setRemoveConfirm(null)}
        onConfirm={() => {
          if (removeConfirm === null) return;
          onRemove(removeConfirm.index);
          setRemoveConfirm(null);
        }}
      />
    </aside>
  );
}

// ---------- stage area ----------

const STAGE_HIGHLIGHT_OVERLAY_Z_INDEX = 9999;
const STAGE_VTUBER_Z_INDEX_BASE = STAGE_HIGHLIGHT_OVERLAY_Z_INDEX + 1;
const STAGE_NARRATION_Z_INDEX_BASE = STAGE_HIGHLIGHT_OVERLAY_Z_INDEX + 1000;

function HighlightOverlay({ regions }: { regions: HighlightRegion[] }) {
  if (regions.length === 0) return null;
  const primary = regions.slice().sort((a, b) => b.zIndex - a.zIndex)[0];
  const overlayOpacity = Math.max(
    ...regions.map((region) => region.highlight.overlay_opacity * region.opacityMultiplier),
  );
  const maskPath = [
    `M0 0H${SLIDE_LOGICAL_WIDTH}V${SLIDE_LOGICAL_HEIGHT}H0Z`,
    ...regions.map((region) =>
      roundedRectPath(
        region.x,
        region.y,
        region.width,
        region.height,
        region.highlight.border_radius_px,
      ),
    ),
  ].join(" ");
  return (
    <svg
      className="pointer-events-none absolute inset-0"
      viewBox={`0 0 ${SLIDE_LOGICAL_WIDTH} ${SLIDE_LOGICAL_HEIGHT}`}
      preserveAspectRatio="none"
      style={{ zIndex: STAGE_HIGHLIGHT_OVERLAY_Z_INDEX }}
    >
      <path
        d={maskPath}
        fill={primary.highlight.overlay_color}
        fillOpacity={overlayOpacity}
        fillRule="evenodd"
      />
    </svg>
  );
}

function EditorPlaybackGlobalAudioTracks({
  coursewareId,
  tracks,
  sceneTimeOffsetMs,
  pausedTimeMs,
  playheadRef,
  playheadFromRef,
  playheadClockRunning,
  isPlaying,
  playIntent,
  onTrackBufferingChange,
}: {
  coursewareId?: string;
  tracks: AudioElement[];
  sceneTimeOffsetMs: number;
  pausedTimeMs: number;
  playheadRef: RefObject<number>;
  playheadFromRef: boolean;
  playheadClockRunning: boolean;
  isPlaying: boolean;
  playIntent: boolean;
  onTrackBufferingChange: (elementId: string, buffering: boolean) => void;
}) {
  return (
    <GlobalAudioTracks
      coursewareId={coursewareId}
      tracks={tracks}
      sceneCurrentTime={sceneTimeOffsetMs + pausedTimeMs}
      sceneTimeOffsetMs={sceneTimeOffsetMs}
      playheadRef={playheadRef}
      playheadFromRef={playheadFromRef}
      playheadClockRunning={playheadClockRunning}
      pausedSceneTimeMs={pausedTimeMs}
      isPlaying={isPlaying}
      playIntent={playIntent}
      onTrackBufferingChange={onTrackBufferingChange}
    />
  );
}

type EditorVtuberPlacement = {
  sourceKey: string;
  element: VtuberElement;
  slide: SlideElement;
  elementId: string;
};

interface StageAreaProps {
  coursewareId: string;
  quiz?: QuizConfig | null;
  slide: SlideElement | undefined;
  allSlides: SlideElement[];
  currentTime: number;
  playheadRef: RefObject<number>;
  playheadFromRef: boolean;
  playheadClockRunning: boolean;
  isPlaying: boolean;
  onPlaybackLoadingTokenChange: (token: string, isLoading: boolean) => void;
  onNarrationPlayheadDriveChange: (localMs: number | null) => void;
  vtuberSnapshotByElementId: Record<string, string>;
  vtuberSnapshotBySourceKey: Record<string, string>;
  onCaptureVtuberSnapshot: (elementId: string, dataUrl: string) => void;
  selectedElementIds: string[];
  selectedRichText: { elementId: string; path: RichTextPath } | null;
  draggedResource: DraggedResource | null;
  onSelectElement: (id: string | null, options?: { toggle?: boolean }) => void;
  onSelectElements: (ids: string[], options?: { toggle?: boolean }) => void;
  onDropResource: (position: { x: number; y: number }) => void;
  onDropFiles?: (files: File[], position: { x: number; y: number }) => void;
  onCommitTransform: (elementId: string, transform: LiveTransform) => void;
  onUpdateSlide: (
    updater: (c: SlideElement) => SlideElement,
    options?: { recordHistory?: boolean },
  ) => void;
  onUpdateElement: (
    id: string,
    updater: (el: CourseElement) => CourseElement,
    options?: { recordHistory?: boolean },
  ) => void;
  onSelectRichText: (selection: { elementId: string; path: RichTextPath } | null) => void;
  onSvgTextStyleSnapshot?: (snapshot: SvgTextStyleSnapshot | null) => void;
  svgTextStylePatch?: { nonce: number; patch: SvgTextStylePatch } | null;
  /** Question audio only: drives the `<audio controls>` on the canvas (not the narration track). */
  quizStemAutoplay?: { wrapperId: string; playUrl: string; nonce: number } | null;
  /** id of the question wrapper whose quiz pause interval the timeline is in (used to reset the canvas player when the pause leaves this question). */
  activeQuizPauseWrapperId?: string | null;
  /** The globally hidden question narration `<audio>` (shared with the automatic playback at quiz pauses). */
  quizContentNarrationAudioRef?: RefObject<HTMLAudioElement | null>;
  /** While question narration audio plays, drives the matching avatar's lip movements (the same RMS lip-sync source as slide narration). */
  quizContentNarrationLipSyncTarget?: { url: string; vtuberElementId: string } | null;
  /** The narration preview `<audio>` in the quiz settings dialog. */
  quizSettingsContentNarrationAudioRef?: RefObject<HTMLAudioElement | null>;
  /** Lip target while the dialog previews narration (mutually exclusive with timeline narration). */
  quizSettingsContentNarrationLipSyncTarget?: { url: string; vtuberElementId: string } | null;
  /** Inline manual marking mode on the canvas */
  manualMarkMode?: boolean;
  manualMarkRegions?: readonly CoursewareManualMarkRegion[];
  pendingManualMark?: CoursewareManualMarkPending | null;
  onPendingManualMarkCreate?: (pending: CoursewareManualMarkPending) => void;
  /** Open the quiz settings dialog located at the given question (the canvas badge edit button). */
  onOpenQuizSettingsForQuestion?: (questionId: string) => void;
  /** Open the visual quiz layout editing dialog (double-click a question or the badge's layout button). */
  onOpenQuizLayoutEditor?: (questionId: string, elementId: string) => void;
  onDuplicateElement?: (elementId: string) => void;
  onRequestDeleteElement?: (elementId: string) => void;
  /** Current zoom of the main canvas, so the left slide list HTML thumbnails align their iframe viewport. */
  onCanvasScaleChange?: (scale: number) => void;
  onOpenElementContextMenu?: OpenElementContextMenuFn;
  onCloseElementContextMenu?: () => void;
}

function editorSubtreePropsEqual<T extends { currentTime: number; playheadFromRef: boolean }>(
  prev: T,
  next: T,
): boolean {
  const keys = Object.keys(prev) as (keyof T)[];
  for (const key of keys) {
    if (key === "currentTime" && prev.playheadFromRef && next.playheadFromRef) continue;
    if (prev[key] !== next[key]) return false;
  }
  return true;
}

const StageArea = memo(function StageArea({
  coursewareId,
  quiz = null,
  slide,
  allSlides,
  currentTime,
  playheadRef,
  playheadFromRef,
  playheadClockRunning,
  isPlaying,
  onPlaybackLoadingTokenChange,
  onNarrationPlayheadDriveChange,
  vtuberSnapshotByElementId,
  vtuberSnapshotBySourceKey,
  onCaptureVtuberSnapshot,
  selectedElementIds,
  selectedRichText,
  draggedResource,
  onSelectElement,
  onSelectElements,
  onDropResource,
  onDropFiles,
  onCommitTransform,
  onUpdateSlide,
  onUpdateElement,
  onSelectRichText,
  onSvgTextStyleSnapshot,
  svgTextStylePatch = null,
  quizStemAutoplay = null,
  activeQuizPauseWrapperId = null,
  quizContentNarrationAudioRef,
  quizContentNarrationLipSyncTarget = null,
  quizSettingsContentNarrationAudioRef,
  quizSettingsContentNarrationLipSyncTarget = null,
  manualMarkMode = false,
  manualMarkRegions = [],
  pendingManualMark = null,
  onPendingManualMarkCreate,
  onOpenQuizSettingsForQuestion,
  onOpenQuizLayoutEditor,
  onDuplicateElement,
  onRequestDeleteElement,
  onCanvasScaleChange,
  onOpenElementContextMenu,
  onCloseElementContextMenu,
}: StageAreaProps) {
  const editorLabels = useCoursewareEditorLabels();
  const { t } = editorLabels;
  const playheadMs = useEditorPlayheadMs(
    playheadFromRef,
    playheadClockRunning,
    currentTime,
    playheadRef,
  );
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [isFileDragOver, setIsFileDragOver] = useState(false);
  const [containerSize, setContainerSize] = useState({ w: 1, h: 1 });
  const [zoom, setZoom] = useState<"fit" | number>("fit");
  const [pan, setPan] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [liveTransforms, setLiveTransforms] = useState<Record<string, LiveTransform>>({});
  /** Kept in sync with state, so a pointerup in the same frame as the last pointermove doesn't read a stale live pose */
  const liveTransformsRef = useRef<Record<string, LiveTransform>>({});
  const updateLiveTransforms = useCallback(
    (updater: (prev: Record<string, LiveTransform>) => Record<string, LiveTransform>): void => {
      setLiveTransforms((prev) => {
        const next = updater(prev);
        liveTransformsRef.current = next;
        return next;
      });
    },
    [],
  );
  const [alignSnapGuides, setAlignSnapGuides] = useState<EditorAlignSnapGuide[]>([]);
  const [editingElementId, setEditingElementId] = useState<string | null>(null);
  const [textEditCaretPoint, setTextEditCaretPoint] = useState<{
    clientX: number;
    clientY: number;
  } | null>(null);
  const [svgEditState, setSvgEditState] = useState<CoursewareSvgEditState>(defaultSvgEditState());
  const [richEditState, setRichEditState] = useState<CoursewareRichEditState>(defaultRichEditState());

  useEffect(() => {
    if (!manualMarkMode) return;
    setEditingElementId(null);
    setTextEditCaretPoint(null);
    setSvgEditState(defaultSvgEditState());
    setRichEditState(defaultRichEditState());
    setMarqueeRect(null);
    setHoveredLockedElementId(null);
  }, [manualMarkMode]);
  const [manualMarkHintHidden, setManualMarkHintHidden] = useState(false);
  useEffect(() => {
    if (!manualMarkMode) setManualMarkHintHidden(false);
  }, [manualMarkMode]);
  const [vtuberLipSyncByElementId, setVtuberLipSyncByElementId] = useState<Record<string, number>>({});
  const [vtuberModelLoadedBySourceKey, setVtuberModelLoadedBySourceKey] = useState<
    Record<string, boolean>
  >({});
  const handleVtuberSourceModelLoading = useCallback((sourceKey: string, loading: boolean): void => {
    if (!loading) return;
    setVtuberModelLoadedBySourceKey((prev) =>
      prev[sourceKey] === false ? prev : { ...prev, [sourceKey]: false },
    );
  }, []);
  const handleVtuberSourceModelLoaded = useCallback((sourceKey: string): void => {
    setVtuberModelLoadedBySourceKey((prev) => (prev[sourceKey] ? prev : { ...prev, [sourceKey]: true }));
  }, []);
  const [hoveredLockedElementId, setHoveredLockedElementId] = useState<string | null>(null);
  const groupMoveRef = useRef<null | {
    leaderId: string;
    leaderStart: {
      x: number;
      y: number;
      width: number;
      height: number;
      rotation: number;
    };
    baseById: Record<string, LiveTransform>;
  }>(null);
  useLayoutEffect(() => {
    if (!containerRef.current) return;
    const el = containerRef.current;
    const update = (): void => {
      const rect = el.getBoundingClientRect();
      setContainerSize({ w: rect.width, h: rect.height });
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const padding = 40;
  const fitScale = Math.min(
    (containerSize.w - padding * 2) / SLIDE_LOGICAL_WIDTH,
    (containerSize.h - padding * 2) / SLIDE_LOGICAL_HEIGHT,
  );
  const scale = zoom === "fit" ? Math.max(0.05, fitScale) : zoom;
  const stageW = SLIDE_LOGICAL_WIDTH * scale;
  const stageH = SLIDE_LOGICAL_HEIGHT * scale;

  useLayoutEffect(() => {
    onCanvasScaleChange?.(scale);
  }, [scale, onCanvasScaleChange]);

  // "canPan" when the zoomed slide exceeds the viewport — pan (drag) navigates; no native scrollbars.
  // Below that threshold the stage always stays perfectly centered, so we ignore any lingering pan.
  const canPan = stageW > containerSize.w + 1 || stageH > containerSize.h + 1;
  const effectivePan = canPan ? pan : { x: 0, y: 0 };
  const stageLayoutKey = `${scale}:${effectivePan.x}:${effectivePan.y}`;

  // Whenever the stage fits the container again, snap pan back to origin to avoid ghost offsets.
  useEffect(() => {
    if (!canPan && (pan.x !== 0 || pan.y !== 0)) {
      setPan({ x: 0, y: 0 });
    }
  }, [canPan, pan.x, pan.y]);

  // Exit text-edit mode when switching slides or when the edited element disappears.
  useEffect(() => {
    if (!editingElementId) return;
    const stillExists = slide?.children_elements.some((el) => el.element_id === editingElementId);
    if (!stillExists) {
      setEditingElementId(null);
      setTextEditCaretPoint(null);
      setSvgEditState(defaultSvgEditState());
      setRichEditState(defaultRichEditState());
    }
  }, [slide, editingElementId]);

  // Selecting a different element cancels inline editing.
  useEffect(() => {
    if (editingElementId && !selectedElementIds.includes(editingElementId)) {
      setEditingElementId(null);
      setTextEditCaretPoint(null);
      setSvgEditState(defaultSvgEditState());
      setRichEditState(defaultRichEditState());
    }
  }, [selectedElementIds, editingElementId]);

  useEffect(() => {
    const vtuberIds = new Set(
      (slide?.children_elements ?? [])
        .filter((el): el is VtuberElement => el.element_type === "vtuber")
        .map((el) => el.element_id),
    );
    setVtuberLipSyncByElementId((prev) => {
      const next: Record<string, number> = {};
      let changed = false;
      for (const [elementId, value] of Object.entries(prev)) {
        if (vtuberIds.has(elementId)) next[elementId] = value;
        else changed = true;
      }
      return changed ? next : prev;
    });
  }, [slide]);

  const zoomState = useRef({ zoom, pan: effectivePan, fitScale, containerSize, canPan });
  zoomState.current = { zoom, pan: effectivePan, fitScale, containerSize, canPan };

  const [isPanning, setIsPanning] = useState(false);
  const stageRef = useRef<HTMLDivElement | null>(null);
  const [marqueeRect, setMarqueeRect] = useState<EditorAxisRect | null>(null);

  const startPan = useCallback((clientX: number, clientY: number): void => {
    const startPanPos = { ...zoomState.current.pan };
    setIsPanning(true);
    const onMove = (ev: PointerEvent): void => {
      setPan({
        x: startPanPos.x + (ev.clientX - clientX),
        y: startPanPos.y + (ev.clientY - clientY),
      });
    };
    const onUp = (): void => {
      setIsPanning(false);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  }, []);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const onWheel = (e: WheelEvent): void => {
      const target = e.target as HTMLElement | null;
      if (target?.closest('[data-role="minimap"]')) return;

      if (target) {
        if (
          target.closest('[contenteditable="true"]') ||
          target.closest("textarea") ||
          target.closest("select") ||
          target.closest("iframe")
        ) {
          return;
        }
        const EPS = 2;
        let node: HTMLElement | null = target;
        while (node && el.contains(node)) {
          if (node === el) break;
          const st = getComputedStyle(node);
          const oy = st.overflowY;
          const ox = st.overflowX;
          const canY =
            (oy === "auto" || oy === "scroll" || oy === "overlay") &&
            node.scrollHeight > node.clientHeight + EPS;
          const canX =
            (ox === "auto" || ox === "scroll" || ox === "overlay") &&
            node.scrollWidth > node.clientWidth + EPS;
          if (canY && Math.abs(e.deltaY) >= Math.abs(e.deltaX)) {
            const atTop = node.scrollTop <= EPS;
            const atBottom = node.scrollTop >= node.scrollHeight - node.clientHeight - EPS;
            if ((e.deltaY < 0 && !atTop) || (e.deltaY > 0 && !atBottom)) {
              return;
            }
          }
          if (canX && Math.abs(e.deltaX) > Math.abs(e.deltaY)) {
            const atLeft = node.scrollLeft <= EPS;
            const atRight = node.scrollLeft >= node.scrollWidth - node.clientWidth - EPS;
            if ((e.deltaX < 0 && !atLeft) || (e.deltaX > 0 && !atRight)) {
              return;
            }
          }
          node = node.parentElement;
        }
      }

      e.preventDefault();
      const state = zoomState.current;
      const rect = el.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const currentScale =
        state.zoom === "fit" ? Math.max(0.05, state.fitScale) : state.zoom;
      // Trackpad pinch on macOS ships with ctrlKey=true — make it zoom more subtly.
      const intensity = e.ctrlKey ? 0.01 : 0.0015;
      const factor = Math.exp(-e.deltaY * intensity);
      const nextScale = clamp(currentScale * factor, 0.05, 4);
      if (Math.abs(nextScale - currentScale) < 1e-4) return;

      const cW = state.containerSize.w;
      const cH = state.containerSize.h;
      const stageWBefore = SLIDE_LOGICAL_WIDTH * currentScale;
      const stageHBefore = SLIDE_LOGICAL_HEIGHT * currentScale;
      const stageLeftBefore = (cW - stageWBefore) / 2 + state.pan.x;
      const stageTopBefore = (cH - stageHBefore) / 2 + state.pan.y;
      const slideX = (mx - stageLeftBefore) / currentScale;
      const slideY = (my - stageTopBefore) / currentScale;

      const stageWAfter = SLIDE_LOGICAL_WIDTH * nextScale;
      const stageHAfter = SLIDE_LOGICAL_HEIGHT * nextScale;
      const nextPanX = mx - slideX * nextScale - (cW - stageWAfter) / 2;
      const nextPanY = my - slideY * nextScale - (cH - stageHAfter) / 2;

      setZoom(nextScale);
      setPan({ x: nextPanX, y: nextPanY });
    };

    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, []);

  const resetZoom = useCallback((): void => {
    setZoom("fit");
    setPan({ x: 0, y: 0 });
  }, []);

  const stepZoom = useCallback(
    (dir: "in" | "out"): void => {
      const factor = dir === "in" ? 1.2 : 0.8;
      const current =
        zoomState.current.zoom === "fit"
          ? Math.max(0.05, zoomState.current.fitScale)
          : zoomState.current.zoom;
      const next = clamp(current * factor, 0.05, 4);
      setZoom(next);
    },
    [],
  );

  const stageLeft = (containerSize.w - stageW) / 2 + effectivePan.x;
  const stageTop = (containerSize.h - stageH) / 2 + effectivePan.y;

  const selectedIdSet = new Set(selectedElementIds);
  const activeHighlights = slide ? getActiveHighlightRegions(slide, playheadMs) : [];
  const handleNarrationLipSyncValueChange = useCallback((vtuberElementId: string, value: number) => {
    const clampedValue = clamp(value, 0, 1);
    setVtuberLipSyncByElementId((prev) => {
      const prevValue = prev[vtuberElementId] ?? 0;
      if (Math.abs(prevValue - clampedValue) < 0.02) return prev;
      if (clampedValue <= 0.001 && !(vtuberElementId in prev)) return prev;
      return { ...prev, [vtuberElementId]: clampedValue };
    });
  }, []);
  const handleNarrationAudioLoadingChange = useCallback(
    (elementId: string, isLoading: boolean) => {
      onPlaybackLoadingTokenChange(`narration:${elementId}`, isLoading);
    },
    [onPlaybackLoadingTokenChange],
  );
  /** Effective stage pose — must match `StageElement` `transform` (live ?? InSlide). */
  const resolveTransform = (item: CourseElement): LiveTransform => {
    const live = liveTransforms[item.element_id];
    if (live) return live;
    if (!slide) {
      const interp = interpolateElementTransform(item, playheadMs);
      return {
        x: interp.position.x,
        y: interp.position.y,
        width: interp.size.width,
        height: interp.size.height,
        rotation: interp.rotation_deg,
      };
    }
    const interp = interpolateElementTransformInSlide(item, playheadMs, slide);
    return {
      x: interp.position.x,
      y: interp.position.y,
      width: interp.size.width,
      height: interp.size.height,
      rotation: interp.rotation_deg,
    };
  };

  const clearAlignSnapGuides = useCallback((): void => {
    setAlignSnapGuides((prev) => (prev.length === 0 ? prev : []));
  }, []);

  const collectAlignSnapPeerBoxes = useCallback(
    (movingIds: Set<string>) => {
      if (!slide) return [];
      return slide.children_elements
        .filter((item) => !movingIds.has(item.element_id))
        .filter((item) => isElementVisibleAtTimeInSlide(item, playheadMs, slide))
        .filter(
          (item) =>
            !(item.element_type === "audio" && getCanvasAudioDisplayMode(item) === "hidden"),
        )
        .map((item) => boxFromLiveTransform(resolveTransform(item)));
    },
    [playheadMs, slide],
  );

  const applyAlignSnapToMove = useCallback(
    (movingIds: Set<string>, raw: LiveTransform): LiveTransform => {
      if (!slide) {
        clearAlignSnapGuides();
        return raw;
      }
      const { x: xTargets, y: yTargets } = collectAlignSnapTargetLines(
        SLIDE_LOGICAL_WIDTH,
        SLIDE_LOGICAL_HEIGHT,
        collectAlignSnapPeerBoxes(movingIds),
      );
      const snapped = snapLiveTransformMove(raw, xTargets, yTargets);
      setAlignSnapGuides(snapped.guides);
      return snapped.transform;
    },
    [clearAlignSnapGuides, collectAlignSnapPeerBoxes, slide],
  );

  const applyAlignSnapToResize = useCallback(
    (movingIds: Set<string>, raw: LiveTransform, handle: EditorResizeHandle): LiveTransform => {
      if (!slide) {
        clearAlignSnapGuides();
        return raw;
      }
      const { x: xTargets, y: yTargets } = collectAlignSnapTargetLines(
        SLIDE_LOGICAL_WIDTH,
        SLIDE_LOGICAL_HEIGHT,
        collectAlignSnapPeerBoxes(movingIds),
      );
      const snapped = snapLiveTransformResize(raw, handle, xTargets, yTargets);
      setAlignSnapGuides(snapped.guides);
      return snapped.transform;
    },
    [clearAlignSnapGuides, collectAlignSnapPeerBoxes, slide],
  );

  const startMarqueeSelection = useCallback(
    (
      startSlideX: number,
      startSlideY: number,
      pointerId: number,
      clientX: number,
      clientY: number,
      toggle: boolean,
    ): void => {
      const stageEl = stageRef.current;
      if (!stageEl || isPlaying || manualMarkMode) return;

      const clientToSlide = (cx: number, cy: number): { x: number; y: number } => {
        const rect = stageEl.getBoundingClientRect();
        return { x: (cx - rect.left) / scale, y: (cy - rect.top) / scale };
      };

      let active = false;
      const onMove = (ev: PointerEvent): void => {
        if (ev.pointerId !== pointerId) return;
        if (!active) {
          const moved =
            Math.hypot(ev.clientX - clientX, ev.clientY - clientY) >= MARQUEE_DRAG_THRESHOLD_PX;
          if (!moved) return;
          active = true;
        }
        const pt = clientToSlide(ev.clientX, ev.clientY);
        setMarqueeRect(normalizeEditorAxisRect(startSlideX, startSlideY, pt.x, pt.y));
      };

      const finish = (ev: PointerEvent): void => {
        if (ev.pointerId !== pointerId) return;
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", finish);
        window.removeEventListener("pointercancel", finish);
        if (active) {
          const pt = clientToSlide(ev.clientX, ev.clientY);
          const rect = normalizeEditorAxisRect(startSlideX, startSlideY, pt.x, pt.y);
          const ids = slide
            ? resolveMarqueeSelectionIds(slide, playheadMs, rect, resolveTransform)
            : [];
          onSelectElements(ids, { toggle });
        } else if (!toggle) {
          onSelectElement(null);
        }
        setMarqueeRect(null);
      };

      window.addEventListener("pointermove", onMove);
      window.addEventListener("pointerup", finish);
      window.addEventListener("pointercancel", finish);
    },
    [isPlaying, manualMarkMode, onSelectElement, onSelectElements, playheadMs, scale, slide],
  );

  const findLockedElementAt = (x: number, y: number): CourseElement | null => {
    if (!slide) return null;
    const candidates: Array<{ element: CourseElement; order: number; z: number }> = [];
    buildQuestionStackRenderUnits(slide).forEach((unit, unitIndex) => {
      const el = unit.element;
      candidates.push({ element: el, order: unitIndex, z: el.style.z_index });
    });
    candidates.sort((a, b) => (a.z === b.z ? a.order - b.order : a.z - b.z));
    for (let i = candidates.length - 1; i >= 0; i -= 1) {
      const el = candidates[i].element;
      if (!isElementLocked(el)) continue;
      if (!isElementVisibleAtTimeInSlide(el, playheadMs, slide)) continue;
      if (el.element_type === "audio" && getCanvasAudioDisplayMode(el) === "hidden") continue;
      const t = resolveTransform(el);
      if (x >= t.x && x <= t.x + t.width && y >= t.y && y <= t.y + t.height) return el;
      if (slidePointHitsLockedElementUnlockChip(x, y, t, scale, stageW, stageH)) return el;
    }
    return null;
  };
  const resolveDropSlidePosition = useCallback(
    (clientX: number, clientY: number): { x: number; y: number } | null => {
      const stageEl = stageRef.current;
      if (!stageEl) return null;
      const rect = stageEl.getBoundingClientRect();
      return {
        x: (clientX - rect.left) / scale,
        y: (clientY - rect.top) / scale,
      };
    },
    [scale],
  );

  const canAcceptFileDrop = Boolean(onDropFiles) && !isPlaying && !manualMarkMode;

  const handleStageDrop = useCallback(
    (e: ReactDragEvent<HTMLDivElement>): void => {
      e.preventDefault();
      setIsFileDragOver(false);
      const files = Array.from(e.dataTransfer.files);
      if (files.length > 0 && canAcceptFileDrop && onDropFiles) {
        const position = resolveDropSlidePosition(e.clientX, e.clientY);
        if (position) void onDropFiles(files, position);
        return;
      }
      if (!draggedResource) return;
      const rect = e.currentTarget.getBoundingClientRect();
      onDropResource({
        x: (e.clientX - rect.left) / scale,
        y: (e.clientY - rect.top) / scale,
      });
    },
    [
      canAcceptFileDrop,
      draggedResource,
      onDropFiles,
      onDropResource,
      resolveDropSlidePosition,
      scale,
    ],
  );

  const handleContainerFileDrop = useCallback(
    (e: ReactDragEvent<HTMLDivElement>): void => {
      if (e.target !== e.currentTarget) return;
      const files = Array.from(e.dataTransfer.files);
      if (files.length === 0 || !canAcceptFileDrop || !onDropFiles) return;
      e.preventDefault();
      setIsFileDragOver(false);
      const position = resolveDropSlidePosition(e.clientX, e.clientY);
      if (position) void onDropFiles(files, position);
    },
    [canAcceptFileDrop, onDropFiles, resolveDropSlidePosition],
  );

  const reportImageIntrinsicSize = useCallback(
    (elementId: string, width: number, height: number) => {
      onUpdateElement(elementId, (prev) => {
        if (prev.element_type !== "image") return prev;
        const img = prev as ImageElement;
        if (img.source_intrinsic_width === width && img.source_intrinsic_height === height) return prev;
        return { ...img, source_intrinsic_width: width, source_intrinsic_height: height };
      });
    },
    [onUpdateElement],
  );

  const vtuberPlacements = useMemo((): EditorVtuberPlacement[] => {
    if (!slide) return [];
    return listVtubersOnSlide(slide).map((element) => ({
      sourceKey: getVtuberSourceKey(element),
      element,
      slide,
      elementId: element.element_id,
    }));
  }, [slide]);

  const renderStackedStageElement = (el: CourseElement, stackZIndex?: number): React.ReactNode => {
            if (!slide) return null;
            if (manualMarkMode && (el.element_type === "vtuber" || el.element_type === "narration")) {
              return null;
            }
            // Legacy fill-blank "hide standalone input" filter no longer
            // applies in the single-element quiz model.
            const live = liveTransforms[el.element_id];
            const interp = interpolateElementTransformInSlide(el, playheadMs, slide);
            const transform: LiveTransform = live ?? {
              x: interp.position.x,
              y: interp.position.y,
              width: interp.size.width,
              height: interp.size.height,
              rotation: interp.rotation_deg,
            };
            const visible = isElementVisibleAtTimeInSlide(el, playheadMs, slide);
            const editBlocked = isElementEditBlocked(el);
            const agentFrozen = isElementAgentChatFrozen(el.element_id);
            const selected = selectedElementIds.includes(el.element_id);
            const editorFillBlankInline = false;
            const fillBlankRichTitleEditor = false;
            return (
              <StageElement
                key={el.element_id}
                element={el}
                slide={slide}
                transform={transform}
                opacity={interp.opacity}
                visible={visible}
                selected={selected && !isPlaying}
                selectedRichTextPath={
                  selectedRichText?.elementId === el.element_id ? selectedRichText.path : null
                }
                editBlocked={editBlocked}
                agentFrozen={agentFrozen}
                scale={scale}
                hideEditorChrome={false}
                editing={!manualMarkMode && editingElementId === el.element_id}
                initialTextCaretPoint={
                  editingElementId === el.element_id ? textEditCaretPoint : null
                }
                currentTime={playheadMs}
                isPlaying={isPlaying}
                playheadRef={playheadRef}
                playheadFromRef={playheadFromRef}
                playheadClockRunning={playheadClockRunning}
                vtuberSnapshotByElementId={vtuberSnapshotByElementId}
                vtuberSnapshotBySourceKey={vtuberSnapshotBySourceKey}
                vtuberLipSyncByElementId={vtuberLipSyncByElementId}
                vtuberModelLoadedBySourceKey={vtuberModelLoadedBySourceKey}
                onCaptureVtuberSnapshot={onCaptureVtuberSnapshot}
                onNarrationLipSyncValueChange={handleNarrationLipSyncValueChange}
                onNarrationAudioLoadingChange={handleNarrationAudioLoadingChange}
                onNarrationPlayheadDriveChange={onNarrationPlayheadDriveChange}
                onStartEditing={(caretPoint) => {
                  if (el.element_type === "text") {
                    onSelectElement(el.element_id);
                    setTextEditCaretPoint(caretPoint ?? null);
                    setEditingElementId(el.element_id);
                    return;
                  }
                  if (el.element_type === "rich") {
                    onSelectElement(el.element_id);
                    setRichEditState(defaultRichEditState());
                    setEditingElementId(el.element_id);
                    return;
                  }
                  if (
                    el.element_type === "svg" &&
                    isInlineSvgSource((el as SvgElement).source)
                  ) {
                    onSelectElement(el.element_id);
                    setSvgEditState(defaultSvgEditState());
                    setEditingElementId(el.element_id);
                  }
                }}
                onStopEditing={() => {
                  setEditingElementId(null);
                  setTextEditCaretPoint(null);
                  setSvgEditState(defaultSvgEditState());
                  setRichEditState(defaultRichEditState());
                  if (el.element_type === "rich") {
                    onSelectRichText(null);
                  }
                  if (el.element_type === "svg") {
                    onSvgTextStyleSnapshot?.(null);
                  }
                }}
                onChangeText={(next) =>
                  onUpdateElement(el.element_id, (prev) =>
                    prev.element_type === "text" ? { ...prev, text: next } : prev,
                  )
                }
                onChangeRichText={(path, text) =>
                  onUpdateElement(el.element_id, (prev) => {
                    if (prev.element_type !== "rich") return prev;
                    const nextLayout = setRichTextAtPath(prev.react_layout, path, text);
                    return nextLayout ? { ...prev, react_layout: nextLayout } : prev;
                  })
                }
                richEditState={
                  editingElementId === el.element_id && el.element_type === "rich"
                    ? richEditState
                    : undefined
                }
                onRichEditStateChange={
                  editingElementId === el.element_id && el.element_type === "rich"
                    ? setRichEditState
                    : undefined
                }
                onChangeRichLayout={(path, patch, options) =>
                  onUpdateElement(
                    el.element_id,
                    (prev) => {
                      if (prev.element_type !== "rich") return prev;
                      const nextLayout = patchRichElementStyleAtPath(prev.react_layout, path, patch);
                      return nextLayout ? { ...prev, react_layout: nextLayout } : prev;
                    },
                    options,
                  )
                }
                onRemoveRichNode={(path, options) =>
                  onUpdateElement(
                    el.element_id,
                    (prev) => {
                      if (prev.element_type !== "rich") return prev;
                      const nextLayout = removeRichNodeAtPath(prev.react_layout, path);
                      return nextLayout ? { ...prev, react_layout: nextLayout } : prev;
                    },
                    options,
                  )
                }
                svgEditState={
                  editingElementId === el.element_id && el.element_type === "svg"
                    ? svgEditState
                    : undefined
                }
                onSvgEditStateChange={
                  editingElementId === el.element_id && el.element_type === "svg"
                    ? setSvgEditState
                    : undefined
                }
                onChangeSvgSource={(source, options) =>
                  onUpdateElement(
                    el.element_id,
                    (prev) =>
                      prev.element_type === "svg" ? { ...prev, source } : prev,
                    options,
                  )
                }
                stageLayoutKey={stageLayoutKey}
                onSvgTextStyleSnapshot={onSvgTextStyleSnapshot}
                svgTextStylePatch={
                  editingElementId === el.element_id && el.element_type === "svg"
                    ? svgTextStylePatch
                    : null
                }
                onSelectRichText={(path) => onSelectRichText({ elementId: el.element_id, path })}
                onSelect={(event) =>
                  onSelectElement(el.element_id, {
                    toggle: event.metaKey || event.ctrlKey || event.shiftKey,
                  })
                }
                onSelectOnly={() => onSelectElement(el.element_id)}
                onLock={() => {
                  onUpdateElement(el.element_id, (prev) => ({ ...prev, locked: true }));
                  onSelectElement(null);
                }}
                onDuplicate={() => {
                  onDuplicateElement?.(el.element_id);
                }}
                onDelete={() => {
                  onRequestDeleteElement?.(el.element_id);
                }}
                onLiveTransform={(t, meta) => {
                  const isMove = meta?.mode === "move";
                  const isResize = meta?.mode === "resize";
                  const resizeHandle = meta?.resizeHandle;
                  if (!isMove && !isResize) clearAlignSnapGuides();
                  // Determine the effective group of elements that must transform
                  // together with this drag. There are two cases:
                  //   (a) The user has multi-selected elements, in which case
                  //       all selected elements transform with the leader.
                  //   (b) The leader is a question wrapper — its member
                  //       elements always tag along with move/resize changes.
                  const groupIdSet = new Set<string>();
                  const isMultiSelectLeader =
                    selectedElementIds.length > 1 && selectedIdSet.has(el.element_id);
                  if (isMultiSelectLeader) {
                    selectedElementIds.forEach((id) => groupIdSet.add(id));
                  }
                  // Quiz elements are single boxes now — no group members.
                  const isGroupLeader = groupIdSet.size > 1 && groupIdSet.has(el.element_id);
                  const snapLeader = (ids: Set<string>, raw: LiveTransform): LiveTransform => {
                    if (isMove) return applyAlignSnapToMove(ids, raw);
                    if (isResize && resizeHandle) {
                      return applyAlignSnapToResize(ids, raw, resizeHandle);
                    }
                    return raw;
                  };
                  if (!isGroupLeader) {
                    const nextT = snapLeader(new Set([el.element_id]), t);
                    updateLiveTransforms((prev) => ({ ...prev, [el.element_id]: nextT }));
                    return;
                  }
                  const leaderMove = snapLeader(groupIdSet, t);
                  const currentGroup = groupMoveRef.current;
                  if (!currentGroup || currentGroup.leaderId !== el.element_id) {
                    const baseById: Record<string, LiveTransform> = {};
                    slide.children_elements.forEach((item) => {
                      if (!groupIdSet.has(item.element_id)) return;
                      baseById[item.element_id] = resolveTransform(item);
                    });
                    const leaderBase = baseById[el.element_id];
                    if (!leaderBase) return;
                    groupMoveRef.current = {
                      leaderId: el.element_id,
                      leaderStart: {
                        x: leaderBase.x,
                        y: leaderBase.y,
                        width: leaderBase.width,
                        height: leaderBase.height,
                        rotation: leaderBase.rotation,
                      },
                      baseById,
                    };
                  }
                  const group = groupMoveRef.current;
                  if (!group || group.leaderId !== el.element_id) return;
                  updateLiveTransforms((prev) => {
                    const next = { ...prev };
                    Object.entries(group.baseById).forEach(([id, base]) => {
                      next[id] = transformGroupMemberFromLeader(
                        base,
                        group.leaderStart,
                        leaderMove,
                      );
                    });
                    return next;
                  });
                }}
                onCommit={(t) => {
                  const liveLeader = liveTransformsRef.current[el.element_id];
                  const commitLeader = liveLeader ?? t;
                  const group = groupMoveRef.current;
                  const isGroupLeader =
                    !!group && group.leaderId === el.element_id;
                  if (isGroupLeader && group) {
                    if (!slide) {
                      groupMoveRef.current = null;
                      return;
                    }
                    // Commit every group follower's final absolute pose. Skipping quiz members when the
                    // wrapper had keyframes left members at stale slide-space coordinates while the
                    // wrapper pose updated (or was cleared by finalizeEditorElement), so the dashed
                    // container and content diverged after pointer-up.
                    Object.entries(group.baseById).forEach(([id, base]) => {
                      const liveMember = liveTransformsRef.current[id];
                      const memberPose =
                        liveMember ??
                        transformGroupMemberFromLeader(base, group.leaderStart, commitLeader);
                      onCommitTransform(id, memberPose);
                    });
                    updateLiveTransforms((prev) => {
                      const next = { ...prev };
                      Object.keys(group.baseById).forEach((id) => {
                        delete next[id];
                      });
                      return next;
                    });
                    groupMoveRef.current = null;
                    clearAlignSnapGuides();
                    return;
                  }
                  onCommitTransform(el.element_id, commitLeader);
                  updateLiveTransforms((prev) => {
                    const next = { ...prev };
                    delete next[el.element_id];
                    return next;
                  });
                  clearAlignSnapGuides();
                }}
                onCancelLiveTransform={() => {
                  const group = groupMoveRef.current;
                  if (group?.leaderId === el.element_id) {
                    updateLiveTransforms((prev) => {
                      const next = { ...prev };
                      Object.keys(group.baseById).forEach((id) => {
                        delete next[id];
                      });
                      return next;
                    });
                    groupMoveRef.current = null;
                    clearAlignSnapGuides();
                    return;
                  }
                  updateLiveTransforms((prev) => {
                    const next = { ...prev };
                    delete next[el.element_id];
                    return next;
                  });
                  clearAlignSnapGuides();
                }}
                onReportImageIntrinsicSize={(w, h) => reportImageIntrinsicSize(el.element_id, w, h)}
                stackZIndex={stackZIndex}
                editorFillBlankInline={editorFillBlankInline}
                fillBlankRichTitleEditor={fillBlankRichTitleEditor}
                owningQuestionWrapperId={null}
                quizStemAutoplay={quizStemAutoplay}
                activeQuizPauseWrapperId={activeQuizPauseWrapperId}
                onPptSlideIndexChange={(elementId, slideIndex) => {
                  onUpdateElement(elementId, (prev) => {
                    if (prev.element_type !== "ppt") return prev;
                    const ppt = prev as PPTElement;
                    const keyframeAt = clamp(currentTime, ppt.timeline.start_at, ppt.timeline.end_at);
                    const filtered = ppt.keyframes.filter((k) => !isSameKeyframeTime(k.at, keyframeAt));
                    const t = interpolateElementTransform(ppt, currentTime);
                    const existing = ppt.keyframes.find((k) => isSameKeyframeTime(k.at, keyframeAt));
                    const kf: Keyframe = {
                      at: keyframeAt,
                      position: existing?.position ?? t.position,
                      size: existing?.size ?? t.size,
                      rotation_deg: existing?.rotation_deg ?? t.rotation_deg,
                      opacity: existing?.opacity ?? t.opacity,
                      easing: existing?.easing ?? "ease-in-out",
                      ppt_slide_index: slideIndex,
                    };
                    return {
                      ...ppt,
                      metadata: {
                        ...(ppt.metadata as Record<string, unknown>),
                        ppt_editor_slide_index: slideIndex,
                      },
                      keyframes: normalizeKeyframesByTime([...filtered, kf]),
                    };
                  });
                }}
                editorQuiz={quiz}
                onOpenQuizSettingsForQuestion={onOpenQuizSettingsForQuestion}
                onOpenQuizLayoutEditor={onOpenQuizLayoutEditor}
                onChangeHtmlContentZoom={
                  el.element_type === "html"
                    ? (zoom, options) =>
                        onUpdateElement(
                          el.element_id,
                          (prev) =>
                            prev.element_type === "html"
                              ? { ...prev, content_zoom: zoom }
                              : prev,
                          options,
                        )
                    : undefined
                }
              />
            );
  };

  if (!slide) {
    return (
      <div className="flex flex-1 items-center justify-center bg-slate-50 dark:bg-slate-950 text-slate-400 dark:text-slate-500">
        {t("coursewareEditor.stage.noEditableCanvas")}
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      tabIndex={-1}
      data-hotkey-scope="stage"
      className="relative min-h-0 min-w-0 flex-1 overflow-hidden bg-slate-50 dark:bg-slate-950 outline-none"
      style={{
        cursor: marqueeRect
          ? "crosshair"
          : canPan && isPanning
            ? "grabbing"
            : undefined,
      }}
      onPointerDownCapture={(e) => {
        e.currentTarget.focus();
      }}
      onPointerDown={(e) => {
        if (e.target !== e.currentTarget) return;
        const wantsPan = e.button === 1 || (e.altKey && e.button === 0);
        if (wantsPan) {
          if (!canPan) return;
          e.preventDefault();
          startPan(e.clientX, e.clientY);
          return;
        }
        if (e.button !== 0) return;
        const stageEl = stageRef.current;
        // Allow starting a rectangle selection even when dragging from outside the stage (the margins).
        // During playback / manual marking, a click still only clears the selection as before.
        if (!stageEl || isPlaying || manualMarkMode) {
          onSelectElement(null);
          return;
        }
        e.preventDefault();
        const rect = stageEl.getBoundingClientRect();
        const startSlideX = (e.clientX - rect.left) / scale;
        const startSlideY = (e.clientY - rect.top) / scale;
        startMarqueeSelection(
          startSlideX,
          startSlideY,
          e.pointerId,
          e.clientX,
          e.clientY,
          e.metaKey || e.ctrlKey || e.shiftKey,
        );
      }}
      onDragEnter={(e) => {
        if (!canAcceptFileDrop || !isExternalFileDrag(e)) return;
        e.preventDefault();
        setIsFileDragOver(true);
      }}
      onDragOver={(e) => {
        if (canAcceptFileDrop && isExternalFileDrag(e)) {
          e.preventDefault();
          e.dataTransfer.dropEffect = "copy";
          setIsFileDragOver(true);
          return;
        }
        if (!draggedResource) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = "copy";
      }}
      onDragLeave={(e) => {
        if (!isExternalFileDrag(e)) return;
        if (e.currentTarget.contains(e.relatedTarget as Node | null)) return;
        setIsFileDragOver(false);
      }}
      onDrop={handleContainerFileDrop}
    >
      {quizContentNarrationAudioRef ? (
        <EditorQuizContentNarrationLipSyncDriver
          audioRef={quizContentNarrationAudioRef}
          target={quizContentNarrationLipSyncTarget}
          onLipSyncValueChange={handleNarrationLipSyncValueChange}
        />
      ) : null}
      {quizSettingsContentNarrationAudioRef &&
      quizSettingsContentNarrationLipSyncTarget &&
      !quizContentNarrationLipSyncTarget ? (
        <EditorQuizContentNarrationLipSyncDriver
          audioRef={quizSettingsContentNarrationAudioRef}
          target={quizSettingsContentNarrationLipSyncTarget}
          onLipSyncValueChange={handleNarrationLipSyncValueChange}
        />
      ) : null}
      <div className="pointer-events-none relative h-full w-full min-h-0 min-w-0">
        <div
          ref={stageRef}
          className="pointer-events-auto absolute shadow-2xl shadow-slate-900/15 dark:shadow-black/50"
          style={{
            left: stageLeft,
            top: stageTop,
            width: stageW,
            height: stageH,
            isolation: "isolate",
            backgroundColor: slide.background_color,
            cursor: manualMarkMode
              ? "crosshair"
              : marqueeRect
                ? "crosshair"
                : canPan && isPanning
                  ? "grabbing"
                  : undefined,
          }}
          onPointerDown={(e) => {
            if (isPlaying || manualMarkMode) return;
            const wantsPan = e.button === 1 || (e.altKey && e.button === 0);
            if (wantsPan) {
              if (!canPan) return;
              e.preventDefault();
              startPan(e.clientX, e.clientY);
              return;
            }
            if (e.button !== 0 || e.target !== e.currentTarget) return;
            e.preventDefault();
            const rect = e.currentTarget.getBoundingClientRect();
            const startSlideX = (e.clientX - rect.left) / scale;
            const startSlideY = (e.clientY - rect.top) / scale;
            startMarqueeSelection(
              startSlideX,
              startSlideY,
              e.pointerId,
              e.clientX,
              e.clientY,
              e.metaKey || e.ctrlKey || e.shiftKey,
            );
          }}
          onPointerMove={(e) => {
            if (manualMarkMode) return;
            const rect = e.currentTarget.getBoundingClientRect();
            const x = (e.clientX - rect.left) / scale;
            const y = (e.clientY - rect.top) / scale;
            const locked = findLockedElementAt(x, y);
            setHoveredLockedElementId((prev) =>
              prev === (locked?.element_id ?? null) ? prev : (locked?.element_id ?? null),
            );
          }}
          onPointerLeave={() => setHoveredLockedElementId(null)}
          onContextMenu={(e) => {
            if (isPlaying || manualMarkMode || !slide || !onOpenElementContextMenu) return;
            const rect = e.currentTarget.getBoundingClientRect();
            const x = (e.clientX - rect.left) / scale;
            const y = (e.clientY - rect.top) / scale;
            const hit = findTopCanvasElementAtPoint(slide, playheadMs, x, y, resolveTransform, {
              manualMarkMode,
              stageScale: scale,
              stageWpx: stageW,
              stageHpx: stageH,
            });
            if (!hit) {
              onCloseElementContextMenu?.();
              return;
            }
            e.preventDefault();
            e.stopPropagation();
            onOpenElementContextMenu(hit.element_id, e.clientX, e.clientY, {
              slideX: x,
              slideY: y,
              stageScale: scale,
              stageWpx: stageW,
              stageHpx: stageH,
              manualMarkMode,
            });
          }}
          onDragOver={(e) => {
            if (canAcceptFileDrop && isExternalFileDrag(e)) {
              e.preventDefault();
              e.dataTransfer.dropEffect = "copy";
              setIsFileDragOver(true);
              return;
            }
            if (!draggedResource) return;
            e.preventDefault();
            e.dataTransfer.dropEffect = "copy";
          }}
          onDragLeave={(e) => {
            if (!isExternalFileDrag(e)) return;
            if (e.currentTarget.contains(e.relatedTarget as Node | null)) return;
            setIsFileDragOver(false);
          }}
          onDrop={handleStageDrop}
        >
          {isFileDragOver ? (
            <div className="pointer-events-none absolute inset-0 z-200 flex items-center justify-center border-2 border-dashed border-blue-400 bg-blue-500/10 dark:bg-blue-500/15">
              <p className="rounded bg-white/90 px-3 py-1.5 text-xs font-medium text-blue-700 shadow-sm dark:bg-slate-900/90 dark:text-blue-300">
                {t("coursewareEditor.common.dropToUpload")}
              </p>
            </div>
          ) : null}
          {(() => {
            const bgImgStyle = getSlideBackgroundImageLayerStyle(
              slide.background_image_url,
              slide.background_image_fit,
            );
            return (
              <>
                {bgImgStyle ? (
                  <div className="pointer-events-none absolute inset-0 z-0" style={bgImgStyle} />
                ) : null}
                <SlideBackgroundHtmlLayer
                  src={slide.background_html_src}
                  slideId={slide.element_id}
                  contentZoom={slide.background_html_content_zoom}
                  scale={scale}
                  zClassName="z-1"
                />
              </>
            );
          })()}
          <div className="pointer-events-none absolute inset-0 z-2">
            {buildQuestionStackRenderUnits(slide).map((unit) =>
              renderStackedStageElement(unit.element),
            )}

            {!manualMarkMode ? (
              <EditorPersistentVtuberLayer
                coursewareId={coursewareId}
                placements={vtuberPlacements}
                scale={scale}
                liveTransforms={liveTransforms}
                vtuberSnapshotByElementId={vtuberSnapshotByElementId}
                vtuberSnapshotBySourceKey={vtuberSnapshotBySourceKey}
                lipSyncByElementId={vtuberLipSyncByElementId}
                allSlides={allSlides}
                isPlaying={isPlaying}
                currentTime={playheadMs}
                onCaptureVtuberSnapshot={onCaptureVtuberSnapshot}
                onVtuberSourceModelLoading={handleVtuberSourceModelLoading}
                onVtuberSourceModelLoaded={handleVtuberSourceModelLoaded}
                onPlaybackLoadingTokenChange={onPlaybackLoadingTokenChange}
              />
            ) : null}

            {!manualMarkMode ? <HighlightOverlay regions={activeHighlights} /> : null}
            {!manualMarkMode
              ? (() => {
              const locked = hoveredLockedElementId
                ? slide.children_elements.find((el) => el.element_id === hoveredLockedElementId)
                : null;
              if (!locked || !isElementLocked(locked)) return null;
              const lockedTransform = resolveTransform(locked);
              const chipLayout = getEditorLockedUnlockChipLayout(lockedTransform, scale, stageW, stageH);
              return (
                <button
                  type="button"
                  className="absolute flex h-5 w-5 cursor-pointer items-center justify-center rounded-full border border-amber-300/90 bg-amber-400 text-slate-950 shadow hover:bg-amber-300 pointer-events-auto"
                  style={{
                    left: chipLayout.chipLeftPx,
                    top: chipLayout.chipTopPx,
                    zIndex: EDITOR_LOCKED_CHIP_Z_INDEX,
                  }}
                  title={t("coursewareEditor.common.clickToUnlock")}
                  aria-label={t("coursewareEditor.common.unlockElement")}
                  onPointerDown={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                  }}
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    onUpdateElement(locked.element_id, (prev) => ({ ...prev, locked: false }));
                    setHoveredLockedElementId(null);
                  }}
                >
                  <Lock className="h-3 w-3" />
                </button>
              );
            })()
              : null}
            {marqueeRect && !manualMarkMode ? (
              <div
                className="pointer-events-none absolute z-50 border border-blue-400 dark:border-blue-400 bg-blue-500/10 dark:bg-blue-500/15"
                style={{
                  left: marqueeRect.left * scale,
                  top: marqueeRect.top * scale,
                  width: (marqueeRect.right - marqueeRect.left) * scale,
                  height: (marqueeRect.bottom - marqueeRect.top) * scale,
                }}
              />
            ) : null}
            {alignSnapGuides.length > 0 && !manualMarkMode ? (
              <>
                {alignSnapGuides.map((guide, index) => {
                  const isSlideEdge = guide.source === "slide-edge";
                  const colorClass = isSlideEdge ? "bg-cyan-400/95" : "bg-fuchsia-500/90";
                  const thicknessPx = isSlideEdge ? 2 : 1;
                  // Canvas edge guides extend somewhat beyond the stage, so they don't coincide with the stage edge / shadow and disappear
                  const overflowPx = isSlideEdge ? 12 : 0;
                  if (guide.axis === "x") {
                    return (
                      <div
                        key={`snap-x-${guide.source}-${guide.position}-${index}`}
                        className={`pointer-events-none absolute z-55 ${colorClass}`}
                        style={{
                          left: guide.position * scale - thicknessPx / 2,
                          top: -overflowPx,
                          width: thicknessPx,
                          height: stageH + overflowPx * 2,
                        }}
                      />
                    );
                  }
                  return (
                    <div
                      key={`snap-y-${guide.source}-${guide.position}-${index}`}
                      className={`pointer-events-none absolute z-55 ${colorClass}`}
                      style={{
                        left: -overflowPx,
                        top: guide.position * scale - thicknessPx / 2,
                        width: stageW + overflowPx * 2,
                        height: thicknessPx,
                      }}
                    />
                  );
                })}
              </>
            ) : null}
          </div>
          {manualMarkMode ? (
            <>
              <div
                className={`absolute left-2 top-2 z-70 max-w-[min(100%,20rem)] transition-opacity duration-200 ${
                  manualMarkHintHidden ? "pointer-events-none opacity-0" : "pointer-events-auto opacity-100"
                }`}
                onMouseEnter={() => setManualMarkHintHidden(true)}
              >
                <div className="rounded-md border border-rose-300/45 dark:border-rose-500/40 bg-rose-950/90 px-2.5 py-1 text-[11px] font-medium text-rose-100 shadow">
                  {t("coursewareEditor.stage.manualMarkBanner")}
                </div>
              </div>
              {onPendingManualMarkCreate ? (
                <CoursewareStageManualMarkOverlay
                  key={`${slide.element_id}-${Math.floor(playheadMs)}`}
                  scale={scale}
                  regions={manualMarkRegions}
                  pendingMark={pendingManualMark}
                  onPendingMarkCreate={onPendingManualMarkCreate}
                />
              ) : null}
            </>
          ) : null}
        </div>
      </div>

      <div className="pointer-events-auto absolute top-2 right-2 z-20 flex items-center gap-1.5 rounded border border-slate-300 dark:border-slate-700 bg-white/85 dark:bg-slate-900/85 px-2 py-1 text-[11px] text-slate-600 opacity-45 shadow-sm transition-opacity hover:opacity-100 dark:text-slate-300">
        <span className="select-none whitespace-nowrap">
          {t("coursewareEditor.common.background")}
        </span>
        <BoundCoursewareColorPicker
          variant="compact"
          className="courseware-color-picker--mini"
          value={slide.background_color}
          fallbackColor="#F0F0ED"
          swatchImageUrl={slide.background_image_url || undefined}
          onChange={(background_color, options) =>
            onUpdateSlide(
              (s) => ({
                ...s,
                background_color,
                ...(s.background_image_url ? { background_image_url: "" } : null),
                ...(s.background_html_src ? { background_html_src: "" } : null),
              }),
              options,
            )
          }
        />
      </div>

      {!canPan && (
        <div className="pointer-events-auto absolute bottom-2 right-2 z-20 flex items-center rounded border border-slate-300 dark:border-slate-700 bg-white/85 dark:bg-slate-900/85 text-[10px] opacity-45 transition-opacity hover:opacity-100">
          <IconButton
            icon={<ZoomOut className="h-3 w-3" />}
            label={t("coursewareEditor.common.zoomOut")}
            onClick={() => stepZoom("out")}
          />
          <span className="min-w-[30px] text-center tabular-nums text-slate-600 dark:text-slate-300">
            {Math.round(scale * 100)}%
          </span>
          <IconButton
            icon={<ZoomIn className="h-3 w-3" />}
            label={t("coursewareEditor.common.zoomIn")}
            onClick={() => stepZoom("in")}
          />
          <button
            className="ml-0.5 rounded px-1.5 py-2 text-[10px] text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800"
            onClick={resetZoom}
            title={t("coursewareEditor.common.fitToWindow")}
          >
{t("coursewareEditor.common.fitShort")}
          </button>
        </div>
      )}

      <Minimap
        slide={slide}
        currentTime={playheadMs}
        liveTransforms={liveTransforms}
        scale={scale}
        pan={effectivePan}
        stageW={stageW}
        stageH={stageH}
        containerSize={containerSize}
        editorQuiz={quiz}
        vtuberSnapshotByElementId={vtuberSnapshotByElementId}
        vtuberSnapshotBySourceKey={vtuberSnapshotBySourceKey}
        onResetView={resetZoom}
        onCenterAt={(slideX, slideY) => {
          setPan({
            x: stageW / 2 - slideX * scale,
            y: stageH / 2 - slideY * scale,
          });
        }}
      />
    </div>
  );
}, editorSubtreePropsEqual);

// ---------- minimap ----------

interface MinimapProps {
  slide: SlideElement;
  currentTime: number;
  liveTransforms: Record<string, LiveTransform>;
  scale: number;
  pan: { x: number; y: number };
  stageW: number;
  stageH: number;
  containerSize: { w: number; h: number };
  editorQuiz?: QuizConfig | null;
  vtuberSnapshotByElementId: Record<string, string>;
  vtuberSnapshotBySourceKey: Record<string, string>;
  onResetView: () => void;
  onCenterAt: (slideX: number, slideY: number) => void;
}

function Minimap({
  slide,
  currentTime,
  liveTransforms,
  scale,
  pan,
  stageW,
  stageH,
  containerSize,
  editorQuiz = null,
  vtuberSnapshotByElementId,
  vtuberSnapshotBySourceKey,
  onResetView,
  onCenterAt,
}: MinimapProps) {
  const { t, t: translateFn } = useI18nNew();
  const mapRef = useRef<HTMLDivElement | null>(null);
  const cW = containerSize.w;
  const cH = containerSize.h;

  const overflowing = stageW > cW + 1 || stageH > cH + 1;
  if (!overflowing) return null;

  const mapW = 160;
  const mapH = (mapW * SLIDE_LOGICAL_HEIGHT) / SLIDE_LOGICAL_WIDTH;

  const stageLeft = (cW - stageW) / 2 + pan.x;
  const stageTop = (cH - stageH) / 2 + pan.y;
  const slideVisibleLeft = -stageLeft / scale;
  const slideVisibleTop = -stageTop / scale;
  const slideVisibleW = cW / scale;
  const slideVisibleH = cH / scale;

  const toMapX = (cx: number): number => (cx / SLIDE_LOGICAL_WIDTH) * mapW;
  const toMapY = (cy: number): number => (cy / SLIDE_LOGICAL_HEIGHT) * mapH;
  const mapScale = mapW / SLIDE_LOGICAL_WIDTH;

  const viewport = {
    left: toMapX(slideVisibleLeft),
    top: toMapY(slideVisibleTop),
    width: clamp(
      toMapX(slideVisibleLeft + slideVisibleW) - toMapX(slideVisibleLeft),
      4,
      mapW,
    ),
    height: clamp(
      toMapY(slideVisibleTop + slideVisibleH) - toMapY(slideVisibleTop),
      4,
      mapH,
    ),
  };

  const jumpFromClient = (clientX: number, clientY: number): void => {
    const el = mapRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const mx = clamp(clientX - rect.left, 0, mapW);
    const my = clamp(clientY - rect.top, 0, mapH);
    const slideX = (mx / mapW) * SLIDE_LOGICAL_WIDTH;
    const slideY = (my / mapH) * SLIDE_LOGICAL_HEIGHT;
    onCenterAt(slideX, slideY);
  };

  const startDrag = (e: ReactPointerEvent<HTMLDivElement>): void => {
    e.preventDefault();
    e.stopPropagation();
    jumpFromClient(e.clientX, e.clientY);
    const onMove = (ev: PointerEvent): void => jumpFromClient(ev.clientX, ev.clientY);
    const onUp = (): void => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  return (
    <div
      data-role="minimap"
      className="pointer-events-auto absolute bottom-1 right-1 z-20 rounded-md border border-slate-300 dark:border-slate-700 bg-white/95 dark:bg-slate-900/95 p-1 shadow-lg"
    >
      <div
        ref={mapRef}
        className="relative isolate cursor-grab active:cursor-grabbing overflow-hidden rounded-sm"
        style={{ width: mapW, height: mapH, backgroundColor: slide.background_color }}
        onPointerDown={startDrag}
      >
        {(() => {
          const s = getSlideBackgroundImageLayerStyle(
            slide.background_image_url,
            slide.background_image_fit,
          );
          return s ? <div className="pointer-events-none absolute inset-0 z-0" style={s} /> : null;
        })()}
        <SlideBackgroundHtmlLayer
          src={slide.background_html_src}
          slideId={slide.element_id}
          contentZoom={slide.background_html_content_zoom}
          scale={mapW / SLIDE_LOGICAL_WIDTH}
          targetSizePx={{ width: mapW, height: mapH }}
          zClassName="z-0"
        />
        <div className="relative z-1 h-full w-full">
        {buildQuestionStackRenderUnits(slide).map((unit) => {
          const renderThumb = (el: CourseElement, stackZ: number): React.ReactNode => {
            // Legacy fill-blank "hide standalone input" filter no longer
            // applies in the single-element quiz model.
            if (!isElementVisibleAtTimeInSlide(el, currentTime, slide)) return null;
            const interp = interpolateElementTransformInSlide(el, currentTime, slide);
            const live = liveTransforms[el.element_id];
            const t = live
              ? {
                  position: { x: live.x, y: live.y },
                  size: { width: live.width, height: live.height },
                  rotation_deg: live.rotation,
                  opacity: interp.opacity,
                }
              : interp;
            const thumbFx = computeElementEnterExitEffectVisual(el, slide, currentTime);
            const thumbOpacity = clamp(t.opacity * thumbFx.opacityFactor, 0, 1);
            if (thumbOpacity <= 0.01) return null;
            const thumbW = Math.max(1, toMapX(t.size.width));
            const thumbH = Math.max(1, toMapY(t.size.height));
            const thumbInnerTransform = `translate(${thumbFx.translateLogicalX * mapScale}px, ${thumbFx.translateLogicalY * mapScale}px) rotate(${thumbFx.rotateExtraDeg}deg) scale(${thumbFx.uniformScale})`;
            return (
              <div
                key={el.element_id}
                className="pointer-events-none absolute overflow-hidden rounded-[1px]"
                style={{
                  left: toMapX(t.position.x),
                  top: toMapY(t.position.y),
                  width: thumbW,
                  height: thumbH,
                  opacity: thumbOpacity,
                  transform: t.rotation_deg ? `rotate(${t.rotation_deg}deg)` : undefined,
                  transformOrigin: "center",
                  zIndex: resolveEditorThumbnailStackZ(el, stackZ),
                }}
              >
                <div
                  className="absolute inset-0"
                  style={{
                    transform: thumbInnerTransform,
                    transformOrigin: "center center",
                  }}
                >
                  {renderElementContent(
                    el,
                    t.size.width,
                    t.size.height,
                    mapScale,
                    "thumbnail",
                    {
                      vtuberSnapshotByElementId,
                      vtuberSnapshotBySourceKey,
                      currentTime,
                      thumbnailViewportPx: { width: thumbW, height: thumbH },
                      htmlReferenceLayoutScale: mapScale,
                      htmlThumbPreferStageLayoutBaseline: false,
                      editorQuiz,
                      translate: translateFn,
                    },
                  )}
                </div>
              </div>
            );
          };
          return renderThumb(unit.element, unit.element.style.z_index);
        })}
        </div>
        <div
          className="pointer-events-none absolute border border-blue-400/90 bg-blue-400/15"
          style={{
            left: viewport.left,
            top: viewport.top,
            width: viewport.width,
            height: viewport.height,
            zIndex: SLIDE_PREVIEW_MINIMAP_VIEWPORT_Z_INDEX,
          }}
        />
      </div>
      <div className="mt-1.5 pl-1 flex items-center justify-between gap-2 text-[10px] tabular-nums text-slate-400 dark:text-slate-500">
        <span>
          {Math.round(scale * 100)}% · {Math.round(slideVisibleW)}×{Math.round(slideVisibleH)}
        </span>
        <button
          className="rounded px-1.5 py-0.5 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 border border-slate-300 dark:border-slate-700"
          onClick={onResetView}
          title={t("coursewareEditor.common.fitToWindow")}
        >
{t("coursewareEditor.common.restoreShort")}
        </button>
      </div>
    </div>
  );
}

// ---------- stage element ----------

interface StageElementProps {
  element: CourseElement;
  slide: SlideElement;
  transform: LiveTransform;
  opacity: number;
  visible: boolean;
  selected: boolean;
  selectedRichTextPath?: RichTextPath | null;
  /** Dragging/editing forbidden (locked by hand or frozen by the agent) */
  editBlocked: boolean;
  /** Frozen exclusively by the agent for this conversation turn: shows the iridescent mask */
  agentFrozen?: boolean;
  /** Manual marking mode: hide the dashed frame and the selection outline */
  hideEditorChrome?: boolean;
  scale: number;
  editing: boolean;
  initialTextCaretPoint?: { clientX: number; clientY: number } | null;
  currentTime: number;
  isPlaying: boolean;
  playheadRef: RefObject<number>;
  playheadFromRef: boolean;
  playheadClockRunning: boolean;
  vtuberSnapshotByElementId: Record<string, string>;
  vtuberSnapshotBySourceKey: Record<string, string>;
  vtuberLipSyncByElementId: Record<string, number>;
  vtuberModelLoadedBySourceKey: Record<string, boolean>;
  onCaptureVtuberSnapshot: (elementId: string, dataUrl: string) => void;
  onNarrationLipSyncValueChange: (vtuberElementId: string, value: number) => void;
  onNarrationAudioLoadingChange: (elementId: string, isLoading: boolean) => void;
  onNarrationPlayheadDriveChange: (localMs: number | null) => void;
  onSelect: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onSelectOnly: () => void;
  onLock: () => void;
  onDuplicate: () => void;
  onDelete: () => void;
  onStartEditing: (caretPoint?: { clientX: number; clientY: number }) => void;
  onStopEditing: () => void;
  onChangeText: (text: string) => void;
  onChangeRichText: (path: number[], text: string) => void;
  onSelectRichText: (path: RichTextPath) => void;
  onLiveTransform: (
    t: LiveTransform,
    meta?: { mode: DragMode["type"]; resizeHandle?: EditorResizeHandle },
  ) => void;
  onCommit: (t: LiveTransform) => void;
  onCancelLiveTransform: () => void;
  /** Persist decoded natural pixel size for image elements after load. */
  onReportImageIntrinsicSize?: (width: number, height: number) => void;
  /**
   * When set, the element is painted inside a question stacking container — use this value
   * as CSS z-index (internal order only). Omit for global narration/vtuber offsets.
   */
  stackZIndex?: number;
  /** Fill-in canvas question: the stem's `<answer>` parses into an inline input (while the text editing overlay is on). */
  editorFillBlankInline?: boolean;
  /** Stem of a fill-in canvas question: the text editing overlay uses TipTap (answer bubble menu). */
  fillBlankRichTitleEditor?: boolean;
  owningQuestionWrapperId?: string | null;
  quizStemAutoplay?: { wrapperId: string; playUrl: string; nonce: number } | null;
  activeQuizPauseWrapperId?: string | null;
  onPptSlideIndexChange?: (elementId: string, index: number) => void;
  editorQuiz?: QuizConfig | null;
  onOpenQuizSettingsForQuestion?: (questionId: string) => void;
  onOpenQuizLayoutEditor?: (questionId: string, elementId: string) => void;
  onChangeHtmlContentZoom?: (
    zoom: number,
    options?: { recordHistory?: boolean },
  ) => void;
  svgEditState?: CoursewareSvgEditState;
  onSvgEditStateChange?: (state: CoursewareSvgEditState) => void;
  onChangeSvgSource?: (source: string, options?: { recordHistory?: boolean }) => void;
  richEditState?: CoursewareRichEditState;
  onRichEditStateChange?: (state: CoursewareRichEditState) => void;
  onChangeRichLayout?: (
    path: RichTextPath,
    patch: Record<string, string | number | null>,
    options?: { recordHistory?: boolean },
  ) => void;
  onRemoveRichNode?: (path: RichTextPath, options?: { recordHistory?: boolean }) => void;
  stageLayoutKey?: string;
  onSvgTextStyleSnapshot?: (snapshot: SvgTextStyleSnapshot | null) => void;
  svgTextStylePatch?: { nonce: number; patch: SvgTextStylePatch } | null;
}

const StageElement = memo(function StageElement({
  element,
  slide,
  transform,
  opacity,
  visible,
  selected,
  selectedRichTextPath = null,
  editBlocked,
  agentFrozen = false,
  hideEditorChrome = false,
  scale,
  editing,
  initialTextCaretPoint = null,
  currentTime,
  isPlaying,
  playheadRef,
  playheadFromRef,
  playheadClockRunning,
  vtuberSnapshotByElementId,
  vtuberSnapshotBySourceKey,
  vtuberLipSyncByElementId,
  vtuberModelLoadedBySourceKey,
  onCaptureVtuberSnapshot,
  onNarrationLipSyncValueChange,
  onNarrationAudioLoadingChange,
  onNarrationPlayheadDriveChange,
  onSelect,
  onSelectOnly,
  onLock,
  onDuplicate,
  onDelete,
  onStartEditing,
  onStopEditing,
  onChangeText,
  onChangeRichText,
  onSelectRichText,
  onLiveTransform,
  onCommit,
  onCancelLiveTransform,
  onReportImageIntrinsicSize,
  stackZIndex,
  editorFillBlankInline,
  fillBlankRichTitleEditor,
  owningQuestionWrapperId = null,
  quizStemAutoplay = null,
  activeQuizPauseWrapperId = null,
  onPptSlideIndexChange,
  editorQuiz = null,
  onOpenQuizSettingsForQuestion,
  onOpenQuizLayoutEditor,
  onChangeHtmlContentZoom,
  svgEditState,
  onSvgEditStateChange,
  onChangeSvgSource,
  richEditState,
  onRichEditStateChange,
  onChangeRichLayout,
  onRemoveRichNode,
  stageLayoutKey,
  onSvgTextStyleSnapshot,
  svgTextStylePatch = null,
}: StageElementProps) {
  const editorLabels = useCoursewareEditorLabels();
  const { t } = editorLabels;
  const TRANSFORM_COMMIT_EPSILON = 0.1;
  const elRef = useRef<HTMLDivElement | null>(null);
  const vtuberSourceKey =
    element.element_type === "vtuber" ? getVtuberSourceKey(element as VtuberElement) : "";
  const isVtuberModelLoaded = vtuberSourceKey
    ? (vtuberModelLoadedBySourceKey[vtuberSourceKey] ?? false)
    : true;
  const dragRef = useRef<null | {
    mode: DragMode;
    startPointerX: number;
    startPointerY: number;
    startTransform: LiveTransform;
    centerX: number;
    centerY: number;
  }>(null);

  const beginDrag = (e: ReactPointerEvent<HTMLDivElement>, mode: DragMode): void => {
    if (e.button !== 0) return;
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    const centerX = transform.x + transform.width / 2;
    const centerY = transform.y + transform.height / 2;
    dragRef.current = {
      mode,
      startPointerX: e.clientX,
      startPointerY: e.clientY,
      startTransform: { ...transform },
      centerX,
      centerY,
    };
  };

  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>): void => {
    if (!dragRef.current) return;
    e.stopPropagation();
    const d = dragRef.current;
    const dxLogical = (e.clientX - d.startPointerX) / scale;
    const dyLogical = (e.clientY - d.startPointerY) / scale;
    const base = d.startTransform;
    let next: LiveTransform = { ...base };
    if (d.mode.type === "move") {
      next.x = base.x + dxLogical;
      next.y = base.y + dyLogical;
    } else if (d.mode.type === "resize") {
      const h = d.mode.handle;
      if (h.includes("e")) next.width = Math.max(20, base.width + dxLogical);
      if (h.includes("s")) next.height = Math.max(20, base.height + dyLogical);
      if (h.includes("w")) {
        const w = Math.max(20, base.width - dxLogical);
        next.x = base.x + (base.width - w);
        next.width = w;
      }
      if (h.includes("n")) {
        const hgt = Math.max(20, base.height - dyLogical);
        next.y = base.y + (base.height - hgt);
        next.height = hgt;
      }
    } else if (d.mode.type === "rotate") {
      const rect = elRef.current?.parentElement?.getBoundingClientRect();
      if (rect) {
        const cx = rect.left + d.centerX * scale;
        const cy = rect.top + d.centerY * scale;
        const angle = (Math.atan2(e.clientY - cy, e.clientX - cx) * 180) / Math.PI + 90;
        next.rotation = Math.round(angle);
      }
    }
    onLiveTransform(
      next,
      d.mode.type === "resize"
        ? { mode: "resize", resizeHandle: d.mode.handle }
        : { mode: d.mode.type },
    );
  };

  const endDrag = (e: ReactPointerEvent<HTMLDivElement>): void => {
    if (!dragRef.current) return;
    e.stopPropagation();
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    const d = dragRef.current;
    dragRef.current = null;
    const dxLogical = (e.clientX - d.startPointerX) / scale;
    const dyLogical = (e.clientY - d.startPointerY) / scale;
    let next: LiveTransform = { ...d.startTransform };
    if (d.mode.type === "move" || d.mode.type === "resize") {
      // Commit the pose last shown on the canvas (including alignment snapping); recomputing from pointer deltas would jump off the guide on release.
      next = { ...transform };
    } else if (d.mode.type === "rotate") {
      const rect = elRef.current?.parentElement?.getBoundingClientRect();
      if (rect) {
        const cx = rect.left + d.centerX * scale;
        const cy = rect.top + d.centerY * scale;
        const angle = (Math.atan2(e.clientY - cy, e.clientX - cx) * 180) / Math.PI + 90;
        next.rotation = Math.round(angle);
      }
    }
    const changed =
      Math.abs(next.x - d.startTransform.x) > TRANSFORM_COMMIT_EPSILON ||
      Math.abs(next.y - d.startTransform.y) > TRANSFORM_COMMIT_EPSILON ||
      Math.abs(next.width - d.startTransform.width) > TRANSFORM_COMMIT_EPSILON ||
      Math.abs(next.height - d.startTransform.height) > TRANSFORM_COMMIT_EPSILON ||
      Math.abs(next.rotation - d.startTransform.rotation) > TRANSFORM_COMMIT_EPSILON;
    if (!changed) {
      onCancelLiveTransform();
      return;
    }
    onCommit(next);
  };

  // In the single-element quiz model a quiz element is just a regular
  // selectable canvas element — there are no nested members to "enter".
  const isQuestionWrapper =
    element.element_type === "quiz" || element.element_type === "quiz_score_summary";
  const quizCanvasBadgeLabel = useMemo(() => {
    if (element.element_type === "quiz_score_summary") {
      return t("coursewareEditor.common.scoreSummaryElement");
    }
    if (!isQuestionWrapper || element.element_type !== "quiz") {
      return t("coursewareEditor.common.questionElement");
    }
    return formatQuizCanvasBadgeLabel(
      t,
      editorQuiz,
      element as QuizSlideElement,
      editorLabels.questionTemplateLabel,
    );
  }, [editorLabels.questionTemplateLabel, editorQuiz, element, isQuestionWrapper, t]);
  const canvasAudioDisplay =
    element.element_type === "audio" ? getCanvasAudioDisplayMode(element) : null;
  const enterExitFx = useMemo(
    () => computeElementEnterExitEffectVisual(element, slide, currentTime),
    [element, slide, currentTime],
  );
  const editingTextElement = editing && element.element_type === "text";
  const enterExitInnerTransform = `translate(${enterExitFx.translateLogicalX * scale}px, ${enterExitFx.translateLogicalY * scale}px) rotate(${enterExitFx.rotateExtraDeg}deg) scale(${enterExitFx.uniformScale})`;
  const wrapperStyle: CSSProperties = {
    position: "absolute",
    left: transform.x * scale,
    top: transform.y * scale,
    width: transform.width * scale,
    height: transform.height * scale,
    zIndex:
      stackZIndex !== undefined
        ? stackZIndex
        : element.element_type === "narration"
          ? STAGE_NARRATION_Z_INDEX_BASE + element.style.z_index
          : element.element_type === "vtuber"
          ? STAGE_VTUBER_Z_INDEX_BASE + element.style.z_index
          : element.style.z_index,
    transform: editingTextElement ? undefined : `rotate(${transform.rotation}deg)`,
    transformOrigin: "center center",
    // Opacity is applied to the content layer, not the wrapper, so the selection
    // outline and handles remain visible even when the element is fully transparent.
    pointerEvents:
      hideEditorChrome || editBlocked || canvasAudioDisplay === "hidden"
        ? "none"
        : visible
          ? "auto"
          : "none",
    outline: hideEditorChrome
      ? "none"
      : editing
        ? "2px solid #22D3EE"
        : element.element_type === "vtuber" && visible && !isVtuberModelLoaded
          ? "1px dashed rgba(148,163,184,0.25)"
          : selected
            ? "2px solid #3B82F6"
            : editBlocked || canvasAudioDisplay === "hidden"
              ? "none"
              : element.element_type === "vtuber" && visible && isVtuberModelLoaded
                ? "none"
                : element.element_type === "narration"
                ? "none"
                : isQuestionWrapper
                  ? "none"
                  : "1px dashed rgba(148,163,184,0.25)",
    outlineOffset: 0,
    cursor: editing
      ? "text"
      : editBlocked
        ? "default"
      : isQuestionWrapper
        ? "move"
        : selected
          ? "move"
          : "pointer",
  };

  // Exited / not-yet-entered elements show nothing at all (0), but the wrapper's dashed
  // outline remains so the element is still visually referenceable. While a text element
  // is being edited, force the content to full opacity regardless of its configured alpha
  // so the user can actually see what they're typing.
  const contentOpacity = editing ? 1 : visible ? opacity * enterExitFx.opacityFactor : 0;

  const handleNarrationAudioLoadingChange = useCallback(
    (isLoading: boolean) => {
      onNarrationAudioLoadingChange(element.element_id, isLoading);
    },
    [onNarrationAudioLoadingChange, element.element_id],
  );

  const content = renderElementContent(element, transform.width, transform.height, scale, "stage", {
    translate: t,
    vtuberSnapshotByElementId,
    vtuberSnapshotBySourceKey,
    vtuberLipSyncByElementId,
    onCaptureVtuberSnapshot,
    onNarrationLipSyncValueChange,
    onNarrationAudioLoadingChange: handleNarrationAudioLoadingChange,
    onNarrationPlayheadDriveChange,
    currentTime,
    isPlaying,
    playheadRef,
    playheadFromRef,
    playheadClockRunning,
    onImageIntrinsicSize: onReportImageIntrinsicSize,
    editorFillBlankInline,
    owningQuestionWrapperId,
    quizStemAutoplay,
    activeQuizPauseWrapperId,
    onPptSlideIndexChange,
    editorQuiz,
    richEditable: editing && element.element_type === "rich",
    richEditState,
    onRichEditStateChange,
    onChangeRichLayout,
    onRemoveRichNode,
    selectedRichTextPath: selectedRichTextPath ?? undefined,
    onRichTextChange: onChangeRichText,
    onRichTextSelect: onSelectRichText,
    onRichExitEdit: onStopEditing,
    svgEditable: editing && element.element_type === "svg",
    svgEditState,
    onSvgEditStateChange,
    onSvgSourceChange: onChangeSvgSource,
    onSvgExitEdit: onStopEditing,
    layoutSyncKey: stageLayoutKey,
    onSvgTextStyleSnapshot,
    svgTextStylePatch,
  });

  return (
    <div
      ref={elRef}
      className={element.element_type === "ppt" ? "group/ppt" : undefined}
      style={wrapperStyle}
      onPointerDown={(e) => {
        if (editing || editBlocked) {
          e.stopPropagation();
          return;
        }
        // PPT: the inner iframe is pointer-events-none, so events land on this wrapper and dragging starts here; page buttons carry data-ppt-slide-nav and stopPropagation.
        if (element.element_type === "ppt") {
          const target = e.target as HTMLElement | null;
          if (target?.closest("[data-ppt-slide-nav]")) return;
        }
        // Slide audio elements with active <audio> controls should not start
        // a drag; just sync selection so the user can still click chrome.
        const target = e.target as HTMLElement | null;
        if (element.element_type === "audio" && target?.closest("audio")) {
          if (!selected) onSelectOnly();
          return;
        }
        const hasModifier = e.metaKey || e.ctrlKey || e.shiftKey;
        if (hasModifier) {
          e.preventDefault();
          onSelect(e);
          return;
        }
        if (!selected) onSelectOnly();
        beginDrag(e, { type: "move" });
      }}
      onPointerMove={editing || editBlocked ? undefined : onPointerMove}
      onPointerUp={editing || editBlocked ? undefined : endDrag}
      onPointerCancel={editing || editBlocked ? undefined : endDrag}
      onDoubleClick={(e) => {
        if (editBlocked) return;
        if (element.element_type === "text") {
          e.stopPropagation();
          onStartEditing({ clientX: e.clientX, clientY: e.clientY });
          return;
        }
        if (element.element_type === "rich") {
          e.stopPropagation();
          onStartEditing({ clientX: e.clientX, clientY: e.clientY });
          return;
        }
        if (
          element.element_type === "svg" &&
          isInlineSvgSource((element as SvgElement).source)
        ) {
          e.stopPropagation();
          onStartEditing();
          return;
        }
        if (
          element.element_type === "quiz" &&
          element.quiz_question_id &&
          onOpenQuizLayoutEditor &&
          getEditorQuestionConfig(editorQuiz, element as QuizSlideElement)
        ) {
          e.stopPropagation();
          onOpenQuizLayoutEditor(element.quiz_question_id, element.element_id);
        }
      }}
    >
      {editingTextElement ? (
        <div className="absolute inset-0" style={{ opacity: contentOpacity }}>
          <div
            aria-hidden
            className="pointer-events-none absolute inset-0 z-0 flex h-full w-full items-center overflow-hidden"
            style={buildTextElementContainerStyle(element, scale)}
          />
          <TextEditOverlay
            element={element}
            scale={scale}
            initialCaretPoint={initialTextCaretPoint}
            onChange={onChangeText}
            onCommit={onStopEditing}
          />
        </div>
      ) : (
        <div
          className="absolute inset-0"
          style={{ opacity: contentOpacity }}
        >
          <div
            className={`absolute inset-0 flex items-stretch justify-stretch ${
              element.element_type === "narration"
                ? "overflow-visible"
                : element.element_type === "quiz"
                  ? "min-h-0 overflow-visible"
                  : editing &&
                      (element.element_type === "rich" || element.element_type === "svg")
                    ? "overflow-visible"
                    : "overflow-hidden"
            } ${editing && (element.element_type === "rich" || element.element_type === "svg") ? "pointer-events-auto" : "pointer-events-none"}`}
            style={{
              transform: enterExitInnerTransform,
              transformOrigin: "center center",
            }}
          >
            {content}
          </div>
        </div>
      )}

      {/* Quiz canvas badge: label (non-interactive); edit opens quiz modal on this question. */}
      {isQuestionWrapper && element.element_type === "quiz" && !editing ? (
        <div
          className="absolute z-20 flex select-none items-center"
          style={{
            left: 0,
            top: -42 * scale,
            gap: 6 * scale,
            pointerEvents: "none",
          }}
        >
          <div
            className={`flex items-center rounded-full border font-medium shadow-sm transition ${
              selected
                ? "border-blue-300 bg-blue-500/95 text-white"
                : "border-blue-400/70 bg-blue-500/80 text-blue-50"
            }`}
            style={{
              gap: 6 * scale,
              padding: `${4 * scale}px ${12 * scale}px`,
              fontSize: 20 * scale,
              lineHeight: 1.25,
            }}
            title={quizCanvasBadgeLabel}
          >
            <span>{quizCanvasBadgeLabel}</span>
            {element.quiz_question_id ? null : (
              <span
                className="rounded-sm bg-amber-500/85 text-amber-950"
                style={{
                  fontSize: 14 * scale,
                  padding: `${2 * scale}px ${6 * scale}px`,
                }}
              >
                {t("coursewareEditor.common.unbound")}
              </span>
            )}
          </div>
          {element.quiz_question_id &&
          getEditorQuestionConfig(editorQuiz, element as QuizSlideElement) ? (
            <>
              {onOpenQuizLayoutEditor ? (
                <button
                  type="button"
                  className={`flex shrink-0 items-center justify-center rounded-full border shadow-sm transition ${
                    selected
                      ? "border-blue-300 bg-blue-500/95 text-white hover:bg-blue-600/95"
                      : "border-blue-400/70 bg-blue-500/80 text-blue-50 hover:bg-blue-500/95"
                  }`}
                  style={{
                    width: 34 * scale,
                    height: 34 * scale,
                    pointerEvents: "auto",
                  }}
                  title={t("coursewareEditor.quizLayout.openEditor")}
                  onPointerDown={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                  }}
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    if (!selected) onSelectOnly();
                    onOpenQuizLayoutEditor(element.quiz_question_id, element.element_id);
                  }}
                >
                  <LayoutTemplate style={{ width: 18 * scale, height: 18 * scale }} />
                </button>
              ) : null}
              {onOpenQuizSettingsForQuestion ? (
                <button
                  type="button"
                  className={`flex shrink-0 items-center justify-center rounded-full border shadow-sm transition ${
                    selected
                      ? "border-blue-300 bg-blue-500/95 text-white hover:bg-blue-600/95"
                      : "border-blue-400/70 bg-blue-500/80 text-blue-50 hover:bg-blue-500/95"
                  }`}
                  style={{
                    width: 34 * scale,
                    height: 34 * scale,
                    pointerEvents: "auto",
                  }}
                  title={t("coursewareEditor.question.editInQuizSettings")}
                  onPointerDown={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                  }}
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    if (!selected) onSelectOnly();
                    onOpenQuizSettingsForQuestion(element.quiz_question_id);
                  }}
                >
                  <PencilLine style={{ width: 18 * scale, height: 18 * scale }} />
                </button>
              ) : null}
            </>
          ) : null}
        </div>
      ) : null}

      {element.element_type === "html" &&
      selected &&
      !hideEditorChrome &&
      !editing &&
      !editBlocked &&
      onChangeHtmlContentZoom ? (
        <CoursewareHtmlContentZoomControl
          value={resolveHtmlContentZoom((element as HtmlElement).content_zoom)}
          hostWidthPx={transform.width * scale}
          scale={scale}
          label={t("coursewareEditor.common.htmlContentZoom")}
          onChange={onChangeHtmlContentZoom}
        />
      ) : null}

      {agentFrozen && !hideEditorChrome ? (
        <div
          className="courseware-editor-agent-frozen-overlay pointer-events-none absolute inset-0 z-25 overflow-hidden rounded-lg"
          aria-hidden
        />
      ) : null}

      {selected && !hideEditorChrome && !editing && !editBlocked && canvasAudioDisplay !== "hidden" ? (
        <>
          <div
            className="absolute z-20 flex items-center gap-1 rounded-full border border-slate-200/90 bg-white/95 px-1.5 py-1 shadow-lg shadow-slate-900/10 backdrop-blur dark:border-slate-700/80 dark:bg-slate-900/95 dark:shadow-black/20"
            style={{
              right: -12,
              top: -12,
              pointerEvents: "auto",
            }}
          >
            <button
              type="button"
              className="flex h-6 w-6 items-center justify-center rounded-full text-slate-600 transition hover:bg-slate-100 hover:text-slate-900 dark:text-slate-300 dark:hover:bg-slate-800 dark:hover:text-white"
              title={t("coursewareEditor.common.lockElement")}
              aria-label={t("coursewareEditor.common.lockElement")}
              onPointerDown={(e) => {
                e.preventDefault();
                e.stopPropagation();
              }}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onLock();
              }}
            >
              <Lock className="h-3.5 w-3.5" />
            </button>
            <button
              type="button"
              className="flex h-6 w-6 items-center justify-center rounded-full text-slate-600 transition hover:bg-slate-100 hover:text-slate-900 dark:text-slate-300 dark:hover:bg-slate-800 dark:hover:text-white"
              title={t("coursewareEditor.common.copy")}
              aria-label={t("coursewareEditor.common.copy")}
              onPointerDown={(e) => {
                e.preventDefault();
                e.stopPropagation();
              }}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onDuplicate();
              }}
            >
              <Copy className="h-3.5 w-3.5" />
            </button>
            <button
              type="button"
              className="flex h-6 w-6 items-center justify-center rounded-full text-rose-500 transition hover:bg-rose-50 hover:text-rose-600 dark:text-rose-300 dark:hover:bg-rose-500/10 dark:hover:text-rose-200"
              title={t("coursewareEditor.common.delete")}
              aria-label={t("coursewareEditor.common.delete")}
              onPointerDown={(e) => {
                e.preventDefault();
                e.stopPropagation();
              }}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                onDelete();
              }}
            >
              <Trash2 className="h-3.5 w-3.5" />
            </button>
          </div>
          {/* resize handles */}
          {(["nw", "ne", "sw", "se", "n", "s", "e", "w"] as const).map((h) => (
            <div
              key={h}
              onPointerDown={(e) => beginDrag(e, { type: "resize", handle: h })}
              className="absolute z-10 h-3 w-3 rounded-sm border border-white bg-blue-500 shadow"
              style={{
                left:
                  h.includes("w")
                    ? -6
                    : h.includes("e")
                      ? "calc(100% - 6px)"
                      : "calc(50% - 6px)",
                top:
                  h.includes("n")
                    ? -6
                    : h.includes("s")
                      ? "calc(100% - 6px)"
                      : "calc(50% - 6px)",
                cursor: resizeCursor(h),
                pointerEvents: "auto",
              }}
            />
          ))}
          {/* rotate handle */}
          <div
            onPointerDown={(e) => beginDrag(e, { type: "rotate" })}
            className="absolute z-10 flex h-6 w-6 items-center justify-center rounded-full border border-white bg-emerald-500 text-white shadow"
            style={{
              left: "calc(50% - 12px)",
              top: -36,
              cursor: "grab",
              pointerEvents: "auto",
            }}
            title={t("coursewareEditor.common.rotate")}
          >
            <RotateCw className="h-3.5 w-3.5" />
          </div>
          {/* connector line from rotate to top edge */}
          <div
            className="pointer-events-none absolute z-0 w-px bg-emerald-500/60"
            style={{ left: "calc(50% - 0.5px)", top: -18, height: 18 }}
          />
        </>
      ) : null}
    </div>
  );
});

// ---------- text edit overlay (inline text editing) ----------

type TextEditCaretPoint = { clientX: number; clientY: number };

const collapseContentEditableCaretAtEnd = (node: HTMLElement): void => {
  node.focus();
  const doc = node.ownerDocument;
  const sel = doc.getSelection();
  if (!sel) return;
  const range = doc.createRange();
  range.selectNodeContents(node);
  range.collapse(false);
  sel.removeAllRanges();
  sel.addRange(range);
};

const placeContentEditableCaretAtPoint = (
  node: HTMLElement,
  clientX: number,
  clientY: number,
): void => {
  node.focus();
  const doc = node.ownerDocument;
  const sel = doc.getSelection();
  if (!sel) return;

  let range: Range | null = null;
  if (typeof doc.caretRangeFromPoint === "function") {
    range = doc.caretRangeFromPoint(clientX, clientY);
  } else {
    const caretPositionFromPoint = (
      doc as Document & {
        caretPositionFromPoint?: (
          x: number,
          y: number,
        ) => { offsetNode: Node; offset: number } | null;
      }
    ).caretPositionFromPoint;
    if (typeof caretPositionFromPoint === "function") {
      const position = caretPositionFromPoint(clientX, clientY);
      if (position) {
        range = doc.createRange();
        range.setStart(position.offsetNode, position.offset);
        range.collapse(true);
      }
    }
  }

  if (range && node.contains(range.startContainer)) {
    sel.removeAllRanges();
    sel.addRange(range);
    return;
  }

  collapseContentEditableCaretAtEnd(node);
};

interface TextEditOverlayProps {
  element: CourseElement & { element_type: "text" };
  scale: number;
  initialCaretPoint?: TextEditCaretPoint | null;
  onChange: (text: string) => void;
  onCommit: () => void;
}

function TextEditOverlay({
  element,
  scale,
  initialCaretPoint = null,
  onChange,
  onCommit,
}: TextEditOverlayProps) {
  const overlayRef = useRef<HTMLDivElement | null>(null);
  const editableRef = useRef<HTMLDivElement | null>(null);
  // Capture the initial text once so we don't re-render React children and lose the caret.
  const initialTextRef = useRef(element.text);
  const initialCaretPointRef = useRef(initialCaretPoint);

  useEffect(() => {
    const node = editableRef.current;
    if (!node) return;
    node.innerText = initialTextRef.current;

    const placeCaret = (): void => {
      const editable = editableRef.current;
      if (!editable) return;
      const point = initialCaretPointRef.current;
      if (point) {
        placeContentEditableCaretAtPoint(editable, point.clientX, point.clientY);
      } else {
        collapseContentEditableCaretAtEnd(editable);
      }
    };

    requestAnimationFrame(() => {
      requestAnimationFrame(placeCaret);
    });
  }, []);

  useEffect(() => {
    const overlayRoot = overlayRef.current;
    if (!overlayRoot) return;

    const onPointerDown = (event: PointerEvent): void => {
      const target = event.target as Node;
      const editable = editableRef.current;
      if (!editable) return;

      if (overlayRoot.contains(target)) {
        if (!editable.contains(target)) {
          event.preventDefault();
          placeContentEditableCaretAtPoint(editable, event.clientX, event.clientY);
        }
        return;
      }

      onCommit();
    };

    document.addEventListener("pointerdown", onPointerDown, true);
    return () => document.removeEventListener("pointerdown", onPointerDown, true);
  }, [onCommit]);

  return (
    <div
      ref={overlayRef}
      data-text-edit-overlay
      className="relative z-10 flex h-full w-full items-center overflow-hidden"
      style={buildTextElementContainerLayoutStyle(element, scale)}
      onPointerDown={(e) => e.stopPropagation()}
      onMouseDown={(e) => e.stopPropagation()}
      onDoubleClick={(e) => e.stopPropagation()}
    >
      <div
        ref={editableRef}
        contentEditable
        suppressContentEditableWarning
        spellCheck={false}
        onInput={(e) => onChange((e.currentTarget as HTMLDivElement).innerText)}
        onKeyDown={(e) => {
          e.stopPropagation();
          if (e.key === "Escape") {
            e.preventDefault();
            onCommit();
          } else if (e.key === "Enter" && !e.shiftKey && !e.metaKey && !e.ctrlKey && !e.altKey) {
            // Enter commits; Shift+Enter (or modifier+Enter) inserts a newline.
            e.preventDefault();
            onCommit();
          }
        }}
        className="w-full"
        style={{
          fontSize: element.font_size * scale,
          color: element.color,
          fontFamily: element.font_family,
          fontWeight: element.bold ? 700 : 400,
          fontStyle: element.italic ? "italic" : "normal",
          textAlign: element.align as CSSProperties["textAlign"],
          lineHeight: resolveTextLineHeight(element.line_height),
          whiteSpace: "pre-wrap",
          wordBreak: "break-all",
          overflowWrap: "anywhere",
          outline: "none",
          width: "100%",
          backgroundColor: "transparent",
          caretColor: element.color,
        }}
      />
    </div>
  );
}

const resizeCursor = (h: string): string => {
  switch (h) {
    case "nw":
    case "se":
      return "nwse-resize";
    case "ne":
    case "sw":
      return "nesw-resize";
    case "n":
    case "s":
      return "ns-resize";
    case "e":
    case "w":
      return "ew-resize";
    default:
      return "default";
  }
};

// ---------- narration stage player ----------

const applyOpacityToHexColor = (hexColor: string, opacity: number): string => {
  const matched = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hexColor.trim());
  if (!matched) return hexColor;
  const [, rHex, gHex, bHex] = matched;
  const r = Number.parseInt(rHex, 16);
  const g = Number.parseInt(gHex, 16);
  const b = Number.parseInt(bHex, 16);
  return `rgba(${r}, ${g}, ${b}, ${clamp(opacity, 0, 1)})`;
};

const formatNarrationSubtitleText = (text: string): string =>
  text.trimEnd().replace(/[。．.，,、！!；;：:…]+$/u, "").trimEnd();

// ---------- shared lip-sync helpers ----------
// We deliberately avoid createMediaElementSource / MES: routing playback through
// an AudioContext is fragile (CORS, user-gesture, suspend states can silently
// swallow the audio). Instead, we play via the native <audio> element and drive
// lip-sync from a pre-decoded AudioBuffer sampled at audio.currentTime.

type DecodedLipSyncBuffer = { data: Float32Array; sampleRate: number };

let sharedDecodeContextRef: AudioContext | null = null;
const getDecodeAudioContext = (): AudioContext | null => {
  if (typeof window === "undefined") return null;
  if (sharedDecodeContextRef && sharedDecodeContextRef.state !== "closed") {
    return sharedDecodeContextRef;
  }
  try {
    const Ctor =
      window.AudioContext ||
      (window as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return null;
    sharedDecodeContextRef = new Ctor();
    return sharedDecodeContextRef;
  } catch {
    return null;
  }
};

const lipSyncBufferCache = new Map<string, DecodedLipSyncBuffer>();
const lipSyncBufferLoading = new Map<string, Promise<DecodedLipSyncBuffer | null>>();

const loadLipSyncBuffer = (url: string): Promise<DecodedLipSyncBuffer | null> => {
  if (!url) return Promise.resolve(null);
  const cached = lipSyncBufferCache.get(url);
  if (cached) return Promise.resolve(cached);
  const pending = lipSyncBufferLoading.get(url);
  if (pending) return pending;
  const ctx = getDecodeAudioContext();
  if (!ctx) return Promise.resolve(null);
  const promise = (async (): Promise<DecodedLipSyncBuffer | null> => {
    try {
      const res = await fetch(url, { mode: "cors", credentials: "omit" });
      if (!res.ok) return null;
      const arrayBuffer = await res.arrayBuffer();
      const decoded = await new Promise<AudioBuffer>((resolve, reject) => {
        try {
          const maybePromise = ctx.decodeAudioData(
            arrayBuffer,
            (buf) => resolve(buf),
            (err) => reject(err),
          );
          if (maybePromise && typeof (maybePromise as Promise<AudioBuffer>).then === "function") {
            (maybePromise as Promise<AudioBuffer>).then(resolve, reject);
          }
        } catch (err) {
          reject(err);
        }
      });
      const data = new Float32Array(decoded.getChannelData(0));
      const result: DecodedLipSyncBuffer = { data, sampleRate: decoded.sampleRate };
      lipSyncBufferCache.set(url, result);
      return result;
    } catch {
      return null;
    } finally {
      lipSyncBufferLoading.delete(url);
    }
  })();
  lipSyncBufferLoading.set(url, promise);
  return promise;
};

const narrationAudioPreloadCache = new Map<string, Promise<void>>();

const preloadNarrationAudioUrls = (urls: string[]): void => {
  if (typeof window === "undefined") return;
  for (const rawUrl of urls) {
    const url = rawUrl.trim();
    if (!url) continue;
    if (narrationAudioPreloadCache.has(url)) continue;
    const promise = loadLipSyncBuffer(url).then(() => undefined);
    narrationAudioPreloadCache.set(url, promise);
    void promise;
  }
};

/** The hidden track of the quiz "question narration": the same RMS lip sync as {@link NarrationStagePlayer}, driving {@link VtuberStagePlayer}. */
function EditorQuizContentNarrationLipSyncDriver({
  audioRef,
  target,
  onLipSyncValueChange,
}: {
  audioRef: RefObject<HTMLAudioElement | null>;
  target: { url: string; vtuberElementId: string } | null;
  onLipSyncValueChange: (vtuberElementId: string, value: number) => void;
}): null {
  const lipSyncFrameRef = useRef<number | null>(null);
  const lipSyncBufferRef = useRef<DecodedLipSyncBuffer | null>(null);
  const mouthCurrentRef = useRef(0);

  useEffect(() => {
    const vtuberElementId = target?.vtuberElementId?.trim() ?? "";
    const src = target?.url?.trim() ?? "";
    if (!target || !src || !vtuberElementId) {
      if (lipSyncFrameRef.current !== null) {
        cancelAnimationFrame(lipSyncFrameRef.current);
        lipSyncFrameRef.current = null;
      }
      mouthCurrentRef.current = 0;
      return;
    }

    const stopLipSync = (): void => {
      if (lipSyncFrameRef.current !== null) {
        cancelAnimationFrame(lipSyncFrameRef.current);
        lipSyncFrameRef.current = null;
      }
      mouthCurrentRef.current = 0;
      onLipSyncValueChange(vtuberElementId, 0);
    };

    lipSyncBufferRef.current = null;
    let cancelled = false;
    const resolveDecodeUrl = (): string => {
      const el = audioRef.current;
      return (el?.currentSrc || el?.src || src || "").trim() || src;
    };
    const kickDecode = (): void => {
      const u = resolveDecodeUrl();
      if (!u) return;
      void loadLipSyncBuffer(u).then((buf) => {
        if (cancelled) return;
        lipSyncBufferRef.current = buf;
      });
    };
    kickDecode();
    const elAttach = audioRef.current;
    const onAudioReady = (): void => {
      kickDecode();
    };
    elAttach?.addEventListener("loadedmetadata", onAudioReady);
    elAttach?.addEventListener("canplay", onAudioReady);

    const LERP_FACTOR = 0.8;
    const WINDOW_SAMPLES = 1024;
    const updateMouth = (): void => {
      const currentAudio = audioRef.current;
      const buf = lipSyncBufferRef.current;
      if (
        !currentAudio ||
        currentAudio.paused ||
        currentAudio.ended ||
        (Number.isFinite(currentAudio.duration) &&
          currentAudio.duration > 0 &&
          currentAudio.currentTime >= currentAudio.duration - 0.02)
      ) {
        onLipSyncValueChange(vtuberElementId, 0);
        mouthCurrentRef.current = 0;
        lipSyncFrameRef.current = requestAnimationFrame(updateMouth);
        return;
      }
      if (!buf) {
        lipSyncFrameRef.current = requestAnimationFrame(updateMouth);
        return;
      }
      const sampleIdx = Math.max(0, Math.floor(currentAudio.currentTime * buf.sampleRate));
      const halfWindow = WINDOW_SAMPLES >> 1;
      const start = Math.max(0, sampleIdx - halfWindow);
      const end = Math.min(buf.data.length, start + WINDOW_SAMPLES);
      let sum = 0;
      const len = end - start;
      if (len > 0) {
        for (let i = start; i < end; i += 1) {
          const v = buf.data[i];
          sum += v * v;
        }
      }
      const rms = len > 0 ? Math.sqrt(sum / len) : 0;
      const targetMouthSyncValue = Math.min(Math.max(rms * 8, 0.1), 1);
      mouthCurrentRef.current += (targetMouthSyncValue - mouthCurrentRef.current) * LERP_FACTOR;
      const naturalVariation = (Math.random() - 0.5) * 0.05;
      const finalValue = Math.max(0, Math.min(1, mouthCurrentRef.current + naturalVariation));
      onLipSyncValueChange(vtuberElementId, finalValue);
      lipSyncFrameRef.current = requestAnimationFrame(updateMouth);
    };
    lipSyncFrameRef.current = requestAnimationFrame(updateMouth);

    return () => {
      cancelled = true;
      elAttach?.removeEventListener("loadedmetadata", onAudioReady);
      elAttach?.removeEventListener("canplay", onAudioReady);
      stopLipSync();
    };
  }, [audioRef, target, onLipSyncValueChange]);

  return null;
}

interface NarrationStagePlayerProps {
  element: NarrationElement;
  widthLogical: number;
  heightLogical: number;
  scale: number;
  currentTime: number;
  isPlaying: boolean;
  playheadRef?: RefObject<number>;
  playheadFromRef?: boolean;
  onLipSyncValueChange?: (vtuberElementId: string, value: number) => void;
  onPlaybackLoadingChange?: (isLoading: boolean) => void;
  onPlayheadDriveChange?: (localMs: number | null) => void;
}

function NarrationStagePlayer({
  element,
  widthLogical,
  heightLogical,
  scale,
  currentTime,
  isPlaying,
  playheadRef,
  playheadFromRef = false,
  onLipSyncValueChange,
  onPlaybackLoadingChange,
  onPlayheadDriveChange,
}: NarrationStagePlayerProps) {
  const isPlayingRef = useRef(isPlaying);
  const lipSyncFrameRef = useRef<number | null>(null);
  const lipSyncBufferRef = useRef<DecodedLipSyncBuffer | null>(null);
  const mouthCurrentRef = useRef(0);

  const { audioRef, resolved, activeSegment, displaySegment, activeIndex } = useNarrationSegmentPlayback({
    element,
    currentTime,
    isPlaying,
    playbackRate: 1,
    volumeMultiplier: 1,
    playheadRef,
    playheadFromRef,
    onPlaybackLoadingChange,
    onPlayheadDriveChange,
  });

  const activeSrc = activeSegment?.audio_url ?? "";
  const subtitleBgOpacity = clamp(
    typeof element.subtitle_background_opacity === "number"
      ? element.subtitle_background_opacity
      : element.subtitle_background_transparent
        ? 0
        : 0.7,
    0,
    1,
  );
  const subtitleBgColor = applyOpacityToHexColor(
    element.subtitle_background_color || "#020617",
    subtitleBgOpacity,
  );
  const subtitleTextColor = element.subtitle_text_color || "#FFFFFF";

  useEffect(() => {
    isPlayingRef.current = isPlaying;
  }, [isPlaying]);

  useEffect(() => {
    preloadNarrationAudioUrls(
      resolved
        .slice(0, 3)
        .map((seg) => seg.audio_url)
        .filter((url): url is string => Boolean(url?.trim())),
    );
  }, [resolved]);

  useEffect(() => {
    if (activeIndex < 0) return;
    preloadNarrationAudioUrls(
      resolved
        .slice(activeIndex, activeIndex + 3)
        .map((seg) => seg.audio_url)
        .filter((url): url is string => Boolean(url?.trim())),
    );
  }, [activeIndex, resolved]);

  const stopLipSync = useCallback(() => {
    if (lipSyncFrameRef.current !== null) {
      cancelAnimationFrame(lipSyncFrameRef.current);
      lipSyncFrameRef.current = null;
    }
    mouthCurrentRef.current = 0;
    onLipSyncValueChange?.(element.vtuber_element_id, 0);
  }, [element.vtuber_element_id, onLipSyncValueChange]);

  // (1) Segment lip-sync decode — audio src/play/seek is handled by useSyncedNarrationAudio.
  useEffect(() => {
    if (!activeSrc) {
      lipSyncBufferRef.current = null;
      stopLipSync();
      return;
    }

    stopLipSync();
    lipSyncBufferRef.current = null;
    let cancelled = false;
    void loadLipSyncBuffer(activeSrc).then((buf) => {
      if (cancelled) return;
      lipSyncBufferRef.current = buf;
    });

    const LERP_FACTOR = 0.8;
    const WINDOW_SAMPLES = 1024;
    const updateMouth = (): void => {
      const currentAudio = audioRef.current;
      const buf = lipSyncBufferRef.current;
      if (!currentAudio || currentAudio.paused || !isPlayingRef.current) {
        onLipSyncValueChange?.(element.vtuber_element_id, 0);
        mouthCurrentRef.current = 0;
        lipSyncFrameRef.current = requestAnimationFrame(updateMouth);
        return;
      }
      if (!buf) {
        lipSyncFrameRef.current = requestAnimationFrame(updateMouth);
        return;
      }
      const sampleIdx = Math.max(0, Math.floor(currentAudio.currentTime * buf.sampleRate));
      const halfWindow = WINDOW_SAMPLES >> 1;
      const start = Math.max(0, sampleIdx - halfWindow);
      const end = Math.min(buf.data.length, start + WINDOW_SAMPLES);
      let sum = 0;
      const len = end - start;
      if (len > 0) {
        for (let i = start; i < end; i += 1) {
          const v = buf.data[i];
          sum += v * v;
        }
      }
      const rms = len > 0 ? Math.sqrt(sum / len) : 0;
      const targetMouthSyncValue = Math.min(Math.max(rms * 8, 0.1), 1);
      mouthCurrentRef.current += (targetMouthSyncValue - mouthCurrentRef.current) * LERP_FACTOR;
      const naturalVariation = (Math.random() - 0.5) * 0.05;
      const finalValue = Math.max(0, Math.min(1, mouthCurrentRef.current + naturalVariation));
      onLipSyncValueChange?.(element.vtuber_element_id, finalValue);
      lipSyncFrameRef.current = requestAnimationFrame(updateMouth);
    };
    lipSyncFrameRef.current = requestAnimationFrame(updateMouth);

    return () => {
      cancelled = true;
      stopLipSync();
    };
  }, [
    activeSrc,
    element.vtuber_element_id,
    onLipSyncValueChange,
    stopLipSync,
  ]);

  useEffect(
    () => () => {
      stopLipSync();
      lipSyncBufferRef.current = null;
    },
    [stopLipSync],
  );

  const widthPx = Math.max(20, Math.round(widthLogical * scale));
  const heightPx = Math.max(20, Math.round(heightLogical * scale));
  const subtitleSize = Math.max(16, Math.min(56, heightPx * 0.45));
  const activeSubtitleText =
    element.subtitle_visible === false
      ? ""
      : displaySegment
        ? formatNarrationSubtitleText(displaySegment.text)
        : "";

  return (
    <div className="relative flex h-full w-full items-end justify-center">
      <audio ref={audioRef} hidden preload="auto" playsInline crossOrigin="anonymous" />
      {activeSubtitleText ? (
        <div
          className="max-w-full rounded px-3 py-2 text-center shadow"
          style={{
            backgroundColor: subtitleBgColor,
            color: subtitleTextColor,
            fontSize: subtitleSize,
            lineHeight: 1.25,
            maxWidth: widthPx,
          }}
        >
          {activeSubtitleText}
        </div>
      ) : null}
    </div>
  );
}

interface EditorPersistentVtuberLayerProps {
  coursewareId: string;
  placements: readonly EditorVtuberPlacement[];
  scale: number;
  liveTransforms: Record<string, LiveTransform>;
  vtuberSnapshotByElementId: Record<string, string>;
  vtuberSnapshotBySourceKey: Record<string, string>;
  lipSyncByElementId: Record<string, number>;
  allSlides: SlideElement[];
  onCaptureVtuberSnapshot: (elementId: string, dataUrl: string) => void;
  isPlaying: boolean;
  currentTime: number;
  onVtuberSourceModelLoading: (sourceKey: string, loading: boolean) => void;
  onVtuberSourceModelLoaded: (sourceKey: string) => void;
  onPlaybackLoadingTokenChange: (token: string, isLoading: boolean) => void;
}

function EditorPersistentVtuberLayer({
  coursewareId,
  placements,
  scale,
  liveTransforms,
  vtuberSnapshotByElementId,
  vtuberSnapshotBySourceKey,
  lipSyncByElementId,
  allSlides,
  isPlaying,
  currentTime,
  onCaptureVtuberSnapshot,
  onVtuberSourceModelLoading,
  onVtuberSourceModelLoaded,
  onPlaybackLoadingTokenChange,
}: EditorPersistentVtuberLayerProps) {
  const visibleLive2dMissingSnapshotSourceKey = useMemo(() => {
    for (const placement of placements) {
      const modelUrl = getVtuberModelUrlFromMetadata(
        placement.element.metadata as Record<string, unknown>,
      );
      if (isInochiModelUrl(modelUrl)) continue;
      if (!isElementVisibleAtTimeInSlide(placement.element, currentTime, placement.slide)) {
        continue;
      }
      if (vtuberSnapshotBySourceKey[placement.sourceKey]) continue;
      return placement.sourceKey;
    }
    return null;
  }, [currentTime, placements, vtuberSnapshotBySourceKey]);

  const snapshotWarmupPlacement = useMemo((): EditorVtuberPlacement | null => {
    if (visibleLive2dMissingSnapshotSourceKey) return null;
    const seenSourceKeys = new Set<string>();
    for (const warmupSlide of allSlides) {
      for (const element of listVtubersOnSlide(warmupSlide)) {
        const sourceKey = getVtuberSourceKey(element);
        if (seenSourceKeys.has(sourceKey)) continue;
        seenSourceKeys.add(sourceKey);
        if (vtuberSnapshotBySourceKey[sourceKey]) continue;
        const modelUrl = getVtuberModelUrlFromMetadata(element.metadata as Record<string, unknown>);
        if (isInochiModelUrl(modelUrl)) continue;
        return {
          sourceKey,
          element,
          slide: warmupSlide,
          elementId: element.element_id,
        };
      }
    }
    return null;
  }, [allSlides, visibleLive2dMissingSnapshotSourceKey, vtuberSnapshotBySourceKey]);

  /** Every Live2D vtuber on the current slide (the mount queue doesn't change with playhead visibility, consistent with preview). */
  const slideLive2dPlacements = useMemo(() => {
    const narrationBoundVtuberIds = new Set<string>();
    for (const placement of placements) {
      for (const el of placement.slide.children_elements) {
        if (el.element_type !== "narration") continue;
        const vtuberId = (el as NarrationElement).vtuber_element_id?.trim();
        if (vtuberId) narrationBoundVtuberIds.add(vtuberId);
      }
    }
    return [...placements]
      .filter((placement) => {
        const modelUrl = getVtuberModelUrlFromMetadata(
          placement.element.metadata as Record<string, unknown>,
        );
        return !isInochiModelUrl(modelUrl);
      })
      .sort((a, b) => {
        const aBound = narrationBoundVtuberIds.has(a.elementId);
        const bBound = narrationBoundVtuberIds.has(b.elementId);
        if (aBound !== bBound) return aBound ? -1 : 1;
        return a.element.style.z_index - b.element.style.z_index;
      });
  }, [placements]);

  const { live2dMountOrderByElementId, live2dModelUrlByElementId } = useMemo(() => {
    const order = new Map<string, number>();
    const urls = new Map<string, string>();
    let index = 0;
    for (const placement of slideLive2dPlacements) {
      const modelUrl = getVtuberModelUrlFromMetadata(
        placement.element.metadata as Record<string, unknown>,
      );
      order.set(placement.elementId, index++);
      urls.set(placement.elementId, modelUrl);
    }
    return { live2dMountOrderByElementId: order, live2dModelUrlByElementId: urls };
  }, [slideLive2dPlacements]);

  const live2dMountSig = useMemo(
    () =>
      [...live2dMountOrderByElementId.entries()]
        .map(([elementId, mountIndex]) => `${elementId}:${mountIndex}`)
        .join("|"),
    [live2dMountOrderByElementId],
  );

  const [live2dUnlockedThroughIndex, setLive2dUnlockedThroughIndex] = useState(0);
  const prevLive2dMountSigRef = useRef("");
  const live2dMountSigRef = useRef(live2dMountSig);
  live2dMountSigRef.current = live2dMountSig;
  const live2dUnlockByMountSigRef = useRef(new Map<string, number>());
  const live2dMountMapsRef = useRef({
    order: live2dMountOrderByElementId,
    urls: live2dModelUrlByElementId,
  });
  live2dMountMapsRef.current = {
    order: live2dMountOrderByElementId,
    urls: live2dModelUrlByElementId,
  };

  useEffect(() => {
    const previousSig = prevLive2dMountSigRef.current;
    const { order, urls } = live2dMountMapsRef.current;
    const initial = resolveInitialLive2dUnlockedThroughIndex(
      order,
      (elementId) => urls.get(elementId) ?? "",
    );
    const remembered = getRememberedLive2dUnlockForMountSig(
      live2dUnlockByMountSigRef.current,
      live2dMountSig,
    );
    const targetUnlock = Math.max(initial, remembered ?? -1);
    const preserveUnlock = shouldPreserveLive2dUnlockAcrossMountSigChange(
      previousSig,
      live2dMountSig,
    );
    prevLive2dMountSigRef.current = live2dMountSig;

    setLive2dUnlockedThroughIndex((prev) => {
      const next = preserveUnlock ? Math.max(prev, targetUnlock) : targetUnlock;
      rememberLive2dUnlockForMountSig(
        live2dUnlockByMountSigRef.current,
        live2dMountSig,
        next,
      );
      return next;
    });
  }, [live2dMountSig]);

  /** Unlock every Live2D at once when timeline playback starts, so serial mounting of several vtubers doesn't keep getting stuck at 0s. */
  const prevIsPlayingForLive2dUnlockRef = useRef(false);
  useEffect(() => {
    const wasPlaying = prevIsPlayingForLive2dUnlockRef.current;
    prevIsPlayingForLive2dUnlockRef.current = isPlaying;
    if (!isPlaying || wasPlaying) return;
    const maxIndex = Math.max(-1, ...live2dMountOrderByElementId.values());
    if (maxIndex < 0) return;
    setLive2dUnlockedThroughIndex((prev) => {
      const next = Math.max(prev, maxIndex);
      rememberLive2dUnlockForMountSig(
        live2dUnlockByMountSigRef.current,
        live2dMountSigRef.current,
        next,
      );
      return next;
    });
  }, [isPlaying, live2dMountOrderByElementId]);

  const handleLive2dReady = useCallback(
    (elementId: string) => {
      const mountIndex = live2dMountOrderByElementId.get(elementId);
      if (mountIndex === undefined) return;
      setLive2dUnlockedThroughIndex((prev) => {
        const next = Math.max(prev, mountIndex + 1);
        rememberLive2dUnlockForMountSig(
          live2dUnlockByMountSigRef.current,
          live2dMountSigRef.current,
          next,
        );
        return next;
      });
    },
    [live2dMountOrderByElementId],
  );

  return (
    <>
      {placements.map((placement) => {
        const modelUrl = getVtuberModelUrlFromMetadata(
          placement.element.metadata as Record<string, unknown>,
        );
        // During playback the model isn't unmounted even when timeline visibility switches
        // (visibility is controlled only by opacity). Like preview, this prevents remount → reload flashes around 0s.
        const renderLiveModel =
          isInochiModelUrl(modelUrl) ||
          isPlaying ||
          isElementVisibleAtTimeInSlide(placement.element, currentTime, placement.slide);
        const visibleOnTimeline = isElementVisibleAtTimeInSlide(
          placement.element,
          currentTime,
          placement.slide,
        );
        const live2dMountIndex = live2dMountOrderByElementId.get(placement.elementId);
        const deferLive2dMount =
          !isPlaying &&
          live2dMountIndex !== undefined &&
          live2dMountIndex > live2dUnlockedThroughIndex;
        return (
          <EditorVtuberSlot
            key={placement.elementId}
            coursewareId={coursewareId}
            placement={placement}
            playheadMs={currentTime}
            scale={scale}
            liveTransform={liveTransforms[placement.elementId]}
            snapshot={resolveVtuberEditorSnapshot(placement.element, vtuberSnapshotBySourceKey)}
            lipSyncValue={resolveVtuberLipSyncValue(
              placement.sourceKey,
              placement.elementId,
              lipSyncByElementId,
              allSlides,
            )}
            onCaptureVtuberSnapshot={onCaptureVtuberSnapshot}
            renderLiveModel={renderLiveModel}
            isPlaying={isPlaying}
            visibleOnTimeline={visibleOnTimeline}
            deferLive2dMount={deferLive2dMount}
            onLive2dReady={() => handleLive2dReady(placement.elementId)}
            onVtuberSourceModelLoading={(loading) =>
              onVtuberSourceModelLoading(placement.sourceKey, loading)
            }
            onVtuberSourceModelLoaded={() => onVtuberSourceModelLoaded(placement.sourceKey)}
            onPlaybackLoadingTokenChange={onPlaybackLoadingTokenChange}
          />
        );
      })}
      {snapshotWarmupPlacement ? (
        <div className="pointer-events-none absolute h-px w-px overflow-hidden opacity-0">
          <VtuberStagePlayer
            key={`snapshot-warmup:${snapshotWarmupPlacement.sourceKey}`}
            element={snapshotWarmupPlacement.element}
            coursewareId={coursewareId}
            widthLogical={snapshotWarmupPlacement.element.size.width}
            heightLogical={snapshotWarmupPlacement.element.size.height}
            scale={0.25}
            renderLiveModel
            onCaptureVtuberSnapshot={onCaptureVtuberSnapshot}
            onModelLoadingChange={(loading) =>
              onVtuberSourceModelLoading(snapshotWarmupPlacement.sourceKey, loading)
            }
            onModelLoaded={() => onVtuberSourceModelLoaded(snapshotWarmupPlacement.sourceKey)}
          />
        </div>
      ) : null}
    </>
  );
}

interface EditorVtuberSlotProps {
  coursewareId: string;
  placement: EditorVtuberPlacement;
  playheadMs: number;
  scale: number;
  liveTransform?: LiveTransform;
  snapshot?: string;
  lipSyncValue: number;
  onCaptureVtuberSnapshot: (elementId: string, dataUrl: string) => void;
  renderLiveModel: boolean;
  isPlaying: boolean;
  visibleOnTimeline: boolean;
  deferLive2dMount?: boolean;
  onLive2dReady?: () => void;
  onVtuberSourceModelLoading: (loading: boolean) => void;
  onVtuberSourceModelLoaded: () => void;
  onPlaybackLoadingTokenChange: (token: string, isLoading: boolean) => void;
}

const EditorVtuberSlot = memo(function EditorVtuberSlot({
  coursewareId,
  placement,
  playheadMs,
  scale,
  liveTransform,
  snapshot,
  lipSyncValue,
  onCaptureVtuberSnapshot,
  renderLiveModel,
  isPlaying,
  visibleOnTimeline,
  deferLive2dMount = false,
  onLive2dReady,
  onVtuberSourceModelLoading,
  onVtuberSourceModelLoaded,
  onPlaybackLoadingTokenChange,
}: EditorVtuberSlotProps) {
  const { element, slide } = placement;
  const visible = visibleOnTimeline;
  const interp = interpolateElementTransformInSlide(element, playheadMs, slide);
  const transform: LiveTransform =
    liveTransform ?? {
      x: interp.position.x,
      y: interp.position.y,
      width: interp.size.width,
      height: interp.size.height,
      rotation: interp.rotation_deg,
    };
  const enterExitFx = useMemo(
    () => computeElementEnterExitEffectVisual(element, slide, playheadMs),
    [element, slide, playheadMs],
  );
  const contentOpacity = visible ? interp.opacity * enterExitFx.opacityFactor : 0;
  /** Even with an entrance opacity of 0, during playback the playhead stops until the model finishes loading (same as preview / TTS). */
  const playbackGateActive = isPlaying && renderLiveModel;
  const vtuberToken = `vtuber:${placement.elementId}`;
  const handleVtuberPlaybackLoading = useCallback(
    (loading: boolean) => onPlaybackLoadingTokenChange(vtuberToken, loading),
    [onPlaybackLoadingTokenChange, vtuberToken],
  );
  useEffect(() => {
    if (!playbackGateActive) {
      onPlaybackLoadingTokenChange(vtuberToken, false);
      return;
    }
    if (deferLive2dMount) {
      onPlaybackLoadingTokenChange(vtuberToken, true);
      return;
    }
    onPlaybackLoadingTokenChange(vtuberToken, false);
  }, [deferLive2dMount, onPlaybackLoadingTokenChange, playbackGateActive, vtuberToken]);
  useEffect(
    () => () => {
      onPlaybackLoadingTokenChange(vtuberToken, false);
    },
    [onPlaybackLoadingTokenChange, vtuberToken],
  );

  return (
    <div
      className="pointer-events-none absolute"
      style={{
        left: transform.x * scale,
        top: transform.y * scale,
        width: transform.width * scale,
        height: transform.height * scale,
        zIndex: STAGE_VTUBER_Z_INDEX_BASE + element.style.z_index,
        transform: `rotate(${transform.rotation}deg)`,
        transformOrigin: "center center",
        opacity: contentOpacity,
        transition:
          enterExitFx.prefersInstantOpacity
            ? "none"
            : `opacity ${QUIZ_PREVIEW_ELEMENT_OPACITY_TRANSITION_MS}ms linear`,
      }}
    >
      <div
        className="absolute inset-0"
        style={{
          transform: `translate(${enterExitFx.translateLogicalX * scale}px, ${enterExitFx.translateLogicalY * scale}px) rotate(${enterExitFx.rotateExtraDeg}deg) scale(${enterExitFx.uniformScale})`,
          transformOrigin: "center center",
        }}
      >
        <VtuberStagePlayer
          element={element}
          coursewareId={coursewareId}
          widthLogical={transform.width}
          heightLogical={transform.height}
          scale={scale}
          snapshot={snapshot}
          lipSyncValue={lipSyncValue}
          renderLiveModel={renderLiveModel}
          deferLive2dMount={deferLive2dMount}
          onLive2dReady={onLive2dReady}
          playbackGateActive={playbackGateActive}
          onCaptureVtuberSnapshot={onCaptureVtuberSnapshot}
          onModelLoadingChange={onVtuberSourceModelLoading}
          onPlaybackLoadingChange={handleVtuberPlaybackLoading}
          onModelLoaded={onVtuberSourceModelLoaded}
        />
      </div>
    </div>
  );
});

interface VtuberStagePlayerProps {
  element: VtuberElement;
  coursewareId: string;
  widthLogical: number;
  heightLogical: number;
  scale: number;
  snapshot?: string;
  onCaptureVtuberSnapshot?: (elementId: string, dataUrl: string) => void;
  onModelLoadingChange?: (loading: boolean) => void;
  onModelLoaded?: () => void;
  renderLiveModel?: boolean;
  deferLive2dMount?: boolean;
  onLive2dReady?: () => void;
  playbackGateActive?: boolean;
  onPlaybackLoadingChange?: (loading: boolean) => void;
  lipSyncValue?: number;
}

const syncedEditorVtuberReadyKeys = new Set<string>();

function useSyncedEditorVtuberLoadingGate({
  liveModelKey,
  playbackGateActive,
  renderLiveModel,
  warmInCache,
  onPlaybackLoadingChange,
}: {
  liveModelKey: string;
  playbackGateActive: boolean;
  renderLiveModel: boolean;
  warmInCache: boolean;
  onPlaybackLoadingChange?: (loading: boolean) => void;
}) {
  const onPlaybackLoadingChangeRef = useRef(onPlaybackLoadingChange);
  onPlaybackLoadingChangeRef.current = onPlaybackLoadingChange;
  const readyRef = useRef(warmInCache || syncedEditorVtuberReadyKeys.has(liveModelKey));
  readyRef.current = warmInCache || syncedEditorVtuberReadyKeys.has(liveModelKey);

  const clearGate = useCallback(() => {
    onPlaybackLoadingChangeRef.current?.(false);
  }, []);

  const reportLoading = useCallback(
    (loading: boolean) => {
      if (!loading || !playbackGateActive || !renderLiveModel || readyRef.current) {
        clearGate();
        return;
      }
      onPlaybackLoadingChangeRef.current?.(true);
    },
    [clearGate, playbackGateActive, renderLiveModel],
  );

  const markReady = useCallback(() => {
    syncedEditorVtuberReadyKeys.add(liveModelKey);
    readyRef.current = true;
    clearGate();
  }, [clearGate, liveModelKey]);

  useEffect(() => {
    if (warmInCache) markReady();
  }, [markReady, warmInCache]);

  useEffect(() => {
    if (!playbackGateActive || !renderLiveModel || readyRef.current) {
      clearGate();
    }
  }, [clearGate, playbackGateActive, renderLiveModel]);

  useEffect(() => clearGate, [clearGate, liveModelKey]);

  return useMemo(
    () => ({ reportLoading, markReady, clearGate }),
    [clearGate, markReady, reportLoading],
  );
}

function VtuberStagePlayer({
  element,
  coursewareId,
  widthLogical,
  heightLogical,
  scale,
  snapshot,
  onCaptureVtuberSnapshot,
  onModelLoadingChange,
  onModelLoaded,
  renderLiveModel = true,
  deferLive2dMount = false,
  onLive2dReady,
  playbackGateActive = false,
  onPlaybackLoadingChange,
  lipSyncValue = 0,
}: VtuberStagePlayerProps) {
  const modelRef = useRef<any>(null);
  const onModelLoadingChangeRef = useRef(onModelLoadingChange);
  onModelLoadingChangeRef.current = onModelLoadingChange;
  const meta = element.metadata as Record<string, unknown>;
  const widthPx = Math.max(20, Math.round(widthLogical * scale));
  const heightPx = Math.max(20, Math.round(heightLogical * scale));
  const modelUrl = getVtuberModelUrlFromMetadata(meta);
  const modelCacheKey = getVtuberModelCacheKey(modelUrl);
  const liveModelKey = `${element.element_id}:${isInochiModelUrl(modelUrl) ? "inochi" : "live2d"}:${modelCacheKey}`;
  const isInochiModel = isInochiModelUrl(modelUrl);
  const warmInCache = isVtuberModelWarmInCache(modelUrl);
  const showLoadingChrome = !warmInCache;
  const [isModelLoading, setIsModelLoading] = useState(
    () => showLoadingChrome,
  );
  const [isModelLoadFailed, setIsModelLoadFailed] = useState(false);
  const vtuberLoadingGate = useSyncedEditorVtuberLoadingGate({
    liveModelKey,
    playbackGateActive,
    renderLiveModel,
    warmInCache,
    onPlaybackLoadingChange,
  });

  useEffect(() => {
    if (!renderLiveModel) {
      modelRef.current = null;
      setIsModelLoadFailed(false);
      setIsModelLoading(false);
      onModelLoadingChangeRef.current?.(false);
      vtuberLoadingGate.clearGate();
      return;
    }
    setIsModelLoadFailed(false);
    const loading = showLoadingChrome && (isInochiModel || !deferLive2dMount);
    setIsModelLoading(loading);
    onModelLoadingChangeRef.current?.(loading);
  }, [deferLive2dMount, isInochiModel, modelUrl, renderLiveModel, showLoadingChrome]);

  const handleModelLoadingChange = useCallback(
    (loading: boolean) => {
      setIsModelLoading(loading);
      onModelLoadingChangeRef.current?.(loading);
      vtuberLoadingGate.reportLoading(loading);
    },
    [vtuberLoadingGate],
  );

  useEffect(() => {
    if (!playbackGateActive || !deferLive2dMount || warmInCache) return;
    vtuberLoadingGate.reportLoading(true);
  }, [deferLive2dMount, playbackGateActive, vtuberLoadingGate, warmInCache]);

  const handleModelError = useCallback(() => {
    // When the model URL is broken, stop the repeated remounts.
    setIsModelLoadFailed(true);
    setIsModelLoading(false);
    onModelLoadingChangeRef.current?.(false);
    vtuberLoadingGate.clearGate();
  }, [vtuberLoadingGate]);

  useEffect(() => {
    const model = modelRef.current;
    if (!model) return;
    const finalValue = Math.max(0, Math.min(1, lipSyncValue));
    if (model?.internalModel?.coreModel) {
      model.internalModel.coreModel.setParameterValueById("ParamMouthOpenY", finalValue);
      return;
    }
    model.setLipSyncValue?.(finalValue);
  }, [lipSyncValue]);

  useEffect(() => {
    return () => {
      const model = modelRef.current;
      if (!model) return;
      if (model?.internalModel?.coreModel) {
        model.internalModel.coreModel.setParameterValueById("ParamMouthOpenY", 0);
      } else {
        model.resetLipSync?.();
        model.setLipSyncValue?.(0);
      }
    };
  }, []);

  if (!renderLiveModel) {
    return snapshot ? (
      <div className="relative h-full w-full">
        <img
          src={snapshot}
          alt={element.name}
          className="block h-full w-full"
          style={{ objectFit: "fill" }}
          draggable={false}
        />
      </div>
    ) : (
      <VtuberModelLoadingPlaceholder showBorder={false} />
    );
  }

  if (!isInochiModel && deferLive2dMount && showLoadingChrome) {
    return (
      <div
        className="relative h-full w-full"
        style={{ display: "flex", alignItems: "flex-end", justifyContent: "center" }}
      >
        <VtuberModelLoadingPlaceholder showBorder={false} />
      </div>
    );
  }

  const showSnapshotWhileLoading = Boolean(
    snapshot && (isModelLoading || isModelLoadFailed) && showLoadingChrome,
  );
  const showPlaceholderWhileLoading =
    !showSnapshotWhileLoading && (isModelLoading || isModelLoadFailed) && showLoadingChrome;

  return (
    <div
      className="relative h-full w-full"
      style={{ display: "flex", alignItems: "flex-end", justifyContent: "center" }}
    >
      <div
        className={
          (isModelLoading || isModelLoadFailed) && showLoadingChrome
            ? "invisible h-full w-full"
            : "h-full w-full"
        }
      >
        {!isModelLoadFailed && isInochiModel ? (
          <Inochi2DModelComponent
            key={liveModelKey}
            {...buildCoursewareInochiStageModelProps(widthPx, heightPx, {
              showLoadingPlaceholder: false,
            })}
            modelUrl={modelUrl}
            onLoadingChange={handleModelLoadingChange}
            onError={handleModelError}
            onModelLoaded={(model) => {
              modelRef.current = model;
              vtuberLoadingGate.markReady();
              setIsModelLoading(false);
              onModelLoadingChangeRef.current?.(false);
              onModelLoaded?.();
            }}
            onCanvasSnapshot={
              snapshot || !onCaptureVtuberSnapshot
                ? undefined
                : (dataUrl) => onCaptureVtuberSnapshot?.(element.element_id, dataUrl)
            }
          />
        ) : !isModelLoadFailed ? (
          <Live2DModelComponent
            key={liveModelKey}
            {...buildCoursewareLive2dStageModelProps(widthPx, heightPx, {
              showLoadingPlaceholder: false,
            })}
            modelUrl={modelUrl}
            coursewareId={coursewareId}
            debugId={`editor:${element.element_id}:${modelUrl}`}
            enableInteraction={false}
            onLoadingChange={handleModelLoadingChange}
            onError={handleModelError}
            onModelLoaded={(model) => {
              modelRef.current = model;
              vtuberLoadingGate.markReady();
              setIsModelLoading(false);
              onModelLoadingChangeRef.current?.(false);
              onModelLoaded?.();
              onLive2dReady?.();
            }}
            onCanvasSnapshot={
              snapshot || !onCaptureVtuberSnapshot
                ? undefined
                : (dataUrl) => onCaptureVtuberSnapshot?.(element.element_id, dataUrl)
            }
          />
        ) : null}
      </div>
      {showSnapshotWhileLoading ? (
        <div className="absolute inset-0 h-full w-full">
          <img
            src={snapshot}
            alt={element.name}
            className="block h-full w-full"
            style={{ objectFit: "fill" }}
            draggable={false}
          />
        </div>
      ) : null}
      {showPlaceholderWhileLoading ? (
        <VtuberModelLoadingPlaceholder showBorder={false} />
      ) : null}
    </div>
  );
}

function VideoStagePreview({
  source,
  name,
  muted,
  loop,
  volume,
  currentTime,
  elementStartAt,
  elementEndAt,
  isPlaying,
}: {
  source: string;
  name: string;
  muted: boolean;
  loop: boolean;
  volume: number;
  currentTime: number;
  elementStartAt: number;
  elementEndAt: number;
  isPlaying: boolean;
}) {
  const { t } = useI18nNew();
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [hasError, setHasError] = useState(false);
  const prevPlayheadMsRef = useRef(currentTime);
  const src = source.trim();
  const shouldPlay = isPlaying && currentTime >= elementStartAt && currentTime <= elementEndAt;

  useEffect(() => {
    setHasError(false);
  }, [src]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    video.volume = clamp(volume, 0, 1);
    video.muted = muted;
  }, [muted, volume]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video || !src || hasError) return;
    const prevMs = prevPlayheadMsRef.current;
    prevPlayheadMsRef.current = currentTime;
    const deltaMs = Math.abs(currentTime - prevMs);
    const isContinuousPlayback = shouldPlay && deltaMs > 0 && deltaMs < 150;
    const expected = Math.max(0, (currentTime - elementStartAt) / 1000);

    const syncMediaTime = (): void => {
      if (video.readyState < HTMLMediaElement.HAVE_METADATA) return;
      if (!isContinuousPlayback && Math.abs(video.currentTime - expected) > 0.35) {
        try {
          video.currentTime = expected;
        } catch {
          /* ignore invalid seeks while metadata is settling */
        }
      }
    };

    syncMediaTime();
    if (shouldPlay) {
      void video.play().catch(() => {});
    } else {
      video.pause();
    }
    video.addEventListener("loadedmetadata", syncMediaTime);
    return () => video.removeEventListener("loadedmetadata", syncMediaTime);
  }, [hasError, currentTime, elementStartAt, shouldPlay, src]);

  if (!src) {
    return (
      <div className="flex h-full w-full flex-col items-center justify-center rounded-md border border-dashed border-slate-400 dark:border-slate-600 bg-white/70 dark:bg-slate-900/70 px-3 text-center text-slate-600 dark:text-slate-300">
        <Video className="h-8 w-8" />
        <span className="mt-2 text-xs">{t("coursewareEditor.common.noVideoUrl")}</span>
      </div>
    );
  }

  if (hasError) {
    return (
      <div className="flex h-full w-full flex-col items-center justify-center rounded-md border border-rose-300/45 dark:border-rose-500/40 bg-rose-950/30 px-3 text-center text-rose-100">
        <Video className="h-8 w-8" />
        <span className="mt-2 text-xs">{t("coursewareEditor.common.videoLoadFailed")}</span>
        <span className="mt-1 max-w-full truncate text-[10px] text-rose-200/70">{name || src}</span>
      </div>
    );
  }

  return (
    <video
      ref={videoRef}
      src={src}
      muted={muted}
      loop={loop}
      playsInline
      preload="metadata"
      className="h-full w-full bg-black"
      style={{ objectFit: "contain" }}
      onError={() => setHasError(true)}
    />
  );
}

/** During a quiz pause playing only question audio: drives the native `<audio controls>` on the canvas (separate from the hidden narration track). */
function EditorQuizStemAudioStage({
  track,
  owningQuestionWrapperId,
  quizStemAutoplay,
  activeQuizPauseWrapperId,
}: {
  track: AudioElement;
  owningQuestionWrapperId: string | null;
  quizStemAutoplay: { wrapperId: string; playUrl: string; nonce: number } | null;
  activeQuizPauseWrapperId: string | null;
}): React.ReactNode {
  const ref = useRef<HTMLAudioElement | null>(null);
  const lastPlayedNonceRef = useRef(-1);

  useEffect(() => {
    const a = ref.current;
    if (!a) return;
    const holding =
      activeQuizPauseWrapperId !== null &&
      owningQuestionWrapperId !== null &&
      activeQuizPauseWrapperId === owningQuestionWrapperId;
    if (!holding) {
      a.pause();
    }
  }, [activeQuizPauseWrapperId, owningQuestionWrapperId]);

  // The legacy quiz stem autoplay used to trigger when canvas member-audio
  // ranges entered the playhead; the single-element quiz model no longer
  // exposes those member audios, so this hook is intentionally empty.

  return (
    <div className="flex h-full w-full items-center justify-center rounded-md px-2">
      <audio ref={ref} src={track.source} controls className="h-10 max-h-full w-full" preload="metadata" />
    </div>
  );
}

// ---------- element content render ----------

/** Non-interactive quiz preview on the editor canvas (layout WYSIWYG; submit is preview-only). */
const EDITOR_QUIZ_CANVAS_PREVIEW_STATE: QuizRuntimeState = {
  submitted: false,
  submitting: false,
  earnedScore: null,
  feedback: null,
  canAdvance: false,
  skipped: false,
};

const renderElementContent = (
  element: CourseElement,
  widthLogical: number,
  heightLogical: number,
  scale: number,
  mode: "stage" | "thumbnail" = "stage",
  options?: {
    vtuberSnapshotByElementId?: Record<string, string>;
    vtuberSnapshotBySourceKey?: Record<string, string>;
    vtuberLipSyncByElementId?: Record<string, number>;
    onCaptureVtuberSnapshot?: (elementId: string, dataUrl: string) => void;
    onVtuberModelLoaded?: () => void;
    onNarrationLipSyncValueChange?: (vtuberElementId: string, value: number) => void;
    onNarrationAudioLoadingChange?: (isLoading: boolean) => void;
    onNarrationPlayheadDriveChange?: (localMs: number | null) => void;
    currentTime?: number;
    isPlaying?: boolean;
    playheadRef?: RefObject<number>;
    playheadFromRef?: boolean;
    playheadClockRunning?: boolean;
    onImageIntrinsicSize?: (width: number, height: number) => void;
    /** Stem of a canvas fill-in question: `<answer>` shown inline (stage only). */
    editorFillBlankInline?: boolean;
    owningQuestionWrapperId?: string | null;
    quizStemAutoplay?: { wrapperId: string; playUrl: string; nonce: number } | null;
    activeQuizPauseWrapperId?: string | null;
    /** PPT element: write keyframes and metadata when the user turns pages (needed only by the editor stage). */
    onPptSlideIndexChange?: (elementId: string, index: number) => void;
    /** User-visible text (fill-in question hints etc.). */
    translate?: CoursewareTranslateFn;
    /**
     * thumbnail: the real CSS pixel size of the outer wrapper (may differ from `widthLogical * scale`, e.g. left thumbnails
     * use min(scaleX,scaleY) while positioning uses scaleX/scaleY; the minimap shouldn't enlarge fonts with an artificial lower bound either).
     */
    thumbnailViewportPx?: { width: number; height: number };
    /** Scene quiz config — used to paint `element_type:"quiz"` via {@link QuizRenderer} on stage. */
    editorQuiz?: QuizConfig | null;
    /** Editor stage: make rich text nodes directly editable inside the canvas. */
    richEditable?: boolean;
    richEditState?: CoursewareRichEditState;
    onRichEditStateChange?: (state: CoursewareRichEditState) => void;
    onChangeRichLayout?: (
      path: RichTextPath,
      patch: Record<string, string | number | null>,
      options?: { recordHistory?: boolean },
    ) => void;
    onRemoveRichNode?: (path: RichTextPath, options?: { recordHistory?: boolean }) => void;
    /** @deprecated Use richEditable + CoursewareRichStageEditor. */
    richEditableText?: boolean;
    selectedRichTextPath?: RichTextPath;
    onRichTextChange?: (path: number[], text: string) => void;
    onRichTextSelect?: (path: RichTextPath) => void;
    onRichExitEdit?: () => void;
    onRichTextCommit?: () => void;
    /** Editor stage: inline SVG subtree editing (drag, drill-down, text). */
    svgEditable?: boolean;
    svgEditState?: CoursewareSvgEditState;
    onSvgEditStateChange?: (state: CoursewareSvgEditState) => void;
    onSvgSourceChange?: (source: string, options?: { recordHistory?: boolean }) => void;
    onSvgExitEdit?: () => void;
    layoutSyncKey?: string;
    onSvgTextStyleSnapshot?: (snapshot: SvgTextStyleSnapshot | null) => void;
    svgTextStylePatch?: { nonce: number; patch: SvgTextStylePatch } | null;
    /** Thumbnail HTML: the same iframe layout baseline as the main canvas (keeps the responsive layout from drifting). */
    htmlReferenceLayoutScale?: number;
    /** minimap: with false the iframe layout follows the thumbnail frame pixels instead of the main stage baseline. */
    htmlThumbPreferStageLayoutBaseline?: boolean;
  },
): React.ReactNode => {
  const tr = options?.translate ?? fallbackEditorMetaT;
  if (element.element_type === "text") {
    const textLineHeight = resolveTextLineHeight(element.line_height);

    const titleSpanStyle: CSSProperties = {
      fontSize: element.font_size * scale,
      color: element.color,
      fontFamily: element.font_family,
      fontWeight: element.bold ? 700 : 400,
      fontStyle: element.italic ? "italic" : "normal",
      textAlign: element.align as CSSProperties["textAlign"],
      lineHeight: textLineHeight,
      whiteSpace: "pre-wrap",
      wordBreak: "break-all",
      overflowWrap: "anywhere",
      width: "100%",
    };

    return (
      <div
        className="flex h-full w-full items-center"
        style={buildTextElementContainerStyle(element, scale)}
      >
        <span style={titleSpanStyle}>{element.text}</span>
      </div>
    );
  }
  if (element.element_type === "quiz") {
    const wrap = element as QuizSlideElement;
    const question = options?.editorQuiz
      ? (options.editorQuiz.questions.find((q) => q.question_id === wrap.quiz_question_id) ?? null)
      : null;
    if (!question?.react_layout) {
      return (
        <div
          className="pointer-events-none flex h-full w-full items-center justify-center rounded-md border border-dashed border-amber-400/70 px-2 text-center text-amber-800/90 dark:text-amber-200/90"
          style={{ fontSize: Math.max(10, 12 * scale) }}
        >
          {tr("coursewareEditor.common.questionElement")}
          {!wrap.quiz_question_id ? ` · ${tr("coursewareEditor.stage.questionUnbound")}` : ""}
        </div>
      );
    }
    return (
      <div className="pointer-events-none relative h-full min-h-0 w-full overflow-hidden rounded-md">
        <div
          className="absolute left-0 top-0"
          style={{
            width: widthLogical,
            height: heightLogical,
            transform: `scale(${scale})`,
            transformOrigin: "top left",
          }}
        >
          <QuizRenderer
            question={question}
            state={EDITOR_QUIZ_CANVAS_PREVIEW_STATE}
            containerStyle={{
              width: widthLogical,
              height: heightLogical,
              boxSizing: "border-box",
            }}
          />
        </div>
      </div>
    );
  }
  if (element.element_type === "quiz_score_summary") {
    const quizConfig = options?.editorQuiz;
    const scoreSummary = quizConfig ? ensureQuizScoreSummaryConfig(quizConfig.score_summary, "en") : null;
    if (!scoreSummary?.react_layout) {
      return (
        <div
          className="pointer-events-none flex h-full w-full items-center justify-center rounded-md border border-dashed border-emerald-400/70 px-2 text-center text-emerald-800/90 dark:text-emerald-200/90"
          style={{ fontSize: Math.max(10, 12 * scale) }}
        >
          {tr("coursewareEditor.common.scoreSummaryElement")}
        </div>
      );
    }
    const previewSnapshot = quizConfig
      ? computeQuizAggregateScore(quizConfig, [], {})
      : {
          earnedScore: 0,
          totalScore: 100,
          questionCount: 0,
          answeredCount: 0,
          gradeLevel: null,
        };
    return (
      <div className="pointer-events-none relative h-full min-h-0 w-full overflow-hidden rounded-md">
        <div
          className="absolute left-0 top-0"
          style={{
            width: widthLogical,
            height: heightLogical,
            transform: `scale(${scale})`,
            transformOrigin: "top left",
          }}
        >
          <QuizScoreSummaryRenderer
            reactLayout={scoreSummary.react_layout}
            snapshot={previewSnapshot}
            containerStyle={{
              width: widthLogical,
              height: heightLogical,
              boxSizing: "border-box",
            }}
          />
        </div>
      </div>
    );
  }
  if (element.element_type === "rich") {
    const richEditable = mode === "stage" && options?.richEditable === true;
    if (richEditable && options?.richEditState) {
      return (
        <CoursewareRichStageEditor
          element={element}
          scale={scale}
          widthLogical={widthLogical}
          heightLogical={heightLogical}
          editState={options.richEditState}
          onEditStateChange={options.onRichEditStateChange}
          onLayoutChange={options.onChangeRichLayout}
          onRemoveNode={options.onRemoveRichNode}
          onTextChange={options.onRichTextChange}
          onSelectRichText={options.onRichTextSelect}
          onExitEdit={options.onRichExitEdit}
          layoutSyncKey={options.layoutSyncKey}
        />
      );
    }
    const editableText = mode === "stage" && options?.richEditableText === true;
    return (
      <div
        className={`relative h-full min-h-0 w-full overflow-hidden ${
          editableText ? "pointer-events-auto" : "pointer-events-none"
        }`}
      >
        <div
          className="absolute left-0 top-0 overflow-hidden"
          style={{
            width: widthLogical,
            height: heightLogical,
            transform: `scale(${scale})`,
            transformOrigin: "top left",
          }}
        >
          <RichRenderer
            reactLayout={element.react_layout}
            editableText={editableText}
            selectedTextPath={options?.selectedRichTextPath}
            onTextChange={options?.onRichTextChange}
            onTextSelect={options?.onRichTextSelect}
            onTextCommit={options?.onRichTextCommit}
            containerStyle={{
              width: widthLogical,
              height: heightLogical,
              overflow: "hidden",
              boxSizing: "border-box",
            }}
          />
        </div>
      </div>
    );
  }
  if (element.element_type === "image") {
    const img = element as ImageElement;
    return (
      <CoursewareRasterImage
        element={img}
        draggable={false}
        onIntrinsicSize={mode === "stage" ? options?.onImageIntrinsicSize : undefined}
      />
    );
  }
  if (element.element_type === "svg") {
    const svgEditable = mode === "stage" && options?.svgEditable === true;
    if (svgEditable && options?.svgEditState) {
      return (
        <CoursewareSvgStageEditor
          element={element as SvgElement}
          editable
          editState={options.svgEditState}
          onEditStateChange={options.onSvgEditStateChange}
          onSourceChange={options.onSvgSourceChange}
          onExitEdit={options.onSvgExitEdit}
          layoutSyncKey={options.layoutSyncKey}
          onSvgTextStyleSnapshot={options.onSvgTextStyleSnapshot}
          svgTextStylePatch={options.svgTextStylePatch ?? null}
        />
      );
    }
    return <CoursewareSvgContent element={element as SvgElement} />;
  }
  if (
    element.element_type === "rectangle" ||
    element.element_type === "ellipse" ||
    element.element_type === "line" ||
    element.element_type === "arrow"
  ) {
    return <CoursewareShapeContent element={element as ShapeElement} scale={scale} />;
  }
  if (element.element_type === "button") {
    const bg = (element.metadata as Record<string, unknown>).background_color;
    const tc = (element.metadata as Record<string, unknown>).text_color;
    return (
      <div
        className="flex h-full w-full items-center justify-center rounded-lg font-semibold"
        style={{
          backgroundColor: typeof bg === "string" ? bg : "#3B82F6",
          color: typeof tc === "string" ? tc : "#FFFFFF",
          fontSize: Math.max(14, heightLogical * 0.3) * scale,
        }}
      >
        {element.label}
      </div>
    );
  }
  if (element.element_type === "input") {
    const bg = (element.metadata as Record<string, unknown>).background_color;
    const tc = (element.metadata as Record<string, unknown>).text_color;
    return (
      <div
        className="flex h-full w-full items-center rounded-lg border px-4"
        style={{
          backgroundColor: typeof bg === "string" ? bg : "rgba(255,255,255,0.08)",
          borderColor: "rgba(148, 163, 184, 0.35)",
          color: typeof tc === "string" ? tc : "#E2E8F0",
          fontSize: Math.max(14, heightLogical * 0.28) * scale,
        }}
      >
        <span className="truncate opacity-70">{element.value || element.placeholder}</span>
      </div>
    );
  }
  if (element.element_type === "textarea") {
    const bg = (element.metadata as Record<string, unknown>).background_color;
    const tc = (element.metadata as Record<string, unknown>).text_color;
    return (
      <div
        className="h-full w-full rounded-lg border p-4"
        style={{
          backgroundColor: typeof bg === "string" ? bg : "rgba(255,255,255,0.08)",
          borderColor: "rgba(148, 163, 184, 0.35)",
          color: typeof tc === "string" ? tc : "#E2E8F0",
          fontSize: Math.max(14, heightLogical * 0.12) * scale,
        }}
      >
        <span className="opacity-70">{element.value || element.placeholder}</span>
      </div>
    );
  }
  if (element.element_type === "video") {
    if (mode === "thumbnail") {
      return (
        <div className="flex h-full w-full flex-col items-center justify-center rounded-md bg-white/70 dark:bg-slate-900/70 text-slate-800 dark:text-slate-200">
          <Video className="h-8 w-8" />
          <span className="mt-2 max-w-full truncate px-2 text-xs">{element.name}</span>
        </div>
      );
    }
    return (
      <VideoStagePreview
        source={element.source}
        name={element.name}
        muted={element.muted}
        loop={element.loop}
        volume={element.volume}
        currentTime={options?.currentTime ?? 0}
        elementStartAt={element.timeline.start_at}
        elementEndAt={element.timeline.end_at}
        isPlaying={options?.isPlaying ?? false}
      />
    );
  }
  if (element.element_type === "audio") {
    const au = element as AudioElement;
    if (mode === "thumbnail") {
      return (
        <div className="flex h-full w-full items-center justify-center rounded border border-slate-300 dark:border-slate-700/40 bg-white/90 dark:bg-slate-900/40">
          <Music className="h-5 w-5 text-slate-400 dark:text-slate-500" aria-hidden />
        </div>
      );
    }
    const display = getCanvasAudioDisplayMode(element);
    if (display === "hidden") {
      return <div className="h-full w-full" aria-hidden />;
    }
    return <CanvasAudioStageWidget track={au} mode={display} />;
  }
  if (element.element_type === "html") {
    const src = element.src.trim();
    if (!src) {
      return (
        <div className="flex h-full w-full flex-col items-center justify-center rounded-md border border-dashed border-slate-400 dark:border-slate-600 bg-white/70 dark:bg-slate-900/70 px-3 text-center text-slate-600 dark:text-slate-300">
          <FileIcon className="h-8 w-8" />
          <span className="mt-2 text-xs">{(tr ?? fallbackEditorMetaT)("coursewareEditor.common.noHtmlUrl")}</span>
        </div>
      );
    }
    const thumbTarget =
      mode === "thumbnail" && options?.thumbnailViewportPx
        ? options.thumbnailViewportPx
        : undefined;
    return (
      <CoursewareHtmlStageEmbed
        elementId={element.element_id}
        title={element.name || element.element_id}
        src={src}
        widthLogical={widthLogical}
        heightLogical={heightLogical}
        scale={scale}
        targetSizePx={thumbTarget}
        layoutScale={thumbTarget ? options?.htmlReferenceLayoutScale : undefined}
        preferStageLayoutBaseline={options?.htmlThumbPreferStageLayoutBaseline ?? true}
        contentZoom={element.content_zoom}
        loadingLabel={(tr ?? fallbackEditorMetaT)("coursewareEditor.common.htmlLoading")}
        loadFailedTitle={(tr ?? fallbackEditorMetaT)("coursewareEditor.common.htmlLoadFailed")}
      />
    );
  }
  if (element.element_type === "ppt") {
    const pptEl = element as PPTElement;
    const timelineMs = options?.currentTime ?? 0;
    const slideIndex = resolvePptSlideIndexForTimeline(pptEl, timelineMs);
    if (mode === "thumbnail") {
      return (
        <PPTRenderer
          element={pptEl}
          mode="stage"
          index={slideIndex}
          suppressNavReveal
          editorCanvasDragThrough
          lightweight
        />
      );
    }
    return (
      <PPTRenderer
        element={pptEl}
        mode="stage"
        index={slideIndex}
        editorCanvasDragThrough
        onIndexChange={
          options?.onPptSlideIndexChange
            ? (i) => options.onPptSlideIndexChange!(pptEl.element_id, i)
            : undefined
        }
      />
    );
  }
  if (element.element_type === "narration") {
    const narration = element as NarrationElement;
    if (mode === "thumbnail") {
      const widthPx = Math.max(
        1,
        Math.round(options?.thumbnailViewportPx?.width ?? widthLogical * scale),
      );
      const heightPx = Math.max(
        1,
        Math.round(options?.thumbnailViewportPx?.height ?? heightLogical * scale),
      );
      const currentTime = options?.currentTime ?? 0;
      const resolvedSegments = resolveNarrationSegments(narration);
      const activeSegment = resolvedSegments.find(
        (seg) => currentTime >= seg.startMs && currentTime < seg.endMs,
      );
      const activeSubtitleText =
        narration.subtitle_visible === false
          ? ""
          : activeSegment
            ? formatNarrationSubtitleText(activeSegment.text)
            : "";
      if (!activeSubtitleText) {
        return null;
      }
      const thumbnailBgOpacity = clamp(
        typeof narration.subtitle_background_opacity === "number"
          ? narration.subtitle_background_opacity
          : narration.subtitle_background_transparent
            ? 0
            : 0.7,
        0,
        1,
      );
      const thumbnailBgColor = applyOpacityToHexColor(
        narration.subtitle_background_color || "#020617",
        thumbnailBgOpacity,
      );
      const thumbnailTextColor = narration.subtitle_text_color || "#FFFFFF";
      /** Thumbnails/minimap: derive the font size from the element's pixel height, so one line of text + padding doesn't break the outer overflow-hidden */
      const bubblePadY = Math.max(1, Math.round(heightPx * 0.06));
      const bubblePadX = Math.max(2, Math.round(heightPx * 0.12));
      const lineHeight = 1.2;
      const innerH = Math.max(4, heightPx - 2 * bubblePadY);
      const subtitleSize = clamp(Math.floor(innerH / lineHeight) - 1, 5, 12);
      const bubbleRadius = Math.max(1, Math.min(8, Math.round(heightPx * 0.15)));
      return (
        <div className="relative flex h-full w-full min-h-0 items-end justify-center">
          <div
            className="max-w-full min-h-0 truncate whitespace-nowrap text-center shadow"
            style={{
              backgroundColor: thumbnailBgColor,
              color: thumbnailTextColor,
              fontSize: subtitleSize,
              lineHeight,
              maxWidth: widthPx,
              borderRadius: bubbleRadius,
              padding: `${bubblePadY}px ${bubblePadX}px`,
              boxSizing: "border-box",
            }}
            title={activeSubtitleText}
          >
            {activeSubtitleText}
          </div>
        </div>
      );
    }
    return (
      <NarrationStagePlayer
        element={narration}
        widthLogical={widthLogical}
        heightLogical={heightLogical}
        scale={scale}
        currentTime={options?.currentTime ?? 0}
        isPlaying={options?.isPlaying ?? false}
        playheadRef={options?.playheadRef}
        playheadFromRef={options?.playheadFromRef}
        onLipSyncValueChange={options?.onNarrationLipSyncValueChange}
        onPlaybackLoadingChange={options?.onNarrationAudioLoadingChange}
        onPlayheadDriveChange={options?.onNarrationPlayheadDriveChange}
      />
    );
  }
  if (element.element_type === "vtuber") {
    const snapshot = options?.vtuberSnapshotBySourceKey
      ? resolveVtuberEditorSnapshot(element, options.vtuberSnapshotBySourceKey)
      : undefined;
    if (mode === "thumbnail") {
      if (snapshot) {
        return (
          <div className="relative h-full w-full">
            <img
              src={snapshot}
              alt={element.name}
              className="block h-full w-full"
              style={{ objectFit: "fill" }}
              draggable={false}
            />
          </div>
        );
      }
      return (
        <div></div>
      );
    }
    return null;
  }
  return (
    <div className="flex h-full w-full items-center justify-center bg-slate-100/90 dark:bg-slate-800/70 text-xs text-slate-600 dark:text-slate-300">
      {element.element_type}
    </div>
  );
};

type SlideCoverCaptureHandle = {
  capture: () => Promise<Blob | null>;
};

type SlideCoverCaptureHostProps = {
  slide: SlideElement | undefined;
  editorQuiz: QuizConfig | null;
  vtuberSnapshotByElementId: Record<string, string>;
  vtuberSnapshotBySourceKey: Record<string, string>;
  stageCanvasScale: number;
  translate: CoursewareTranslateFn;
};

/** Render the most complete frame of the first slide offscreen, for exporting the cover image on save. */
const SlideCoverCaptureHost = forwardRef<SlideCoverCaptureHandle, SlideCoverCaptureHostProps>(
  function SlideCoverCaptureHost(
    {
      slide,
      editorQuiz,
      vtuberSnapshotByElementId,
      vtuberSnapshotBySourceKey,
      stageCanvasScale,
      translate,
    },
    ref,
  ) {
    const rootRef = useRef<HTMLDivElement | null>(null);
    const snapshotAt = slide ? pickMostCompleteSnapshotTime(slide) : 0;

    useImperativeHandle(
      ref,
      () => ({
        capture: async (): Promise<Blob | null> => {
          await new Promise<void>((resolve) => {
            requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
          });
          const root = rootRef.current;
          if (!root || !slide) return null;
          return captureSlideCoverBlob(root);
        },
      }),
      [slide],
    );

    if (!slide) return null;

    return (
      <div
        aria-hidden
        className="pointer-events-none fixed overflow-hidden"
        style={{
          left: -20000,
          top: 0,
          width: SLIDE_LOGICAL_WIDTH,
          height: SLIDE_LOGICAL_HEIGHT,
          zIndex: -1,
        }}
      >
        <div
          ref={rootRef}
          className="relative isolate overflow-hidden"
          style={{
            width: SLIDE_LOGICAL_WIDTH,
            height: SLIDE_LOGICAL_HEIGHT,
            backgroundColor: slide.background_color,
          }}
        >
          {(() => {
            const bgImgStyle = getSlideBackgroundImageLayerStyle(
              slide.background_image_url,
              slide.background_image_fit,
            );
            return (
              <>
                {bgImgStyle ? (
                  <div className="pointer-events-none absolute inset-0 z-0" style={bgImgStyle} />
                ) : null}
                <SlideBackgroundHtmlLayer
                  src={slide.background_html_src}
                  slideId={slide.element_id}
                  contentZoom={slide.background_html_content_zoom}
                  scale={1}
                  zClassName="z-0"
                />
              </>
            );
          })()}
          <div className="relative z-1 h-full w-full">
            {buildQuestionStackRenderUnits(slide).map((unit) => {
              const renderCoverElement = (el: CourseElement, stackZ: number): React.ReactNode => {
                if (!isElementVisibleAtTimeInSlide(el, snapshotAt, slide)) return null;
                const transform = interpolateElementTransformInSlide(el, snapshotAt, slide);
                const fx = computeElementEnterExitEffectVisual(el, slide, snapshotAt);
                const opacity = clamp(transform.opacity * fx.opacityFactor, 0, 1);
                if (opacity <= 0.01) return null;
                const thumbW = transform.size.width;
                const thumbH = transform.size.height;
                const innerTransform = `translate(${fx.translateLogicalX}px, ${fx.translateLogicalY}px) rotate(${fx.rotateExtraDeg}deg) scale(${fx.uniformScale})`;
                return (
                  <div
                    key={el.element_id}
                    className="absolute overflow-hidden"
                    style={{
                      left: transform.position.x,
                      top: transform.position.y,
                      width: thumbW,
                      height: thumbH,
                      opacity,
                      transform: transform.rotation_deg
                        ? `rotate(${transform.rotation_deg}deg)`
                        : undefined,
                      transformOrigin: "center",
                      zIndex: resolveEditorThumbnailStackZ(el, stackZ),
                    }}
                  >
                    <div
                      className="absolute inset-0"
                      style={{
                        transform: innerTransform,
                        transformOrigin: "center center",
                      }}
                    >
                      {renderElementContent(
                        el,
                        transform.size.width,
                        transform.size.height,
                        1,
                        "thumbnail",
                        {
                          vtuberSnapshotByElementId,
                          vtuberSnapshotBySourceKey,
                          currentTime: snapshotAt,
                          thumbnailViewportPx: { width: thumbW, height: thumbH },
                          htmlReferenceLayoutScale: stageCanvasScale,
                          editorQuiz,
                          translate,
                        },
                      )}
                    </div>
                  </div>
                );
              };
              return renderCoverElement(unit.element, unit.element.style.z_index);
            })}
          </div>
        </div>
      </div>
    );
  },
);


/**
 * Single timeline row update: the logic of multi-select and linked movement of quiz wrappers and member children (formerly inline callbacks in Timeline).
 */
function createGroupedTimelineRowUpdater(
  el: CourseElement,
  slide: SlideElement | undefined,
  selectedElementIds: string[],
  onUpdateElement: (
    id: string,
    updater: (el: CourseElement) => CourseElement,
    options?: { recordHistory?: boolean },
  ) => void,
  onUpdateSlide: (updater: (c: SlideElement) => SlideElement) => void,
  quiz: QuizConfig | null | undefined,
): (updater: (el: CourseElement) => CourseElement, options?: { recordHistory?: boolean }) => void {
  return (updater, options) => {
    const selectedIdSet = new Set(selectedElementIds);
    const groupIdSet = new Set<string>();
    const isMultiGrouped =
      selectedIdSet.has(el.element_id) && selectedElementIds.length > 1;
    if (isMultiGrouped) {
      selectedElementIds.forEach((id) => groupIdSet.add(id));
    }
    // In the single-element quiz model a quiz element has no "members" to
    // sweep along with the group transform.

    const isGrouped = groupIdSet.size > 1;
    if (!isGrouped || !slide) {
      onUpdateElement(el.element_id, updater, options);
      return;
    }
    const current = el.timeline;
    const nextEl = updater(el);
    const next = nextEl.timeline;
    const deltaStart = next.start_at - current.start_at;
    const deltaEnd = next.end_at - current.end_at;
    if (Math.abs(deltaStart) < 0.001 && Math.abs(deltaEnd) < 0.001) {
      onUpdateElement(el.element_id, () => nextEl, options);
      return;
    }

    onUpdateSlide((c) => {
      const groupElements = c.children_elements.filter((item) => groupIdSet.has(item.element_id));
      const slideStart = c.timeline.start_at;
      const slideDur = Math.max(1, c.timeline.end_at - slideStart);
      // Quiz elements no longer come with companion "member" elements, so
      // group-move bounds are computed over the selection itself.
      const boundsSource = groupElements;
      const groupMinStartLocal = boundsSource.reduce(
        (min, item) => Math.min(min, item.timeline.start_at - slideStart),
        Number.POSITIVE_INFINITY,
      );
      const groupMaxEndLocal = boundsSource.reduce(
        (max, item) => Math.max(max, item.timeline.end_at - slideStart),
        Number.NEGATIVE_INFINITY,
      );
      const isMove = Math.abs(deltaStart - deltaEnd) < 0.001;
      const safeMoveDelta = isMove
        ? clamp(deltaStart, -groupMinStartLocal, slideDur - groupMaxEndLocal)
        : 0;

      return {
        ...c,
        children_elements: c.children_elements.map((item) => {
          if (!groupIdSet.has(item.element_id)) return item;
          const start = item.timeline.start_at;
          const end = item.timeline.end_at;
          if (isMove) {
            return finalizeEditorElement(
              shiftElementTimedRanges(
                {
                  ...item,
                  timeline: {
                    start_at: start + safeMoveDelta,
                    end_at: end + safeMoveDelta,
                  },
                },
                safeMoveDelta,
              ),
              c,
              quiz,
            );
          }
          if (Math.abs(deltaEnd) < 0.001) {
            const newStart =
              slideStart +
              clampResizeStartLocal(
                end - slideStart,
                start + deltaStart - slideStart,
                slideDur,
                MIN_ELEMENT_TIMELINE_SPAN_MS,
              );
            return finalizeEditorElement(
              {
                ...item,
                timeline: { start_at: newStart, end_at: end },
              },
              c,
              quiz,
            );
          }
          if (Math.abs(deltaStart) < 0.001) {
            const newEnd =
              slideStart +
              clampResizeEndLocal(
                start - slideStart,
                end + deltaEnd - slideStart,
                slideDur,
                MIN_ELEMENT_TIMELINE_SPAN_MS,
              );
            return finalizeEditorElement(
              {
                ...item,
                timeline: { start_at: start, end_at: newEnd },
              },
              c,
              quiz,
            );
          }
          const { start_at: nsLocal, end_at: neLocal } = normalizeTimelinePairLocal(
            start + deltaStart - slideStart,
            end + deltaEnd - slideStart,
            slideDur,
            MIN_ELEMENT_TIMELINE_SPAN_MS,
          );
          return finalizeEditorElement(
            {
              ...item,
              timeline: {
                start_at: slideStart + nsLocal,
                end_at: slideStart + neLocal,
              },
            },
            c,
            quiz,
          );
        }),
      };
    });
  };
}

// ---------- timeline playhead (60fps refreshes only the indicator, without redrawing the whole timeline) ----------

function EditorTimelinePlayheadClock({
  playheadRef,
  playheadFromRef,
  playheadClockRunning,
  pausedTimeMs,
  duration,
  className,
}: {
  playheadRef: RefObject<number>;
  playheadFromRef: boolean;
  playheadClockRunning: boolean;
  pausedTimeMs: number;
  duration: number;
  className?: string;
}) {
  const playheadMs = useEditorPlayheadMs(
    playheadFromRef,
    playheadClockRunning,
    pausedTimeMs,
    playheadRef,
  );
  return (
    <div
      className={
        className ??
        "ml-2 font-mono text-xs tabular-nums text-slate-600 dark:text-slate-300"
      }
    >
      {formatTimeMs(playheadMs)} / {formatTimeMs(duration)}
    </div>
  );
}

/** Playhead X on the timeline (px). % isn't used because the ruler's border shifts the containing block width. */
function editorTimelinePlayheadLeftPx(
  ratio: number,
  timelineWidthPx: number,
): number {
  return ratio * timelineWidthPx;
}

function EditorTimelinePlayheadMarker({
  playheadRef,
  playheadFromRef,
  playheadClockRunning,
  pausedTimeMs,
  duration,
  timelineWidthPx,
  className,
}: {
  playheadRef: RefObject<number>;
  playheadFromRef: boolean;
  playheadClockRunning: boolean;
  pausedTimeMs: number;
  duration: number;
  timelineWidthPx: number;
  className: string;
}) {
  const playheadMs = useEditorPlayheadMs(
    playheadFromRef,
    playheadClockRunning,
    pausedTimeMs,
    playheadRef,
  );
  const ratio = duration > 0 ? clamp(playheadMs / duration, 0, 1) : 0;
  return (
    <div
      className={className}
      style={{
        left: editorTimelinePlayheadLeftPx(ratio, timelineWidthPx),
        transform: "translateX(-50%)",
      }}
    />
  );
}

const TIMELINE_SCROLL_REVEAL_MS = 320;
/** After the initial scene loading overlay closes, wait one more frame for batching/layout to settle, then ease-scroll to the playhead. */
const TIMELINE_INITIAL_REVEAL_DELAY_MS = 520;

function easeOutCubic(t: number): number {
  return 1 - (1 - t) ** 3;
}

function computeTimelineScrollLeftForPlayheadMs(
  scrollEl: HTMLDivElement,
  playheadMs: number,
  durationMs: number,
  timelineWidthPx: number,
  options?: { mode?: "center" | "minimal"; followPadding?: number },
): number {
  const mode = options?.mode ?? "center";
  const followPadding = options?.followPadding ?? 32;
  const ratio = durationMs > 0 ? clamp(playheadMs / durationMs, 0, 1) : 0;
  // Use the same timelineWidthPx as the scan line (scrollWidth would drift with borders/children and make the follow run ahead)
  const playheadX = editorTimelinePlayheadLeftPx(ratio, timelineWidthPx);
  const maxScrollLeft = Math.max(0, scrollEl.scrollWidth - scrollEl.clientWidth);
  if (mode === "center") {
    return clamp(playheadX - scrollEl.clientWidth / 2, 0, maxScrollLeft);
  }
  const visibleLeft = scrollEl.scrollLeft;
  const visibleRight = visibleLeft + scrollEl.clientWidth;
  let nextScrollLeft: number | null = null;
  if (playheadX > visibleRight - followPadding) {
    nextScrollLeft = clamp(
      playheadX - scrollEl.clientWidth + followPadding,
      0,
      maxScrollLeft,
    );
  } else if (playheadX < visibleLeft + followPadding) {
    nextScrollLeft = clamp(playheadX - followPadding, 0, maxScrollLeft);
  }
  return nextScrollLeft ?? scrollEl.scrollLeft;
}

function animateTimelineScrollLeft(
  scrollEl: HTMLDivElement,
  targetScrollLeft: number,
  onStep?: () => void,
): () => void {
  const startScrollLeft = scrollEl.scrollLeft;
  const delta = targetScrollLeft - startScrollLeft;
  if (Math.abs(delta) < 1) {
    onStep?.();
    scrollEl.scrollLeft = targetScrollLeft;
    return () => {};
  }
  const startTime = performance.now();
  let rafId = 0;
  const tick = (now: number): void => {
    const t = clamp((now - startTime) / TIMELINE_SCROLL_REVEAL_MS, 0, 1);
    onStep?.();
    scrollEl.scrollLeft = startScrollLeft + delta * easeOutCubic(t);
    if (t < 1) {
      rafId = requestAnimationFrame(tick);
    }
  };
  rafId = requestAnimationFrame(tick);
  return () => cancelAnimationFrame(rafId);
}

/** Wait for the timeline's horizontal content width before revealing (on first load the DOM comes later than the playhead update). */
function waitForTimelineScrollLayout(
  scrollEl: HTMLDivElement,
  minContentWidthPx: number,
  onReady: () => void,
): () => void {
  let cancelled = false;
  let frames = 0;
  let rafId = 0;
  const tick = (): void => {
    if (cancelled) return;
    frames += 1;
    if (scrollEl.scrollWidth >= minContentWidthPx - 1 || frames >= 30) {
      onReady();
      return;
    }
    rafId = requestAnimationFrame(tick);
  };
  rafId = requestAnimationFrame(tick);
  return () => {
    cancelled = true;
    cancelAnimationFrame(rafId);
  };
}

/** After switching slides (and on first entering the editor), ease-scroll the timeline so the playhead lands in the middle of the viewport. */
function EditorTimelineRevealPlayheadOnSlide({
  slideElementId,
  revealAtMs,
  duration,
  timelineRevealReady,
  timelineContentWidthPx,
  rightScrollRef,
  timelineScrollProgrammaticRef,
  playheadFollowScrollDisabledRef,
  suppressScrollToPlayheadRef,
}: {
  slideElementId: string | undefined;
  revealAtMs: number;
  duration: number;
  /** Reveal only after the initial scene load finished, the overlay disappeared and (on first entry) after a delay. */
  timelineRevealReady: boolean;
  timelineContentWidthPx: number;
  rightScrollRef: RefObject<HTMLDivElement | null>;
  timelineScrollProgrammaticRef: RefObject<boolean>;
  playheadFollowScrollDisabledRef: RefObject<boolean>;
  /** When true, skip scrolling the viewport to the playhead (e.g. while dragging the slide duration). */
  suppressScrollToPlayheadRef?: RefObject<boolean>;
}) {
  const cancelAnimRef = useRef<(() => void) | null>(null);
  const revealAtMsRef = useRef(revealAtMs);
  const durationRef = useRef(duration);
  const timelineContentWidthPxRef = useRef(timelineContentWidthPx);
  revealAtMsRef.current = revealAtMs;
  durationRef.current = duration;
  timelineContentWidthPxRef.current = timelineContentWidthPx;

  useEffect(() => {
    cancelAnimRef.current?.();
    cancelAnimRef.current = null;

    if (!timelineRevealReady || !slideElementId || durationRef.current <= 0) return;
    if (suppressScrollToPlayheadRef?.current) return;

    let cancelled = false;
    let cancelLayoutWait: (() => void) | null = null;
    let rafAfterLayout: number | null = null;

    const runReveal = (): void => {
      if (cancelled) return;
      const scrollEl = rightScrollRef.current;
      if (!scrollEl) return;
      if (suppressScrollToPlayheadRef?.current) return;

      playheadFollowScrollDisabledRef.current = false;
      const layoutWidthPx = timelineContentWidthPxRef.current;
      const revealDurationMs = durationRef.current;
      const target = computeTimelineScrollLeftForPlayheadMs(
        scrollEl,
        revealAtMsRef.current,
        revealDurationMs,
        layoutWidthPx,
        { mode: "center" },
      );
      cancelAnimRef.current = animateTimelineScrollLeft(scrollEl, target, () => {
        timelineScrollProgrammaticRef.current = true;
      });
    };

    const scheduleRevealAfterLayout = (): void => {
      if (cancelled) return;
      const scrollEl = rightScrollRef.current;
      if (!scrollEl) return;

      const startReveal = (): void => {
        if (cancelled) return;
        rafAfterLayout = requestAnimationFrame(() => {
          rafAfterLayout = requestAnimationFrame(runReveal);
        });
      };

      const layoutWidthPx = timelineContentWidthPxRef.current;
      if (scrollEl.scrollWidth < layoutWidthPx - 1) {
        cancelLayoutWait = waitForTimelineScrollLayout(
          scrollEl,
          layoutWidthPx,
          startReveal,
        );
        return;
      }
      startReveal();
    };

    scheduleRevealAfterLayout();

    return () => {
      cancelled = true;
      cancelLayoutWait?.();
      cancelLayoutWait = null;
      if (rafAfterLayout !== null) cancelAnimationFrame(rafAfterLayout);
      cancelAnimRef.current?.();
      cancelAnimRef.current = null;
    };
    // Scroll to the playhead only on a slide switch / the first reveal; changing the slide duration or the preview width doesn't trigger it.
  }, [
    slideElementId,
    timelineRevealReady,
    rightScrollRef,
    timelineScrollProgrammaticRef,
    playheadFollowScrollDisabledRef,
    suppressScrollToPlayheadRef,
  ]);

  return null;
}

function EditorTimelinePlayheadFollowScroll({
  playheadRef,
  playheadFromRef,
  playheadClockRunning,
  pausedTimeMs,
  duration,
  timelineWidthPx,
  isPlaying,
  isPlayLoading,
  rightScrollRef,
  scrubbingRef,
  playheadFollowScrollDisabledRef,
  timelineScrollProgrammaticRef,
  suppressScrollToPlayheadRef,
}: {
  playheadRef: RefObject<number>;
  playheadFromRef: boolean;
  playheadClockRunning: boolean;
  pausedTimeMs: number;
  duration: number;
  timelineWidthPx: number;
  isPlaying: boolean;
  isPlayLoading: boolean;
  rightScrollRef: RefObject<HTMLDivElement | null>;
  scrubbingRef: RefObject<boolean>;
  playheadFollowScrollDisabledRef: RefObject<boolean>;
  timelineScrollProgrammaticRef: RefObject<boolean>;
  suppressScrollToPlayheadRef?: RefObject<boolean>;
}) {
  const pausedTimeMsRef = useRef(pausedTimeMs);
  pausedTimeMsRef.current = pausedTimeMs;

  useEffect(() => {
    if (!isPlaying || isPlayLoading || duration <= 0) return;

    let raf = 0;
    const tick = (): void => {
      if (
        !isPlaying ||
        isPlayLoading ||
        scrubbingRef.current ||
        playheadFollowScrollDisabledRef.current ||
        suppressScrollToPlayheadRef?.current
      ) {
        raf = requestAnimationFrame(tick);
        return;
      }
      const scrollEl = rightScrollRef.current;
      if (scrollEl) {
        const playheadMs = playheadFromRef && playheadClockRunning
          ? playheadRef.current
          : pausedTimeMsRef.current;
        const nextScrollLeft = computeTimelineScrollLeftForPlayheadMs(
          scrollEl,
          playheadMs,
          duration,
          timelineWidthPx,
          { mode: "minimal" },
        );
        if (nextScrollLeft !== scrollEl.scrollLeft) {
          timelineScrollProgrammaticRef.current = true;
          scrollEl.scrollLeft = nextScrollLeft;
        }
      }
      raf = requestAnimationFrame(tick);
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [
    playheadRef,
    playheadFromRef,
    playheadClockRunning,
    duration,
    timelineWidthPx,
    isPlaying,
    isPlayLoading,
    rightScrollRef,
    scrubbingRef,
    playheadFollowScrollDisabledRef,
    timelineScrollProgrammaticRef,
    suppressScrollToPlayheadRef,
  ]);

  return null;
}

// ---------- timeline ----------

interface TimelineProps {
  slide: SlideElement | undefined;
  currentTime: number;
  playheadRef: RefObject<number>;
  playheadFromRef: boolean;
  playheadClockRunning: boolean;
  duration: number;
  isPlaying: boolean;
  isPlayLoading: boolean;
  selectedKeyframe: SelectedKeyframe | null;
  selectedHighlight: SelectedHighlight | null;
  onPlayPause: () => void;
  onSeek: (ms: number) => void;
  selectedElementIds: string[];
  onSelectElement: (id: string | null, options?: { toggle?: boolean }) => void;
  onUpdateElement: (
    id: string,
    updater: (el: CourseElement) => CourseElement,
    options?: { recordHistory?: boolean },
  ) => void;
  onCaptureHistorySnapshot: () => Scene;
  onCommitHistorySnapshot: (snapshot: Scene) => void;
  onDurationChange: (ms: number, options?: { recordHistory?: boolean }) => void;
  recordKeyframes: boolean;
  onToggleRecord: () => void;
  onAddHighlightAtCurrentTime: (elementId: string) => void;
  onReorderLayerRow: (fromRow: number, toRow: number) => void;
  onUpdateSlide: (
    updater: (c: SlideElement) => SlideElement,
    options?: { recordHistory?: boolean },
  ) => void;
  onOpenElementProperties: (elementId: string) => void;
  onSelectKeyframe: (keyframe: SelectedKeyframe | null) => void;
  onSelectHighlight: (highlight: SelectedHighlight | null) => void;
  narrationButtonMode: "add" | "edit";
  onOpenNarrationModal: () => void;
  quiz: QuizConfig | null;
  timelineRevealReady: boolean;
  onOpenElementContextMenu?: OpenElementContextMenuFn;
  flowPausePoints: SlideFlowPausePoint[];
  selectedFlowPauseId: string | null;
  onUpdateFlowPausePoint: (
    pauseId: string,
    atMs: number,
    options?: { recordHistory?: boolean },
  ) => void;
  onSelectFlowPause: (pauseId: string | null) => void;
  onDeleteFlowPause: (pauseId: string) => void;
  onTimelineBarDragStart?: () => void;
  onTimelineBarDragEnd?: () => void;
}

const Timeline = memo(function Timeline({
  slide,
  currentTime,
  playheadRef,
  playheadFromRef,
  playheadClockRunning,
  duration,
  isPlaying,
  isPlayLoading,
  selectedKeyframe,
  selectedHighlight,
  onPlayPause,
  onSeek,
  selectedElementIds,
  onSelectElement,
  onUpdateElement,
  onCaptureHistorySnapshot,
  onCommitHistorySnapshot,
  onDurationChange,
  recordKeyframes,
  onToggleRecord,
  onAddHighlightAtCurrentTime,
  onReorderLayerRow,
  onUpdateSlide,
  onOpenElementProperties,
  onSelectKeyframe,
  onSelectHighlight,
  narrationButtonMode,
  onOpenNarrationModal,
  quiz,
  timelineRevealReady,
  onOpenElementContextMenu,
  flowPausePoints,
  selectedFlowPauseId,
  onUpdateFlowPausePoint,
  onSelectFlowPause,
  onDeleteFlowPause,
  onTimelineBarDragStart,
  onTimelineBarDragEnd,
}: TimelineProps) {
  const { t } = useI18nNew();
  const rulerRef = useRef<HTMLDivElement | null>(null);
  const leftScrollRef = useRef<HTMLDivElement | null>(null);
  const rightScrollRef = useRef<HTMLDivElement | null>(null);
  const syncingScrollFromRef = useRef<"left" | "right" | null>(null);
  const scrubbingRef = useRef(false);
  /** User scrolled the timeline horizontally; skip playhead follow until pause or ruler seek. */
  const playheadFollowScrollDisabledRef = useRef(false);
  const slideDurationDraggingRef = useRef(false);
  const timelineScrollProgrammaticRef = useRef(false);
  const lastTimelineScrollLeftRef = useRef(0);
  /** Slide-local timeline origin (children often use absolute scene times in [start,end]). */
  const slideTimeStart = slide?.timeline.start_at ?? 0;
  const timelineWidthPx = Math.max(1, (duration / 1000) * TIMELINE_PX_PER_SECOND);

  // Quiz canvas elements are single boxes in the new model — no member ids to hide.
  const questionMemberIds = useMemo(() => new Set<string>(), []);
  const [timelineSnapGuides, setTimelineSnapGuides] = useState<TimelineSnapGuide[]>([]);
  const clearTimelineSnapGuides = useCallback((): void => {
    setTimelineSnapGuides((prev) => (prev.length === 0 ? prev : []));
  }, []);
  const buildTimelineSnapTargets = useCallback(
    (excludeElementId: string): TimelineSnapTarget[] => {
      if (!slide) return [];
      const peers = slide.children_elements
        .filter((el) => !questionMemberIds.has(el.element_id))
        .map((el) => ({
          element_id: el.element_id,
          start_at: el.timeline.start_at,
          end_at: el.timeline.end_at,
        }));
      const narrations = slide.children_elements
        .filter((el): el is NarrationElement => el.element_type === "narration")
        .map((el) => ({
          element_id: el.element_id,
          timeline_start_at: el.timeline.start_at,
          segments: el.segments,
        }));
      return collectTimelineSnapTargets({
        slideStart: slide.timeline.start_at,
        slideEnd: slide.timeline.end_at,
        peers,
        excludeElementId,
        playheadMs: slideTimeStart + currentTime,
        narrations,
      });
    },
    [currentTime, questionMemberIds, slide, slideTimeStart],
  );
  const timelineAutoScrollFrameRef = useRef<number | null>(null);
  const timelineAutoScrollStateRef = useRef<{
    clientX: number;
    onScrolled: (clientX: number) => void;
  } | null>(null);
  const [slideDurationDragPreviewMs, setSlideDurationDragPreviewMs] = useState<number | null>(
    null,
  );
  const [slideDurationDragPointer, setSlideDurationDragPointer] = useState<{
    x: number;
    y: number;
  } | null>(null);
  const slideDurationDragPointerYRef = useRef(0);
  const slideDurationDragRef = useRef<{
    startDurationMs: number;
    historySnapshot: Scene;
  } | null>(null);
  const timelineLayoutAnimRef = useRef<HTMLDivElement | null>(null);
  const slideDurationReleaseAnimRef = useRef<{ toWidthPx: number } | null>(null);
  const [isSlideDurationReleaseAnimating, setIsSlideDurationReleaseAnimating] = useState(false);
  const [releaseAnimLayoutWidthPx, setReleaseAnimLayoutWidthPx] = useState<number | null>(null);
  const isSlideDurationDragging = slideDurationDragPreviewMs !== null;
  const slideDurationPreviewMs = slideDurationDragPreviewMs ?? duration;
  const layoutDurationForTracksMs = isSlideDurationDragging
    ? Math.max(duration, slideDurationPreviewMs)
    : duration;
  const committedTimelineWidthPx = Math.max(
    1,
    (duration / 1000) * TIMELINE_PX_PER_SECOND,
  );
  const timelineLayoutWidthPx = isSlideDurationDragging
    ? Math.max(
        committedTimelineWidthPx,
        (slideDurationPreviewMs / 1000) * TIMELINE_PX_PER_SECOND,
      )
    : committedTimelineWidthPx;
  /** During the release transition React controls the content width; the trailing blank space takes its own place, avoiding a jump at the end. */
  const displayTimelineLayoutWidthPx = releaseAnimLayoutWidthPx ?? timelineLayoutWidthPx;
  const slideEndLayoutPct =
    (duration / Math.max(1, layoutDurationForTracksMs)) * 100;
  const slideDurationPreviewLayoutPct =
    (slideDurationPreviewMs / Math.max(1, layoutDurationForTracksMs)) * 100;
  const timelineScrollContentWidthPx =
    displayTimelineLayoutWidthPx + TIMELINE_TAIL_PADDING_PX;

  const finishSlideDurationReleaseAnim = useCallback((): void => {
    if (!slideDurationReleaseAnimRef.current) return;
    slideDurationReleaseAnimRef.current = null;
    setReleaseAnimLayoutWidthPx(null);
    setIsSlideDurationReleaseAnimating(false);
    slideDurationDraggingRef.current = false;
    if (!isPlaying) {
      playheadFollowScrollDisabledRef.current = false;
    }
  }, [isPlaying]);

  const handleReleaseLayoutWidthTransitionEnd = useCallback(
    (event: React.TransitionEvent<HTMLDivElement>): void => {
      if (event.propertyName !== "width" || !slideDurationReleaseAnimRef.current) return;
      finishSlideDurationReleaseAnim();
    },
    [finishSlideDurationReleaseAnim],
  );

  useLayoutEffect(() => {
    if (!isSlideDurationReleaseAnimating || !slideDurationReleaseAnimRef.current) return;

    const targetWidthPx = slideDurationReleaseAnimRef.current.toWidthPx;
    const rafId = requestAnimationFrame(() => {
      setReleaseAnimLayoutWidthPx(targetWidthPx);
    });
    const fallbackTimer = window.setTimeout(() => {
      finishSlideDurationReleaseAnim();
    }, SLIDE_DURATION_RELEASE_TRANSITION_MS + 64);

    return () => {
      cancelAnimationFrame(rafId);
      window.clearTimeout(fallbackTimer);
    };
  }, [isSlideDurationReleaseAnimating, finishSlideDurationReleaseAnim]);

  const updateSlideDurationFromDrag = useCallback(
    (clientX: number): void => {
      const d = slideDurationDragRef.current;
      const scrollEl = rightScrollRef.current;
      if (!d || !slide || !scrollEl) return;
      setSlideDurationDragPointer({ x: clientX, y: slideDurationDragPointerYRef.current });
      // Convert the duration with timeline content coordinates, so scrollLeft changes from the playhead follow don't scramble the delta.
      const xInContent =
        clientX - scrollEl.getBoundingClientRect().left + scrollEl.scrollLeft;
      const anchorPx = (d.startDurationMs / 1000) * TIMELINE_PX_PER_SECOND;
      const dxMs = ((xInContent - anchorPx) / SLIDE_DURATION_DRAG_PX_PER_SECOND) * 1000;
      let newDurationMs = Math.max(
        SLIDE_DURATION_DRAG_MIN_MS,
        d.startDurationMs + dxMs,
      );
      const absoluteEnd = slideTimeStart + newDurationMs;
      const slideEndMs = slide.timeline.end_at;
      const targets = buildTimelineSnapTargets(SLIDE_DURATION_RESIZE_SNAP_EXCLUDE_ID).filter(
        (t) =>
          !(t.source === "slide-edge" && Math.abs(t.positionMs - slideEndMs) < 1) &&
          t.source !== "playhead",
      );
      const { snappedMs, guide } = snapTimelineAnchorMs(absoluteEnd, targets);
      const snappedLocalMs = snappedMs - slideTimeStart;
      newDurationMs = Math.max(
        SLIDE_DURATION_DRAG_MIN_MS,
        Math.round(snappedLocalMs / SLIDE_DURATION_DRAG_STEP_MS) *
          SLIDE_DURATION_DRAG_STEP_MS,
      );
      setTimelineSnapGuides(guide ? [guide] : []);
      setSlideDurationDragPreviewMs(newDurationMs);
    },
    [buildTimelineSnapTargets, slide, slideTimeStart],
  );

  const beginSlideDurationDrag = (e: React.PointerEvent<HTMLDivElement>): void => {
    if (!slide) return;
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    slideDurationDraggingRef.current = true;
    playheadFollowScrollDisabledRef.current = true;
    slideDurationDragRef.current = {
      startDurationMs: duration,
      historySnapshot: onCaptureHistorySnapshot(),
    };
    slideDurationDragPointerYRef.current = e.clientY;
    setSlideDurationDragPointer({ x: e.clientX, y: e.clientY });
    setSlideDurationDragPreviewMs(duration);
  };

  const onSlideDurationDragMove = (e: React.PointerEvent<HTMLDivElement>): void => {
    if (!slideDurationDragRef.current) return;
    e.stopPropagation();
    slideDurationDragPointerYRef.current = e.clientY;
    setSlideDurationDragPointer({ x: e.clientX, y: e.clientY });
    updateSlideDurationFromDrag(e.clientX);
    requestTimelineAutoScroll(e.clientX, updateSlideDurationFromDrag);
  };

  const endSlideDurationDrag = (e: React.PointerEvent<HTMLDivElement>): void => {
    const d = slideDurationDragRef.current;
    if (!d) return;
    e.stopPropagation();
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    const committedMs = slideDurationDragPreviewMs ?? d.startDurationMs;
    const toLayoutWidthPx = Math.max(
      1,
      (committedMs / 1000) * TIMELINE_PX_PER_SECOND,
    );
    const startLayoutWidthPx = Math.max(
      1,
      (d.startDurationMs / 1000) * TIMELINE_PX_PER_SECOND,
    );
    // Lengthening: transition from the drag start width to the target; shortening: from the current preview layout width to the target.
    const isGrowingRelease = committedMs > d.startDurationMs;
    const fromLayoutWidthPx = isGrowingRelease
      ? startLayoutWidthPx
      : timelineLayoutWidthPx;
    const needsWidthTransition = Math.abs(fromLayoutWidthPx - toLayoutWidthPx) >= 1;

    slideDurationDragRef.current = null;
    setSlideDurationDragPreviewMs(null);
    setSlideDurationDragPointer(null);
    clearTimelineSnapGuides();
    stopTimelineAutoScroll();

    if (committedMs !== d.startDurationMs) {
      onDurationChange(committedMs, { recordHistory: false });
    }
    onCommitHistorySnapshot(d.historySnapshot);

    if (needsWidthTransition) {
      slideDurationReleaseAnimRef.current = { toWidthPx: toLayoutWidthPx };
      setReleaseAnimLayoutWidthPx(fromLayoutWidthPx);
      setIsSlideDurationReleaseAnimating(true);
      return;
    }

    slideDurationDraggingRef.current = false;
    if (!isPlaying) {
      playheadFollowScrollDisabledRef.current = false;
    }
  };

  const slideDurationDragDeltaMs =
    isSlideDurationDragging && slideDurationDragRef.current
      ? slideDurationPreviewMs - slideDurationDragRef.current.startDurationMs
      : 0;

  const seekFromClientX = (clientX: number): void => {
    if (!rulerRef.current) return;
    const rect = rulerRef.current.getBoundingClientRect();
    // Match the scroll content width in `style` below so scrubbing maps 1:1
    // to slide-local 0..duration (avoids end-clamp when DOM width != layout).
    const ratio = clamp((clientX - rect.left) / timelineWidthPx, 0, 1);
    onSeek(ratio * duration);
  };

  const flowPauseClientXToLocalMs = useCallback(
    (clientX: number): number => {
      const scrollEl = rightScrollRef.current;
      if (!scrollEl) return 0;
      const xInContent =
        clientX - scrollEl.getBoundingClientRect().left + scrollEl.scrollLeft;
      const ratio = clamp(xInContent / timelineWidthPx, 0, 1);
      return ratio * duration;
    },
    [duration, timelineWidthPx],
  );

  const stopTimelineAutoScroll = useCallback((): void => {
    if (timelineAutoScrollFrameRef.current !== null) {
      cancelAnimationFrame(timelineAutoScrollFrameRef.current);
      timelineAutoScrollFrameRef.current = null;
    }
    timelineAutoScrollStateRef.current = null;
  }, []);

  const requestTimelineAutoScroll = useCallback(
    (clientX: number, onScrolled: (clientX: number) => void): void => {
      timelineAutoScrollStateRef.current = { clientX, onScrolled };
      if (timelineAutoScrollFrameRef.current !== null) return;

      const tick = (): void => {
        const state = timelineAutoScrollStateRef.current;
        const scrollEl = rightScrollRef.current;
        if (!state || !scrollEl) {
          timelineAutoScrollFrameRef.current = null;
          return;
        }

        const rect = scrollEl.getBoundingClientRect();
        const edgeSize = 48;
        const maxStep = 28;
        let step = 0;
        if (state.clientX < rect.left + edgeSize) {
          step = -maxStep * clamp((rect.left + edgeSize - state.clientX) / edgeSize, 0, 1);
        } else if (state.clientX > rect.right - edgeSize) {
          step = maxStep * clamp((state.clientX - (rect.right - edgeSize)) / edgeSize, 0, 1);
        }

        if (Math.abs(step) < 0.1) {
          timelineAutoScrollFrameRef.current = null;
          timelineAutoScrollStateRef.current = null;
          return;
        }

        const prevScrollLeft = scrollEl.scrollLeft;
        timelineScrollProgrammaticRef.current = true;
        scrollEl.scrollLeft = clamp(
          prevScrollLeft + step,
          0,
          scrollEl.scrollWidth - scrollEl.clientWidth,
        );
        if (scrollEl.scrollLeft !== prevScrollLeft) {
          state.onScrolled(state.clientX);
          timelineAutoScrollFrameRef.current = requestAnimationFrame(tick);
          return;
        }

        timelineAutoScrollFrameRef.current = null;
        timelineAutoScrollStateRef.current = null;
      };

      timelineAutoScrollFrameRef.current = requestAnimationFrame(tick);
    },
    [],
  );

  useEffect(() => stopTimelineAutoScroll, [stopTimelineAutoScroll]);

  useEffect(() => {
    if (!isPlaying) playheadFollowScrollDisabledRef.current = false;
  }, [isPlaying]);

  const syncScrollTop = (from: "left" | "right"): void => {
    const left = leftScrollRef.current;
    const right = rightScrollRef.current;
    if (!left || !right) return;
    const source = from === "left" ? left : right;
    const target = from === "left" ? right : left;
    if (target.scrollTop === source.scrollTop) return;
    syncingScrollFromRef.current = from;
    target.scrollTop = source.scrollTop;
  };

  const handleLeftScroll = (): void => {
    if (syncingScrollFromRef.current === "right") {
      syncingScrollFromRef.current = null;
      return;
    }
    syncScrollTop("left");
  };

  const handleRightScroll = (): void => {
    if (syncingScrollFromRef.current === "left") {
      syncingScrollFromRef.current = null;
      return;
    }
    const scrollEl = rightScrollRef.current;
    if (scrollEl) {
      const scrollLeft = scrollEl.scrollLeft;
      const scrollLeftChanged = scrollLeft !== lastTimelineScrollLeftRef.current;
      lastTimelineScrollLeftRef.current = scrollLeft;
      if (timelineScrollProgrammaticRef.current) {
        timelineScrollProgrammaticRef.current = false;
      } else if (scrollLeftChanged && isPlaying && !scrubbingRef.current) {
        playheadFollowScrollDisabledRef.current = true;
      }
    }
    syncScrollTop("right");
  };
  const selectedHighlightTarget =
    selectedElementIds.length === 1
      ? slide?.children_elements.find((el) => el.element_id === selectedElementIds[0])
      : null;
  const canAddHighlightFromTimeline = !!selectedHighlightTarget;
  const rulerTickCount = Math.floor(layoutDurationForTracksMs / 1000);

  return (
    <>
    <div
      tabIndex={-1}
      data-hotkey-scope="timeline"
      className="flex h-full min-h-0 shrink-0 flex-col bg-white dark:bg-slate-900 outline-none"
      onPointerDownCapture={(e) => {
        e.currentTarget.focus();
      }}
    >
      <div className="flex items-center gap-2 border-b border-slate-200 dark:border-slate-800 px-3 py-1.5">
        <IconButton icon={<SkipBack className="h-4 w-4" />} label={t("coursewareEditor.timeline.rewind")} onClick={() => onSeek(0)} />
        <IconButton
          icon={isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
          label={isPlayLoading ? t("coursewareEditor.common.loading") : isPlaying ? t("coursewareEditor.common.pause") : t("coursewareEditor.common.play")}
          loading={isPlayLoading}
          onClick={onPlayPause}
        />
        <IconButton
          icon={<SkipForward className="h-4 w-4" />}
          label={t("coursewareEditor.timeline.seekEnd")}
          onClick={() => onSeek(duration)}
        />
        <EditorTimelinePlayheadClock
          playheadRef={playheadRef}
          playheadFromRef={playheadFromRef}
          playheadClockRunning={playheadClockRunning}
          pausedTimeMs={currentTime}
          duration={duration}
        />
        <div className="ml-auto flex items-center gap-2">
          <NarrationButton mode={narrationButtonMode} onClick={onOpenNarrationModal} />
          <button
            type="button"
            disabled={!canAddHighlightFromTimeline}
            className={`flex items-center gap-1 rounded px-2 py-1 text-xs ${
              canAddHighlightFromTimeline
                ? "bg-amber-100 text-amber-900 hover:bg-amber-200 dark:bg-amber-500/15 dark:text-amber-200 dark:hover:bg-amber-500/25"
                : "cursor-not-allowed text-slate-400 dark:text-slate-600"
            }`}
            onClick={() => {
              if (selectedHighlightTarget) onAddHighlightAtCurrentTime(selectedHighlightTarget.element_id);
            }}
            title={t("coursewareEditor.timeline.insertHighlight")}
          >
            <Star className="h-3.5 w-3.5" />
            {t("coursewareEditor.common.highlight")}
          </button>
          <label className="flex items-center gap-1 text-xs text-slate-400 dark:text-slate-500">
            {t("coursewareEditor.common.duration")}
            <NumberInputField
              value={Math.round(slideDurationPreviewMs / 100) / 10}
              step={0.5}
              min={1}
              disabled={isSlideDurationDragging}
              onChange={(secs) => onDurationChange(Math.max(1, secs) * 1000)}
              className={`w-16 rounded bg-slate-100 dark:bg-slate-800 px-2 py-0.5 text-xs text-slate-800 dark:text-slate-200 outline-none ring-1 ring-slate-300 dark:ring-slate-700 focus:ring-blue-500 ${
                isSlideDurationDragging ? "text-cyan-800 dark:text-cyan-200" : ""
              }`}
            />
            <span className="text-slate-400 dark:text-slate-500">{t("coursewareEditor.common.seconds")}</span>
          </label>
          <button
            className={`flex items-center gap-1 rounded px-2 py-1 text-xs ${
              recordKeyframes
                ? "bg-rose-100 text-rose-700 dark:bg-rose-500/20 dark:text-rose-300"
                : "text-slate-600 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-800"
            }`}
            onClick={onToggleRecord}
            title={t("coursewareEditor.timeline.recordKeyframesTitle")}
          >
            <CircleIcon className="h-3 w-3 fill-current" />
            {recordKeyframes ? t("coursewareEditor.common.recording") : t("coursewareEditor.common.record")}
          </button>
        </div>
      </div>

      <div className="flex min-h-0 flex-1">
        <div className="flex w-[230px] shrink-0 flex-col border-r border-slate-200 dark:border-slate-800 bg-slate-100/85 dark:bg-slate-950/40">
          <div className="flex h-6 items-center justify-between border-b border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 px-2 text-[10px] uppercase tracking-wide text-slate-400 dark:text-slate-500">
            <span>{t("coursewareEditor.timeline.layers")}</span>
            <span>{t("coursewareEditor.common.topLayer")}</span>
          </div>
          <div
            ref={leftScrollRef}
            className="min-h-0 flex-1 overflow-y-auto"
            onScroll={handleLeftScroll}
          >
            <LayerList
              slide={slide}
              selectedElementIds={selectedElementIds}
              onSelectElement={onSelectElement}
              onReorderLayerRow={onReorderLayerRow}
              hiddenElementIds={questionMemberIds}
              onOpenElementContextMenu={onOpenElementContextMenu}
            />
            {(!slide || slide.children_elements.length === 0) && (
              <div className="px-3 py-4 text-center text-xs text-slate-400 dark:text-slate-500">
                {t("coursewareEditor.common.emptyCanvasHint")}
              </div>
            )}
          </div>
        </div>

        <div className="flex min-w-0 flex-1 flex-col bg-slate-50 dark:bg-slate-950/30">
          <div
            ref={rightScrollRef}
            className="min-h-0 flex-1 overflow-auto"
            onScroll={handleRightScroll}
          >
            <EditorTimelineRevealPlayheadOnSlide
              slideElementId={slide?.element_id}
              revealAtMs={currentTime}
              duration={duration}
              timelineRevealReady={timelineRevealReady}
              timelineContentWidthPx={timelineWidthPx + TIMELINE_TAIL_PADDING_PX}
              rightScrollRef={rightScrollRef}
              timelineScrollProgrammaticRef={timelineScrollProgrammaticRef}
              playheadFollowScrollDisabledRef={playheadFollowScrollDisabledRef}
              suppressScrollToPlayheadRef={slideDurationDraggingRef}
            />
            <EditorTimelinePlayheadFollowScroll
              playheadRef={playheadRef}
              playheadFromRef={playheadFromRef}
              playheadClockRunning={playheadClockRunning}
              pausedTimeMs={currentTime}
              duration={duration}
              timelineWidthPx={timelineWidthPx}
              isPlaying={isPlaying}
              isPlayLoading={isPlayLoading}
              rightScrollRef={rightScrollRef}
              scrubbingRef={scrubbingRef}
              playheadFollowScrollDisabledRef={playheadFollowScrollDisabledRef}
              timelineScrollProgrammaticRef={timelineScrollProgrammaticRef}
              suppressScrollToPlayheadRef={slideDurationDraggingRef}
            />
            <div
              className="relative flex min-h-full"
              style={{ width: `${timelineScrollContentWidthPx}px` }}
            >
              <div
                ref={timelineLayoutAnimRef}
                className={`relative shrink-0 ${
                  releaseAnimLayoutWidthPx !== null
                    ? "transition-[width] ease-out"
                    : ""
                }`}
                style={{
                  width: `${displayTimelineLayoutWidthPx}px`,
                  transitionDuration:
                    releaseAnimLayoutWidthPx !== null
                      ? `${SLIDE_DURATION_RELEASE_TRANSITION_MS}ms`
                      : undefined,
                }}
                onTransitionEnd={handleReleaseLayoutWidthTransitionEnd}
              >
                <div
                  className="pointer-events-none absolute inset-y-0 border-r border-slate-200 dark:border-slate-800"
                  style={{ left: `${slideEndLayoutPct}%` }}
                />
                {isSlideDurationDragging ? (
                  <>
                    {slideDurationPreviewMs > duration ? (
                      <div
                        className="pointer-events-none absolute inset-y-0 bg-cyan-500/[0.07] dark:bg-cyan-400/9"
                        style={{
                          left: `${slideEndLayoutPct}%`,
                          width: `${slideDurationPreviewLayoutPct - slideEndLayoutPct}%`,
                        }}
                      />
                    ) : slideDurationPreviewMs < duration ? (
                      <div
                        className="pointer-events-none absolute inset-y-0 bg-amber-500/8 dark:bg-amber-400/10"
                        style={{
                          left: `${slideDurationPreviewLayoutPct}%`,
                          width: `${slideEndLayoutPct - slideDurationPreviewLayoutPct}%`,
                        }}
                      />
                    ) : null}
                    <div
                      className="pointer-events-none absolute inset-y-0 z-15 border-r border-cyan-500/55 dark:border-cyan-400/50"
                      style={{ left: `${slideDurationPreviewLayoutPct}%` }}
                    />
                    <div
                      className="pointer-events-none absolute inset-y-0 z-14 bg-slate-500/8 dark:bg-slate-950/25"
                      style={{
                        left: `${Math.max(slideEndLayoutPct, slideDurationPreviewLayoutPct)}%`,
                        right: 0,
                      }}
                    />
                  </>
                ) : null}
                <div
                  ref={rulerRef}
                  className="sticky top-0 z-20 h-6 cursor-pointer border-b border-slate-200 dark:border-slate-800 bg-slate-100 dark:bg-slate-900 select-none"
                  onPointerDown={(e) => {
                    scrubbingRef.current = true;
                    playheadFollowScrollDisabledRef.current = false;
                    onSelectFlowPause(null);
                    (e.target as HTMLElement).setPointerCapture(e.pointerId);
                    seekFromClientX(e.clientX);
                  }}
                  onPointerMove={(e) => {
                    if (!scrubbingRef.current) return;
                    seekFromClientX(e.clientX);
                    requestTimelineAutoScroll(e.clientX, seekFromClientX);
                  }}
                  onPointerUp={(e) => {
                    scrubbingRef.current = false;
                    stopTimelineAutoScroll();
                    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
                  }}
                  onPointerCancel={() => {
                    scrubbingRef.current = false;
                    stopTimelineAutoScroll();
                  }}
                >
                  {Array.from({ length: rulerTickCount }).map((_, i) => (
                    <div
                      key={i}
                      className={`pointer-events-none absolute top-0 h-full border-l border-slate-300 dark:border-slate-700/60 text-[10px] text-slate-600 dark:text-slate-500 ${
                        i === rulerTickCount - 1
                          ? "border-r border-slate-300 dark:border-slate-700/60"
                          : ""
                      }`}
                      style={{
                        left: i * TIMELINE_PX_PER_SECOND,
                        width: TIMELINE_PX_PER_SECOND,
                      }}
                    >
                      <span className="ml-1">{i}s</span>
                    </div>
                  ))}
                  {slide ? (
                    <div
                      role="separator"
                      aria-orientation="vertical"
                      aria-label={t("coursewareEditor.timeline.slideDurationDrag")}
                      title={t("coursewareEditor.timeline.slideDurationDrag")}
                      className="group/slide-end absolute top-0 z-40 flex h-full w-5 -translate-x-1/2 cursor-ew-resize items-stretch justify-center"
                      style={{ left: `${slideDurationPreviewLayoutPct}%` }}
                      onPointerDown={(e) => {
                        e.stopPropagation();
                        beginSlideDurationDrag(e);
                      }}
                      onPointerMove={onSlideDurationDragMove}
                      onPointerUp={endSlideDurationDrag}
                      onPointerCancel={endSlideDurationDrag}
                      onClick={(e) => e.stopPropagation()}
                    >
                      <div
                        className={`h-full w-1 shrink-0 rounded-full bg-cyan-500/0 transition-opacity group-hover/slide-end:bg-cyan-500/55 dark:group-hover/slide-end:bg-cyan-400/55 ${
                          isSlideDurationDragging
                            ? "bg-cyan-500/75! dark:bg-cyan-400/70!"
                            : ""
                        }`}
                      />
                    </div>
                  ) : null}
                  <EditorTimelinePlayheadMarker
                    playheadRef={playheadRef}
                    playheadFromRef={playheadFromRef}
                    playheadClockRunning={playheadClockRunning}
                    pausedTimeMs={currentTime}
                    duration={duration}
                    timelineWidthPx={timelineWidthPx}
                    className="pointer-events-none absolute top-0 z-30 h-full w-0.5 bg-rose-400"
                  />
                  <FlowPauseTimelineMarkers
                    points={flowPausePoints}
                    durationMs={duration}
                    layoutDurationMs={layoutDurationForTracksMs}
                    clientXToLocalMs={flowPauseClientXToLocalMs}
                    onUpdatePoint={(pauseId, atMs) =>
                      onUpdateFlowPausePoint(pauseId, atMs, { recordHistory: false })
                    }
                    onCaptureHistorySnapshot={onCaptureHistorySnapshot}
                    onCommitHistorySnapshot={onCommitHistorySnapshot}
                    selectedPauseId={selectedFlowPauseId}
                    onSelectPause={onSelectFlowPause}
                    onDeletePause={onDeleteFlowPause}
                    variant="ruler"
                    dragLabel={t("coursewareEditor.timeline.flowPauseDrag")}
                  />
                </div>

              <div className="relative">
                <FlowPauseTimelineMarkers
                  points={flowPausePoints}
                  durationMs={duration}
                  layoutDurationMs={layoutDurationForTracksMs}
                  clientXToLocalMs={flowPauseClientXToLocalMs}
                  onUpdatePoint={(pauseId, atMs) =>
                    onUpdateFlowPausePoint(pauseId, atMs, { recordHistory: false })
                  }
                  onCaptureHistorySnapshot={onCaptureHistorySnapshot}
                  onCommitHistorySnapshot={onCommitHistorySnapshot}
                  selectedPauseId={selectedFlowPauseId}
                  onSelectPause={onSelectFlowPause}
                  onDeletePause={onDeleteFlowPause}
                  variant="tracks"
                  dragLabel={t("coursewareEditor.timeline.flowPauseDrag")}
                />
                {timelineSnapGuides.length > 0 ? (
                  <>
                    {timelineSnapGuides.map((guide, index) => {
                      const localMs = guide.positionMs - slideTimeStart;
                      const leftPct =
                        (localMs / Math.max(1, layoutDurationForTracksMs)) * 100;
                      const isSlideEdge = guide.source === "slide-edge";
                      const isPlayhead = guide.source === "playhead";
                      const isNarrationSeg = guide.source === "narration-segment";
                      const colorClass = isSlideEdge
                        ? "bg-cyan-400/95"
                        : isPlayhead
                          ? "bg-rose-400/90"
                          : isNarrationSeg
                            ? "bg-violet-400/95"
                            : "bg-fuchsia-500/90";
                      return (
                        <div
                          key={`tl-snap-${guide.source}-${guide.positionMs}-${index}`}
                          className={`pointer-events-none absolute inset-y-0 z-25 ${colorClass}`}
                          style={{
                            left: `${leftPct}%`,
                            width: isSlideEdge ? 2 : 1,
                            marginLeft: isSlideEdge ? -1 : -0.5,
                          }}
                        />
                      );
                    })}
                  </>
                ) : null}
                {slide &&
                  buildEditorTimelineRows(slide).map((row) => {
                    const el = slide.children_elements[row.childIndex];
                    if (!el) return null;
                    const slideDur = Math.max(1, slide.timeline.end_at - slide.timeline.start_at);
                    const quizNarrationLocked =
                      el.element_type === "quiz" &&
                      resolveQuizQuestionFixedNarrationSpanMs(slideDur, {
                        quiz,
                        questionId: (el as QuizSlideElement).quiz_question_id,
                      }) != null;
                    return (
                      <TimelineTrack
                        key={el.element_id}
                        element={el}
                        duration={duration}
                        timelineLayoutDurationMs={layoutDurationForTracksMs}
                        slideTimeStart={slideTimeStart}
                        isQuizQuestionTimeline={quizNarrationLocked}
                        selected={selectedElementIds.includes(el.element_id)}
                        currentTime={currentTime}
                        selectedKeyframe={selectedKeyframe}
                        selectedHighlight={selectedHighlight}
                        getScrollLeft={() => rightScrollRef.current?.scrollLeft ?? 0}
                        onRequestAutoScroll={requestTimelineAutoScroll}
                        onStopAutoScroll={stopTimelineAutoScroll}
                        onSeek={onSeek}
                        onOpenElementProperties={onOpenElementProperties}
                        onSelectKeyframe={onSelectKeyframe}
                        onSelectHighlight={onSelectHighlight}
                        onCaptureHistorySnapshot={onCaptureHistorySnapshot}
                        onCommitHistorySnapshot={onCommitHistorySnapshot}
                        seekFromTimelineClientX={seekFromClientX}
                        getTimelineSnapTargets={buildTimelineSnapTargets}
                        onTimelineSnapGuidesChange={setTimelineSnapGuides}
                        onClearTimelineSnapGuides={clearTimelineSnapGuides}
                        onSelect={(event) =>
                          onSelectElement(el.element_id, {
                            toggle: event.metaKey || event.ctrlKey || event.shiftKey,
                          })
                        }
                        onUpdateElement={createGroupedTimelineRowUpdater(
                          el,
                          slide,
                          selectedElementIds,
                          onUpdateElement,
                          onUpdateSlide,
                          quiz,
                        )}
                        onOpenElementContextMenu={onOpenElementContextMenu}
                        onTimelineBarDragStart={onTimelineBarDragStart}
                        onTimelineBarDragEnd={onTimelineBarDragEnd}
                      />
                    );
                  })}
                <EditorTimelinePlayheadMarker
                  playheadRef={playheadRef}
                  playheadFromRef={playheadFromRef}
                  playheadClockRunning={playheadClockRunning}
                  pausedTimeMs={currentTime}
                  duration={duration}
                  timelineWidthPx={timelineWidthPx}
                  className="pointer-events-none absolute inset-y-0 z-30 w-0.5 bg-rose-400/70"
                />
              </div>
              </div>
              <div
                className="shrink-0"
                style={{ width: TIMELINE_TAIL_PADDING_PX }}
                aria-hidden
              />
            </div>
          </div>
        </div>
      </div>
    </div>
    {typeof document !== "undefined" &&
    isSlideDurationDragging &&
    slideDurationDragPointer &&
    slideDurationDragDeltaMs !== 0
      ? createPortal(
          <div
            role="status"
            aria-live="polite"
            className={`pointer-events-none fixed z-99999 -translate-x-1/2 whitespace-nowrap rounded-md border px-2 py-0.5 text-[11px] font-mono font-semibold tabular-nums shadow-lg ${
              slideDurationDragDeltaMs > 0
                ? "border-cyan-300/80 bg-white text-cyan-800 dark:border-cyan-500/50 dark:bg-slate-900 dark:text-cyan-200"
                : "border-amber-300/80 bg-white text-amber-900 dark:border-amber-500/50 dark:bg-slate-900 dark:text-amber-200"
            }`}
            style={{
              left: slideDurationDragPointer.x,
              top: slideDurationDragPointer.y - 40,
            }}
          >
            {formatSlideDurationDragDeltaLabel(slideDurationDragDeltaMs)}
          </div>,
          document.body,
        )
      : null}
    </>
  );
}, editorSubtreePropsEqual);

function ElementTypeIcon({ type }: { type: string }) {
  const cls = "h-3.5 w-3.5 shrink-0";
  if (type === "text") return <Type className={cls} />;
  if (type === "image") return <ImageIcon className={cls} />;
  if (type === "button") return <Square className={cls} />;
  if (type === "video") return <Video className={cls} />;
  if (type === "audio") return <Music className={cls} />;
  if (type === "html") return <FileIcon className={cls} />;
  if (type === "ppt") return <Presentation className={cls} />;
  if (type === "vtuber") return <User className={cls} />;
  if (type === "narration") return <AudioLines className={cls} />;
  if (type === "quiz") return <ClipboardCheck className={cls} />;
  if (type === "line") return <Minus className={cls} />;
  if (type === "arrow") return <ArrowRight className={cls} />;
  if (type === "ellipse") return <CircleIcon className={cls} />;
  return <Square className={cls} />;
}

function NarrationButton({
  mode,
  onClick,
}: {
  mode: "add" | "edit";
  onClick: () => void;
}) {
  const { t } = useI18nNew();
  const tip =
    mode === "edit"
      ? t("coursewareEditor.narration.editForNarration")
      : t("coursewareEditor.narration.generateForVtuber");
  const labelKey =
    mode === "edit"
      ? "coursewareEditor.narration.editButton"
      : "coursewareEditor.narration.addButton";
  return (
    <button
      type="button"
      onClick={onClick}
      title={tip}
      className="flex items-center gap-1 rounded border border-violet-400/60 bg-violet-100 px-2 py-1 text-xs text-violet-900 transition hover:bg-violet-200 dark:border-violet-500/30 dark:bg-violet-500/15 dark:text-violet-200 dark:hover:bg-violet-500/25"
    >
      <AudioLines className="h-3.5 w-3.5" />
      {t(labelKey)}
    </button>
  );
}

// ---------- narration modal helpers (batch TTS / teacher rebind) ----------

/** When an old organization's AI teacher can't be resolved: keep ai_teacher_id in the element to satisfy serialization, and mark the binding as removed in metadata. */
const clearNarrationTeacherUnlinkedMeta = (
  metadata: NarrationElement["metadata"],
): NarrationElement["metadata"] => {
  if (!metadata || typeof metadata !== "object") return metadata;
  const next = { ...(metadata as Record<string, unknown>) };
  delete next[NARRATION_TEACHER_BINDING_UNLINKED_META];
  return next as NarrationElement["metadata"];
};

const applyNarrationTeacherBinding = (
  narration: NarrationElement,
  teacher: AITeacherInfo,
  vtuberElementId: string,
  previousTeacherStyle?: string | null,
): NarrationElement => {
  // Keep the narration text and existing speech; only rebind the teacher / default voice, and let the user decide whether to regenerate.
  // Rebinding resets only "inherited values": an element style equal to the old teacher's config (never chosen explicitly
  // by the user) → cleared along with the rebind, and the new teacher inherits by its config; any other value counts as an explicit user choice
  // and is kept as-is (custom text included). When the old teacher isn't among the candidates, it conservatively keeps it.
  const storedStyle = narration.ai_teacher_tts_style?.trim() || "";
  const inheritedFromPrevious =
    Boolean(storedStyle) &&
    previousTeacherStyle != null &&
    storedStyle === previousTeacherStyle.trim();
  const { ai_teacher_tts_style: _reboundOutStyle, ...narrationRest } = narration;
  void _reboundOutStyle;
  return {
    ...(inheritedFromPrevious
      ? narrationRest
      : { ...narrationRest, ai_teacher_tts_style: narration.ai_teacher_tts_style }),
    vtuber_element_id: vtuberElementId,
    ai_teacher_id: teacher.ai_teacher_id,
    ai_teacher_name: teacher.ai_teacher_name || narration.ai_teacher_name,
    ai_teacher_tts_id: teacher.ai_teacher_tts_id ?? narration.ai_teacher_tts_id,
    ai_teacher_tts_speed: teacher.ai_teacher_tts_speed ?? narration.ai_teacher_tts_speed,
    ai_teacher_tts_volume: teacher.ai_teacher_tts_volume ?? narration.ai_teacher_tts_volume,
    ai_teacher_tts_pitch: teacher.ai_teacher_tts_pitch ?? narration.ai_teacher_tts_pitch,
    ai_teacher_language: teacher.ai_teacher_language ?? narration.ai_teacher_language,
    metadata: {
      ...clearNarrationTeacherUnlinkedMeta(narration.metadata),
      ai_teacher_id: teacher.ai_teacher_id,
      ai_teacher_name: teacher.ai_teacher_name,
      vtuber_element_id: vtuberElementId,
    },
  };
};

const LAYER_ROW_BASE_CLASS =
  "relative flex h-[36px] items-center gap-1 border-b border-slate-200 dark:border-slate-800/60 px-1.5 text-xs transition select-none";
const LAYER_ROW_IDLE_CLASS =
  "text-slate-700 hover:bg-slate-200/50 dark:text-slate-300 dark:hover:bg-slate-800/70";
const LAYER_ROW_SELECTED_CLASS =
  "bg-blue-50 text-blue-800 hover:bg-blue-100/70 dark:bg-blue-500/10 dark:text-blue-200 dark:hover:bg-blue-500/15";

interface LayerListProps {
  slide: SlideElement | undefined;
  selectedElementIds: string[];
  onSelectElement: (id: string | null, options?: { toggle?: boolean }) => void;
  /**
   * Reorder by stack-unit index (same order as {@link buildQuestionStackRenderUnits}).
   * Display rows are narration-first, so callers translate display rows → unit indices
   * via `EditorLayerRow.unitIndex` before invoking.
   */
  onReorderLayerRow: (fromUnit: number, toUnit: number) => void;
  /** Element ids that should be excluded from the layer list (e.g. members of question wrappers). */
  hiddenElementIds?: Set<string>;
  onOpenElementContextMenu?: OpenElementContextMenuFn;
}

function LayerList({
  slide,
  selectedElementIds,
  onSelectElement,
  onReorderLayerRow,
  hiddenElementIds: _hiddenElementIds,
  onOpenElementContextMenu,
}: LayerListProps) {
  const { t } = useI18nNew();
  // Drag-reorder state: the original (array) index of the row being dragged and the
  // original index of the row we're currently hovering (where it would land).
  const [drag, setDrag] = useState<{ from: number; hoverTo: number | null }>({
    from: -1,
    hoverTo: null,
  });

  if (!slide) return null;
  const layerRows = buildEditorLayerRows(slide);
  const rowCount = layerRows.length;
  // Pinned rows (narration, vtuber) stay at the top; first reorderable row follows them.
  const pinnedRowCount = layerRows.findIndex(
    (r) => r.kind !== "narration" && r.kind !== "vtuber",
  );
  const firstReorderableRow = pinnedRowCount === -1 ? rowCount : pinnedRowCount;
  // Translate display row indices → stack-unit indices, since narration-first display
  // ordering diverges from the underlying z-ordered stack units.
  const reorderByDisplayRow = (fromDisplay: number, toDisplay: number): void => {
    const fromRow = layerRows[fromDisplay];
    const toRow = layerRows[toDisplay];
    if (!fromRow || !toRow) return;
    if (fromRow.unitIndex === toRow.unitIndex) return;
    onReorderLayerRow(fromRow.unitIndex, toRow.unitIndex);
  };

  return (
    <div>
      {layerRows.map((row, rowIdx) => {
        const el = slide.children_elements[row.childIndex];
        if (!el) return null;
        const isNarration = el.element_type === "narration";
        const isVtuber = el.element_type === "vtuber";
        const isLayerPinned = isPinnedLayerElement(el);
        const isDragging = drag.from === rowIdx;
        const showDropLine = drag.from !== -1 && drag.hoverTo === rowIdx && drag.from !== rowIdx;
        const canShiftRowUp = !isLayerPinned && rowIdx > firstReorderableRow;
        const canShiftRowDown = !isLayerPinned && rowIdx < rowCount - 1;
        const canBringToListTop = !isLayerPinned && rowIdx > firstReorderableRow;
        const canSendToListBottom = !isLayerPinned && rowIdx < rowCount - 1;

        return (
          <div
            key={el.element_id}
            onDragOver={(e) => {
              if (isLayerPinned) return;
              if (drag.from === -1) return;
              e.preventDefault();
              e.dataTransfer.dropEffect = "move";
              if (drag.hoverTo !== rowIdx) setDrag((d) => ({ ...d, hoverTo: rowIdx }));
            }}
            onDrop={(e) => {
              if (isLayerPinned) {
                setDrag({ from: -1, hoverTo: null });
                return;
              }
              e.preventDefault();
              const from = Number(e.dataTransfer.getData("text/plain"));
              if (!Number.isFinite(from)) {
                setDrag({ from: -1, hoverTo: null });
                return;
              }
              if (from !== rowIdx) {
                reorderByDisplayRow(from, rowIdx);
              }
              setDrag({ from: -1, hoverTo: null });
            }}
            onDragLeave={() => {
              if (drag.hoverTo === rowIdx) setDrag((d) => ({ ...d, hoverTo: null }));
            }}
            className={`${LAYER_ROW_BASE_CLASS} ${
              selectedElementIds.includes(el.element_id)
                ? LAYER_ROW_SELECTED_CLASS
                : LAYER_ROW_IDLE_CLASS
            } ${isDragging ? "opacity-40" : ""}`}
            onContextMenu={(e) => {
              if (!onOpenElementContextMenu || isElementAgentChatFrozen(el.element_id)) return;
              e.preventDefault();
              e.stopPropagation();
              onOpenElementContextMenu(el.element_id, e.clientX, e.clientY);
            }}
          >
            {showDropLine ? (
              <span className="pointer-events-none absolute inset-x-0 -top-px h-0.5 bg-blue-500 dark:bg-blue-400" />
            ) : null}

            <span
              draggable={!isLayerPinned}
              onDragStart={(e) => {
                if (isLayerPinned) {
                  e.preventDefault();
                  return;
                }
                e.dataTransfer.setData("text/plain", String(rowIdx));
                e.dataTransfer.effectAllowed = "move";
                setDrag({ from: rowIdx, hoverTo: rowIdx });
              }}
              onDragEnd={() => setDrag({ from: -1, hoverTo: null })}
              className={`flex h-full items-center ${
                isLayerPinned
                  ? "cursor-not-allowed text-slate-700"
                  : "cursor-grab text-slate-400 dark:text-slate-500 hover:text-slate-800 dark:hover:text-slate-200 active:cursor-grabbing"
              }`}
              title={
                isNarration
                  ? t("coursewareEditor.layers.narrationFixedTop")
                  : isVtuber
                    ? t("coursewareEditor.layers.vtuberFixedBelowNarration")
                    : t("coursewareEditor.layers.dragReorder")
              }
            >
              <GripVertical className="h-3.5 w-3.5" />
            </span>

            <button
              onClick={(event) =>
                onSelectElement(el.element_id, {
                  toggle: event.metaKey || event.ctrlKey || event.shiftKey,
                })
              }
              className="flex min-w-0 flex-1 items-center gap-1.5 text-left"
            >
              <ElementTypeIcon type={el.element_type} />
              <span className="truncate">{el.name}</span>
              {el.keyframes.length > 0 ? (
                <span className="text-[10px] text-slate-400 dark:text-slate-500">{el.keyframes.length}k</span>
              ) : null}
            </button>

            {!isLayerPinned ? (
              <div className="flex shrink-0 items-center gap-0.5">
                <LayerButton
                  icon={<ChevronsUp className="h-3 w-3" />}
                  title={t("coursewareEditor.common.bringToFront")}
                  disabled={!canBringToListTop}
                  onClick={() => reorderByDisplayRow(rowIdx, firstReorderableRow)}
                />
                <LayerButton
                  icon={<ChevronUp className="h-3 w-3" />}
                  title={t("coursewareEditor.common.bringForward")}
                  disabled={!canShiftRowUp}
                  onClick={() => reorderByDisplayRow(rowIdx, rowIdx - 1)}
                />
                <LayerButton
                  icon={<ChevronDown className="h-3 w-3" />}
                  title={t("coursewareEditor.common.sendBackward")}
                  disabled={!canShiftRowDown}
                  onClick={() => reorderByDisplayRow(rowIdx, rowIdx + 1)}
                />
                <LayerButton
                  icon={<ChevronsDown className="h-3 w-3" />}
                  title={t("coursewareEditor.common.sendToBack")}
                  disabled={!canSendToListBottom}
                  onClick={() => reorderByDisplayRow(rowIdx, rowCount - 1)}
                />
              </div>
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

function LayerButton({
  icon,
  title,
  disabled,
  onClick,
}: {
  icon: React.ReactNode;
  title: string;
  disabled?: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      title={title}
      disabled={disabled}
      onClick={(e) => {
        e.stopPropagation();
        onClick();
      }}
      className="flex h-5 w-5 items-center justify-center rounded disabled:hover:text-slate-400 dark:text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700 hover:text-slate-900 dark:hover:text-slate-100 disabled:opacity-30 disabled:hover:bg-transparent"
    >
      {icon}
    </button>
  );
}

function TimelineTrack({
  element,
  duration,
  timelineLayoutDurationMs = duration,
  slideTimeStart,
  isQuizQuestionTimeline,
  selected,
  currentTime,
  selectedKeyframe,
  selectedHighlight,
  getScrollLeft,
  onRequestAutoScroll,
  onStopAutoScroll,
  seekFromTimelineClientX,
  onSeek,
  onOpenElementProperties,
  onSelectKeyframe,
  onSelectHighlight,
  onCaptureHistorySnapshot,
  onCommitHistorySnapshot,
  onSelect,
  onUpdateElement,
  getTimelineSnapTargets,
  onTimelineSnapGuidesChange,
  onClearTimelineSnapGuides,
  onOpenElementContextMenu,
  onTimelineBarDragStart,
  onTimelineBarDragEnd,
}: {
  element: CourseElement;
  duration: number;
  /** The duration matching the layout width of timeline rows (may exceed {@link duration} while previewing a slide duration drag). */
  timelineLayoutDurationMs?: number;
  /** Absolute time at slide start (children timelines are usually absolute within the slide window). */
  slideTimeStart: number;
  /** Canvas quiz question wrapper: no left/right resize handles and no timeline keyframes; it can only move as a whole. */
  isQuizQuestionTimeline: boolean;
  selected: boolean;
  currentTime: number;
  selectedKeyframe: SelectedKeyframe | null;
  selectedHighlight: SelectedHighlight | null;
  getScrollLeft: () => number;
  onRequestAutoScroll: (clientX: number, onScrolled: (clientX: number) => void) => void;
  onStopAutoScroll: () => void;
  seekFromTimelineClientX: (clientX: number) => void;
  onSeek: (ms: number) => void;
  onOpenElementProperties: (elementId: string) => void;
  onSelectKeyframe: (keyframe: SelectedKeyframe | null) => void;
  onSelectHighlight: (highlight: SelectedHighlight | null) => void;
  onCaptureHistorySnapshot: () => Scene;
  onCommitHistorySnapshot: (snapshot: Scene) => void;
  onSelect: (event: ReactMouseEvent<HTMLDivElement>) => void;
  onUpdateElement: (
    updater: (el: CourseElement) => CourseElement,
    options?: { recordHistory?: boolean },
  ) => void;
  getTimelineSnapTargets: (excludeElementId: string) => TimelineSnapTarget[];
  onTimelineSnapGuidesChange: (guides: TimelineSnapGuide[]) => void;
  onClearTimelineSnapGuides: () => void;
  onOpenElementContextMenu?: OpenElementContextMenuFn;
  onTimelineBarDragStart?: () => void;
  onTimelineBarDragEnd?: () => void;
}) {
  const { t } = useI18nNew();
  const barRef = useRef<HTMLDivElement | null>(null);
  const dragRef = useRef<
    | null
    | {
        kind: "move" | "left" | "right";
        startX: number;
        startStart: number;
        startEnd: number;
        startScrollLeft: number;
        width: number;
        startElement: CourseElement;
      }
  >(null);
  const keyframeDragRef = useRef<
    | null
    | {
        keyframeIndex: number;
        startX: number;
        startAt: number;
        currentAt: number;
        startScrollLeft: number;
        width: number;
        hasMoved: boolean;
        historySnapshot: Scene;
      }
  >(null);
  const highlightDragRef = useRef<
    | null
    | {
        highlightId: string;
        kind: "move" | "left" | "right";
        startX: number;
        startStart: number;
        startEnd: number;
        currentStart: number;
        currentEnd: number;
        startScrollLeft: number;
        width: number;
        hasMoved: boolean;
        historySnapshot: Scene;
      }
  >(null);
  const suppressHighlightClickRef = useRef(false);
  /** Same as the quiz track: after dragging to move/resize a bar, suppress one click to avoid a mistaken seek */
  const suppressBarPointerClickRef = useRef(false);

  const start = element.timeline.start_at;
  const end = element.timeline.end_at;
  const localStart = Math.max(0, start - slideTimeStart);
  const localEnd = Math.max(localStart, end - slideTimeStart);
  const layoutDenom = Math.max(1, timelineLayoutDurationMs);
  const left = (localStart / layoutDenom) * 100;
  const width = ((localEnd - localStart) / layoutDenom) * 100;
  const secondGridSizePercent = (1000 / layoutDenom) * 100;
  const highlightSegments = getElementHighlightSegments(element);
  /** Same px width as the timeline content container (must match `dxMs` mapping). */
  const timelineWidthPx = Math.max(1, (duration / 1000) * TIMELINE_PX_PER_SECOND);

  const beginBarDrag = (
    e: ReactPointerEvent<HTMLDivElement>,
    kind: "move" | "left" | "right",
  ): void => {
    e.preventDefault();
    e.stopPropagation();
    suppressBarPointerClickRef.current = false;
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    onTimelineBarDragStart?.();
    dragRef.current = {
      kind,
      startX: e.clientX,
      startStart: start,
      startEnd: end,
      startScrollLeft: getScrollLeft(),
      width: timelineWidthPx,
      startElement: element,
    };
  };

  const updateBarDrag = (clientX: number): void => {
    if (!dragRef.current) return;
    const d = dragRef.current;
    if (Math.abs(clientX - d.startX) > 2) suppressBarPointerClickRef.current = true;
    const scrollDelta = getScrollLeft() - d.startScrollLeft;
    const dxMs = ((clientX - d.startX + scrollDelta) / d.width) * duration;
    const t0 = slideTimeStart;
    const snapTargets = getTimelineSnapTargets(d.startElement.element_id);

    let proposedStart = d.startStart;
    let proposedEnd = d.startEnd;
    if (d.kind === "move") {
      const length = d.startEnd - d.startStart;
      const newLocalStart = clamp(
        d.startStart - t0 + dxMs,
        0,
        Math.max(0, duration - length),
      );
      proposedStart = t0 + newLocalStart;
      proposedEnd = proposedStart + length;
    } else if (d.kind === "left") {
      proposedStart =
        t0 +
        clampResizeStartLocal(
          d.startEnd - t0,
          d.startStart + dxMs - t0,
          duration,
          MIN_ELEMENT_TIMELINE_SPAN_MS,
        );
      proposedEnd = d.startEnd;
    } else {
      proposedStart = d.startStart;
      proposedEnd =
        t0 +
        clampResizeEndLocal(
          d.startStart - t0,
          d.startEnd + dxMs - t0,
          duration,
          MIN_ELEMENT_TIMELINE_SPAN_MS,
        );
    }

    const snapped = snapElementTimelineDrag(d.kind, proposedStart, proposedEnd, snapTargets);
    onTimelineSnapGuidesChange(snapped.guides);

    onUpdateElement((el) => {
      if (d.kind === "move") {
        const delta = snapped.start_at - d.startStart;
        return clampElementTimedRangesToTimeline(
          shiftElementTimedRanges(
            {
              ...d.startElement,
              timeline: { start_at: snapped.start_at, end_at: snapped.end_at },
            },
            delta,
          ),
        );
      }
      if (d.kind === "left") {
        return clampElementTimedRangesToTimeline({
          ...el,
          timeline: { start_at: snapped.start_at, end_at: snapped.end_at },
        });
      }
      return clampElementTimedRangesToTimeline({
        ...el,
        timeline: { start_at: snapped.start_at, end_at: snapped.end_at },
      });
    });
  };

  const onBarPointerMove = (e: ReactPointerEvent<HTMLDivElement>): void => {
    if (!dragRef.current) return;
    e.stopPropagation();
    updateBarDrag(e.clientX);
    onRequestAutoScroll(e.clientX, updateBarDrag);
  };

  const endBarDrag = (e: ReactPointerEvent<HTMLDivElement>): void => {
    if (!dragRef.current) return;
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    dragRef.current = null;
    onStopAutoScroll();
    onClearTimelineSnapGuides();
    onTimelineBarDragEnd?.();
  };

  const beginKeyframeDrag = (
    e: ReactPointerEvent<HTMLDivElement>,
    keyframeAt: number,
    keyframeIndex: number,
  ): void => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    keyframeDragRef.current = {
      keyframeIndex,
      startX: e.clientX,
      startAt: keyframeAt,
      currentAt: keyframeAt,
      startScrollLeft: getScrollLeft(),
      width: timelineWidthPx,
      hasMoved: false,
      historySnapshot: onCaptureHistorySnapshot(),
    };
  };

  const updateKeyframeDrag = (clientX: number): void => {
    const d = keyframeDragRef.current;
    if (!d) return;
    const scrollDelta = getScrollLeft() - d.startScrollLeft;
    const dx = clientX - d.startX + scrollDelta;
    d.hasMoved = d.hasMoved || Math.abs(dx) > 3;
    const nextAt = clamp(Math.round(d.startAt + (dx / d.width) * duration), start, end);
    if (Math.abs(nextAt - d.currentAt) < 0.001) return;

    onUpdateElement((el) => {
      const currentIndex = el.keyframes.findIndex((kf) => isSameKeyframeTime(kf.at, d.currentAt));
      if (currentIndex < 0 || hasKeyframeAt(el.keyframes, nextAt, currentIndex)) return el;
      d.currentAt = nextAt;
      return {
        ...el,
        keyframes: el.keyframes.map((kf, index) =>
          index === currentIndex ? { ...kf, at: nextAt } : kf,
        ),
      };
    }, { recordHistory: false });
  };

  const onKeyframePointerMove = (e: ReactPointerEvent<HTMLDivElement>): void => {
    if (!keyframeDragRef.current) return;
    e.preventDefault();
    e.stopPropagation();
    updateKeyframeDrag(e.clientX);
    onRequestAutoScroll(e.clientX, updateKeyframeDrag);
  };

  const endKeyframeDrag = (e: ReactPointerEvent<HTMLDivElement>): void => {
    const d = keyframeDragRef.current;
    if (!d) return;
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    keyframeDragRef.current = null;
    onStopAutoScroll();

    if (!d.hasMoved) {
      onSeek(d.currentAt);
      onSelectKeyframe({ elementId: element.element_id, at: d.currentAt });
      onOpenElementProperties(element.element_id);
      return;
    }

    onCommitHistorySnapshot(d.historySnapshot);
    onUpdateElement((el) => ({
      ...el,
      keyframes: normalizeKeyframesByTime(el.keyframes),
    }), { recordHistory: false });
    onSelectKeyframe({ elementId: element.element_id, at: d.currentAt });
  };

  const beginHighlightDrag = (
    e: ReactPointerEvent<HTMLElement>,
    highlight: ElementHighlight,
    kind: "move" | "left" | "right",
  ): void => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    highlightDragRef.current = {
      highlightId: highlight.highlight_id,
      kind,
      startX: e.clientX,
      startStart: highlight.start_at,
      startEnd: highlight.end_at,
      currentStart: highlight.start_at,
      currentEnd: highlight.end_at,
      startScrollLeft: getScrollLeft(),
      width: timelineWidthPx,
      hasMoved: false,
      historySnapshot: onCaptureHistorySnapshot(),
    };
  };

  const updateHighlightDrag = (clientX: number): void => {
    const d = highlightDragRef.current;
    if (!d) return;
    const scrollDelta = getScrollLeft() - d.startScrollLeft;
    const dx = clientX - d.startX + scrollDelta;
    d.hasMoved = d.hasMoved || Math.abs(dx) > 3;
    const dxMs = Math.round((dx / d.width) * duration);
    let nextStart = d.startStart;
    let nextEnd = d.startEnd;
    if (d.kind === "move") {
      const length = d.startEnd - d.startStart;
      nextStart = clamp(
        d.startStart + dxMs,
        element.timeline.start_at,
        element.timeline.end_at - length,
      );
      nextEnd = nextStart + length;
    } else if (d.kind === "left") {
      const maxStart = Math.max(element.timeline.start_at, d.startEnd - MIN_HIGHLIGHT_DURATION_MS);
      nextStart = clamp(
        d.startStart + dxMs,
        element.timeline.start_at,
        maxStart,
      );
    } else {
      const minEnd = Math.min(element.timeline.end_at, d.startStart + MIN_HIGHLIGHT_DURATION_MS);
      nextEnd = clamp(
        d.startEnd + dxMs,
        minEnd,
        element.timeline.end_at,
      );
    }
    if (
      Math.abs(nextStart - d.currentStart) < 0.001 &&
      Math.abs(nextEnd - d.currentEnd) < 0.001
    ) {
      return;
    }
    d.currentStart = nextStart;
    d.currentEnd = nextEnd;
    onUpdateElement((el) => ({
      ...el,
      highlight_segments: getElementHighlightSegments(el)
        .map((highlight) =>
          highlight.highlight_id === d.highlightId
            ? { ...highlight, start_at: nextStart, end_at: nextEnd }
            : highlight,
        )
        .sort((a, b) => a.start_at - b.start_at),
    }), { recordHistory: false });
  };

  const onHighlightPointerMove = (e: ReactPointerEvent<HTMLElement>): void => {
    if (!highlightDragRef.current) return;
    e.preventDefault();
    e.stopPropagation();
    updateHighlightDrag(e.clientX);
    onRequestAutoScroll(e.clientX, updateHighlightDrag);
  };

  const endHighlightDrag = (e: ReactPointerEvent<HTMLElement>): void => {
    const d = highlightDragRef.current;
    if (!d) return;
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    highlightDragRef.current = null;
    onStopAutoScroll();
    if (d.hasMoved) {
      suppressHighlightClickRef.current = true;
      onCommitHistorySnapshot(d.historySnapshot);
      return;
    }
    onSeek(d.currentStart);
    onSelectHighlight({ elementId: element.element_id, highlightId: d.highlightId });
    onOpenElementProperties(element.element_id);
  };

  const isNarration = element.element_type === "narration";
  const narrationSegments: NarrationSegment[] = isNarration
    ? (element as NarrationElement).segments
    : [];
  const narrationTotalMs = narrationSegments.reduce(
    (acc, seg) => acc + seg.gap_ms + seg.duration_ms,
    0,
  );

  // Inline editing of an individual narration segment's leading gap.
  // Activated by double-clicking the segment block; while active the user can
  // drag the block left/right to shrink/grow its `gap_ms` (which represents
  // the silence between this segment and the previous block / track start).
  const [editingSegIndex, setEditingSegIndex] = useState<number | null>(null);
  const editingSegRef = useRef<HTMLSpanElement | null>(null);
  const segDragRef = useRef<
    | null
    | {
        segIndex: number;
        startX: number;
        startGap: number;
        msPerPx: number;
      }
  >(null);

  useEffect(() => {
    if (!isNarration) setEditingSegIndex(null);
  }, [isNarration]);

  useEffect(() => {
    if (editingSegIndex === null) return;
    const onDocMouseDown = (e: MouseEvent): void => {
      if (segDragRef.current) return;
      const node = editingSegRef.current;
      if (node && !node.contains(e.target as Node)) {
        setEditingSegIndex(null);
      }
    };
    const onKey = (e: KeyboardEvent): void => {
      if (e.key === "Escape") setEditingSegIndex(null);
    };
    window.addEventListener("mousedown", onDocMouseDown, true);
    window.addEventListener("keydown", onKey);
    return () => {
      window.removeEventListener("mousedown", onDocMouseDown, true);
      window.removeEventListener("keydown", onKey);
    };
  }, [editingSegIndex]);

  // Compute a practical upper bound for gap_ms while still allowing drag
  // beyond the current narration bar. This is especially important for the
  // last segment, whose "remaining space" inside current bar is often 0.
  const computeMaxGapMs = (segIndex: number): number => {
    if (!isNarration) return 0;
    const segs = narrationSegments;
    let acc = 0;
    for (let i = 0; i < segIndex; i += 1) {
      acc += segs[i].gap_ms + segs[i].duration_ms;
    }
    // Space left inside current narration bar from this segment onward.
    const remainingInsideBar = Math.max(0, end - start - acc - segs[segIndex].duration_ms);
    // Allow extending beyond current bar by one slide-length budget; slide
    // duration is normalized later via expandSlideToFitNarration.
    const extraGrowthBudget = Math.max(duration, narrationTotalMs, 1000);
    return Math.max(segs[segIndex].gap_ms, remainingInsideBar + extraGrowthBudget);
  };

  const beginSegmentDrag = (
    e: ReactPointerEvent<HTMLSpanElement>,
    segIndex: number,
    startGap: number,
  ): void => {
    e.stopPropagation();
    const barWidthPx = barRef.current?.getBoundingClientRect().width ?? 0;
    if (barWidthPx <= 0) return;
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    const totalForLayout = Math.max(1, narrationTotalMs);
    segDragRef.current = {
      segIndex,
      startX: e.clientX,
      startGap,
      msPerPx: totalForLayout / barWidthPx,
    };
  };

  const onSegmentPointerMove = (e: ReactPointerEvent<HTMLSpanElement>): void => {
    if (!segDragRef.current) return;
    e.stopPropagation();
    const d = segDragRef.current;
    const dxMs = (e.clientX - d.startX) * d.msPerPx;
    const maxGap = computeMaxGapMs(d.segIndex);
    let accBefore = 0;
    for (let i = 0; i < d.segIndex; i += 1) {
      accBefore += narrationSegments[i].gap_ms + narrationSegments[i].duration_ms;
    }
    const proposedSentenceStart = start + accBefore + Math.round(d.startGap + dxMs);
    const snapTargets = getTimelineSnapTargets(element.element_id);
    const { snappedMs, guide } = snapTimelineAnchorMs(proposedSentenceStart, snapTargets);
    onTimelineSnapGuidesChange(guide ? [guide] : []);
    const newGap = clamp(Math.round(snappedMs - start - accBefore), 0, maxGap);
    onUpdateElement((el) => {
      if (el.element_type !== "narration") return el;
      const n = el as NarrationElement;
      if (n.segments[d.segIndex]?.gap_ms === newGap) return el;
      return {
        ...n,
        segments: n.segments.map((s, i) =>
          i === d.segIndex ? { ...s, gap_ms: newGap } : s,
        ),
      };
    });
  };

  const endSegmentDrag = (e: ReactPointerEvent<HTMLSpanElement>): void => {
    if (!segDragRef.current) return;
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    segDragRef.current = null;
    onClearTimelineSnapGuides();
  };

  return (
    <div
      className={`relative h-9 border-b border-slate-200 bg-white/70 dark:border-slate-800/60 dark:bg-transparent ${
        selected ? "bg-blue-50/90 dark:bg-blue-500/5" : ""
      } select-none`}
      onClick={onSelect}
      onContextMenu={(e) => {
        if (!onOpenElementContextMenu || isElementAgentChatFrozen(element.element_id)) return;
        e.preventDefault();
        e.stopPropagation();
        onOpenElementContextMenu(element.element_id, e.clientX, e.clientY);
      }}
    >
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: "linear-gradient(90deg, var(--editor-timeline-grid) 1px, transparent 1px)",
          backgroundSize: `${secondGridSizePercent}% 100%`,
        }}
      />
      <div
        ref={barRef}
        className={`absolute top-1.5 bottom-1.5 rounded border ${
          isNarration
            ? selected
              ? "border-violet-600 bg-violet-200 dark:border-violet-400 dark:bg-violet-500/25"
              : "border-violet-500 bg-violet-100 hover:bg-violet-200 dark:border-violet-500/50 dark:bg-violet-500/15 dark:hover:bg-violet-500/25"
            : selected
              ? "border-blue-600 bg-blue-200 dark:border-blue-400 dark:bg-blue-500/30"
              : "border-slate-400 bg-slate-200 hover:bg-slate-300 dark:border-slate-600 dark:bg-slate-700/70 dark:hover:bg-slate-600"
        }`}
        style={{ left: `${left}%`, width: `${width}%` }}
        title={
          isQuizQuestionTimeline
            ? t("coursewareEditor.timeline.quizDragTitle", { name: element.name })
            : undefined
        }
        onPointerDown={(e) => beginBarDrag(e, "move")}
        onPointerMove={onBarPointerMove}
        onPointerUp={endBarDrag}
        onPointerCancel={endBarDrag}
        onClick={(e) => {
          if (suppressBarPointerClickRef.current) {
            suppressBarPointerClickRef.current = false;
            return;
          }
          e.stopPropagation();
          seekFromTimelineClientX(e.clientX);
          onSelect(e);
        }}
      >
        {isNarration && narrationSegments.length > 0 ? (
          <>
            <div className="absolute inset-0 flex items-stretch overflow-hidden rounded">
              {narrationSegments.map((seg, segIndex) => {
                const totalForLayout = Math.max(1, narrationTotalMs);
                const gapPct = (seg.gap_ms / totalForLayout) * 100;
                const segPct = (seg.duration_ms / totalForLayout) * 100;
                const blockPct = gapPct + segPct;
                const isEditing = editingSegIndex === segIndex;
                return (
                  <span
                    key={segIndex}
                    className="flex h-full"
                    style={{ width: `${blockPct}%` }}
                  >
                    {seg.gap_ms > 0 ? (
                      <span
                        className="h-full bg-transparent"
                        style={{ width: `${(gapPct / blockPct) * 100}%` }}
                        title={t("coursewareEditor.common.gapPause", { ms: seg.gap_ms })}
                      />
                    ) : null}
                    <span
                      ref={isEditing ? editingSegRef : null}
                      className={`flex h-full min-w-0 items-center overflow-hidden border-l px-1 text-[10px] text-violet-950 dark:text-white/90 ${
                        isEditing
                          ? "z-10 cursor-ew-resize border-amber-500 bg-amber-200 text-amber-950 ring-2 ring-amber-400 dark:border-amber-300 dark:bg-amber-400/60 dark:text-white dark:ring-amber-300"
                          : "border-violet-400/70 bg-violet-300/80 dark:border-violet-300/40 dark:bg-violet-400/40"
                      }`}
                      style={{ width: `${(segPct / blockPct) * 100}%` }}
                      title={
                        isEditing
                          ? t("coursewareEditor.timeline.segmentGapDrag", { ms: seg.gap_ms })
                          : t("coursewareEditor.timeline.segmentInfo", {
                              index: segIndex + 1,
                              text: seg.text,
                              seconds: (seg.duration_ms / 1000).toFixed(1),
                            })
                      }
                      onDoubleClick={(e) => {
                        e.stopPropagation();
                        setEditingSegIndex(segIndex);
                      }}
                      onClick={(e) => {
                        if (isEditing) e.stopPropagation();
                      }}
                      onPointerDown={(e) => {
                        if (!isEditing) return;
                        beginSegmentDrag(e, segIndex, seg.gap_ms);
                      }}
                      onPointerMove={onSegmentPointerMove}
                      onPointerUp={endSegmentDrag}
                      onPointerCancel={endSegmentDrag}
                    >
                      <span className="ml-2 truncate">{seg.text}</span>
                    </span>
                  </span>
                );
              })}
            </div>
          </>
        ) : (
          <div className="flex h-full items-center gap-1 overflow-hidden px-1 text-[10px] text-slate-800 dark:text-white/80">
            <div className="w-1"></div>
            <ElementTypeIcon type={element.element_type} />
            <span className="truncate">{element.name}</span>
          </div>
        )}
        {!isQuizQuestionTimeline ? (
          <>
            <div
              className="absolute left-0 top-0 z-10 h-full w-2 cursor-ew-resize rounded-l bg-blue-600/85 ring-1 ring-blue-500/50 dark:bg-blue-400/70 dark:ring-blue-300/40"
              onPointerDown={(e) => beginBarDrag(e, "left")}
              onClick={(e) => e.stopPropagation()}
            />
            <div
              className="absolute right-0 top-0 z-10 h-full w-2 cursor-ew-resize rounded-r bg-blue-600/85 ring-1 ring-blue-500/50 dark:bg-blue-400/70 dark:ring-blue-300/40"
              onPointerDown={(e) => beginBarDrag(e, "right")}
              onClick={(e) => e.stopPropagation()}
            />
          </>
        ) : null}
        {highlightSegments.map((highlight) => {
          const relStart = (highlight.start_at - start) / Math.max(1, end - start);
          const relEnd = (highlight.end_at - start) / Math.max(1, end - start);
          const active = currentTime >= highlight.start_at && currentTime <= highlight.end_at;
          const isSelectedHighlight =
            selected &&
            selectedHighlight?.elementId === element.element_id &&
            selectedHighlight.highlightId === highlight.highlight_id;
          return (
            <div
              key={highlight.highlight_id}
              className={`group absolute bottom-0.5 top-0.5 z-8 cursor-grab rounded-sm active:cursor-grabbing ${
                isSelectedHighlight ? "ring-2 ring-amber-500/80 dark:ring-amber-200/90" : ""
              } ${
                active
                  ? "bg-amber-400/85 dark:bg-amber-300/70"
                  : "bg-amber-300/70 hover:bg-amber-400/80 dark:bg-amber-400/35 dark:hover:bg-amber-400/55"
              }`}
              style={{
                left: `${clamp(relStart, 0, 1) * 100}%`,
                width: `${Math.max(1, (clamp(relEnd, 0, 1) - clamp(relStart, 0, 1)) * 100)}%`,
              }}
              title={t("coursewareEditor.common.narrationHighlightRange", {
                start: formatTimeMs(highlight.start_at),
                end: formatTimeMs(highlight.end_at),
              })}
              onPointerDown={(e) => beginHighlightDrag(e, highlight, "move")}
              onPointerMove={onHighlightPointerMove}
              onPointerUp={endHighlightDrag}
              onPointerCancel={(e) => {
                if (!highlightDragRef.current) return;
                e.preventDefault();
                e.stopPropagation();
                (e.target as HTMLElement).releasePointerCapture(e.pointerId);
                highlightDragRef.current = null;
                onStopAutoScroll();
              }}
              onClick={(e) => {
                e.stopPropagation();
                if (suppressHighlightClickRef.current) {
                  suppressHighlightClickRef.current = false;
                  return;
                }
                onSeek(highlight.start_at);
                onOpenElementProperties(element.element_id);
              }}
            >
              {(["left", "right"] as const).map((kind) => (
                <span
                  key={kind}
                  className={`absolute top-0 h-full w-2 cursor-ew-resize bg-amber-700/75 opacity-0 transition-opacity group-hover:opacity-100 dark:bg-amber-100/90 ${
                    kind === "left" ? "left-0 rounded-l-sm" : "right-0 rounded-r-sm"
                  }`}
                  onPointerDown={(e) => beginHighlightDrag(e, highlight, kind)}
                  onPointerMove={onHighlightPointerMove}
                  onPointerUp={endHighlightDrag}
                  onClick={(e) => e.stopPropagation()}
                  onPointerCancel={(e) => {
                    if (!highlightDragRef.current) return;
                    e.preventDefault();
                    e.stopPropagation();
                    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
                    highlightDragRef.current = null;
                    onStopAutoScroll();
                  }}
                  title={kind === "left" ? t("coursewareEditor.timeline.highlightDragIn") : t("coursewareEditor.timeline.highlightDragOut")}
                />
              ))}
            </div>
          );
        })}
        {!isQuizQuestionTimeline && element.element_type !== "audio"
          ? element.keyframes.map((kf, keyframeIndex) => {
              const rel = (kf.at - start) / Math.max(1, end - start);
              const isSelectedKeyframe =
                selected &&
                selectedKeyframe?.elementId === element.element_id &&
                Math.abs(selectedKeyframe.at - kf.at) <= 0.001;
              return (
                <div
                  key={keyframeIndex}
                  className="absolute top-1/2 z-10 flex h-4 w-4 -translate-x-1/2 -translate-y-1/2 cursor-ew-resize items-center justify-center"
                  style={{
                    left: `${rel * 100}%`,
                  }}
                  title={t("coursewareEditor.common.keyframeAt", { time: formatTimeMs(kf.at) })}
                  onPointerDown={(e) => beginKeyframeDrag(e, kf.at, keyframeIndex)}
                  onPointerMove={onKeyframePointerMove}
                  onPointerUp={endKeyframeDrag}
                  onClick={(e) => e.stopPropagation()}
                  onPointerCancel={(e) => {
                    if (!keyframeDragRef.current) return;
                    e.preventDefault();
                    e.stopPropagation();
                    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
                    keyframeDragRef.current = null;
                    onStopAutoScroll();
                  }}
                >
                  <div
                    className={`h-2 w-2 rotate-45 border ${
                      isSelectedKeyframe
                        ? "border-amber-700 bg-amber-400 ring-2 ring-amber-500/60 dark:border-amber-100 dark:bg-amber-300 dark:ring-amber-300/70"
                        : "border-amber-800 bg-amber-500 dark:border-white dark:bg-amber-400"
                    }`}
                  />
                </div>
              );
            })
          : null}
      </div>
    </div>
  );
}

